\begin{theorem}\label{thm:dir}
	Assume that $|\partial_{\nu} u_\infty|^{\frac{p-q}{q-1}}\partial_{\nu}u_\infty\in W^{1-1/p,p}(\partial\Om)$ and let $\bar{u}\in W^{1,p}(\Om)$ be an extension of $-|\partial_{\nu} u_\infty|^{\frac{p-q}{q-1}}\partial_{\nu}u_\infty$ to $\Om$. Then
	\begin{equation*}
		-\frac{q-1}{q}\int_{\partial\Om}|\partial_{\nu} u_\infty|^{\frac{(p-1)q}{q-1}}\ds\leq\alpha^\gamma(E_\alpha-E_\infty)\leq -\frac{q-1}{q}\int_{\partial\Om}|\partial_{\nu} u_\infty|^{\frac{(p-1)q}{q-1}}\ds+\rho_\alpha,
	\end{equation*}
	where
	\begin{equation*}
		\rho_\alpha:=\frac{\alpha^\gamma}{p}\int_\Om\Big(|\nabla (u_\infty+\alpha^{-\gamma}\bar{u})|^p-|\nabla u_\infty|^p-p\alpha^{-\gamma}|\nabla u_\infty|^{p-2}\nabla u_\infty\cdot\nabla \bar{u}\Big)\dx
	\end{equation*}
	satisfies $\rho_\alpha\to 0$ as $\alpha\to+\infty$ and $\gamma:=1/(q-1)$. Moreover, if $\partial_{\nu}u_\infty \in L^{\frac{(p-1)q}{q-1}}(\partial\Om)$, then
	\begin{equation*}
		E_\alpha=E_\infty-\frac{q-1}{q}\alpha^{-\gamma}\int_{\partial\Om}|\partial_\nu u_\infty|^{\frac{(p-1)q}{q-1}}\ds+o\big(\alpha^{-\gamma}\big),\qquad\text{as }\alpha\to+\infty.
	\end{equation*}
\end{theorem}
\begin{proof}
	First of all, we prove that the following equivalent formulation for $E_\alpha$ holds true:
	\begin{equation}\label{eq:dir_1}
		E_\alpha=E_\infty+\alpha^{-\gamma}R_\alpha,
	\end{equation}
	where the remainder term $R_\alpha$ is given by
	\[\begin{split}
		R_\alpha:=\inf_{u\in W^{1,p}(\Om)}\bigg\{\frac{\alpha^\gamma}{p}\int_\Om\Big(|\nabla(u_\infty&+\alpha^{-\gamma}u)|^p-|\nabla u_\infty|^p\dx-p\alpha^{-\gamma}|\nabla u_\infty|^{p-2}\nabla u_\infty\cdot\nabla u\Big)\dx\\
		&+\int_{\partial\Om}\Big(\frac{1}{q}|u|^{q-2}u+|\nabla u_\infty|^{p-2}\partial_\nu u_\infty\Big)u\bigg\}.
	\end{split}\]
		We first perform the change of variables $u\mapsto u_\infty+\alpha^{-\gamma}u$, with $u\in W^{1,p}(\Om)$, and get that
	\begin{equation*}
		E_\alpha=E_\infty+\widetilde{R}_\alpha,
	\end{equation*}
	with
	\[\begin{split}
		\widetilde{R}_\alpha:=\inf_{u\in W^{1,p}(\Om)}\bigg\{\frac{1}{p}\int_\Om|\nabla(u_\infty+\alpha^{-\gamma}u)|^p\dx&-\frac{1}{p}\int_\Om|\nabla u_\infty|^p\dx\\
		&+\frac{\alpha^{1-\gamma q}}{q}\int_{\partial\Om}|u|^q\ds-\alpha^{-\gamma}\int_\Om fu\dx\bigg\}.
	\end{split}\]
	Then, by using the fact that $1-\gamma q=-\gamma$ and the integration-by-parts identity
	\begin{equation*}
		\int_\Om|\nabla u_\infty|^{p-2}\nabla u_\infty\cdot\nabla u\dx=\int_\Om fu\dx+\int_{\partial\Om}|\nabla u_\infty|^{p-2}\partial_\nu u_\infty u\ds,
	\end{equation*}
	we get that $\widetilde{R}_\alpha=\alpha^{-\gamma}R_\alpha$, which concludes the proof of \eqref{eq:dir_1}. In view of \eqref{eq:dir_1} we are left to prove that
	\begin{equation*}
		-\frac{q-1}{q}\int_{\partial\Om}|\partial_{\nu} u_\infty|^{\frac{(p-1)q}{q-1}}\ds\leq R_\alpha\leq -\frac{q-1}{q}\int_{\partial\Om}|\partial_{\nu} u_\infty|^{\frac{(p-1)q}{q-1}}\ds+\rho_\alpha.
	\end{equation*}
	In order to prove the lower bound, we simply observe that by convexity of the function $t\mapsto |t|^p$ there holds
	\begin{equation*}
		\frac{\alpha^\gamma}{p}\int_\Om|\nabla(u_\infty+\alpha^{-\gamma}u)|^p\dx-\frac{\alpha^\gamma}{p}\int_\Om|\nabla u_\infty|^p\dx \\
		-\int_\Om|\nabla u_\infty|^{p-2}\nabla u_\infty\cdot\nabla u\dx\geq 0
	\end{equation*}
	for all $u\in W^{1,p}(\Om)$ and all $\alpha>0$. Therefore, we have
	\begin{equation*}
		R_\alpha\geq \inf_{u\in W^{1,p}(\Om)}\left\{ \int_{\partial\Om}\left(\frac{1}{q}|u|^{q-2}u+|\partial_{\nu} u_\infty|^{p-2}\partial_{\nu} u_\infty\right)u\ds \right\}.
	\end{equation*}
	At this point, we optimize with respect to $u$ and find (see \Cref{rmk:g}) that the infimum is achieved with $u=\bar{u}$ on $\partial\Om$. Then, by explicit computations we conclude the proof of the lower bound.
	On the other hand, the upper is proved by testing the definition of $R_\alpha$ with $\bar{u}$, while the fact that $\rho_\alpha\to 0$ as $\alpha\to 0^+$ is trivial.

	Let us now pass to the proof of the second part. Since $|\partial_{\nu}u_\infty|^{\frac{p-q}{q-1}}\partial_{\nu}u_\infty \in L^q(\partial\Om)$, then there exists $v_n\in W^{1-1/p,p}(\partial\Omega)$ such that
	\begin{equation}\label{eq:dir_2}
		v_n\to -|\partial_{\nu}u_\infty|^{\frac{p-q}{q-1}}\partial_{\nu} u_\infty \quad\text{in }L^q(\partial\Omega)~\text{as }n\to\infty.
	\end{equation}
	Now, let $\bar{v}_n\in W^{1,p}(\Omega)$ be an extension of $v_n$ in $\Omega$. We can replicate the proof of the previous step by using $\bar{v}_n$ in place of $\bar{u}$ and obtain that
\[\begin{split}
-\frac{q-1}{q}\int_{\partial\Om}|\partial_\nu u_\infty|^{\frac{(p-1)q}{q-1}}\ds
&\le\alpha^\gamma(E_\alpha-E_\infty)\\
&\le\tilde{\rho}_{\alpha,n}+\int_{\partial\Om}\left(\frac{1}{q}|v_n|^q+|\partial_\nu u_\infty|^{p-2}\partial_\nu u_\infty v_n\right)\ds,
\end{split}\]
	where
	\begin{equation*}
		\tilde{\rho}_{\alpha,n}:=\frac{\alpha^\gamma}{p}\int_\Om\Big(|\nabla (u_\infty+\alpha^{-\gamma}\bar{v}_n)|^p-|\nabla u_\infty|^p-p\alpha^{-\gamma}|\nabla u_\infty|^{p-2}\nabla u_\infty\cdot\nabla \bar{v}_n\Big)\dx
	\end{equation*}
	satisfies $\tilde{\rho}_{\alpha,n}\to 0$ as $\alpha\to+\infty$. Now we pass to the limit as $\alpha\to+\infty$ and obtain that
	\begin{align*}
-\frac{q-1}{q}\int_{\partial\Om}|\partial_\nu u_\infty|^{\frac{(p-1)q}{q-1}}\ds
&\le\liminf_{\alpha\to+\infty}\alpha^\gamma(E_\alpha-E_\infty)\\
&\le\limsup_{\alpha\to+\infty}\alpha^\gamma(E_\alpha-E_\infty)\\
&\le\int_{\partial\Om}\left(\frac{1}{q}|v_n|^q+|\partial_\nu u_\infty|^{p-2}\partial_\nu u_\infty v_n\right)\ds.
	\end{align*}
Finally, we pass to the limit as $n\to\infty$ and, by the strong convergence \eqref{eq:dir_2}, we obtain
$$\lim_{\alpha\to+\infty}\alpha^\gamma(E_\alpha-E_\infty)=-\frac{q-1}{q}\int_{\partial\Om}|\partial_\nu u_\infty|^{\frac{(p-1)q}{q-1}}\ds,$$
as required.	
\end{proof}

