\section{The Neumann limit}\label{sec:neumann}

In this section, we study of the asymptotic behaviour of $E_\alpha$ as $\alpha\to 0^+$. In contrast to the Dirichlet limit, here we distinguish the two cases
\begin{equation*}
	\int_\Om f\dx=0\qquad\text{and}\qquad\int_\Om f\dx\neq 0,
\end{equation*}
which determine whether the Neumann problem
\begin{equation*}
	\begin{cases}
		-\Delta_p u= f, &\text{in }\Om, \\
		|\nabla u|^{p-2}\partial_\nu u=0, &\text{on }\partial\Om,
	\end{cases}
\end{equation*}
has a solution or not.

\subsection{\texorpdfstring{The case $\int_\Om f\dx= 0$}{The zero mean case}}
Let us consider the minimization problem
\begin{equation*}
	E_0:=\inf_{u\in W^{1,p}(\Om)}\Bigg\{\frac{1}{p}\int_\Om|\nabla u|^p\dx-\int_\Om fu\dx\colon u\in W^{1,p}(\Om),~\int_{\partial\Om} |u|^{q-2}u\ds=0\Bigg\},
\end{equation*}
which is the natural limit problem for $E_\alpha$, as $\alpha\to 0^+$. Indeed, by testing the weak formulation of the equation of $u_\alpha$ with a constant test function, we obtain the condition
\begin{equation*}
	\int_{\partial\Om}|u_\alpha|^{q-2}u_\alpha\ds=\frac{1}{\alpha}\int_\Om f\dx=0.
\end{equation*}
Hence, we denote by $u_0\in W^{1,p}(\Omega)$ the unique minimizer of $E_0$, which exists in view of the validity of the compatibility condition
\begin{equation*}
	\int_\Om f\dx=0.
\end{equation*}
Moreover, $u_0$ weakly satisfies
$$\begin{cases}
-\Delta_p u_0=f&\text{in }\Om\\
|\nabla u_0|^{p-2}\partial_\nu u_0=0&\text{on }\partial\Om\\
\int_{\partial\Om}|u_0|^{q-2}u_0\ds=0,
\end{cases}$$
that is
\begin{equation*}
	\int_\Om|\nabla u_0|^{p-2}\nabla u_0\cdot\nabla \varphi\dx=\int_\Om f\varphi\dx\qquad\text{for all }\varphi\in W^{1,p}(\Om).
\end{equation*}
We now prove the main result concerning the asymptotic behavior of $E_\alpha$ in the case $\int_\Om f\dx=0$, that is \eqref{eq:neumann_th1}.
\begin{theorem}
	Assume that $u_0\in L^q(\partial\Om)$. Then
	\begin{equation*}
		E_\alpha=E_0+ \frac{\alpha}{q}\int_{\partial\Om}|u_0|^q\ds+o(\alpha),\quad\text{as }\alpha\to 0^+.
	\end{equation*}
\end{theorem}
\begin{proof}
	By reasoning as in the proof of the second part of \Cref{lemma:diff}, we get that
	\begin{equation}\label{eq:neum_1}
		\frac{1}{q}\int_{\partial\Omega}|u_\alpha|^q\ds\leq \frac{E_\alpha-E_0}{\alpha}\leq \frac{1}{q}\int_{\partial\Omega}|u_0|^q\ds
	\end{equation}
	for all $\alpha>0$. Hence, by weak lower semicontinuity of the $L^q(\partial\Omega)$-norm, the theorem is proved once we prove that
	\begin{equation*}
		u_\alpha\weak  u_0\quad\text{weakly in }L^q(\partial\Omega)~\text{as }\alpha\to 0^+.
	\end{equation*}
	By definition of $E_\alpha$ and in view of \eqref{eq:neum_1} we derive that
	\begin{equation*}
		\frac{1}{p}\int_\Omega|\nabla u_\alpha|^p\dx+\frac{\alpha}{q}\int_{\partial\Omega}|u_\alpha|^q\ds=E_\alpha+\int_\Omega fu_\alpha\dx\leq E_0+\frac{\alpha}{q}\int_{\partial\Omega}|u_0|^q\ds+\int_\Omega fu_\alpha\dx.
	\end{equation*}
	In particular,
	\begin{equation}\label{eq:neum_2}
		\norm{\nabla u_\alpha}_{L^p(\Omega)}^p\leq C+\norm{f}_{(W^{1,p}(\Omega))^*}\norm{u_\alpha}_{W^{1,p}(\Omega)},
	\end{equation}
	for some $C>0$ not depending on $\alpha$ and for $\alpha$ sufficiently small.
	On the other hand, thanks to \Cref{lemma:poinc} and \eqref{eq:neum_1} we get that, for $\alpha$ sufficiently small
	\begin{align*}
		\norm{u_\alpha}_{L^p(\Omega)} &\leq C\left(\norm{\nabla u_\alpha}_{L^p(\Omega)}+\norm{u_\alpha}_{L^q(\partial\Omega)}\right) \\
		&\leq C\left(\norm{\nabla u_\alpha}_{L^p(\Omega)}+\norm{u_0}_{L^q(\partial\Omega)}\right) .
	\end{align*}
	At this point, putting together this last estimate with \eqref{eq:neum_2} and \eqref{eq:neum_1} provides that $\{u_\alpha\}_{\alpha}$ is bounded in $W^{1,p}(\Omega)\cap L^q(\partial\Omega)$ (i.e. in $\mathcal{W}_{p,q}$), as $\alpha\to 0^+$. Therefore, up to a subsequence
	\begin{align*}
		&u_\alpha\weak U \quad\text{weakly in }W^{1,p}(\Omega), \\
		&u_\alpha\weak U \quad\text{weakly in }L^q(\partial \Omega), \\
		&u_\alpha\to U \quad\text{strongly in }L^p(\Omega)\cap L^p(\partial\Omega), 
	\end{align*}
	as $\alpha\to 0$, for some $U\in W^{1,p}(\Omega)$. From the equation satisfied by $u_\alpha$, since 
	\begin{equation*}
		|\nabla u_\alpha|^{p-2}\nabla u_\alpha\weak |\nabla U|^{p-2}\nabla U\quad\text{weakly in }L^{p'}(\Omega,\R^d)
	\end{equation*}
	 as $\alpha\to 0$, we obtain that
	\begin{equation*}
		\int_\Omega |\nabla U|^{p-2}\nabla U\cdot\nabla\varphi\dx=\int_\Omega f\varphi\dx\quad\text{for all }\varphi \in W^{1,p}(\Omega).
	\end{equation*}
	Analogously, since $u_\alpha \weak U$ in $L^q(\partial\Omega)$ as $\alpha\to 0$ we get that
	\begin{equation*}
		|u_\alpha|^{q-2}u_\alpha\weak |U|^{q-2}U\quad\text{weakly in }L^{q'}(\partial\Omega)
	\end{equation*}
	as $\alpha\to 0$, thus implying that
	\begin{equation*}
		0=\lim_{\alpha\to 0}\int_{\partial\Omega}|u_\alpha|^{q-2}u_\alpha\ds=\int_{\partial\Omega}|U|^{q-2}U\ds.
	\end{equation*}
	In particular, by uniqueness of the minimizer, we have that $U=u_0$. Then, since the limit $U$ is uniquely determined, we have that 
	\begin{equation*}
		u_\alpha\weak u_0\quad\text{weakly in }L^q(\partial\Omega)~\text{as }\alpha\to 0,
	\end{equation*}
	without passing to subsequences. By \eqref{eq:neum_1} and weak lower semicontinuity of the $L^q(\partial\Omega)$-norm, we conclude the proof.
\end{proof}


