\subsection{\texorpdfstring{The case $\int_\Om f\dx\neq 0$}{The non-zero mean case}}

In this case, the expected limit Neumann problem does not have a solution and, as observed in the introduction, the Robin energy $E_\alpha$ diverges to $-\infty$ as $\alpha\to 0^+$. In the next result, we detect its   asymptotic behavior, thus proving \eqref{eq:neumann_th2}.

\begin{theorem}
	There holds
	\begin{equation*}
		-\frac{q-1}{q}\frac{\displaystyle \left|\int_\Om f\dx\right|^{\frac{q}{q-1}}}{\mathcal{H}^{d-1}(\partial\Om)^{\frac{1}{q-1}}}+\alpha^{\gamma}K_f\leq \alpha^\gamma E_\alpha\leq -\frac{q-1}{q}\frac{\displaystyle \left|\int_\Om f\dx\right|^{\frac{q}{q-1}}}{\mathcal{H}^{d-1}(\partial\Om)^{\frac{1}{q-1}}},
	\end{equation*}
	where $\gamma:=1/(q-1)$ and
	\begin{equation*}
		K_f:=\inf\left\{\frac{1}{p}\int_\Om|\nabla v|^p\dx-\int_\Om fv\dx\ :\ v\in W^{1,p}(\Om),~\int_{\partial\Om}v\ds=0\right\}.
	\end{equation*}
	In particular,
	\begin{equation*}
		E_\alpha=-\frac{1}{\alpha^\gamma}\frac{q-1}{q}\frac{\displaystyle \left|\int_\Om f\dx\right|^{\frac{q}{q-1}}}{\mathcal{H}^{d-1}(\partial\Om)^{\frac{1}{q-1}}}+o\left(\frac{1}{\alpha^\gamma}\right),\quad\text{as }\alpha\to 0^+.
	\end{equation*}
\end{theorem}
\begin{proof}
	The upper bound can be easily obtained by testing $E_\alpha$ with a constant $u\equiv t\in\R$. Indeed, we get $E_\alpha\leq g(t)$, with
	\begin{equation*}
		g(t):=\frac{\alpha\mathcal{H}^{d-1}(\partial\Om)}{q}|t|^q-t\int_\Om f\dx,
	\end{equation*}
	and so, by \Cref{rmk:g} we deduce the upper bound.

	For what concerns the upper bound, we let
	\begin{equation*}
		v_u:=u-\intn_{\partial\Om} u\ds,
	\end{equation*}
	so that $u=t_u+v_u$ with
	\begin{equation*}
		t_u:=\intn_{\partial\Om} u\ds. 
	\end{equation*}
	With this change, thanks to the convexity inequality
	\begin{equation*}
		|t+v|^q\geq |t|^q+q|t|^{q-2}tv
	\end{equation*}
	and the fact that
	\begin{equation*}
		\int_{\partial\Om}v_u\ds=0,
	\end{equation*}
	we have that
	\begin{align}
		E_\alpha&=\inf\left\{\frac{1}{p}\int_\Om|\nabla v_u|^p\dx+\frac{\alpha}{q}\int_{\partial\Om}|t_u+v_u|^q\ds-\int_\Om f v_u\dx-t_u\int_\Om f\dx\colon u\in W^{1,p}(\Om)\right\}\notag \\
		&\geq \inf\Bigg\{\frac{1}{p}\int_\Om|\nabla v_u|^p\dx+\frac{\alpha}{q}\int_{\partial\Om}|t_u|^q\ds+\alpha |t_u|^{q-2}t_u\int_{\partial\Om}v_u\ds \notag\\
		&\qquad\quad-\int_\Om f v_u\dx-t_u\int_\Om f\dx\colon u\in W^{1,p}(\Om)\Bigg\}\notag \\
		&\geq \inf\left\{\frac{1}{p}\int_\Om|\nabla v|^p\dx-\int_\Om f v\colon v\in W^{1,p}(\Om),~\int_{\partial\Om}v\ds=0\right\} \notag\\
		&+\inf\left\{\frac{\alpha |t|^q}{q}\mathcal{H}^{d-1}(\partial\Om)-t\int_\Om f\dx\colon t\in\R\right\}.\label{eq:neumann_f_not_0_1}
	\end{align}	
	Now, by classical variational methods, one can easily see that the first term
	\begin{equation*}
		K_f:=\inf\left\{\frac{1}{p}\int_\Om|\nabla v|^p\dx-\int_\Om f v\colon v\in W^{1,p}(\Om),~\int_{\partial\Om}v\ds=0\right\}>-\infty
	\end{equation*}
	is achieved by a unique function $v\in W^{1,p}(\Om)$ satisfying
	\begin{equation*}
		\begin{cases}
			-\Delta_p v=f, &\text{in }\Om, \\
			\displaystyle|\nabla v|^{p-2}\partial_\nu v =-\frac{1}{\mathcal{H}^{d-1}(\partial\Om)}\int_\Om f\dx, &\text{on }\partial\Om, \\
			\displaystyle \int_{\partial\Om} v\ds=0. &
		\end{cases}
	\end{equation*}
	Finally, in view of \Cref{rmk:g}, we can explicitly write the second term \eqref{eq:neumann_f_not_0_1} and conclude the proof.
\end{proof}

