    \item\label{M1} Linear Gaussian model:
    \(
    Y = 5X_1+\varepsilon,
    \) where $\varepsilon\sim\cN(0,1)$ and \(X\sim\cN_{10}(0,\Sigma)\) with \(\diag(\Sigma)=1, \Sigma_{12}=\Sigma_{21}=\rho\) and zero otherwise.

    \item\label{M2} Non-linear model:
    \(
    Y = 5\cos(X_1)+5\cos(X_{2})+\varepsilon,
    \) with the same covariate and noise as \hyperref[M1]{(M1)}.


    \item\label{M3} Piecewise interaction with indicators:    
    \(
    Y = 1.5X_1X_{2}\,\ind\{X_{3}>0\} + X_{4}X_{5}\,\ind\{X_{3}<0\} + \varepsilon ,
    \)
    where $\varepsilon\sim\cN(0,0.4)$ and \(
    X\sim\cN_{5}(0,\Sigma),\;
    \Sigma_{jj}=1,\;
    \Sigma_{12}=\Sigma_{21}=\Sigma_{45}=\Sigma_{54}=\rho ,
    \) and $0$ otherwise.

    \item\label{M4} Low-density model:
    \(
    Y = 5X_1+\varepsilon,
    \) where
    \(
    X_{-2}\sim\cN_9(0,1),
    X_{2}=3X_1^{2}+\delta
    \) and \((\delta,\varepsilon)\sim\cN_2(0,1)\).


    \end{enumerate}






