\section{Proof in \Cref{sec:properties}}\label{app:proof-properties}

\subsection{Proof of \Cref{lem:null-feature}}\label{app:sub:lem:null-feature}
\begin{proof}[Proof of \Cref{lem:null-feature}]
        Note that $X^{(j)} \indep Y \mid X_{-j}$, because $X^{(j)}_j$ is constructed without using $Y$ (i.e., $X^{(j)}_j\indep Y\mid X_{-j}$).
        From the construction of $X^{(j)}$, we have that $X^{(j)} \overset{\iid}{\sim} X$.
        Under the null that $X_j\indep Y\mid X_{-j}$, we further have $(X^{(j)}, Y) \overset{\iid}{\sim}  (X,Y)$ and $\mu(X) = \mu_{-j}(X_{-j}) = \mu(X^{(j)})$.
        Consequently, $\psi^{\cpi}_{X_j} = \psi^{\loco}_{X_j}= 0$. This finishes the proof.
    \end{proof}


\subsection{Proof of \Cref{lem:equiv}}\label{app:sub:lem:equiv}

\begin{proof}[Proof of \Cref{lem:equiv}]
        For any random variable $W$, its variance can be expressed as $\VV[W] = \EE[(W- \EE[W])^2] = \EE[(W- W')^2]/2$ where $W'$ is an independent copy of $W$.
        Conditioned on $X_{-j}$, it follows that
        \begin{align*}
            \VV[\mu(X) \mid X_{-j}] &= \EE[ (\mu(X) - \EE[\mu(X)\mid X_{-j}])^2\mid X_{-j}] = \EE[(\mu(X) - \mu_{-j}(X_{-j}))^2\mid X_{-j}]  \\
            \VV[\mu(X) \mid X_{-j}] &= \frac{1}{2} \EE[ (\mu(X) - \EE[\mu(X^{(j)}) \mid X_{-j}])^2\mid X_{-j}] = \frac{1}{2}\EE[(\mu(X) - \mu(X^{(j)}))^2\mid X_{-j}].
        \end{align*}
        On the other hand, for $\ell_2$-loss, we have
        \begin{align*}
            \psi^{\loco}_{X_j}&= \EE[(Y - \mu_{-j}(X_{-j}))^2] - \EE[(Y- \mu(X) )^2]\\
            &= 
            \EE[(\mu(X) - \mu_{-j}(X_{-j}))^2] - 2\EE[(\mu(X) - Y)(\mu(X) - \mu_{-j}(X_{-j}))]    \\
            &= \EE[(\mu(X) - \mu_{-j}(X_{-j}))^2] ,
        \end{align*}
        because $\EE[Y(\mu(X) - \mu_{-j}(X_{-j})) ] = \EE[\EE[Y(\mu(X) - \mu_{-j}(X_{-j})) \mid X]] = 
        \EE[\mu(X) (\mu(X) - \mu_{-j}(X_{-j}))]
        $ by iterative expectation.
        Analogously, one has
        \begin{align*}
            2 \psi^{\cpi}_{X_j} &= \EE[(Y - \mu(X^{(j)}))^2] - \EE[(Y- \mu(X) )^2]\\
            &= \EE[(\mu(X) - \mu(X^{(j)}))^2] - 2\EE[(\mu(X) - Y)(\mu(X) - \mu(X^{(j)}))]    \\
            &= \EE[(\mu(X) - \mu(X^{(j)}))^2] .
        \end{align*}
        Combining the above results finishes the proof.
    \end{proof}




