\section{Proof of main results}\label{app:proof}

\subsection{Proof of \Cref{prop:free-cor}}\label{app:sub:prop:free-cor}
\begin{proof}[Proof of \Cref{prop:free-cor}]
        From \Cref{lem:equiv}, we have $\phi_{Z_j}= \EE[\VV[\mu(W)\mid Z_{-j}]]$.
        Because $\VV[\mu(W)\mid Z_{-j}]\geq 0$, we have that $\phi_{Z_j} = 0$ if and only if $\VV[\mu(W)\mid Z_{-j}] =0$ almost surely.
        This is equivalent to $\mu(W) = \EE[\mu(W)\mid Z_{-j}]$ almost surely.
        Also note that $\EE[Y\mid Z] = \EE[\EE[Y\mid W]\mid Z] = \EE[\mu(W)\mid Z] = \mu(W)$ because of $W\sim p(W\mid Z)$ and tower property of conditional expectation.
        Then, the condition is equivalent to $\EE[Y\mid Z] = \EE[\mu(W)\mid Z_{-j}] $ almost surely.
        By the tower property, we also have $\EE[\mu(W)\mid Z_{-j}] = \EE[\EE[Y\mid Z]\mid Z_{-j}] = \EE[Y\mid Z_{-j}]$.
        These imply that $\phi_{Z_j} = 0$ if and only if $\EE[Y\mid Z] = \EE[Y\mid Z_{-j}]$.
        % i.e., $\EE[Y \mid Z]$ does not depend on $Z_j$
        Because $Z_j$ and $Z_{-j}$ are independent, $\EE[Y\mid Z] = \EE[Y\mid Z_{-j}]$ is equivalent to the event that $\EE[Y\mid Z]$ does not depend on $Z_j$ almost surely.
    \end{proof}




\subsection{Proof of \Cref{thm:error-decom}}\label{app:sub:them:error-decom}
    \begin{proof}[Proof of \Cref{thm:error-decom}]

    We split the proof into three steps.






    \noindent\textbf{Step 1: Error decomposition for the LOCO functional.}

    From \citet[Lemma 1]{williamson2021nonparametric}, the efficient influence function for $\phi_{Z_j} = \EE[ (\eta(Z) - \eta_{-j}(Z_{-j}))^2 ]$ is $\varphi(O;\PP) = 2 (Y - \eta(Z))(\eta(Z) - \eta_{-j}(Z_{-j}) + (\eta(Z) - \eta_{-j}(Z_{-j}))^2 - \phi_{Z_j}$.
    Furthermore, for any given estimator $\hat{\PP}$ (with associated estimators $\hat{\eta}$ and $\hat{\eta}_{-j}$) of the nonparametric model $\PP$, the LOCO estimator
    \begin{align}
        \hat{\phi}_{Z_j}^{\loco}(\PP; \hat{\eta},\hat{\eta}_{-j}) := \PP_n \left[ (Y - \hat{\eta}_{-j}(Z_{-j}))^2 - (Y - \hat{\eta}(Z))^2 \right],\label{eq:phi-hat-loco}
    \end{align}
    admits the following error decomposition (see the proof of \citet[Theorem 1]{williamson2021nonparametric}):
    \begin{align*}
        \hat{\phi}_{Z_j}^{\loco}(\PP;\hat{\eta},\hat{\eta}_{-j}) - \phi_{Z_j} &= (\PP_n-\PP) \{\varphi(O;\PP)\} + R(\hat{\PP}, \PP) + H(\hat{\PP}, \PP),
    \end{align*}
    where the first term scaled by $\sqrt{n}$ is asymptotically normal by the Central Limit Theorem (since $\varphi$ is mean-zero and square-integrable), and the remaining terms read as
    \begin{align}
        R(\hat{\PP}, \PP) &= \|\hat{\eta}_{-j} - \eta_{-j}\|_{L_2}^2 - \|\hat{\eta} - \eta\|_{L_2}^2 \label{eq:R-loco}\\
        H(\hat{\PP}, \PP) &= (\PP_n-\PP)\{\varphi(O;\hat{\PP}) - \varphi(O;\PP)\}.
    \end{align}
    Define the estimation errors:
    \[
    \delta(Z):=\hat{\eta}(Z)-\eta(Z),
    \qquad
    \delta_{-j}(Z_{-j}):=\hat{\eta}_{-j}(Z_{-j})-\eta_{-j}(Z_{-j}).
    \]
    By the Cauchy–Schwarz inequality and the fact that
    \(\PP_n-\PP\) is an average of \(n\) i.i.d. mean–zero variables,
    \begin{align}
        |H(\hat{\PP},\PP)|
    \;\le\;
        \|\varphi_{\hat{\PP}}-\varphi_{\PP}\|_{L_2}\,
        \sqrt{\frac{\mathrm{Var}[\varphi_{\hat{\PP}}-\varphi_{\PP}]}{n}}
        \;=\;
        \Op\left(
        \frac{\|\varphi_{\hat{\PP}}-\varphi_{\PP}\|_{L_2}}{\sqrt{n}}
        \right).
        \label{A.4}
    \end{align}
    Further by \Cref{lem:decomp-varphi-diff}, we have
    \[
    \;|H(\hat{\PP},\PP)|
     = \Op\left(
     \frac{1}{\sqrt{n}}\left(
     \|\delta\|_{L_2}+\|\delta_{-j}\|_{L_2}
     \right)
     \;+\;
     \frac{1}{\sqrt{n}}\left(
     \|\delta\|_{L_2}+\|\delta_{-j}\|_{L_2}
     \right)^{2} \right).
    \]
    Consequently, we have
    \begin{align}
        \hat{\phi}_{Z_j}^{\loco}(\PP;\hat{\eta},\hat{\eta}_{-j}) - \phi_{Z_j} &= (\PP_n-\PP) \{\varphi(O;\PP)\}         
        + \Op(\|\delta\|_{L_2}^2 + \|\delta_{-j}\|_{L_2}^2)  + \frac{1}{\sqrt{n}}\Op(\|\delta\|_{L_2} + \|\delta_{-j}\|_{L_2}) 
        .\label{eq:error-loco}
    \end{align}



    \noindent\textbf{Step 2: Error decomposition for the CPI functional.}
    Next, we relate the CPI functional to the LOCO functional.
    Recall that our estimator is defined as
    \[
    \hat{\phi}_{Z_j} := \frac{1}{2} \PP_n \left[ (Y - \hat{\eta}(Z^{(j)}))^2 - (Y - \hat{\eta}(Z))^2 \right].
    \]
    Note that for $\hat\eta_{-j}=\eta_{-j}$, $\delta_{-j} = 0$.
    We decompose the estimation error:
    \begin{align}
        \hat\phi_{Z_j}-\phi_{Z_j} & \;=\; [\hat\phi_{Z_j}-\hat{\phi}_{Z_j}^{\loco}(\PP;\hat{\eta},\eta_{-j})] + [\hat{\phi}_{Z_j}^{\loco}(\PP;\hat{\eta},\eta_{-j}) -\phi_{Z_j}    ] \notag\\
        &= \frac{1}{2}\PP_n\left[ (Y - \hat{\eta}(Z^{(j)}))^2 - (Y - \eta_{-j}(Z_{-j}))^2 \right] \notag\\
        &\quad+\frac{1}{2}\PP_n\left[ (Y - \hat{\eta}(Z))^2 - (Y - \eta_{-j}(Z_{-j}))^2 \right] \notag\\
        &\quad + (\PP_n-\PP) \{\varphi(O;\PP)\} + \Op(n^{-1/2}\|\delta\|_{L_2} + \|\delta\|_{L_2}^2) \notag\\
        &= \frac{1}{2}R_e + \frac{1}{2} R  + (\PP_n-\PP) \{\varphi(O;\PP)\} + \Op(n^{-1/2}\|\delta\|_{L_2} + \|\delta\|_{L_2}^2), \label{eq:decomp-cpi}
    \end{align}
    where the emprical process terms $R_e$ and remaining bias terms $R_b$ are defined as:
    \begin{align*}
        R_e &= (\PP_n-\PP) [ \hat\phi_{Z_j}-\hat{\phi}_{Z_j}^{\loco}(\PP;\hat{\eta},\eta_{-j})  ]\\
        R_b & = \PP [ \hat\phi_{Z_j}-\hat{\phi}_{Z_j}^{\loco}(\PP;\hat{\eta},\eta_{-j})  ].
    \end{align*}
    Before analyzing each of these terms, we introduce
    \[
      \zeta:=\eta(Z)-\eta_{-j}(Z_{-j}),
      \quad
      \zeta_j:=\eta(Z^{(j)})-\eta_{-j}(Z_{-j}),
      \quad
      \delta_j:=\hat\eta(Z^{(j)})-\eta(Z^{(j)}),
    \]
    and write $\varepsilon:=Y-\eta$, $U:=\varepsilon+\zeta$, $U_j:=\varepsilon+\zeta_j$.
    Because
    \begin{align*}
         (Y-\hat\eta(Z))^2-(Y-\eta_{-j}(Z_{-j}))^2
          &=(U-\delta)^2-U^2
          =\delta^2-2U\delta, \\
        (Y-\hat\eta(Z^{(j)}))^2-(Y-\eta_{-j}(Z_{-j}))^2
          &=(U_j-\delta_j)^2-U^2
          =\delta_j^2-2U_j\delta_j,
    \end{align*}
    we have
    \begin{align*}
        R_e &= \frac12\,(\PP_n-\PP) [(Y-\hat\eta(Z^{(j)}))^2-(Y-\eta_{-j}(Z_{-j}))^2 ]
         +\frac12\,(\PP_n-\PP) [(Y-\hat\eta(Z))^2-(Y-\eta_{-j}(Z_{-j}))^2 ]\\
         &= \frac12\,(\PP_n-\PP) [\delta^2-2U\delta+\delta_j^2-2U_j\delta_j ].
    \end{align*}
    Because $\|\delta\|_{L_\infty}\le 2C$ from \Cref{asm:data}~\eqref{asm:data:mu} and $\|U\|_{L_2}\le C$ from \Cref{lem:L2-boundedness}, we have
    \begin{align*}
        \|\delta^2\|_{L_2} &\;\le\; 2C\,\|\delta\|_{L_2} \\
        \|U\delta\|_{L_2}
           &
           \le \|U\|_{L_2}\,\|\delta\|_{L_2}
            \leq 3C\|\delta\|_{L_2} .    
    \end{align*}
    Similarly, we have $2C\,\|\delta_j^2\|_{L_2}\leq 2C\,\|\delta_j\|_{L_2}$ and $\|U\delta_j\|_{L_2}\leq 3C\,\|\delta_j\|_{L_2}$.
    Additionally,
    \[
    \|\delta_j\|_{L_2}^2
          =\EE[\EE [(\hat\eta(Z^{(j)})-\eta(Z^{(j)}))^{2}\mid Z_{-j} ]]
          =\EE [(\hat\eta(Z)-\eta(Z))^{2} ]
          =\|\delta\|_{L_2}^{2},
    \]
    Hence, it follows that
    \begin{align}
        R_e \;=\;\Op(n^{-1/2}\,\|\delta^2-2U\delta+\delta_j^2-2U_j\delta_j\|_{L_2} )
            =  \Op(n^{-1/2}\,\|\delta\|_{L_2}).\label{eq:E}
    \end{align}



    For the bias term, note that
    \[
        R_b
       =\frac12\,\EE [(Y-\hat\eta(Z^{(j)}))^2-(Y-\eta_{-j}(Z_{-j}))^2 ]
         +\frac12\,\EE [(Y-\hat\eta(Z))^2-(Y-\eta_{-j}(Z_{-j}))^2 ] =: A_1 + A_2.
    \]    
    Using $\hat\eta(Z^{(j)})-\eta_{-j}(Z_{-j})=\zeta_j+\delta_j$ and
    $\EE[Y-\eta_{-j}(Z_{-j})\mid Z^{(j)},Z_{-j}]=0$, the two terms of $R$ can be written as:
    \begin{align*}
        A_1
        &= \frac{1}{2}\EE[(Y-\eta(Z^{(j)})+ \eta(Z^{(j)})-\hat\eta(Z^{(j)}))^2-(Y-\eta_{-j}(Z_{-j}))^2]    \\
        &= \frac{1}{2}\EE[(Y-\eta(Z^{(j)})^2 + (\eta(Z^{(j)})-\hat\eta(Z^{(j)}))^2-(Y-\eta_{-j}(Z_{-j}))^2]\\
        &= -\frac{1}{2}\phi_{Z_j} +\frac{1}{2}\EE[(\eta(Z^{(j)})-\hat\eta(Z^{(j)}))^2] \\
        &= -\frac{1}{2}\phi_{Z_j} + \frac{1}{2}\|\delta\|_{L_2}^2\\
        A_2
        &= \frac12\,\EE [(Y- \eta(Z) +\eta(Z)-\hat\eta(Z))^2-(Y-\eta_{-j}(Z_{-j}))^2 ]\\
        &= \frac12\,\EE [(Y- \eta(Z))^2 + (\eta(Z)-\hat\eta(Z))^2-(Y-\eta_{-j}(Z_{-j}))^2 ]\\
        &= \frac{1}{2}\phi_{Z_j} + \frac{1}{2}\|\delta\|_{L_2}^2,
    \end{align*}
    Hence, one has
    \begin{align}
        R_b = \|\delta\|_{L_2}^2    \label{eq:R}
    \end{align}    


    Combining \eqref{eq:decomp-cpi}, \eqref{eq:E} and \eqref{eq:R} yields that
    \begin{align}
        \hat\phi_{Z_j}-\phi_{Z_j} & \;=\;  (\PP_n-\PP) \{\varphi(O;\PP)\} + \Op(n^{-1/2}\|\delta\|_{L_2} + \|\delta\|_{L_2}^2).
       \label{eq:decomp-cpi-2}
    \end{align}




\noindent\textbf{Step 3: bounding $\|\delta\|_{L_2}=\|\hat\eta-\eta\|_{L_2(\PP_Z)}$.}

Recall that $\eta=\mu\circ T^{-1}$, $\hat\eta=\hat\mu\circ\hat T^{-1}$, and decompose for every $z\in\cZ$
\begin{equation}\label{eq:S3-split}
   \hat\eta(z)-\eta(z)
      = \hat\mu(\hat T^{-1}(z))
                    -\hat\mu(T^{-1}(z))
      + \hat\mu(T^{-1}(z))
                    -\mu(T^{-1}(z)) = : B_1 + B_2.
\end{equation}

Term $B_1$ is the transport error.
Set
\(X:=T^{-1}(Z)\sim \PP_X\) and
\(X':=\hat T^{-1}(Z)\sim \PP_{X'}\),
and define
\[
    \varepsilon_{\mu}:=\|\hat \mu-\mu\|_{L_{2}(\PP_X)},\qquad  \varepsilon_{T^{-1}}
    :=\|\hat T^{-1}-T^{-1}\|_{L_{2}(\PP_Z)},\qquad  \varepsilon_{T}
    :=\|\hat T-T\|_{L_{2}(\PP_X)}.
\]
Introduce the truncation event $E:=\{\|Z\|\le R_{\varepsilon_{\mu}}/\lambda\}$ with $R_{\varepsilon_{\mu}}=\lambda\sqrt{d+2\log(1/\varepsilon_{\mu})}$, for which $\PP(E)\ge1-\varepsilon_{\mu}^{2}$ by a Gaussian tail bound.
On $E$ both $X$ and $X'$ lie in the ball
\(B:=\{x\in\RR^{d}:\|x\|\le R_{\varepsilon_{\mu}}\}\).
By \Cref{prop:Lip-bound}, with probability at least $1-\varepsilon_{\mu}^{2}$,
\begin{equation}\label{eq:good-Lip-local}
    L_{\mu,\varepsilon_{\mu}}
    :=\Lip(\hat\mu;B)
    \;\le\;
    L_\mu
    +
    C\,L_\mu^{1/2}\lambda^{-1/2}
       [d+2\log(1/\varepsilon_{\mu})]^{-1/4}
       \varepsilon_{\mu}^{1/2},
\end{equation}
where $C=4\sqrt2$ is the universal constant from the proposition.
Event~\eqref{eq:good-Lip-local} is contained in $E$, so it also occurs
with probability at least $1-\varepsilon_{\mu}^{2}$.
At this event, we have
\[
    |B_1|
    =|\hat\mu(X')-\hat\mu(X)|
    \le
    L_{\mu,\varepsilon_{\mu}}\,\|X'-X\|,
    \qquad
    \EE_Z[B_1^{2}]
    \le
    L_{\mu,\varepsilon_{\mu}}^{2}\,\varepsilon_{T^{-1}}^{2} \leq \lambda^2 L_{\mu,\varepsilon_{\mu}}^{2}\,\varepsilon_{T}^{2},
\]
where the last inequality is from \Cref{asm:strong-convexity}.

Term $B_2$ is the regression error. By definition,
\[
    \EE_Z[B_2^{2}]
    =\|\hat\mu-\mu\|_{L_2(\PP_X)}^{2}
    =:\varepsilon_{\mu}^{2}.
\]


Use the inequality $(a+b)^2\le2a^{2}+2b^{2}$ with
$a=B_1$ and $b=B_2$:
\[
    \|\hat\eta-\eta\|_{L_2(\PP_Z)}^{2}
    =\EE_Z[(B_1+B_2)^2]
    \le
    2\,\EE_Z[B_1^{2}]
    +
    2\,\EE_Z[B_2^{2}]
    \le
    2\lambda^2 L_{\mu,\varepsilon_{\mu}}^{\,2}\,\varepsilon_T^{2}
    +2\,\varepsilon_{\mu}^{2}.
\]
Taking square roots and keeping only the leading factor
$\sqrt2$ yields
\begin{equation}\label{eq:eta-bound}
    \|\hat\eta-\eta\|_{L_2(\PP_Z)}
    \;\le\;
    \sqrt2\lambda
    L_{\mu,\varepsilon_{\mu}}\,\varepsilon_T
    +
    \sqrt2\,\varepsilon_{\mu},
\end{equation}
with probability at least $1-\varepsilon_{\mu}^2 $.



    Finally, combining \eqref{eq:decomp-cpi-2} with \eqref{eq:eta-bound}, we further have
    \begin{align*}
        \hat{\phi}_{Z_j}-\phi_{Z_j}
      =(\PP_n-\PP)\varphi(O;\PP)
       +\cO(n^{-1/2}(\| \hat\mu-\mu \|_{L_2(\PP_X)}^2+ \| \hat T-T\|_{L_2(\PP_X)}^2)^{1/2} \\
            +  \| \hat\mu-\mu \|_{L_2(\PP_X)}^2 \;+\; \| \hat T-T\|_{L_2(\PP_X)}^2
                  ),
    \end{align*}
    with probability at least $1-\| \hat\mu-\mu \|_{L_2(\PP_X)}^2 $.
    This completes the proof.
    \end{proof}










