\subsection{Proof of \Cref{prop:eif-loco-weighted}}\label{app:sub:prop:eif-loco-weighted}


\begin{proof}[Proof of \Cref{prop:eif-loco-weighted}]

    Throughout the proof, we drop the subscript $j$ for simplicity and put
    \[
        A(O)\;:=\;\Delta(Z)^{2},
        \qquad 
        B(O)\;:=\;H(X),
        \qquad 
        \psi_{A}(\PP)\;:=\;\PP [A(O) ],
        \qquad 
        \psi_{B}(\PP)\;:=\;\theta(\PP)=\PP [B(O) ].
    \]
    With this notation, the target parameter is the expectation of a product,
	\(
		\phi(\PP)=\PP[A(O)B(O)].
	\)

    \noindent\textbf{Step 1: EIF of $A$.}
    From \citet[Lemma 1]{williamson2021nonparametric}, the efficient influence function (EIF) of $\psi_{A}(\PP)=\EE[\Delta(Z)^{2}]$ is
	\[
		\varphi_{A}(O;\PP)
		=
		2\,[Y-\eta(Z)]\,\Delta(Z)\;+\;\Delta(Z)^{2}\;-\;\psi_{A}(\PP).
	\]
	Writing $A_{c}(O)=A(O)-\psi_{A}(\PP)$ we therefore have the decomposition
	\[
		\varphi_{A}(O;\PP)
		=\;
		A_{c}(O)\;+\;\alpha_{A}(O),
		\qquad 
		\alpha_{A}(O):=2\,[Y-\eta(Z)]\,\Delta(Z).
	\]

    \noindent\textbf{Step 2: EIF of $B$.}
    By assumption the (non‑degenerate) parameter $\theta(\PP)=\EE[H(X)]$ is pathwise differentiable with EIF $\varphi_{H}(O;\PP)$.  
    Writing $B_{c}(O)=B(O)-\theta(\PP)$ we set
	\[
		\alpha_{B}(O)\;:=\;\varphi_{H}(O;\PP)\;-\;B_{c}(O)
		\;=\;
		\varphi_{H}(O;\PP)\;-\; \{H(X)-\theta(\PP) \}.
	\]

    \noindent\textbf{Step 3: EIF of the product functional.}
    Apply \Cref{lem:EIF-product} with $A,B,\alpha_{A},\alpha_{B}$ defined above, it follows that
	\[
		\varphi_{{\Delta^2H}}(O;\PP)
		\;=\;
		A(O)B(O)-\phi(\PP)\;+\;B(O)\,\alpha_{A}(O)\;+\;A(O)\,\alpha_{B}(O).
	\]
	Substituting the explicit expressions gives
	\begin{align*}
		\varphi_{\Delta^2H}(O;\PP)
		&=
		H(X)\,\Delta(Z)^{2}
		-\phi(\PP)
		+\;
		H(X)\, \{2\,[Y-\eta(Z)]\,\Delta(Z) \}
		\\
		&\quad
		+\;
		\Delta(Z)^{2}\,
		 \{\varphi_{H}(O;\PP)-H(X)+\theta(\PP) \}.
	\end{align*}
	Re‑arranging the terms completes the proof.
\end{proof}




