\subsection{Proof of \Cref{thm:err-phi-X}}\label{app:sub:them:err-phi-X}

\begin{proof}[Proof of \Cref{thm:err-phi-X}]

    Before we present the proof, we will introduce some notation for clarity.
    Fix a coordinate $l\in[d]$.  
    For each $j\in[d]$, define
    \[
    	H_{j,l}(x)\;:=\;(\partial_{x_l}T_j(x))^2,
    	\qquad 	
    	\Delta_j(z)\;:=\;\eta(z)-\eta_{-j}(z_{-j}),
    	\qquad 	
    	\phi_{j,l}(\PP)\;:=\;\EE [H_{j,l}(X)\,\Delta_j(Z)^2 ].
    \]
    Under the Bures--Wasserstein (BW) map $T(x)=Lx$ we have  
    $H_{j,l}(x)=L_{jl}^{2}$, a constant that depends only
    on $L:=\Sigma^{-\frac{1}{2}}$.  
    The target parameter is the sum
    \(
    	\phi_{X_l}=\sum_{j=1}^{d}\phi_{j,l}(\PP).
    \)




    %--------------------------------------------------
    \noindent\textbf{Step 1: Influence function expansion.}
    From \Cref{prop:eif-loco-weighted,prop:EIF-H}, the efficient influence function of $\phi_{X_l}$ is given by
    \[
    	\varphi_{X_l}(O;\PP)
    	=
    	\sum_{j=1}^{d}
    		\left\{
                L_{jl}^2\,
    		 [
    			2\,(Y-\eta(Z))\,\Delta_j(Z) + \Delta_j(Z)^{2}
    		 ]
                - 
                L_{jl} (Z_jZ_l - \delta_{jl}) \Delta(Z)^2 \right\}
    		-
    		\phi_{X_l}.
    \]
    Let $ \{(X_i,Z_i,Y_i) \}_{i=1}^{n}$ be an i.i.d.\ sample independent of the nuisance estimates $(\widehat\eta,\widehat\eta_{-j},\widehat T)$,
    \(
    	\widehat H_{j,l}(x)=(\partial_{x_l}\,\widehat{T}_j(x))^2
    \)
    and
    $
    	\widehat\Delta_j(z)=\widehat\eta(z)-\widehat\eta_{-j}(z_{-j})
    $.

    Recall that the one-step estimator is defined as
    \begin{align}
        \widehat\phi_{X_l}^{\loco}(\PP) &\;=\; \phi_{X_l}(\hat{\PP}) + \PP_n\{\varphi(O; \hat{\PP})\} \notag\\
            &=  \frac{1}{2}\PP_n\left\{
            \sum_{j=1}^d \hat L_{jl}^2 [(Y - \hat{\eta}({Z}^{(j)}) )^2 - ( Y - \hat{\eta}({Z}) )^2] 
        \right\} + \Op(n^{-1/2}\|\delta\|_{L_2} + \|\delta\|_{L_2}^2) \notag\\
        &=  \widehat\phi_{X_l}(\PP) + \Op(n^{-1/2}\|\delta\|_{L_2} + \|\delta\|_{L_2}^2), \label{eq:diff-philoco-phi}
    \end{align}
    where the second equality follows similarly from Step 2 in the proof of \Cref{thm:error-decom} and the remainder term corresponds to the difference of the LOCO estimator $\widehat\phi_{X_l}^{\loco}(\PP)$ and the CPI estimator $\widehat\phi_{X_l}(\PP)$, weighted by $\hat L_{jl}^2$'s.
    Note that $\hat{\eta}_{-j}(Z_{-j}) =\EE[\hat{\eta}(Z) \mid Z_{-j}]$ and $\hat T(X) = \hat{L} X$ and $\partial_{x_l}\hat T_j(X) = \hat{L}_{jl}$; hence, we only need to estimate two nuisance functions, essentially.


    Because the nuisance functions are estimated from independent samples other than $\PP_n$, the classical von~Mises expansion (see, e.g., \citet[Equation (2.2)]{du2025causal}) reads
    \begin{equation}\label{eq:vM}
    	\widehat\phi_{X_l}^{\loco}-\phi_{X_l}
    	=
    	(\PP_n-\PP) \{\varphi_{X_l}(O;\PP) \}
    	+
    	\underbrace{(\PP_n-\PP) [\varphi_{X_l}(O;\widehat \PP)-\varphi_{X_l}(O;\PP) ]}_{E_n}
        +
    	\underbrace{\PP [\varphi_{X_l}(O;\widehat \PP)-\varphi_{X_l}(O;\PP) ]}_{R_n} .
    \end{equation}
    It therefore suffices to show
    $
    	|E_n|=\Op(n^{-1/2}\,\varepsilon_n),
    $
    and
    $
    	|R_n|=\Op(\varepsilon_n^{2}).
    $


    \noindent\textbf{Step 2: Bounding the empirical process term $E_n$.}
    Conditioning on the auxiliary split, the summands $\varphi_{X_l}(O;\widehat \PP)-\varphi_{X_l}(O;\PP)$ are i.i.d.\ with mean~$0$,
    so that
    \[
    	|E_n|
    	\;=\;
    	 |
    		(\PP_n-\PP)
    		 [
    			\varphi_{X_l}(O;\widehat \PP)-\varphi_{X_l}(O;\PP)
    		 ]
    	 |
    	\;\le\;
    	n^{-1/2}\,
    	 \|\varphi_{X_l}(O;\widehat \PP)-\varphi_{X_l}(O;\PP) \|_{L_2}
    	= \Op(n^{-1/2}\,\varepsilon_n)
    \]
    where the last equality is from \Cref{lem:err-varphi-X}.

    \noindent\textbf{Step 3: Bounding the bias remainder $R_n$.}
    From \Cref{lem:err-varphi-X}, the bias term is bounded by $|R_n|=\Op(\varepsilon_n^{2})$.

    Finally, combining the bounds for $E_n$ and $R_n$ with \eqref{eq:diff-philoco-phi} and \eqref{eq:vM} completes the proof.    
\end{proof}





