\subsection{Proof of \Cref{lem:latent-importance-decomp}}\label{app:subsec:decomp}
\begin{proof}[Proof of \Cref{lem:latent-importance-decomp}]
We split the proof into two parts.

For Part (1), we begin with the definition of the latent feature importance, $\phi_{Z_j} = \EE[\VV(\eta(Z) \mid Z_{-j})]$. Substituting the functional ANOVA decomposition of $\eta(Z)$ yields:
$$ \phi_{Z_j} = \EE\left[\VV\left(\sum_{\cS \subseteq [d]} \eta_\cS(Z_\cS) \;\bigg|\; Z_{-j}\right)\right] $$
Due to the independence of the latent features $Z_k$ and the orthogonality of the ANOVA terms ($\EE[\eta_\cS\eta_{\cS'}] = 0$ for $\cS \neq \cS'$), any term $\eta_\cS(Z_\cS)$ where $j \notin \cS$ is a constant when conditioning on $Z_{-j}$. All terms for which $j \in \cS$ remain as random variables that are functions of $Z_j$, which is independent of the conditioning set $Z_{-j}$. The variance of the sum is therefore the sum of the variances of terms involving $Z_j$:
$$ \VV\left(\sum_{\cS \subseteq [d]} \eta_\cS(Z_\cS) \;\bigg|\; Z_{-j}\right) = \sum_{\cS: j \in \cS} \VV[\eta_\cS(Z_\cS)] $$
Since the right-hand side is a constant, taking the outer expectation is trivial, so $\phi_{Z_j} = \sum_{\cS: j \in \cS} \VV[\eta_\cS(Z_\cS)]$. Summing over all $j$:
$$ \sum_{j=1}^d \phi_{Z_j} = \sum_{j=1}^d \sum_{\cS: j \in \cS} \VV[\eta_\cS(Z_\cS)] $$
By reversing the order of summation, we count how many times each term $\VV[\eta_\cS(Z_\cS)]$ appears. A term $\eta_\cS$ is included in the sum for $\phi_{Z_j}$ for every $j \in \cS$. Thus, the term $\VV[\eta_\cS(Z_\cS)]$ appears exactly $|\cS|$ times in the total sum, which proves the first statement.

For Part (2), the law of total variance for orthogonal ANOVA terms states that the total predictive variability is the sum of the variances of each term:
$$ \VV[\EE[Y \mid X]] = \VV[\eta(Z)] = \sum_{\emptyset \neq \cS \subseteq [d]} \VV[\eta_\cS(Z_\cS)] $$
Comparing this with the result from Part (1), the equality $\sum_j \phi_{Z_j} = \VV[\eta(Z)]$ holds if and only if:
$$ \sum_{\emptyset \neq \cS \subseteq [d]} |\cS| \cdot \VV[\eta_\cS(Z_\cS)] = \sum_{\emptyset \neq \cS \subseteq [d]} \VV[\eta_\cS(Z_\cS)] $$
This equality is satisfied if and only if $\VV[\eta_\cS(Z_\cS)] = 0$ for all sets $\cS$ where $|\cS| > 1$. This is the definition of a purely additive function, $\eta(Z) = \eta_\emptyset + \sum_{j=1}^d \eta_{\{j\}}(Z_j)$, which we write as $c + \sum_j g_j(Z_j)$.
\end{proof}



\subsection{Proof of \Cref{prop:decomp-phi}}\label{app:sub-prop:decomp-phi}
\begin{proof}[Proof of \Cref{prop:decomp-phi}]
    Recall that
    \begin{align*}
        \phi_{X_l}(\PP) = \sum_{j=1}^d L_{lj}^2 \phi_{Z_j} (\PP).
    \end{align*}
    Summing the above display over \(l\) and exchanging the order of summation gives
    \begin{align}
        \sum_{l=1}^d\phi_{X_l}(\PP)
          =\sum_{j=1}^d\phi_{Z_j}(\PP)
            \left(\sum_{l=1}^d L_{lj}^{2}\right) = \sum_{j=1}^d w_j\phi_{Z_j}(\PP). \label{eq:sum-phi-1}    
    \end{align}
    Because \(L=L^\top\) and \(L^2=\Sigma^{-1}\), we have
    \begin{align}
        w_j=\sum_{l=1}^d L_{lj}^{2}
            =(L^\top L)_{jj}
            =\Sigma_{jj}.\label{eq:sum-phi-2}
    \end{align}

    Substituting \eqref{eq:sum-phi-2} into \eqref{eq:sum-phi-1} yields that
    \[
        \sum_{j=1}^d
            \Sigma_{jj}\,\phi_{Z_j}(\PP)
            \;=\;
            \sum_{l=1}^d\phi_{X_l}(\PP),
    \]
    which completes the proof.
\end{proof}


