\subsection{Knothe-Rosenblatt transport}\label{app:sub:KR}


The classical Brenier map is the unique solution of the quadratic optimal-transport problem  
$c(x,y)=\|x-y\|_{2}^{2}$ \citep{brenier1991polar}.
A series of papers by \citet{carlier2010knothe,bonnotte2013knothe} shows that the triangular Knothe–Rosenblatt rearrangement $T_{\KR}$ may be recovered from Brenier maps by anisotropically rescaling the cost:
\[
   c_{\varepsilon}(x,y)
   \;=\;
   \sum_{j=1}^{d}\lambda_{j}(\varepsilon)\,(x_{j}-y_{j})^{2},
   \qquad
\]
where $\lambda_{1}(\varepsilon)\gg\lambda_{2}(\varepsilon)\gg\cdots\gg \lambda_{d}(\varepsilon)$ and $  \lambda_{j+1}(\varepsilon)\,/\,\lambda_{j}(\varepsilon) \rightarrow0$ as $\varepsilon\to0$.
Typical weights are $\lambda_{j}(\varepsilon)=\varepsilon^{\,j-1}$.
Let $T_{\varepsilon}$ be the $\cW_{2}$-optimal map for $c_{\varepsilon}$.
Then, whenever the source measure $\PP$ is absolutely continuous and the target $\QQ$ is non-degenerate, \citet[Theorem 3.1]{carlier2010knothe} implies that
\[
        T_{\varepsilon}\;\longrightarrow\;T_{\KR}
        \quad\text{in }L^{2}(\PP)\;\text{ as }\;\varepsilon\to 0.
\]
Hence $T_{\KR}$ inherits a genuine optimal-transport interpretation: it is the map one obtains when infinitely prioritising the first
coordinate over the second, the second over the third, and so on.
The resulting continuation path $\varepsilon\mapsto T_{\varepsilon}$ provides a homotopy strategy for numerical solvers that bridges the inexpensive $T_{\KR}$ and the fully isotropic Brenier map \citep{carlier2010knothe}.

\medskip
Below, we recall a self-contained existence lemma.


\begin{lemma}[Knothe–Rosenblatt (K–R) transport]\label{lem:KR-map}
    For two Borel probability measures $\PP$ and $\QQ$ on $\RR^{d}$, consider the transport map $T:X\mapsto Z$ such that $T_\sharp\PP=\QQ$:
    \[
       T(x_1,\dots,x_d)
          =\left(T_1(x_1),\;T_2(x_1,x_2),\;\dots,\;
                 T_d(x_1,\dots,x_d)\right)
       \quad\text{with}\quad T_\sharp\PP=\QQ ,
    \]
    where each coordinate is given by:
    \begin{align*}
        T_1(x_1)
           &= F_{Z_1}^{-1}\left( F_{X_1}(x_1) \right),\\[3pt]
         T_j(x_{1:j})
           &= F_{Z_j\mid Z_{1:(j-1)}}
              ^{-1} \left(
                   F_{X_j\mid X_{1:(j-1)}}(x_j\mid x_{1:(j-1)})
                   \,\middle|\,
                   z_{1:(j-1)}
               \right), \quad 2\le j\le d,
    \end{align*}
    and $z_{1:(j-1)}:=T_{1:(j-1)}(x_{1:(j-1)})$.

    If (i) $\PP$–a.s. within the class of triangular, coordinate-wise non-decreasing maps, if $\PP$ is absolutely continuous and (ii) each one–dimensional \emph{conditional} cdf of $\QQ$ is continuous and strictly increasing, then $T$ is well-defined and unique within the monotone triangular class $\PP$-almost surely.
\end{lemma}
\begin{proof}



We split the proof into 2 steps.

\noindent\textbf{Step 1: Existence.}
The absolute continuity of $\PP$ possesses a joint density $f(x)$; in particular every conditional distribution $F_{X_j\mid X_{1:j-1}}(\,\cdot\,\mid x_{1:j-1})$ is well defined.
Thus, we may factorise $\PP$ sequentially:
\[
   \rd\PP(x)
      = f_{X_1}(x_1)\;
        f_{X_2\mid1}(x_2\mid x_1)\;
        \cdots\;
        f_{X_d\mid1:(d-1)}(x_d\mid x_{1:d-1})\,
        \rd x .
\]
Choose coordinates of $T$ by matching conditional quantiles:
\begin{align*}
    T_1(x_1)
       &= F_{Z_1}^{-1}\left( F_{X_1}(x_1) \right),\\[3pt]
     T_j(x_{1:j})
       &= F_{Z_j\mid Z_{1:(j-1)}}
          ^{-1} \left(
               F_{X_j\mid X_{1:(j-1)}}(x_j\mid x_{1:(j-1)})
               \,\middle|\,
               z_{1:(j-1)}
           \right), \quad 2\le j\le d,
\end{align*}
where $z_{1:(j-1)}:=T_{1:(j-1)}(x_{1:(j-1)})$.
Each step is well-defined because the inner cdf is continuous and the outer inverse cdf exists and is unique by the second assumption.  
Induction shows $T_\sharp\PP=\QQ$, establishing the existence.

%----------------------------------------------------
\noindent\textbf{Step 2: Uniqueness (within the monotone triangular class).}

Restrict to maps satisfying $x_j\;\mapsto\;T_j(x_{1:j}) $ is non-decreasing for every fixed $x_{1:(j-1)}$.
Let $T$ and $\tilde T$ be two such transports.  
Because both first coordinates push $X_1$ to the same measure $\QQ_1$ and both are monotone, we must have $T_1(x_1)=\tilde T_1(x_1)$ $\PP$-almost surely.
By induction, we have $T_j=\tilde T_j$ for $j=2,\dots,d$ $\PP$-almost surely.
Hence, uniqueness holds in this class.
\end{proof}




When $\QQ=\Unif[0,1]^{\otimes d}$, the following lemma provides efficient influence function for $\theta_{jl}(\PP)= \EE[(\partial_{z_l}S_j(Z))^2]$, where $S:=T^{-1}$.




\begin{lemma}[Efficient influence function of $ \theta_{jl}(\PP)$ under the triangular (Knothe–Rosenblatt) transport]
\label{lem:eif-Rosenblatt-mixed}

Let $X=(X_1,\dots ,X_d)^\top$ have a joint distribution $\PP$
that admits a Lebesgue density and let  
\[
   T(X)
      =\left(
          F_{1}(X_1),\;
          F_{2\mid1}(X_2\mid X_1),\;
          \dots,\;
          F_{d\mid1:(d-1)}\left(X_d\mid X_{1:(d-1)}\right)
        \right)
      =:Z\sim\Unif(0,1)^{\otimes d}.
\]
Write $S:=T^{-1}$.
For any pair of indices $(j,l)\in[d]^2$ define $H_{jl}(X)
:=\left\{\partial_{z_l}S_j(Z)\right\}^{2}$ and $ \theta_{jl}(\PP):=\EE_{\PP}\!\left[ H_{jl}(X) \right]$.
\begin{enumerate}[(i)]
    \item If $l>j$ then $H_{jl}(X)\equiv 0$, so $\theta_{jl}(\PP)=0$ and the efficient influence function is identically~$0$.

    \item If $l\le j$, the parameter is non–degenerate and its efficient influence function (EIF) is
    \begin{equation}\label{eq:eif-mixed}
       \varphi_{jl}(x)
          = H_{jl}(x)-\theta_{jl}
            \;-\; 2\,H_{jl}(x)\,
                  \left\{
                      \ind\{X_l\le x_l\}
                      -F_{l\mid1:(l-1)}\!\left(x_l\mid x_{1:(l-1)}\right)
                  \right\},
    \end{equation}
    which attains the semiparametric efficiency bound.
    % for every regular parametric sub–model $\{\PP_t: t\in(-\varepsilon,\varepsilon)\}$ with score $\dot\ell(X)=\partial_t\!\log\rd\PP_t(X)|_{t=0}$,
    % \[
    %      \frac{\rd}{\rd t}\Big|_{t=0}\theta_{jl}(\PP_t)
    %      \;=\;
    %      \EE_{\PP}\!\left[
    %          \varphi_{jl}(X)\,\dot\ell(X)
    %      \right].
    % \]
\end{enumerate}
\end{lemma}
\begin{proof}[Proof of \Cref{lem:KR-map}]



    If $l>j$, because the inverse K–R map is lower–triangular, $S_j$ depends only on $(z_1,\dots ,z_j)$, hence $\partial_{z_l}S_j\equiv 0$ whenever $l>j$; all assertions are immediate.



    Next, we analyze the second case in two steps.
    First, we introduce some notation.
    Fix $(j,l)$ with $l\le j$.
    Denote the lower–triangular Jacobian $J_{T}(X):=\left[\partial_{x_k}T_j(X)\right]_{j,k\le d}$ and
    \[
    d_j(X):=J_{T}(X)_{jj}
            =f_{\,j\mid 1:(j-1)}\!\left(X_j\mid X_{1:(j-1)}\right),
    \quad
    b_{jk}(X):=J_{T}(X)_{jk}
               =\partial_{x_k}F_{\,j\mid 1:(j-1)}
                 \!\left(X_j\mid X_{1:(j-1)}\right)
               ,\quad k<j.
    \]    
    Because $J_{T}(X)$ is unit–triangular up to the positive diagonal $\{d_j\}$, its inverse $J_{S}(Z)=J_{T}^{-1}(X)=\left[\gamma_{jk}(X)\right]_{j,k\le d}$ is also lower–triangular.


    Set
    \[
       W:=X_{1:(l-1)},\qquad
       V:=X_l,\qquad
       U:=X_{(l+1):d},
    \]
    so that $X=(W,V,U)$ and the factorisation of $\PP$ reads $f_{X} = f_W  f_{V\mid W} f_{U\mid W,V}$.    
    Because $S_j$ depends only on $X_{1:j}$, $H_{jl}$ may be viewed as a measurable functional of $(W,V,U_{1:(j-l)})$; its exact algebraic form, is multiplicatively proportional to $d_{l}(X)^{-2}$:
    \begin{equation}\label{eq:H-factorisation}
          H_{jl}(X)=\gamma_{jl}(X)^{2}=R_{jl}(X)d_l(X)^{-2},
          \qquad R_{jl}(X)=\left\{d_l(X)\,\gamma_{jl}(X)\right\}^{2}.
    \end{equation}
    Alternatively, because the inverse–Jacobian entries satisfy
    \[
        \gamma_{ll}(X)=\frac{1}{d_l(X)},\qquad
        \gamma_{jl}(X)=-\frac{1}{d_j(X)}
                   \sum_{k=l}^{j-1}b_{jk}(X)\,\gamma_{kl}(X),
    \]
    the weight $R_{jl}$ can be computed recursively:
    \[
       R_{ll}(X)=1,\qquad
       R_{jl}(X)=
          \left[
            -\sum_{k=l}^{j-1}
               \frac{b_{jk}(X)}{d_j(X)}
               \sqrt{R_{kl}(X)}
          \right]^{2},\qquad l<j.
    \]
    The factor $R_{jl}$ depends on lower–order conditional CDFs only through the values of $(W, V, U)$ and therefore behaves as a fixed, bounded weight in the influence–function calculation.


    \noindent\textbf{Pathwise differentiability.}
    Let $\{\PP_t:|t|<\varepsilon\}$ be a regular sub–model with score
    $\dot\ell(X)$.
    Write  
    $f_{V\mid W,t}$ for the conditional density of $V$ given $W$ under
    $\PP_t$ and set $\dot f_{V\mid W}:=\partial_t f_{V\mid W,t}|_{t=0}$.
    A simple differentiation gives
    \[
       \dot f_{V\mid W}(v\mid w)
            = f_{V\mid W}(v\mid w)
              \left\{\dot\ell(w,v,U)-\EE[\dot\ell(X)\mid W=w]\right\}.
    \]
    Hence, differentiating  
    $\theta_{jl}(t):=\EE_{\PP_t}[H_{jl}(X)]$ and using
    \eqref{eq:H-factorisation},
    \[
       \dot\theta_{jl}
         =\EE\!\left[
             \dot H_{jl}(X)
             \;+\;
             H_{jl}(X)\,\dot\ell(X)
           \right]
         =\EE\!\left[
             \left\{-2H_{jl}(X)\,\eta(X)+H_{jl}(X)-\theta_{jl}\right\}
             \dot\ell(X)
           \right],
    \]
    where
    $\eta(X):=\dot\ell(X)-\EE\!\left[\dot\ell(X)\mid W\right]=\dot\ell(X)-\EE[\dot\ell(X)\mid X_{1:(l-1)}]$.
    Now note the well–known representation  
    \(
        \eta(X)
          =\dfrac{\partial}{\partial v}
           \left\{\ind\{V\le v\}
                  -F_{V\mid W}(v\mid W)
           \right\}\Big|_{v=V};
    \)
    integrating once in $v$ yields  
    \(
        \eta(X)
          = f_{V\mid W}(V\mid W)\,
            \left\{\ind\{V\le x_l\}
                  -F_{V\mid W}(x_l\mid W)
            \right\},
    \)
    so that  
    $-2H_{jl}(X)\eta(X)=
     -2H_{jl}(X)\{\ind\{X_l\le x_l\}-F_{l\mid1:(l-1)}(x_l\mid x_{1:(l-1)})\}$.
    Substituting back proves that \eqref{eq:eif-mixed} is a centered influence function.

    %------------------------------------------------------------

    \noindent\textbf{Efficiency.}
    Because $\varphi_{jl}$ lies in the tangent space and reproduces the pathwise derivative for every sub–model, it is the unique canonical gradient.
    Square integrability follows from $\EE[R_{jl}(X)]<\infty$ and $\EE[f_{V\mid W}^{-4}(V\mid W)]<\infty$ (which holds whenever the joint density is locally bounded and strictly positive on compact sets).
\end{proof}


Some comments on \Cref{lem:KR-map} follow.

Firstly, the proof of \Cref{lem:KR-map} hinges only on the multiplicative decomposition \eqref{eq:H-factorisation}; it does not require an explicit closed form for $R_{jl}$. 
Hence, the lemma extends to any smooth functional of the K–R map whose density–dependence enters solely through
$f_{l\mid1:(l-1)}^{-2}$.

Secondly, the EIF is identically zero for $l>j$, reflecting the fact that the triangular Rosenblatt inverse does not respond to perturbations in later coordinates when reconstructing an earlier component.






