\begin{lemma}[$L_2$ boundedness]\label{lem:L2-boundedness}
Let $(Y, Z)$ be a pair of random variables with $Z = (Z_1, \dots, Z_d)$ and $Z_{-j}$ denoting all components except $Z_j$. Define the conditional expectations
\[
\eta(Z) := \EE[Y \mid Z], \qquad \eta_{-j}(Z_{-j}) := \EE[Y \mid Z_{-j}].
\]
If $\EE[Y^2] \leq C$, then it holds that 
\begin{enumerate}[(1)]
    \item $\EE[\eta_{-j}(Z_{-j})^2] \leq \EE[\eta(Z)^2] \leq C$;
    \item $\EE[(Y - \eta(Z))^2] \leq C $ and $ \EE[(\eta(Z) - \eta_{-j}(Z_{-j}))^2] \leq C$.
\end{enumerate}
\end{lemma}
\begin{proof}[Proof of \Cref{lem:L2-boundedness}]
    For (1), by Jensen's inequality,
    \[
    \EE[\eta(Z)^2] \leq \EE[Y^2] < \infty, \quad \EE[\eta_{-j}(Z_{-j})^2] \leq \EE[Y^2] \leq C.
    \]

    For (2), by the law of total variance,
    \[
    \VV(Y) = \EE[\VV(Y \mid Z)] + \VV(\EE[Y \mid Z]).
    \]
    Since $\EE[Y^2] < \infty$, both terms on the right-hand side are finite. In particular,
    \[
    \EE[(Y - \eta(Z))^2] = \EE[\VV(Y \mid Z)] \leq \VV[Y]\leq \EE[Y^2] \leq C.
    \]

    Next, define the function $\delta(Z) := \eta(Z) - \eta_{-j}(Z_{-j})$. Then,
    \[
    \EE[\delta(Z)^2] = \EE[(\eta(Z) - \eta_{-j}(Z_{-j}))^2] \leq 2\left( \EE[\eta(Z)^2] + \EE[\eta_{-j}(Z_{-j})^2] \right).
    \]
    From (1), we have
    \[
    \EE[(\eta(Z) - \eta_{-j}(Z_{-j}))^2] \leq \EE[\eta(Z)^2] \leq C.
    \]
    This completes the proof.
\end{proof}




