\begin{proposition}[High–probability Lipschitz bound for the regression estimator]\label{prop:Lip-bound}
    Under \Crefrange{asm:abs-continuity}{asm:data}, assume that the estimator $\hat\mu$ satisfies the mean--squared error
    \(\displaystyle
      \varepsilon
      :=\|\hat\mu-\mu\|_{L_{2}(\PP_X)}\in(0,1/\sqrt{2}).
    \)    
    Define the data–dependent radius
    \begin{align}
        R_\varepsilon
        :=\lambda\,
          \sqrt{\,d+2\log(1/\varepsilon)},\label{eq:Reps}
    \end{align}
    and the ball
    \[B:=\{x\in\RR^{d}:\|x\|\le R_\varepsilon\}.\]
    Then there exists a universal constant $C=4\sqrt2$, such that
    \[
        \PP_{Z}(
            \Lip(\hat\mu; B)
            \;\le\;
            L_\mu
            +
            C\,
            L_\mu^{1/2}\,
            \lambda^{-1/2}\,
            [\,d+2\log(1/\varepsilon)\,]^{-1/4}\,
            \varepsilon^{1/2}
        )
        \;\ge\;
        1-\varepsilon^{2}.
    \]
\end{proposition}
\begin{proof}[Proof of \Cref{prop:Lip-bound}]
    Throughout the proof, we rely on two arguments, {truncation} and a {covering–number} bound.
    We split the proof into multiple steps.

    \noindent\textbf{Step~1:  Truncation of the input domain.}

    For $Z\sim\cN(0,I_{d})$ the standard tail bound
    \(\PP(\|Z\|>t)\le\exp(-t^{2}/2)\) implies
    \[
        \PP(\|Z\|>R_\varepsilon/\lambda)
        \;\le\;
        \exp(-\tfrac12[d+2\log(1/\varepsilon)])
        \;=\;
        \varepsilon^{2}.
    \]
    Because $X=T^{-1}(Z)$ and $T^{-1}$ is $\lambda$–Lipschitz,
    \(\|X\|\le\lambda\|Z\|\); hence, with probability at least
    \(1-\varepsilon^{2}\), $X\in B$.

    \noindent\textbf{Step~2: A finite $h$–net of the truncated ball.}
    Conditioned on event $X\in B$, and fix a mesh size \(h>0\).  The ball \(B\) admits an $h$–net
    \(\cN_{h}=\{x_{1},\dots,x_{N_{h}}\}\) of cardinality
    \(N_{h}\le(1+2R_\varepsilon/h)^{d}\).
    Write \(\Delta_\mu:=\hat\mu-\mu\).
    By Cauchy–Schwarz,
    \begin{align}
        \max_{x_{i}\in\cN_{h}}
              |\Delta_\mu(x_{i})|
        \;\le\;
        \frac{\|\Delta_\mu\|_{L_{2}(\PP_X)}}
             {\sqrt{\PP_X(B)}}
        \;\le\;
        \frac{\varepsilon}{\sqrt{1-\varepsilon^{2}}}
        \;\le\;
        2\varepsilon . \label{eq:Delta-mu-cover}
    \end{align}


    \noindent\textbf{Step 3: Lipschitz bound on the ball \(B\).}
    For arbitrary \(x,y\in B\) choose \(x_{i},x_{j}\in\cN_{h}\) with
    \(\|x-x_{i}\|\le h\) and \(\|y-x_{j}\|\le h\).
    Insert and remove \(\mu\):
    \begin{align*}
        |\hat\mu(x)-\hat\mu(y)|
        &\le
        |\hat\mu(x)-\hat\mu(x_{i})|
        +|\hat\mu(x_{i})-\hat\mu(x_{j})|
        +|\hat\mu(x_{j})-\hat\mu(y)|                                                  \\
        &\le
        L_\mu(\|x-x_{i}\|+\|x_{j}-y\|)
        +|\Delta_\mu(x_{i})|
        +|\Delta_\mu(x_{j})|                                                           \\
        &\le
        L_\mu(\|x-y\|+2h)+4\varepsilon,
    \end{align*}
    where the second line uses the $L_\mu$–Lipschitzness of $\mu$ and the third invokes \eqref{eq:Delta-mu-cover}.  Dividing by $\|x-y\|$ and taking the supremum over \(x,y\in B\) yields
    \begin{align}
        \Lip(\hat\mu;B)
        \;\le\;
        L_\mu
        +2L_\mu h/R_\varepsilon
        +4\varepsilon/h. \label{eq:lip-hat-mu}
    \end{align}


    \noindent\textbf{Step 4: Optimizing the mesh size.}
    Minimizing the right‐hand side of \eqref{eq:lip-hat-mu} over \(h>0\) gives the
    choice
    \[
        h^{*}=\sqrt{\frac{2\varepsilon R_\varepsilon}{L_\mu}}.
    \]
    Substituting it into \eqref{eq:lip-hat-mu} yields that
    \begin{align}
        \Lip(\hat\mu;B)
        &\le
        L_\mu
        +
        4\sqrt{2}\sqrt{\frac{L_\mu\varepsilon}{R_\varepsilon}}
          \nonumber\\
        &=
        L_\mu
        +
        C\,
        L_\mu^{1/2}\,
        \lambda^{-1/2}\,
        [\,d+2\log(1/\varepsilon)\,]^{-1/4}\,
        \varepsilon^{1/2},
        \label{eq:B-bound}
    \end{align}
    where the last equality is from the definition of $R_{\varepsilon}$ in \eqref{eq:Reps} and $C=4\sqrt{2}$.
    This finishes the proof.
\end{proof}



\subsection{Basic properties of transport maps}\label{app:sub:basic-transport}


\begin{lemma}[Bi-Lipschitz $\boldsymbol{\Longrightarrow}$ Bijective]\label{lem:bilipshitz-bijective}
    Let $T:\mathbb{R}^{d}\to\mathbb{R}^{d}$ satisfy the \emph{global bi-Lipschitz} bounds
    \[
        c\,\|x-y\|
        \;\le\;
        \|T(x)-T(y)\|
        \;\le\;
        C\,\|x-y\|,
        \qquad\forall x,y\in\mathbb{R}^{d},
    \]
    for some constants $0<c\le C<\infty$.
    Then $T$ is a bijection and a bi-Lipschitz homeomorphism of $\mathbb{R}^{d}$ onto itself.    
\end{lemma}
\begin{proof}[Proof of \Cref{lem:bilipshitz-bijective}]

We split the proof into two steps.

\noindent\textbf{Step 1: Bijection.}
We verify the properties of $T$ one by one:
\begin{enumerate}[(a)]
    \item \emph{Injectivity.}  If $T(x)=T(y)$ then $c\|x-y\|\le0$, so $x=y$. Hence, $T$ is injective

    \item \emph{Properness.}  From the lower bound,
          $\|T(x)\|\ge c\|x\|-\|T(0)\|$, hence $\|x\|\to\infty\implies\|T(x)\|\to\infty$.
          Thus inverse images of bounded sets are bounded (and closed by continuity), hence compact.
    \item \emph{Openness.}  For any ball $B(x,r)$ one has
          $B(T(x),cr)\subset T(B(x,r))\subset B(T(x),Cr)$,
          so $T$ maps open sets to open sets.
    \item \emph{Surjectivity.}  The image $T(\mathbb{R}^{d})$ is non-empty, open (3) and closed
          (properness $\,+$\, continuity).  Since $\mathbb{R}^{d}$ is connected,
          the only such subset is $\mathbb{R}^{d}$ itself.
    \end{enumerate}
    Consequently, $T$ is a bijection.

    \noindent\textbf{Step 2: Lipshitzness of inverse mapping.}
    For any two points \(u,v\in\mathbb R^{d}\) and set  
    \(x:=T^{-1}(u),\;y:=T^{-1}(v)\).
    This gives
    \[
            c\|x-y\|
            \;\le\;
            \|T(x)-T(y)\|
            \;=\;
            \|u-v\|.
    \]
    Rearranging yields
    \[
            \|T^{-1}(u)-T^{-1}(v)\|
            \;=\;
            \|x-y\|
            \;\le\;
            \frac1c\,\|u-v\|,
            \qquad\forall u,v\in\mathbb R^{d}.
    \]
    Hence \(T^{-1}\) is globally Lipschitz with 
    \[
        \Lip(T^{-1})\;\le\;1/c.
    \]
    Consequently, $T$ is a bijection and a bi-Lipschitz homeomorphism of $\mathbb{R}^{d}$ onto itself.
\end{proof}



\begin{lemma}[Bi-Lipschitz gradient $\Longleftrightarrow$ uniform Hessian bounds]\label{lem:bilipshitz-potential}
    Let $\Phi:\mathbb{R}^d\to\mathbb{R}$ be a $C^{2}$, convex function and set $T=\nabla\Phi$.
    The following are equivalent:
    \begin{enumerate}[(a)]
    \item {Uniform Hessian bounds:}  
          There exist constants $0<m\le M<\infty$ such that, for all $x\in\mathbb{R}^d$,
          \begin{align}
              m\,I_d \;\preceq\; \nabla^2\Phi(x) \;\preceq\; M\,I_d .\label{eq:hessian}
          \end{align}
    \item {Global bi-Lipschitz gradient:}  
          There exist constants $0<m\le M<\infty$ such that, for all $x,y\in\mathbb{R}^d$,
          \begin{align}
              m\|x-y\|
              \;\le\;
              \|\nabla\Phi(x)-\nabla\Phi(y)\|
              \;\le\;
              M\|x-y\|.  \label{eq:bi-lipshitz}
          \end{align}
    \end{enumerate}
    % Under either (and hence both) conditions, if $T$ is a bijection, then its inverse satisfies $\Lip(T^{-1})\le 1/m$.
\end{lemma}
\begin{proof}[Proof of \Cref{lem:bilipshitz-potential}]
    We split the proof into different steps.

    \noindent\textbf{Step 1: (a) $\Rightarrow$ (b).}
    For $x,y\in\mathbb{R}^d$ define $\gamma(t)=y+t(x-y)$, $t\in[0,1]$.  
    By the fundamental theorem of calculus,
    \[
      \nabla\Phi(x)-\nabla\Phi(y)
      \;=\;
      \int_{0}^{1} \nabla^2\Phi(\gamma(t))\,(x-y)\,dt .
    \]
    Applying the bounds \eqref{eq:hessian} inside the integral gives
    \[
      m\|x-y\|
      \;\le\;
      \|\nabla\Phi(x)-\nabla\Phi(y)\|
      \;\le\;
      M\|x-y\|,
    \]
    establishing \eqref{eq:bi-lipshitz}.


    \noindent\textbf{Step 2: (b) $\Rightarrow$ (a).}
    Fix $x\in\mathbb{R}^d$ and a unit vector $v$.  
    For $t>0$ let $y=x+tv$.  Using \eqref{eq:bi-lipshitz},
    \[
      m t
      \;\le\;
      \|\nabla\Phi(x+tv)-\nabla\Phi(x)\|
      \;\le\;
      M t .
    \]
    Divide by $t$ and send $t\downarrow0$ to obtain
    \(
      m\;\le\;\|\nabla^2\Phi(x)v\|\;\le\;M.
    \)
    Since $v$ is arbitrary, this yields \eqref{eq:hessian}.
\end{proof}







