\subsection{LOCO estimation}\label{app:sub:loco}

\begin{lemma}[Estimated influence function for LOCO]\label{lem:decomp-varphi-diff}
    Assume that $\hat{\eta}$ and $\eta$ are bounded in $L_{\infty}$ with probability tending to one.
    Under \Cref{asm:data}, the influence function estimation error for the LOCO estimator \eqref{eq:phi-hat-loco} satisfies that
    \begin{align*}
         \|\varphi_{Z_j}(O;\hat{\PP})-\varphi_{Z_j}(O;\PP) \|_{L_2}
        &\;=\;
      \Op(\|\hat\eta-\eta\|_{L_2}
                 +\|\hat\eta_{-j}-\eta_{-j}\|_{L_2}
        + \|\hat\eta-\eta\|_{L_2}^2+\|\hat\eta_{-j}-\eta_{-j}\|_{L_2}^2),
    \end{align*}    
\end{lemma}
\begin{proof}[Proof of \Cref{lem:decomp-varphi-diff}]
    For the proof below, we drop the subscript $Z_j$ and the dependency in $(Z,Z_{-j})$ for simplicity.
    Recall the efficient influence function
    \[
    \varphi(O;\PP)
    =\;2\,(Y-\eta)(\eta-\eta_{-j})
      +(\eta-\eta_{-j})^2-\phi,
    \qquad
    \eta:=\EE[Y\mid Z],\;
    \eta_{-j}:=\EE[Y\mid Z_{-j}].
    \]
    For the estimated distribution \(\hat{\PP}\) we plug in
    \(\hat\eta,\hat\eta_{-j}\):
    \[
    \varphi(O;\hat{\PP})
    =\;2\,(Y-\hat\eta)(\hat\eta-\hat\eta_{-j})
      +(\hat\eta-\hat\eta_{-j})^2-\hat{\phi}_{Z_j}.
    \]
    Denote $\delta:=\hat\eta-\eta$, $\delta_{-j}:=\hat\eta_{-j}-\eta_{-j}$ and $V:=\delta-\delta_{-j}$.
    Observe
    \(\hat\eta-\hat\eta_{-j}=(\eta-\eta_{-j})+V\).
    Then, we have
    \[
    \varphi(O;\hat{\PP})-\varphi(O;\PP)
    =2[(Y-\hat\eta)(\hat\eta-\hat\eta_{-j})
            -(Y-\eta)(\eta-\eta_{-j}) ]
     +[(\hat\eta-\hat\eta_{-j})^2-(\eta-\eta_{-j})^2 ] + (\phi -\hat{\phi}).
    \]
    Insert
    \(Y-\hat\eta=(Y-\eta)-\delta\)
    and
    \(\hat\eta-\hat\eta_{-j}=(\eta-\eta_{-j})+V\), it follows that
    \[
    \varphi(O;\hat{\PP})-\varphi(O;\PP)
       = 2\,(Y-\eta)\,V
         -2\delta(\eta-\eta_{-j})
         -2\delta V
         +2(\eta-\eta_{-j})V
         +V^{2} + (\phi -\hat{\phi}).
    \]
    Because
    \((\eta-\eta_{-j})V-\delta(\eta-\eta_{-j})
       =-(\eta-\eta_{-j})\delta_{-j}\), we further have
    \[
    \varphi(O;\hat{\PP})-\varphi(O;\PP)
      = 2\,(Y-\eta)\,V
        \;-\;2(\eta-\eta_{-j})\,\delta_{-j}
        \;-\;2\delta V
        \;+\;V^{2}+ (\phi -\hat{\phi}).
    \]

    Under the boundedness assumption $\EE[Y^2] \leq C$ with \Cref{lem:L2-boundedness} and using Cauchy–Schwarz:
    \begin{align*}
        \|\varphi(O;\hat{\PP})-\varphi(O;\PP) \|_{L_2}
      &\leq
      2\|Y-\eta\|_{L_2}\|V\|_{L_2}
      \;+\;
      2\|\eta-\eta_{-j}\|_{L_2}\|\delta_{-j}\|_{L_2} +
     2 \|\delta\|_{L_2}\|V\|_{L_2}
      \;+\; \|V\|_{L_2}^2 + \|\phi -\hat{\phi}\|_{L_2}
      \\
      &\leq 4C\|V\|_{L_2} + 2C\|\delta_{-j}\|_{L_2} + \|V\|_{L_2}^2 + (\phi -\hat{\phi}).
    \end{align*}
    Because $\hat{\phi}$ is uniformly bounded in probability and $\hat{\phi}-\phi = \op(1)$, by dominate convergence theorem, we have that $\|\phi -\hat{\phi}\|_{L_2} =\op(1)$.
    Since \(\|V\|_{L_2}\le\|\delta\|_{L_2}+\|\delta_{-j}\|_{L_2}\), the right–hand side is
    \[
        \Op(\|\hat\eta-\eta\|_{L_2}
                 +\|\hat\eta_{-j}-\eta_{-j}\|_{L_2}
        + \|\hat\eta-\eta\|_{L_2}^2+\|\hat\eta_{-j}-\eta_{-j}\|_{L_2}^2),
    \]
    which completes the proof.
\end{proof}




\begin{lemma}[$L_2$‐bound for LOO estimator]\label{lem:eta-j}
    Let $\hat{\eta}$ be an estimator of $\eta$, estimated from independent samples.
    Suppose $Z_j\indep Z_{-j}$ and define the leave‐$j$‐out estimator
    \[
    \hat\eta_{-j}(z_{-j})
    \;=\;
    \EE[\hat\eta(Z)\mid \hat{\eta}, Z_{-j}=z_{-j}] = \EE[\hat\eta(Z^{(j)})\mid \hat{\eta},Z_{-j}=z_{-j}],
    \]
    for $\eta_{-j}(z_{-j})=\EE[\eta(Z)\mid Z_j=z_j]$.  
    Then
    \[
    \|\hat\eta_{-j}(Z_{-j})-\eta_{-j}(Z_{-j}) \|_{L_2(P_{Z_{-j}})}
    \;\le\;
    \|\hat\eta(Z)-\eta(Z) \|_{L_2(\PP_Z)}.
    \]
\end{lemma}
\begin{proof}[Proof of \Cref{lem:eta-j}]
    Since $Z_j\indep Z_{-j}$, the joint law of $(Z_{-j},Z_j)$ (the same holds for $(Z_{-j},Z_j^{(j)})$ ) factors and by Jensen's inequality
    \[
    \begin{aligned}
        \EE_{Z_{-j}}[(\hat\eta_{-j}(Z_{-j})-\eta_{-j}(Z_{-j}))^2 ]
        &=\EE_{Z_{-j}}[(\int[\hat\eta(Z_{-j},z_j)-\eta(Z_{-j},z_j) ]\,dF_{Z_j}(z_j))^{2} ]\\
        &\le 
        \EE_{Z_{-j}}[\int[\hat\eta(Z_{-j},z_j)-\eta(Z_{-j},z_j) ]^{2}\,dF_{Z_j}(z_j) ]\\
        &=
        \EE_{Z}[(\hat\eta(Z)-\eta(Z))^{2} ].
        \end{aligned}
    \]
    Taking square roots yields the result.
\end{proof}





