% \subsection{EIF of product}
\begin{lemma}[EIF of the expected product]\label{lem:EIF-product}
    Let the data be \(O\sim P \) and suppose that the (possibly distribution–dependent) functions \(A\) and \(B\) satisfy
    \[
    \psi_A( P ) \;=\; \EE_{ P }[A(O) ], 
    \qquad
    \psi_B( P ) \;=\; \EE_{ P }[B(O) ].
    \]
    Denote by \(\varphi_A(O; P )\) and \(\varphi_B(O; P )\) their efficient
    influence functions (EIFs), normalised so that
    \[
    \EE_{ P } [\varphi_A(O; P ) ]=
    \EE_{ P } [\varphi_B(O; P ) ]=0.
    \]
    Define the centered functions
    \(A_c(O)=A(O)-\psi_A( P )\) and \(B_c(O)=B(O)-\psi_B( P )\),
    and the remainder term
    \[
        \alpha_A(O) := \varphi_A(O; P ) - A_c(O) , 
        \qquad 
        \alpha_B(O) := \varphi_B(O; P ) - B_c(O) ,
    \]
    where the remainder terms \(\alpha_A,\alpha_B\) collect the pathwise‐derivative contributions coming from the dependence of \(A\) and \(B\) on \( P \).
    Then, the EIF of $\psi_{AB}( P ):=\EE_{ P }[A(O)B(O)]$ is given by:
    \begin{align}
        \varphi_{AB}(O; P )
      = A(O)B(O)-\psi_{AB}( P )
        +B(O)\alpha_A(O)
        +A(O)\alpha_B(O). \label{eq:EIF-prod}
    \end{align}
\end{lemma}
\begin{proof}[Proof of \Cref{lem:EIF-product}]

    Let \( P _\varepsilon=(1+\varepsilon h) P \) be a regular, mean‑zero submodel with score \(h\).
    Differentiating \(\psi_{AB}( P _\varepsilon)=\int A_{ P _\varepsilon}B_{ P _\varepsilon}\,d P _\varepsilon\) at \(\varepsilon=0\) gives
    \begin{align}
        \frac{\rd}{\rd\varepsilon}\psi_{AB}( P _\varepsilon)\Big|_{\varepsilon=0}
        = \EE_{ P } [h(O)\,A(O)B(O) ]
      + \EE_{ P } [B(O)\,\dot{A}_h(O) ]
      + \EE_{ P } [A(O)\,\dot{B}_h(O) ], \label{eq:EIF-prod-1}
    \end{align}
    where \(\dot{A}_h,\dot{B}_h\) are the pathwise derivatives of
    \(A_{ P _\varepsilon}(O)\) and \(B_{ P _\varepsilon}(O)\) along \(h\).


    The defining property of \(\varphi_A\) and \(\varphi_B\) is
    \begin{align}
        \EE_{ P } [h(O)\,\varphi_A(O; P ) ]
      \;=\;
      \EE_{ P } [h(O)\,A(O) ] 
      + \EE_{ P } [\dot{A}_h(O) ], \label{eq:EIF-prod-2}
    \end{align}
    and similarly for $B$.
    This implies
    \begin{align}
        \EE_{ P } [\dot{A}_h(O) ] 
      \;=\;
      \EE_{ P } [h(O)\,\alpha_A(O) ],
    \qquad
    \EE_{ P } [\dot{B}_h(O) ] 
      \;=\;
      \EE_{ P } [h(O)\,\alpha_B(O) ].    \label{eq:EIF-prod-3} 
    \end{align}


    Define
    \begin{align}
        \varphi_{AB}(O; P )
        \;:=\;
        A(O)B(O) - \psi_{AB}( P )
        \;+\;
        B(O)\,\alpha_A(O)
        \;+\;
        A(O)\,\alpha_B(O).\label{eq:EIF-prod-4}
    \end{align}
    We verify that \eqref{eq:EIF-prod-4} satisfies the EIF equation.  Using \eqref{eq:EIF-prod-1}-\eqref{eq:EIF-prod-3}, we have
    \[
    \EE_{ P } [h(O)\,\varphi_{AB}(O; P ) ]
    \;=\;
    \frac{\rd}{\rd\varepsilon}\psi_{AB}( P _\varepsilon)\Big|_{\varepsilon=0},
    \]
    and \(\EE_{ P }[\varphi_{AB}]=0\) by construction, so \eqref{eq:EIF-prod-4} is indeed the
    efficient influence function of \(\psi_{AB}\).
    This completes the proof.
\end{proof}



\begin{remark}[Special cases of \Cref{lem:EIF-product}]
     When \(A\) is distribution‑dependent, one has \(\alpha_A=0\) and \eqref{eq:EIF-prod} becomes \(\varphi_{AB}=A\,\varphi_B\).     
     When neither \(A\) nor \(B\) depends on \( P \),  one has \(\alpha_A=\alpha_B=0\), \(\varphi_A=A_c\), \(\varphi_B=B_c\), and \eqref{eq:EIF-prod} reduces to \(\varphi_{AB}=A B-\EE[AB]\).
     This can also happen if \(A\) and \(B\) are linear functions.
     For instance, for the covariance parameter $\psi_{AB}( P ) = \EE_{ P }[(A-\EE_{ P }[A])(B-\EE_{ P }[B])]$, one has $X(O) = X $ and $\varphi_X(O; P ) = X_c(O) = X - \EE_{ P }[X]$ for $X\in\{A,B\}$.
      Hence, \(\alpha_A=\alpha_B=0\) and the last two terms in \eqref{eq:EIF-prod} vanish and \eqref{eq:EIF-prod} reduces to $\varphi_{AB}(O; P ) = (A-\EE_{ P }[A])(B-\EE_{ P }[B]) - \psi_{AB}( P )$.
\end{remark}










