\begin{proposition}[EIF of $\theta(\PP)$ under Bures-Wasserstein transport]\label{prop:EIF-H}
    Let the observable $O=X\in\RR^{d}$ satisfy
    \[
      \PP[X]=0,
      \qquad
      \Sigma=\PP[XX^{\top}]\;\succ\;0,
      \qquad
      L:=\Sigma^{-1/2}.
    \]
    For fixed indices $j,l\in[d]$ define
    \[
      T(x):=L x,
      \qquad
      H_{jl}(X):=\partial_{x_l}T_j(X)=L_{jl}.
    \]
    The efficient influence function of the parameter
    \[
      \theta_{jl}(\PP):=\PP [H_{jl}(X)^2 ]
                     =L_{jl}^{2},
    \]
    is given by
    \[
        \varphi_{jl}(O;\PP)
          = -\;L_{jl} (X^{\top}L e_{j}e_{l}^{\top}L X-\delta_{jl}) = -L_{jl} (Z_jZ_l - \delta_{jl}).
    \]
\end{proposition}
\begin{proof}[Proof of \Cref{prop:EIF-H}]
    Take an arbitrary regular one‑dimensional sub‑model $\{\PP_\varepsilon:\varepsilon\in(-\varepsilon_0,\varepsilon_0)\}$ embedded in the non‑parametric model such that $\PP_{\varepsilon=0}=\PP$ and with score $s_\varepsilon(O)=\partial_\varepsilon\log p_\varepsilon(O) |_{\varepsilon=0}$.
    The usual regularity conditions give $\PP[s(O)]=0$ and $\PP[Xs(O)]=0$ (the latter enforces the constraint $\EE[X]=0$ along the path).

    Write $\Sigma(\varepsilon):=\EE_{\PP_\varepsilon}[XX^{\top}]$.
    Differentiating at $\varepsilon=0$,
    \[
      \partial_\varepsilon\Sigma(\varepsilon) |_{\varepsilon=0}
         =\PP [
             XX^{\top}\,s(O)
            ]
         \;=\;\PP [
             \{XX^{\top}-\Sigma\}\,s(O)
            ],
    \]
    because $\PP[s(O)]=0$. 
    Hence, the influence function for~$\Sigma$ is
    \[
      U_\Sigma(O)\;:=\;XX^{\top}-\Sigma,
      \qquad
      \PP[U_\Sigma(O)]=0.
    \]


    Treat $\theta_{jl}$ as the composition $\theta_{jl}=h\circ\Sigma$ with $h(M)=(M^{-1/2})_{jl}^{2}$.  
    A matrix calculus identity gives the Fréchet derivative of $M\mapsto M^{-1/2}$:
    \[
      \rd L
        \;=\;
        \rd(\Sigma^{-\frac{1}{2}})
        \;=\;
        -\tfrac12\,L\,(\rd \Sigma)\,L.
    \]
    Because
    $\langle A,B\rangle_{F}:=\tr(A^{\top}B)$, we can rewrite the last term
    as an inner product:
    \[
      \rd\theta_{jl}
        \;=\;
         \langle
           \nabla_{\Sigma}\theta_{jl}(\Sigma),\;
           \rd\Sigma
          \rangle_{F},
      \quad
      \nabla_{\Sigma}\theta_{jl}(\Sigma)
         =-\frac{L_{jl}}{2}\,
           (L e_{j}e_{l}^{\top}L
                 +L e_{l}e_{j}^{\top}L).
    \]

    Insert $\rd\Sigma=
      \partial_\varepsilon\Sigma(\varepsilon)|_{\varepsilon=0}
     =\PP[U_\Sigma(O)\,s(O)]$ from Step 1:
    \[
      \partial_\varepsilon\theta_{jl}(\PP_\varepsilon)\Big|_{\varepsilon=0}
      \;=\;
       \langle\nabla_{\Sigma}\theta_{jl},\,
                \PP[U_\Sigma(O)\,s(O)] \rangle_{F}
      \;=\;
      \PP
         [
          \langle\nabla_{\Sigma}\theta_{jl},U_\Sigma(O)\rangle_{F}\;s(O)
         ].
    \]
    Therefore, the efficient influence function $\varphi_{jl}$ in the tangent space satisfies that $\partial_\varepsilon\theta_{jl}(\PP_\varepsilon)|_{\varepsilon=0} =\PP[\varphi_{jl}(O)\,s(O)]$ for every score $s$ is
    \[
        \varphi_{jl}(O;\PP)
          = \langle\nabla_{\Sigma}\theta_{jl}(\Sigma),
                     U_\Sigma(O) \rangle_{F}
          =-\;L_{jl} \{
              X^{\top}L e_{j}e_{l}^{\top}L X-\delta_{jl}
             \}.
    \]
    Centring holds automatically because
    $\PP[X^{\top}L e_{j}e_{l}^{\top}L X]=\delta_{jl}$, so
    $\PP[\varphi_{jl}(O;\PP)]=0$.
\end{proof}





\begin{lemma}[Estimated influence function for $\phi_{X_l}$]\label{lem:err-varphi-X}
    Under the assumptions of \Cref{thm:err-phi-X}, let
  \[
     \varphi_{X_{l}}(O;\PP)
       \;=\;
       \sum_{j=1}^{d}
    		\left\{
                L_{jl}^2\,
    		 [
    			2\,(Y-\eta(Z))\,\Delta_j(Z) + \Delta_j(Z)^{2}
    		 ]
                - 
                L_{jl} (Z_jZ_l - \delta_{jl}) \Delta(Z)^2 \right\}
    		-\;
       \phi_{X_{l}}(\PP),
  \]
  and let $\varphi_{X_l}(O;\hat \PP)$ be the same expression with
  $(\eta, L)$ replaced by $(\hat\eta,\hat L)$ and $\eta_{-j}$ replaced with $\hat\eta_{-j} = \EE_{Z_j}[\hat{\eta}(Z)\mid Z_{-j}]$.
  Then
  \[
      \|\varphi_{X_l}(O;\hat \PP)-\varphi_{X_l}(O;\PP) \|_{L_2}
       \;=\;\Op(\varepsilon_n),
     \qquad
     \PP \{\varphi_{X_l}(O;\hat \PP)-\varphi_{X_l}(O;\PP) \}
       \;=\;\Op(\varepsilon_n^{2}),
  \]
  where $\varepsilon_n = \|L_{\cdot l}\|_{2}\|\hat \mu -\mu\|_{L_2} + \tr(\Sigma)^{1/2} \|\hat{L} - L\|_{\oper}$.
\end{lemma}
\begin{proof}[Proof of \Cref{lem:err-varphi-X}]

    For simplicity, we will not explicitly indicate the dependency on \( Z \).
    For $l\in[d]$ fixed and for every $j\in[d]$, we use the following notation $\delta=\hat\eta-\eta$, $\delta_{-j}=\hat\eta_{-j}-\eta_{-j}$, $\vartheta_{j}=\delta-\delta_{-j}$, $\Delta_j = \eta - \eta_{-j}$, $\hat\Delta_j = \hat\eta - \hat\eta_{-j}$, $D_{jl}\;:=\;\hat L_{jl}^{2}\;-\;L_{jl}^{2}$, $U=Y-\eta$, $\hat U=Y-\hat\eta$.




    \noindent\textbf{Step 1: Decomposition.}
    Put
    \[
       A_{j}\;:=\;L_{jl}^{2} [\,2U\Delta_j+\Delta_j^{2} ],
       \qquad
       B_{j}\;:=\;L_{jl}\,(Z_jZ_l-\delta_{jl})\,\Delta_j^{2},
    \]
    and denote by $\hat A_{j},\hat B_{j}$ the corresponding quantities with
    $(L_{jl},\eta,\Delta_j)$ replaced by
    $(\hat L_{jl},\hat\eta,\hat\Delta_j)$.
    Then
    \begin{align}
       \varphi_{X_l}(O;\hat\PP)-\varphi_{X_l}(O;\PP)
       \;=\;
       \sum_{j=1}^{d}(E_{1,j}+E_{2,j})
             \;-\;
              [\phi_{X_l}(\hat\PP)-\phi_{X_l}(\PP) ],
       \label{eq:varphi-X-decomp}
    \end{align}
    where $E_{1,j}:=\hat A_{j}-A_{j}$ and $E_{2,j}:=-\hat B_{j}+B_{j}$.
    Using $\hat\Delta_j=\Delta_j+\vartheta_j$ and
    $U-\delta=Y-\hat\eta$ we obtain
    \begin{align}
       E_{1,j}
       &=\;
          D^{(2)}_{j} [\,2U\Delta_j+\Delta_j^{2} ]
          +\hat L_{jl}^{2} [\,2(U-\delta)\vartheta_j
          +\vartheta_j^{2}-2\delta_{-j}\Delta_j ],
       \label{eq:varphi-X-E1}\\[2pt]
       E_{2,j}
       &=\;
          -D^{(1)}_{j}\,(Z_jZ_l-\delta_{jl})\,\Delta_j^{2}
          -\hat L_{jl}(Z_jZ_l-\delta_{jl})
                [\,2\Delta_j\vartheta_j+\vartheta_j^{2} ],
       \label{eq:varphi-X-E2}
    \end{align}
    with
    \(
       D^{(2)}_{j}:=\hat L_{jl}^{2}-L_{jl}^{2},\;
       D^{(1)}_{j}:=\hat L_{jl}-L_{jl}.
    \)

    Because the plug‑in estimator of $\phi_{X_l}$ employs the empirical mean of
    $\hat\Delta_j^{2}$, 
    \begin{equation}
      \phi_{X_l}(\hat\PP)-\phi_{X_l}(\PP)
      \;=\;
      \sum_{j=1}^{d}
          \{
            D^{(2)}_{j}\,\PP[\Delta_j^{2}]
            \;+\;
            \hat L_{jl}^{2}\,\PP [\,2\Delta_j\vartheta_j+\vartheta_j^{2} ]
            \;+\;
            \hat L_{jl}^{2}\,(\PP_n-\PP) [\hat\Delta_j^{2} ]
          \}.
      \label{eq:varphi-X-phi}
    \end{equation}

    \noindent
    Substituting \eqref{eq:varphi-X-E1}–\eqref{eq:varphi-X-phi} into
    \eqref{eq:varphi-X-decomp} and collecting like terms yields
    \begin{equation}
      \varphi_{X_l}(O;\hat\PP)-\varphi_{X_l}(O;\PP)
      \;=\;
      T_{1l}+T_{2l}+T_{3l}+T_{4l}, \label{eq:varphi-X-final-split}
    \end{equation}
    where
    \begin{align*}
       T_{1l}
        &:=\sum_{j}D^{(2)}_{j} [\,2U\Delta_j+\Delta_j^{2}-\PP[\Delta_j^{2}] ],
    \\[2pt]
      T_{2l}
        &:=\sum_{j}\hat L_{jl}^{2}
             \{
              2(U-\delta)\vartheta_j
              +\vartheta_j^{2}
              -2\delta_{-j}\Delta_j
              -\PP[\,2\Delta_j\vartheta_j+\vartheta_j^{2} ]
             \},
    \\[2pt]
      T_{3l}
        &:=\sum_{j}
             [
              -D^{(1)}_{j}(Z_jZ_l-\delta_{jl})\,\Delta_j^{2}
              -\hat L_{jl}(Z_jZ_l-\delta_{jl})
                 (2\Delta_j\vartheta_j+\vartheta_j^{2})
             ],
    \\[2pt]
      T_{4l}
        &:=\,-\sum_{j}\hat L_{jl}^{2}\,(\PP_n-\PP)[\hat\Delta_j^{2}].
    \end{align*}




    \noindent\textbf{Step 2: $L_2$–norm bound.}
    We bound $\|T_{kl}\|_{L_2}$ for $k=1,\ldots, 4$, term by term.
    Define $e_{L,l}\;:= \|\hat L_{\cdot l} - L_{\cdot l}\|_{2}$, $e_{\eta} =\|\hat\eta -\eta\|_{L_2}$, and \(e_n= e_{L,l}+\|L_{\cdot l}\|_2 e_{\eta}\).


    \textit{(i) Term $T_{1l}$.}  
    Because $|D^{(2)}_{j}|\le 2C|D^{(1)}_{j}|$ and
    $ \|2U\Delta_j+\Delta_j^{2}-\PP[\Delta_j^{2}] \|_{L_2}\le 10C^{2}$,
    \[
       \|T_{1l}\|_{L_2}
          \;\le\;
          20C^{3}\sum_{j}|D^{(1)}_{j}|
          \;\le\;
          20C^{3}\,e_{L,l}
          \;=\;\Op(e_n).
    \]


    \textit{(ii) Term $T_{2l}$.}  
    Each factor in the curly braces of $T_{2l}$ contains at least one of \(\vartheta_j\) or \(\delta_{-j}\):
    \[
       \|\vartheta_j\|_{L_2}\le 2(\|\hat\eta-\eta\|_{L_2} + \|\hat\eta_{-j}-\eta_{-j}\|_{L_2}) ,\quad
       \|\delta_{-j}\|_{L_2}\le \|\hat\eta_{-j}-\eta_{-j}\|_{L_2}.
    \]
    Hence, from Cauchy-Schwartz inequality and \Cref{lem:eta-j}, it follows that
    \[
       \|T_{2l}\|_{L_2}
          \;\le\;
          \|\hat L_{\cdot l}\|_{L_2}
          (\|\hat\eta-\eta\|_{L_2}
                +\|\hat\eta_{-j}-\eta_{-j}\|_{L_2})
          \;=\;\Op(e_n),
    \]
    by noting that $\|\hat L_{\cdot l}\|_{L_2} \leq \|L_{\cdot l}\|_{2} + e_{L,l}$.

    \textit{(iii) Term $T_{3l}$.}  
    For the first piece in $T_{3l}$,
    \(
       \|(Z_jZ_l-\delta_{jl})\Delta_j^{2}\|_{L_2}\le 4C^{3},
    \)
    so
    \(
       \|D^{(1)}_{j}(\,\cdot\,)\|_{L_2}\le 4C^{3}|D^{(1)}_{j}|.
    \)
    Summation gives $\Op(e_{L,l})$.
    For the second piece, note that
    \(
      \|Z_jZ_l-\delta_{jl}\|_{L_2}\le 2C^{2}
    \)
    and
    \(
      \|2\Delta_j\vartheta_j+\vartheta_j^{2}\|_{L_2}
         \lesssim\|\hat\eta-\eta\|_{L_2}
                 +\|\hat\eta_{-j}-\eta_{-j}\|_{L_2} \leq 2 e_{\eta},
    \) from \Cref{lem:eta-j}.
    Hence, by Cauchy–Schwarz inequality, we have
    \[
       \|T_{3l}\|_{L_2}
          =\Op(e_n).
    \]


    \textit{(iv) Term $T_{4l}$.}  
    Conditional on the nuisance estimates,
    \(
       \VV \{(\PP_{n}-\PP)[\hat\Delta_j^{2}] \}
          \le \frac{16C^{4}}{n},
    \)
    so
    \(
       \|(\PP_{n}-\PP)[\hat\Delta_j^{2}]\|_{L_2}
          =\cO(n^{-1/2}).
    \)
    With $|\hat L_{jl}|\le C$,
    \(
       \|T_{4l}\|_{L_2}
          =\Op(n^{-1/2}).
    \)


    Putting the four bounds together, we have
    \[
        \|\varphi_{X_l}(O;\hat\PP)-\varphi_{X_l}(O;\PP) \|_{L_2}
          \;\le\;
          \|T_{1l}\|_{L_2}+\|T_{2l}\|_{L_2}+\|T_{3l}\|_{L_2}+\|T_{4l}\|_{L_2}
          \;=\;
          \Op(e_n+n^{-1/2}).
    \]



    \noindent\textbf{Step 3: Expectation bound.} We again bound the expectation term by term.

    \textit{(i) Term $T_{1l}$.}
    $T_{1l}$ is of the form
    \(D^{(2)}_{j}\{2U\Delta_j+\Delta_j^{2}-\EE[\Delta_j^{2}]\}\).
    Conditional on the (independent) nuisance estimates, the factor
    $D^{(2)}_{j}$ is fixed, while  
    \(\EE[\,2U\Delta_j\mid Z]=0\) and  
    \(\EE[\Delta_j^{2}]=\EE[\Delta_j^{2}]\) by definition, so the centered bracket has mean~0.  
    Thus, $\EE[T_{1l}]=0$.


    \textit{(ii) Term $T_{2l}$.}
    Each term inside the braces of $T_{2l}$ contains at least one factor
    \(\vartheta_j=\delta-\delta_{-j}\) or $\delta_{-j}$.  Because
    \(\|\delta_{-j}\|_{L_2}\le\|\delta\|_{L_2}=e_{\eta}\), Cauchy–Schwarz inequality gives
    \[
       |\EE[(U-\delta)\vartheta_j]|
            =|\EE[\delta\vartheta_j]|
            \le \|\delta\|_{L_2}\|\vartheta_j\|_{L_2}
            \;\lesssim\; e_{\eta}^2,
    \]
    and similarly
    \(|\EE[\delta_{-j}\Delta_j]|\lesssim e_{\eta}^{2}\).
    All other raw moments in the bracket are of this same order.
    Therefore, we have
    \[
       |\EE[T_{2l}]|
         \lesssim
         \|\hat L_{\cdot l}\|_{L_2}^{2}\, e_{\eta}^{2}
         =\Op(e_n^{2}).
    \]


    \textit{(iii) Term $T_{3l}$.}
    Because $\EE[Z_jZ_l-\delta_{jl}]=0$, we have
    \[
        \PP[T_{3l}]
        =-\sum_{j}\hat L_{jl}\,
            \EE [(Z_jZ_l-\delta_{jl})
                       (2\Delta_j\vartheta_j+\vartheta_j^{2}) ].
    \]
    Every summand contains at least one factor \(\vartheta_j\); by
    Cauchy–Schwarz,
    \[
        |\EE[(Z_jZ_l-\delta_{jl})
                (2\Delta_j\vartheta_j+\vartheta_j^{2})] |
       \le
       3C^{2}\|\vartheta_j\|_{L_2}\,
            \max  \{2\|\Delta_j\|_{\infty},\|\vartheta_j\|_{L_2} \}
       =\Op(e_{\eta}^{2}).
    \]
    Multiplying by $|\hat L_{jl}|\le C$ and summing gives
    \[
       |\EE[T_{3l}]|
         \lesssim
         \|\hat L_{\cdot l}\|_{L_2}\,e_{\eta}^{2}
         =\Op(e_n^{2}).
    \]


    \textit{(iv) Term $T_{4l}$.} 
    Because $\EE[(\PP_{n}-\PP)f]=0$ for any square–integrable $f$, we have $\EE[T_{4l}]=0$.


    Combining the above results yields that
    \(
      \PP\{\varphi_{X_l}(O;\hat \PP)-\varphi_{X_l}(O;\PP)\}
        =\Op(e_n^{2}).
    \)
    Finally, we will show that $e_n\lesssim \varepsilon_{n}$.
    From \eqref{eq:eta-bound}, we have that
    \begin{align*}
        \|\hat\eta - \eta\|_{L_2} &\lesssim \|\hat\mu - \mu\|_{L_2} + \|\hat T - T\|_{L_2} .
    \end{align*}


    Let \(E := \hat L-L\).  Using the cyclic property of the trace,
\[
       \|\hat T-T\|_{L_2(\PP_X)}^{2}
          = \EE[\|EX\|_2^{2}]
          = \tr(E\Sigma E^{\top})
          = \tr(E^{\top}E\,\Sigma).
    \]
    For any two positive–semidefinite matrices \(A,B\succeq0\),
    \(\tr(AB)\le \lambda_{\max}(A)\,\tr(B)\).  Applying this with
    \(A = E^{\top}E\) and \(B = \Sigma\) yields
    \[
       \|\hat T-T\|_{L_2(\PP_X)}^{2}
          \;\le\;
          \lambda_{\max}(E^{\top}E)\,\tr(\Sigma)
          = \|E\|_{\oper}^{2}\,\tr(\Sigma)
          = \tr(\Sigma)\,\|\hat L-L\|_{\oper}^{2}.
    \]
    Furthermore, the column-wise error can also be bounded by:
    \[
       \max_{l\in[d]}\|\hat L_{\cdot\,l}-L_{\cdot\,l}\|_{2}
          \;\le\;
          \|\hat L-L\|_{\oper}.
    \]
    Thus, we further have $e_n \lesssim   \|\hat{L}_{\cdot l} - L_{\cdot l}\|_{2} + \|L_{\cdot l}\|_{2}[\|\hat \mu -\mu\|_{L_2} + \tr(\Sigma)^{1/2} \|\hat{L} - L\|_{\oper}] \lesssim \varepsilon_n$, which completes the proof.
\end{proof}






\section{Simulation details}\label{app:sec:simu}
    \subsection{Practical considerations}\label{app:subsec:practical}
    In practice, the estimation of \eqref{def:hat-phi-Z} can be improved by drawing multiple samples.
    More specifically, we can define the LOCO-type and CPI-type estimators as
    \begin{align*}
        \hat{\phi}_{Z_j}^{\loco}(\PP) &= \PP_n\left[
        (Y - \PP_{Z_j^{(j)},m}\{\hat{\eta}({Z}^{(j)})\} )^2 - ( Y - \hat{\eta}({Z}) )^2 
        \right].
    \end{align*}
    or 
    \begin{align*}
        \hat{\phi}_{Z_j}^{\cpi}(\PP) &= \frac{1}{2} \PP_n \{\PP_{Z_j^{(j)},m} \left[ (Y - \hat{\eta}(Z^{(j)}))^2 - (Y - \hat{\eta}(Z))^2 \right] \} .
    \end{align*}    
    Here, \( \PP_n \) denotes the empirical average over $n$ samples of $(Z,X,Y)$ and \( \PP_{Z_j^{(j)},m} \) denotes the empirical average over $m$ samples of $Z_j^{(j)}$.
    The estimator $\hat{\phi}_{Z_j}^{\loco}(\PP)$ is exactly the LOCO estimator for \eqref{eq:phi-Z} except the submodel $\eta_{-j}(Z_{-j})$ is estimated by $\hat\eta_{-j}(Z_{-j}):=\PP_{Z_j^{(j)},m}\{\hat{\eta}({Z}^{(j)})\}$.
    For our implementation, we use $\hat{\phi}_{Z_j}^{\loco}(\PP)$ with $m=50$ by default.



    \subsection[Model M3]{Detailed calculation under Model \hyperref[M3]{(M3)}}\label{app:subsec:M3}


    We derive the theoretical DFI values for the latent features $Z$ and original features $X$ under the specified model.
    For a Gaussian $X$, the optimal transport map to $Z \sim \cN_5(0, I_5)$ is the linear transformation $Z = \Sigma^{-1/2}X$. The inverse map is $X = LZ$, where $L = \Sigma^{1/2}$. Given the block-diagonal structure of $\Sigma$, $L$ is also block-diagonal:
    \begin{align*}
        X_1 &= aZ_1 + bZ_2 & X_4 &= aZ_4 + bZ_5 \\
        X_2 &= bZ_1 + aZ_2 & X_5 &= bZ_4 + aZ_5 \\
        X_3 &= Z_3
    \end{align*}
    where $a = \frac{1}{2}(\sqrt{1+\rho}+\sqrt{1-\rho})$ and $b = \frac{1}{2}(\sqrt{1+\rho}-\sqrt{1-\rho})$. Note that $a^2+b^2=1$ and $ab=\rho/2$.

    The regression function $\eta(Z) = \EE[Y \mid Z]$ becomes:
    \begin{align*}
        \eta(Z) &= \eta_1(Z_1, Z_2) \ind_{\{Z_3>0\}} + \eta_2(Z_4, Z_5) \ind_{\{Z_3<0\}},
    \end{align*}
    where
    \begin{align*}
        \eta_1(Z_1, Z_2) &= 1.5\left[\tfrac{\rho}{2}(Z_1^2+Z_2^2) + Z_1Z_2\right] \\
        \eta_2(Z_4, Z_5) &= \tfrac{\rho}{2}(Z_4^2+Z_5^2) + Z_4Z_5.
    \end{align*}

    \noindent\textbf{DFI for Latent Features ($\phi_{Z_j}$)}
    The importance of a latent feature $Z_j$ is $\phi_{Z_j} = \EE[\VV(\eta(Z) \mid Z_{-j})]$. Since the components of $Z$ are independent, we can compute this for each $j \in \{1, \dots, 5\}$.
    \begin{itemize}
        \item For $Z_1$ and $Z_2$: By symmetry, $\phi_{Z_1} = \phi_{Z_2}$. The importance arises from the variance of $\eta_1$ conditional on one of its components, averaged over the indicator.
        \begin{align*}
            \phi_{Z_1} = \phi_{Z_2} = \frac{1}{2}\left(\EE[\eta_1^2] - \EE[(\EE[\eta_1 \mid Z_1])^2]\right) = \frac{9}{16}\rho^2 + \frac{9}{8}
        \end{align*}

        \item For $Z_3$: The importance is driven by the switching between the two regression components.
        \begin{align*}
            \phi_{Z_3} = \EE\left[\frac{1}{4}(\eta_1 - \eta_2)^2\right] = \frac{1}{4}\left(\VV(\eta_1-\eta_2) + (\EE[\eta_1-\eta_2])^2\right) = \frac{7}{8}\rho^2 + \frac{13}{16}
        \end{align*}

        \item For $Z_4$ and $Z_5$: By symmetry, $\phi_{Z_4} = \phi_{Z_5}$. The importance arises from the variance of $\eta_2$.
        \begin{align*}
            \phi_{Z_4} = \phi_{Z_5} = \frac{1}{2}\left(\EE[\eta_2^2] - \EE[(\EE[\eta_2 \mid Z_4])^2]\right) = \frac{1}{8}\rho^2 + \frac{1}{4}
        \end{align*}
    \end{itemize}

    \noindent\textbf{DFI for Original Features ($\phi_{X_l}$)}
    The importance is attributed back to the original features via $\phi_{X_l} = \sum_{j=1}^5 L_{lj}^2 \phi_{Z_j}$.

    \begin{itemize}
        \item For $X_1$ and $X_2$: The importance is a weighted average of the importances of $Z_1$ and $Z_2$.
        \begin{align*}
           \phi_{X_1} = a^2\phi_{Z_1} + b^2\phi_{Z_2} = (a^2+b^2)\phi_{Z_1} = \phi_{Z_1} = \frac{9}{16}\rho^2 + \frac{9}{8} \\
           \phi_{X_2} = b^2\phi_{Z_1} + a^2\phi_{Z_2} = (a^2+b^2)\phi_{Z_1} = \phi_{Z_1} = \frac{9}{16}\rho^2 + \frac{9}{8}
        \end{align*}

        \item For $X_3$: The feature is independent and its importance is preserved.
        \begin{align*}
            \phi_{X_3} = 1^2 \cdot \phi_{Z_3} = \frac{7}{8}\rho^2 + \frac{13}{16}
        \end{align*}

        \item For $X_4$ and $X_5$: Similar to $X_1, X_2$, the total importance within the correlated block is preserved and distributed.
        \begin{align*}
            \phi_{X_4} = a^2\phi_{Z_4} + b^2\phi_{Z_5} = (a^2+b^2)\phi_{Z_4} = \phi_{Z_4} = \frac{1}{8}\rho^2 + \frac{1}{4} \\
            \phi_{X_5} = b^2\phi_{Z_4} + a^2\phi_{Z_5} = (a^2+b^2)\phi_{Z_4} = \phi_{Z_4} = \frac{1}{8}\rho^2 + \frac{1}{4}
        \end{align*}
    \end{itemize}

In summary, the DFI values as a function of $\rho$ is given by \Cref{tab:M3}.

