\subsection{Posterior Distribution of the Market Equilibrium}\label{sec4.2}
Now, we explore the Bayesian approach of statistical inference to derive the mean and variance of the distribution $\tilde{R}_{\tilde{\nu}}^{\tilde{\lambda}}$ of the random vector of excess returns given the distributions of the shadow-costs and subjective views. The result is stated as follows:
\begin{theorem}[Posterior Distribution of Equilibrium Excess Returns]\label{thm1}
    The posterior distribution of the random vector $\tilde{R}^{\tilde\lambda}_{\tilde\nu}\sim\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)$ of excess returns, given the subjective views' random vector $\tilde{\nu}\sim\mathcal{N}(q;\Omega)$, in the imperfect information market with random vector $\tilde{\lambda}\sim\mathcal{N}(\lambda;\Lambda)$ of shadow-costs has a multivariate normal distribution characterized by
    \begin{equation}\label{eq36_}
    \tilde{R}^{\tilde\lambda}_{\tilde\nu}\sim\mathcal{N}\bigl(\pi^*:={\Sigma^*}\pi^\lambda_\nu;\Sigma^*\bigr),
    \end{equation}
    where
$$\pi^\lambda_\nu:=\Sigma_\gamma^{-1}\pi+P^\top\Omega^{-1} q,$$
and
$$\Sigma^*:=\bigl[\Sigma_\gamma^{-1}+P^\top\Omega^{-1} P\bigr]^{-1},$$
for $\pi$ and $\Sigma_\gamma$ are given by equations (\ref{eq3}) and (\ref{eq32}), respectively.
\end{theorem}
\begin{proof}
We start by exploring Bayesian inference framework to compute the posterior equilibrium distribution, given the distributions of shadow-costs $\tilde{\lambda}$ and subjective views $\tilde{\nu}$. This posterior turns out to be the double-conditional distribution we express by means of Bayes' Rule as
\begin{equation}\label{eq26}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)=\frac{\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigl|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}\bigr)}{\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigr)},
\end{equation}
where
\begin{itemize}
    \item[$\boldsymbol{(i)}$] $\mathcal{P}\bigl(\tilde{R}\bigr)$ is the "Prior" distribution of investor's belief on the CAPM-equilibrium in the complete information market before observing the shadow-costs and incorporating subjective views;
    \item[$\boldsymbol{(ii)}$] $\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigl|\tilde{R}\bigr)$ represents the "Likelihood" of observing the shadow-costs and incorporating the subjective views, given the implied equilibrium;
    \item[$\boldsymbol{(iii)}$] $\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigr)$ the "Marginal Likelihood" of observing the imperfection of information among investors as well as incorporating the subjective beliefs.
\end{itemize}
The knowledge about $\boldsymbol{(i)}$ and $\boldsymbol{(ii)}$ is sufficient to characterize the conditional posterior distribution, in fact we can marginalize the distribution in $\boldsymbol{(iii)}$ by the prior in $\boldsymbol{(i)}$ as
\begin{equation*}
\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigr)=\int_{\mathcal{R}}\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigl|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}\bigr)d\tilde{R},
\end{equation*}
for $\mathcal{R}$ being the probability support of $\tilde{R}$. From Assumption \ref{assumption4}, the Likelihood rewrites as
$$\mathcal{P}\bigl(\tilde\lambda\bigl|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde\nu\bigl|\tilde{R}\bigr),$$
combined with equation (\ref{eq26}) yields
\begin{align*}
\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)&=\frac{\mathcal{P}\bigl(\tilde\lambda\bigr)\mathcal{P}\bigl(\tilde\nu\bigl|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda\bigr)}{\mathcal{P}\bigl(\tilde\lambda;\tilde\nu\bigr)}\\
&=\frac{\mathcal{P}\bigl(\tilde\nu\bigl|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda\bigr)}{\mathcal{P}\bigl(\tilde\nu\bigl|\tilde\lambda\bigr)}.
\end{align*}
Thus, the posterior distribution is the product of the two conditional distributions
\begin{itemize}
    \item \textbf{The Prior $\boldsymbol{\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda\bigr)}$}: Market reference model distribution $\tilde{R}^{\tilde{\lambda}}$ that account for the shadow-costs, it is in fact the posterior distribution of equilibrium for random shadow-costs;
    \item \textbf{The Likelihood $\boldsymbol{\mathcal{P}\bigl(\tilde\nu\bigl|\tilde{R}\bigr)}$}: Distribution of subjective beliefs one obtain after observing the prior CAPM-equilibrium, which turns to be $\mathcal{P}\bigl(P\tilde{R}^{\tilde{\lambda}}\bigr)$.
\end{itemize}
While the denominator cancels to the constant of integration. Therefore, we deduce that the posterior distribution satisfies
\begin{equation*}
\tilde{R}^{\tilde\lambda}_{\tilde\nu}\propto\mathcal{P}\bigl(P\tilde{R}^{\tilde{\lambda}}\bigr)\tilde{R}^{\tilde{\lambda}},
\end{equation*}
where $\propto$ stands for "proportional to". Recalling now Assumption \ref{Assump05}, we write
\begin{equation*}
    \begin{aligned}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)\propto&\exp\Bigl(-\frac{1}{2}\bigl(P\tilde{R}^{\tilde\lambda}-q\bigr)^\top\Omega^{-1}\bigl(\tilde P\tilde{R}^{\tilde\lambda}-q\bigr)\Bigr)\\
    &\exp\Bigl(-\frac{1}{2}\bigl(\tilde{R}^{\tilde\lambda}-\pi)^\top\Sigma_\gamma^{-1}\bigl(\tilde{R}^{\tilde\lambda}-\pi\bigr)\Bigr),
\end{aligned}
\end{equation*}
next, we develop the right-hand side of this equation to obtain
\begin{equation*}
    \begin{aligned}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)\propto\;\exp\Bigl(-\frac{1}{2}\Bigl(&\bigl(P\tilde{R}^{\tilde\lambda}\bigr)^\top\Omega^{-1}P\tilde{R}^{\tilde\lambda}-\bigl(P\tilde{R}^{\tilde\lambda}\bigr)^\top\Omega^{-1}q-q^\top\Omega^{-1}P\tilde{R}^{\tilde\lambda}+q^\top\Omega^{-1}q\\
        &+\bigl(\tilde{R}^{\tilde\lambda}\bigr)^\top\Sigma_\gamma^{-1}\tilde{R}^{\tilde\lambda}-\bigl(\tilde{R}^{\tilde\lambda}\bigr)^\top\Sigma_\gamma^{-1}\pi-\pi^\top\Sigma_\gamma^{-1}\tilde{R}^{\tilde\lambda}+\pi^\top\Sigma_\gamma^{-1}\pi\Bigr)\Bigr).
    \end{aligned}
\end{equation*}
Since matrices $\Sigma_\gamma$ and $\Omega$ are symmetric, it follows that
\begin{equation*}
    \begin{aligned}
        \mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)\propto\;\exp\Bigl(-\frac{1}{2}\Bigl(&\bigl(\tilde{R}^{\tilde\lambda}\bigr)^\top P^\top\Omega^{-1}P\tilde{R}^{\tilde\lambda}-2q^\top\Omega^{-1}P\tilde{R}^{\tilde\lambda}+q^\top\Omega^{-1}q\\
        &+\bigl(\tilde{R}^{\tilde\lambda}\bigr)^\top\Sigma_\gamma^{-1}\tilde{R}^{\tilde\lambda}-2\pi^\top\Sigma_\gamma^{-1}\tilde{R}^{\tilde\lambda}+\pi^\top\Sigma_\gamma^{-1}\pi\Bigr)\Bigr),
    \end{aligned}
\end{equation*}
then, we get
\begin{equation*}
    \begin{aligned}
        \mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)\propto\;\exp\Bigl(-\frac{1}{2}\Bigl(&\bigl(\tilde{R}^{\tilde\lambda}\bigr)^\top\Bigl(\underset{H}{\underbrace{P^\top\Omega^{-1}P+\Sigma_\gamma^{-1}}}\Bigr)\tilde{R}^{\tilde\lambda}-2\Bigl(\underset{C^\top}{\underbrace{q^\top\Omega^{-1}P+\pi^\top\Sigma_\gamma^{-1}}}\Bigr)\tilde{R}^{\tilde\lambda}\\
        &+\underset{A}{\underbrace{q^\top\Omega^{-1}q+\pi^\top\Sigma_\gamma^{-1}\pi}}\Bigr)\Bigr),\\
    \end{aligned}
\end{equation*}
therefore,
\begin{equation*}
\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)\propto\;\exp\Bigl(-\frac{1}{2}\Bigl(\bigl(\tilde{R}^{\tilde\lambda}\bigr)^\top H^\top\tilde{R}^{\tilde\lambda}-2C^\top\tilde{R}^{\tilde\lambda}+A\Bigr)\Bigr).
\end{equation*}
Since the first term in the right-hand side is equal to $\bigl(H\tilde{R}\bigr)^\top H^{-1}H\tilde{R}$, the second term is equal to $2C^\top H^{-1}H\tilde{R}$ and the last term $A$ vanishes due to the integration, we obtain
\begin{equation*}
\mathcal{P}\bigl(\tilde{R}\bigl|\tilde\lambda;\tilde\nu\bigr)\propto\;\exp\bigl(-\frac{1}{2}(H\tilde{R}^{\tilde\lambda}-C)^\top H^{-1}(H\tilde{R}^{\tilde\lambda}-C)-C^\top H^{-1}C\bigr),
\end{equation*}
that is, since the expression $C^\top H^{-1}C$ cancels to the constant of integration,
\begin{equation*}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda};\tilde{\nu}\bigr)\propto\;\exp\bigl(-\frac{1}{2}(\tilde{R}^{\tilde\lambda}-H^{-1}C)^\top H(\tilde{R}^{\tilde\lambda}-H^{-1}C)\bigr).
\end{equation*}
Finally, the posterior distribution $\tilde{R}^{\tilde\lambda}_{\tilde\nu}$ of the random vector $\tilde{R}$ of excess returns, given the distributions of the imperfection of information $\tilde{\lambda}$ and subjective views $\tilde{\nu}$, is multivariate normal with mean vector $H^{-1}C$ and covariance matrix $H^{-1}$. The proof is then finished.
\end{proof}
\begin{corollary}[Shadow-Costs with Random Expectation]
    Let the expectation of $\tilde\lambda$ be random and given by a multivariate normal distribution as in Remark \ref{rk2}. We write $\tilde{\lambda}\sim\mathcal{N}(\lambda_1;\tau_1\Lambda)$, for $\tau_1>0$, then we deduce from Theorem \ref{thm1} the distribution of $\tilde{R}^{\tilde{\lambda}}_{\tilde{\nu}}$ as
    $$\mathcal{N}\bigl(\hat\pi^*:={\hat\Sigma^*}\hat\pi^\lambda_\nu;\hat\Sigma^*\bigr),$$
    where, for $\hat\pi$ and $\hat{\Sigma}_\gamma$ are given as in Remark \ref{rk2},

    $$\hat\pi^\lambda_\nu:=\hat\Sigma_\gamma^{-1}\hat\pi+P^\top\Omega^{-1} q,$$
and
$$\hat\Sigma^*:=\bigl[\hat\Sigma_\gamma^{-1}+P^\top\Omega^{-1} P\bigr]^{-1}.$$ \qed
\end{corollary}
We now present an alternative approach for the derivation of the equilibrium on which the prior is given by the posterior distribution of the equilibrium related to the incomplete information market.
\begin{proposition}[Bayes' Rule Conditioning on $\tilde{\lambda}$]\label{prop3}
    The equilibrium posterior distribution of Theorem \ref{thm1} assumed the prior to be the implied equilibrium of the complete information market. Equivalently, the expression of the posterior distribution is
    \begin{equation}\label{eq40}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda};\tilde{\nu}\bigr)=\frac{\overset{\text{Predictive Distribution}}{\overbrace{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{R}\bigr)}}\;\overset{\text{Posterior Distribution}}{\overbrace{\mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda}\bigr)}}}{\underset{\text{Posterior Predictive Distribution}}{\underbrace{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda}\bigr)}}},
    \end{equation}
    which gives the equilibrium by means of our prior reference model $\tilde{R}^{\tilde{\lambda}}\sim\mathcal{P}\bigl(\tilde{R}|\tilde{\lambda}\bigr)$.
    \end{proposition}
    \begin{proof}
    It suffices to prove that the formula given in equation (\ref{eq40}) is equivalent to the straight forward equation (\ref{eq26}). We express the posterior distribution of $\tilde{R}$, conditioned on the shadow-costs and subjective views distributions, by first conditioning on shadow-costs $\tilde{\lambda}$ and using Bayes' rule as
    \begin{equation*}            \mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda};\tilde{\nu}\bigr)=\frac{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{R};\tilde{\lambda}\bigr)\mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda}\bigr)}{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda}\bigr)},
    \end{equation*}
    considering then Assumption \ref{assumption2}, we obtain
    \begin{equation*}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda};\tilde{\nu}\bigr)=\frac{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda}\bigr)}{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda}\bigr)}.
    \end{equation*}
    Now, to get the equivalence, we start by marginalizing the joint likelihood over $\tilde{\lambda}$ to write
    $$\mathcal{P}\bigl(\tilde{\lambda};\tilde{\nu}\bigl|\tilde{R}\bigr)=\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda};\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{\lambda}\bigl|\tilde{R}\bigr).$$
    Then, we rewrite equation (\ref{eq26}) as
    \begin{equation}\label{equ42}
    \mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda};\tilde{\nu}\bigr)=\frac{\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda};\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{\lambda}\bigl|\tilde{R}\bigr)\mathcal{P}(\tilde{R})}{\mathcal{P}(\tilde{\nu};\tilde{\lambda})},
    \end{equation}
    for the marginal likelihood being
\begin{equation*}
    \begin{aligned}
        \mathcal{P}(\tilde{\nu};\tilde{\lambda})&=\int_{\mathcal{R}}\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda};\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{\lambda}\bigl|\tilde{R}\bigr)\mathcal{P}(\tilde{R})d\tilde{R}\\
        &=\int_{\mathcal{R}}\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda};\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}\bigl|\tilde{\lambda}\bigr)\mathcal{P}\bigl(\tilde{\lambda}\bigr)d\tilde{R}\\
                &=\mathcal{P}\bigl(\tilde{\nu}\bigl|\tilde{\lambda}\bigr)\mathcal{P}\bigl(\tilde{\lambda}\bigr).
    \end{aligned}
\end{equation*}
Recalling assumption (\ref{Assump05}), the numerator of equation (\ref{equ42}) become $\mathcal{P}\bigl(\tilde{\nu}|\tilde{R}\bigr)\mathcal{P}\bigl(\tilde{R}|\tilde{\lambda}\bigr)\mathcal{P}\bigl(\tilde{\lambda}\bigr)$, then substituting in this equation completes the proof.
\end{proof}
This allows investors to first use the available knowledge about the shadow-costs of information to update their beliefs about the equilibrium without incorporating their subjective views. This step involves computing the posterior distribution $\mathcal{P}\bigl(\tilde{R}|\tilde{\lambda}\bigl)$. Subsequently, investors integrate their subjective views through the likelihood distribution $\mathcal{P}\bigl(\tilde{\nu}|\tilde{R}\bigl)$ of their anticipations, given the implied equilibrium, along with the posterior distribution encompassing the shadow-costs, where the normalization constant is determined by the posterior predictive distribution $\mathcal{P}\bigl(\tilde{\nu}|\tilde{\lambda}\bigl)$. Exploring the result of the above Proposition \ref{prop3}, a similar proof to Theorem \ref{thm1} leads us to the alternative equilibrium below.
\begin{corollary}[Posterior Distribution by Bayes' Rule]
The posterior distribution $\tilde{R}_{\tilde{\nu}}^{\tilde{\lambda}}$ of the random vector of excess returns, given the views in a market with incomplete information, is expressed by the posterior distribution $\tilde{R}^{\tilde{\lambda}}$ of the equilibrium related to the incomplete information market and the distribution $\tilde{\nu}$ of subjective views, and has the multivariate normal distribution (\ref{eq36_}). \qed
\end{corollary}
\subsection{Optimal Portfolio in Incomplete Information Market with Views}
As mentioned in Assumptions \ref{assumption1} and \ref{assumption2}, investor $j$ aims at allocating optimal portfolios in markets with incomplete information while reflecting there subjective beliefs, and chooses to perform the standard "unconstrained mean-variance quadratic utility maximization" problem. Thus, similarly to the optimization problem (\ref{eeq24}), the investor solves the problem of finding the portfolio allocation
\begin{equation}\label{equ49}
w_M=\argmax_{w}\biggl\{w^\top\mathbb{E}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]-\frac{1}{2}\delta w^\top\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]w\biggr\},
\end{equation}
for the equilibrium excess returns sub-vector $\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)^{J_j}$ being the posterior distribution of our model's equilibrium related to the securities about which the investor holds information. Any security $k$ that is held on $j$-th investor's information set $J_j$ can be subject of weighting in the allocated portfolio, yielding the equivalent expression for the vector of excess returns
$$\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}:=\biggl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j},{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j^c}\biggr]^\top,$$
where, letting $\tilde{R}_k^{\tilde{\lambda},\tilde{\nu}}$ be the $\{\tilde{\lambda},\tilde{\nu}\}$-conditioned random excess return of asset $k$ in the incomplete information market with subjective views,
$$\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)^{J_j}:=\Bigl\{\tilde{R}_1^{\tilde{\lambda},\tilde{\nu}}-r_f,\dots,\tilde{R}_{n_j}^{\tilde{\lambda},\tilde{\nu}}-r_f\Bigr\}\;\text{and}\;\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)^{J_j^c}:=\Bigl\{\tilde{R}_{n_j+1}^{\tilde{\lambda},\tilde{\nu}}-r_f,\dots,\tilde{R}_{n}^{\tilde{\lambda},\tilde{\nu}}-r_f\Bigr\}.$$
The solution to the problem (\ref{equ49}) is then given as follows:
\begin{theorem}[Unconstrained Optimal Portfolio]
    The optimal allocation in the imperfect information market with subjective views and risk-adjusted return utility maximization is described, for investor $j$ with shadow-costs and subjective views distributions $\tilde{\lambda}$ and $\tilde{\nu}$, respectively, as
    \begin{align*}
    w_M^{\lambda,\nu}:&=\delta^{-1}\biggl[\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]\biggr]^{-1}\mathbb{E}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]\\
        &=\delta^{-1}\bigl[\Sigma^*_{1,\dots,n_j\times1,\dots,n_j}\bigr]^{-1}\pi^*_{1,\dots,n_j},
    \end{align*}
    where $J_j=\{1,\dots,n_j\}$ is the set of securities subject of allocation for investor $j$. \qed
\end{theorem}
\par As an alternative, the investor might choose to solve other optimization problems depending on his/her goal, and these might include the following: 
\begin{itemize}
    \item \textbf{Risk-Constrained Problem}: A more classical approach for portfolio optimization problem is the maximization of the expectation while maintaining the variance under a risk threshold, it is given as
\begin{equation*}
\left\{
\begin{aligned}
    &{w_M^{\text{RiskConstraints}}}=\argmax_{w}\Bigl\{w^\top\mathbb{E}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]\Bigr\},\\
&\text{Subject to:}\;w^\top\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]w\leq\sigma^2;
\end{aligned}
\right.
\end{equation*}
\item \textbf{Risk- and Budget-Constrained Problem}: In this type of problem we write
\begin{equation*}
\left\{
\begin{aligned}
    &{w_M^{\text{RiskBudgetConstraints}}}=\argmax_{w}\Bigl\{w^\top\mathbb{E}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]\Bigr\},\\
&\text{Subject to:}\;w^\top\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]w\leq\sigma^2\;\text{and}\;w^\top\textbf{1}=1;
\end{aligned}
\right.
\end{equation*}
\item \textbf{Minimum Variance Problem}: Here we only minimize the variance of the portfolio's return by solving
\begin{equation*}
    {w_M^{\text{MinimumVariance}}}=\argmin_{w}\Bigl\{w^\top\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]w\Bigr\}.
\end{equation*}
\end{itemize}
By solving these alternative problems, one gets the following result:
\begin{proposition}[Constrained and Minimum Variance Optimal Portfolios]
    The optimal portfolio allocation in the imperfect information market with subjective views and risk-constraint is
    $$w_M^{^{\text{RiskConstraints}}}:=\frac{\sigma}{\sqrt{\bigl(w_M^{\lambda,\nu}\bigr)^\top\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl] w_M^{\lambda,\nu}}}w_M^{\lambda,\nu},$$
    $$w_M^{\text{RiskBudgetConstraints}}:=aw_M^{\lambda,\nu}+b{w_M^{\text{MinimumVariance}}},$$
    for $w_M^{\lambda,\nu}$ being the solution of the unconstrained problem, $a,b$ weighting coefficients satisfying the risk and budget constraints, and $w_M^{\text{MinimumVariance}}$ the optimal portfolio for the minimum variance portfolio given as
    $$w_M^{\text{MinimumVariance}}=\frac{1}{\boldsymbol{1}_{\mathbb{R}^{n_j}}^\top{\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]}^{-1}\boldsymbol{1}_{\mathbb{R}^{n_j}}}{\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]}^{-1}\boldsymbol{1}_{\mathbb{R}^{n_j}}.$$
    Here, $\text{Var}\Bigl[{\bigl(\tilde{R}^{\tilde{\lambda}}_{\tilde\nu}\bigr)}^{J_j}\Bigl]=\Sigma^*_{1,\dots,n_j\times1,\dots,n_j}$. \qed
\end{proposition}
