\section{Appendix: Useful Identities \& Tables}


\subsection{Some relations from the 3+1 decomposition:}

\begin{eqnarray}
& \mbox{} &
{\widetilde H} = \frac{H}{N}
\quad , \quad 
{\widetilde H}^2 = \frac{H^2}{N^2} 
= - {\widetilde g}^{00} H^2 
\; , \label{Htilde} \\
& \mbox{} &
\delta^0_{\, \mu} = - \frac{1}{N} u_{\mu}
\quad , \quad
{\widetilde g}^{0\mu} = - \frac{1}{N} u^{\mu}
\quad , \quad
{\widetilde g}^{\mu\nu} u_{\mu} u_{\nu} 
= -1 =
{\widetilde g}_{\mu\nu} u^{\mu} u^{\nu} 
\; . \qquad\qquad \label{u's}
\end{eqnarray}


\subsection{Some tensor algebra identities:}

\begin{equation}
{\widetilde g}^{\mu\nu} =
\eta^{\mu\nu} - \kappa h^{\mu}_{\; \alpha} \; {\widetilde g}^{\alpha\nu}
\; , \label{ID1}
\end{equation}
\begin{equation}
\eta_{\mu\nu} =
{\overline \eta}_{\mu\nu} - \delta^0_{\; \mu} \delta^0_{\; \nu}
\quad , \quad
\delta^{\mu}_{\; \nu} =
{\overline \delta}^{\mu}_{\nu} + \delta^{\mu}_{\; 0} \delta^0_{\; \nu}
\; , \label{ID2}
\end{equation}
\begin{equation}
\delta^{\mu}_{\; \alpha} \delta^{\nu}_{\; \beta}
=
{\overline \delta}^{\mu}_{\; (\alpha} 
{\overline \delta}^{\nu}_{\; \beta)}
+ 2 \delta^{(\mu}_{\;\; 0} \, {\overline \delta}^{\nu)}_{\; (\alpha}
  \delta^0_{\; \beta)}
+ \delta^{\mu}_{\; 0} \delta^{\nu}_{\; 0}
  \delta^0_{\; \alpha} \delta^0_{\; \beta}
\; , \label{ID3}
\end{equation}
\begin{equation}
{\widetilde g}^{\mu\nu}_{~~ , \alpha} =
- {\widetilde g}^{\mu\rho} \, {\widetilde g}^{\nu\sigma}
\kappa h_{\rho\sigma , \alpha}
\quad , \quad
\delta^{\mu}_{\; 0} =
{\widetilde g}^{\mu\rho} \, {\widetilde g}_{\rho 0} =
{\overline \gamma}^{\mu\rho} \, {\widetilde g}_{\rho 0}
- u^{\mu} u_0
\; , \label{ID4}
\end{equation}
\begin{equation}
\kappa h_{\mu 0} =
{\widetilde g}_{\mu 0} - \eta_{\mu 0} =
{\widetilde g}_{\mu 0} + \delta^0_{\; \mu} =
\tfrac12 u_0 B_{\mu} + u_0 u_{\mu} C 
\; , \label{ID5}
\end{equation}
\begin{equation}
u^{\alpha} \kappa h_{\alpha\beta} =
- \tfrac12 B_{\beta} - u_{\beta} C
\quad , \quad
u^{\alpha} u^{\beta} \kappa h_{\alpha\beta} =
C
\; , \label{ID6}
\end{equation}
\begin{equation}
{\overline \gamma}^{\alpha\beta} \kappa h_{\alpha\beta} =
{\overline \gamma}^{\alpha\beta} A_{\alpha\beta}
\quad , \quad 
{\overline \gamma}^{\mu \alpha} A_{\alpha\beta} =
\Big[ {\widetilde g}^{\mu\alpha} + u^{\mu} u^{\alpha} \Big] 
A_{\alpha\beta} =
A^{\mu}_{\; \beta}
\; . \label{ID7}
\end{equation}
\begin{equation}
u \cdot \partial (A \!-\! \mathcal{A}) = 
\tfrac{\kappa^2 {\widetilde H}^3}{2 \pi^2} a \Big[ 
2 \!-\! \overline{\gamma}^{\alpha\beta} A_{\alpha\beta} \!-\! 4 C \Big] 
+ (\tfrac43 \!-\! 2 N^2) A^{\alpha\beta} \partial_{\alpha} B_{\beta} 
\; . \label{Atrace}
\end{equation}


\subsection{Quadratic operator properties:} 

$\bullet \,$ 
The ${\widetilde D}_A$ quadratic operator equals:
\begin{equation}
{\widetilde D}_A 
\equiv
\partial_{\alpha} \big[ a^{D-2} {\sqrt {-\widetilde g}} \,
{\widetilde g}^{\alpha\beta} \partial_{\beta} \big]
\; , \label{D_A}
\end{equation}
and its operation on the three kinds of scalar propagators
gives:
\begin{eqnarray}
{\widetilde D}_A \, i {\widetilde \Delta}_A(x;x') 
&\!\!\!=\!\!\!& 
i \delta^D(x-x')
\; , \label{iDeltaA} \\
{\widetilde D}_A \, i {\widetilde \Delta}_B(x;x')
&\!\!\!=\!\!\!& 
i \delta^D(x-x') 
+ (D-2) {\widetilde H}^2 a^D {\sqrt {-\widetilde g}} \;
  i {\widetilde \Delta}_B(x;x')
\; , \label{iDeltaB} \\
{\widetilde D}_A \, i {\widetilde \Delta}_C(x;x')
&\!\!\!=\!\!\!& 
i \delta^D(x-x') 
+ 2(D-3) {\widetilde H}^2 a^D {\sqrt {-\widetilde g}} \; 
  i {\widetilde \Delta}_C(x;x') 
\; . \qquad \label{iDeltaC}
\end{eqnarray}
$\bullet \,$
The other two quadratic operators equal:
\begin{eqnarray}
{\widetilde D}_B 
&\!\!\!=\!\!\!&
{\widetilde D}_A - (D-2) \widetilde{H}^2 a^D \sqrt{-\widetilde{g}}
\; , \label{D_B} \\
{\widetilde D}_C 
&\!\!\!=\!\!\!& 
\widetilde{D}_A - 2(D-3) \widetilde{H}^2 a^D \sqrt{-\widetilde{g}}
\; . \label{D_C}
\end{eqnarray}
In $D \!=\! 4$ we have $(D-2) = 2(D-3) = 2$ so that 
${\widetilde D}_B = {\widetilde D}_C$ .
%\\ [11pt]

\newpage

\noindent
$\bullet \,$
The graviton quadratic operator equals: 
\begin{equation}
\widetilde{\mathcal D}^{\mu\nu\alpha\beta}
=
\tfrac12 \Big[ {\widetilde g}^{\mu(\alpha} \, {\widetilde g}^{\beta)\nu}
  - \tfrac12 {\widetilde g}^{\mu\nu} \, {\widetilde g}^{\alpha\beta} \Big] 
  \widetilde{\mathcal D}_A
+ (D-2){\widetilde H}^2 a^D \sqrt{- {\widetilde g}} \,
  u^{(\mu} \, {\widetilde g}^{\nu)(\alpha} \, u^{\beta)}
\; , \label{Dgrav}
\end{equation}
and allows us to check that indeed the proper condition
is satisfied:
\begin{equation}
\widetilde{\mathcal D}^{\mu\nu\alpha\beta} \, 
i \Bigl[ \mbox{}_{\alpha\beta} \widetilde{\Delta}_{\rho\sigma} \Bigr](x;x') 
=
\delta^{\mu}_{\; (\rho} \delta^{\nu}_{\; \sigma)} \,
i \delta^D (x-x')
\; . \label{propcheck}
\end{equation}

\noindent
$\bullet \,$
The ghost kinetic operator equals:
\begin{equation}
\widetilde{\mathcal D}^{\mu\alpha}
=
{\widetilde g}^{\mu\alpha} {\widetilde D}_A 
+ (D-2) {\widetilde H}^2 a^D {\sqrt {-\widetilde g}} \,
u^{\mu} u^{\alpha} 
\; , \label{ghostquadratic} 
\end{equation}
so that its action on (\ref{ghostprop}) gives:
\begin{equation}
\widetilde{\mathcal D}^{\mu\alpha} \, 
i \Bigl[ \mbox{}_{\alpha} \widetilde{\Delta}_{\rho} \Bigr](x;x') 
=
\delta^{\mu}_{\; \rho} \, i \delta^D (x-x')
\; . \label{ghostpropcheck}
\end{equation}


