	\section{Consecutive Collision Orbits and Floer homology}
	\label{orbits}
	In this section, we will compute the Lagrangian Rabinowitz Floer homology of $(S^1\times S^2,\alpha)$ with respect to Legendrian knots given by meridians in $\{0\}\times S^2$. Using this computation, we then show the existence of consecutive collision orbits in the R3BP for energy levels slightly above the first critical energy value.

	\subsection{Equivariant Lagrangian RFH}\label{sec:equiv}

	Let us endow $S^1\times\mathbb{R}^3$ with the symplectic form $\D\lambda$, where $\lambda=z \D\eta+x\D y- y \D x$, and let us choose a Lagrangian submanifold $L_0:=\{0\}\times\mathbb{R}\times \{0\}\times\mathbb{R}$. We consider a contact form $e^f\alpha$ on $S^1\times S^2$, which supports the same contact structure $\xi$ as $\alpha$, and choose an embedding $\iota_f:S^1\times S^2\hookrightarrow S^1\times\mathbb{R}^3$ so that $\iota_f^*\lambda=e^f\alpha$. We denote 
	\[
	\Sigma:=\iota_f(S^1\times S^2),\qquad \Lambda^\Sigma_0:=\Sigma\cap L_0.
	\]
	The latter is a Legendrian knot in $(\Sigma,\lambda|_{\Sigma})$. From now on, we assume that every Reeb chord on $\Sigma$ with endpoints on $\Lambda_0^\Sigma$ is nondegenerate. 

	To introduce the Rabinowitz action functional associated to $(\Sigma,\Lambda_0^\Sigma)$, let $H:S^1\times\mathbb{R}^3\to \mathbb{R}$ be a smooth function such that $H^{-1}(0)=\Sigma$ is a regular level set, the Hamiltonian vector field $X_H$ defined by $\iota_{X_H} d\lambda= -dH$ coincides with the Reeb vector field on $(\Sigma,\lambda|_\Sigma)$, and $H$ is constant outside a bounded region. Let $P\left(S^1\times \mathbb{R}^3,L_{0};[\text{pt.}]\right)$ be the space of smooth paths $\gamma:([0,1],\{0,1\})\to(S^1\times \mathbb{R}^3,L_0)$ having the trivial homotopy class in $\pi_1(S^1\times\mathbb{R}^3,L_0)$. The Rabinowitz action functional is defined by
	\[
	\mathcal{A}^H:\; P\left(S^1\times \mathbb{R}^3,L_{0};[\text{pt.}]\right)\times\mathbb{R}\longrightarrow\mathbb{R},\qquad\mathcal{A}^H(\gamma,\tau):=\int\limits_0^1 \gamma^*\lambda - \tau \int\limits_0^1 H(\gamma(t))\D t.
	\]
	A pair $(\gamma,\tau)$ is a critical point of $\mathcal{A}^H$ if and only if 
	\[
	\del_t \gamma(t)=\tau X_H(\gamma(t)),\qquad \gamma(t)\in \Sigma,\qquad \forall t\in [0,1].
	\]
	The former implies that $\bar\gamma(t):=\gamma(t/\tau)$ for $t\in [0,\tau]$ is a (generalized) Reeb chord with  both endpoints on $\Lambda_0^\Sigma$. By generalized, we mean that $\tau$ can be nonpositive. If $\tau=0$, then $\gamma$ is a constant chord on $\Lambda_0^\Sigma$. If $\tau<0$, then $\bar\gamma$ is an orbit of the negative Reeb vector field. The connected components of $\mathrm{Crit\,}\mathcal{A}^H$ that consist of constant chords is diffeomorphic to $\Lambda_0^\Sigma$. We choose a Morse function $h$ on this space, which is diffeomorphic to a circle, with maximum points $(\gamma_{\mathrm{const},\ell}^+ ,0)$ and minimum points $(\gamma_{\mathrm{const},\ell}^- ,0)$, where $\ell\in\{1,\dots,\ell_0\}$ for some $\ell_0\geq1$. The Lagrangian Rabinowitz Floer chain modules are defined by
	\[
	RFC_i\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)=\begin{cases} 
		\displaystyle\bigoplus_{(\gamma,\tau)}\mathbb{Z}_2\langle(\gamma,\tau)\rangle \qquad & i\in\mathbb{Z}\setminus\{0,1\}\\[2ex]
		\displaystyle\bigoplus_{(\gamma,\tau)}\mathbb{Z}_2\langle(\gamma,\tau)\rangle \oplus \bigoplus_{1\leq \ell\leq\ell_0} \mathbb{Z}_2\langle(\gamma_{\mathrm{const},\ell}^+ ,0)\rangle & i=1\\[2ex]
		\displaystyle\bigoplus_{(\gamma,\tau)}\mathbb{Z}_2\langle(\gamma,\tau)\rangle \oplus \bigoplus_{1\leq \ell\leq\ell_0}\mathbb{Z}_2\langle(\gamma_{\mathrm{const},\ell}^- ,0)\rangle & i=0
	\end{cases}
	\] 
	where each direct sum $\displaystyle\bigoplus_{(\gamma,\tau)}$ ranges over all critical points $(\gamma,\tau)$ of $\mathcal{A}^H$ such that $\tau\neq 0$ and $\mu_{RS}(\bar\gamma)+\frac{1}{2}=i$. As usual, the boundary operator 
	\[
	\partial_i: RFC_i\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)\to  RFC_{i-1}\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)
	\] 
	is defined by counting $L^2$-gradient flow lines of $\mathcal{A}^H$ (together with gradient flow lines of the Morse function $h$ in degree 0 and 1).
	We write $RFH_*\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)$ for the homology of this chain complex. We refer to \cite{merry2014a} for details on the construction of the Lagrangian Rabinowitz Floer homology. 
	\medskip

	Since the hypersurface $\Sigma$ can be displaced from the Lagrangian $L_{0}$ by a compactly supported Hamiltonian in $S^1\times \mathbb{R}^3$, due to \cite[Chapter 2.4]{merry2014a}, we have 
	\begin{equation}\label{eq:vanishing}
		RFH_i\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)=0 \qquad \forall i\in\mathbb{Z}.
	\end{equation}
	Since there are constant generators $(\gamma_\mathrm{const,\ell}^\pm ,0)$, the above vanishing result implies the existence of a nonconstant Reeb chord on $(\Sigma,\Lambda_0^\Sigma)$. To go beyond the mere existence result, we incorporate the symplectic involution $\sigma$ defined in \eqref{eq:sym} into our analysis.

	From now on, we assume that $\Sigma$ is invariant under $\sigma$. We may assume that the Morse function $h$ is invariant under $\sigma$. Since $\sigma^*\lambda=\lambda$ and $\sigma(L_0)=L_0$, $\sigma$ acts freely on the chain complex $RFC_i\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)$. The boundary operators $\partial_i$ can be made equivariant with respect to the action induced by $\sigma$ by defining them with a $\sigma$-equivariant almost complex structure.  
	Therefore, we can define the $\mathbb{Z}_2$-equivariant complex and denote its homology by
	\[
	RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right),
	\] 
	where the superscript $\mathbb{Z}_2$ refers to the $\mathbb{Z}_2$-action generated by $\sigma$, cf.~\cite[Theorem~4.5.6]{ruck24b}. This equivariant homology can be computed by means of the Tate homology, see \cite{ruck2024a}. Below we provide a direct  computation.


	\begin{proposition}\label{prop:equiv_rfh}
		Let $\Sigma$ be as above. Then,
		\[
		RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)\cong \mathbb{Z}_2\qquad  \forall i\in \mathbb{Z}.
		\]
	\end{proposition}
	\begin{proof}
		A standard continuation argument shows that 
		\[
		RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)\cong RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, S^1\times S^2, L_{0};[\text{pt.}]\right).
		\]
		It suffices to show
		\begin{equation}\label{eq:rfh_s1xs2}
			RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, S^1\times S^2, L_{0};[\text{pt.}]\right)\cong \mathbb{Z}_2\qquad \forall i\in\mathbb{Z}.
		\end{equation}
		While this computation can be carried out using Tate homology, it can also be seen directly as follows. We identify the space of constant Reeb chords on $(S^1\times S^2,\alpha)$ with  $\Lambda_0:=(S^1\times S^2)\cap L_0$. We choose a Morse function $h$ on $\Lambda_0$ that is invariant under $\sigma|_{\Lambda_0}$ and has exactly two maximum points $\gamma_\mathrm{const,1}^+,\,\gamma_\mathrm{const,2}^+$ and two minimum points $\gamma_\mathrm{const,1}^-,\,\gamma_\mathrm{const,2}^-$. By the index computation in \eqref{index1}, we have
		\begin{equation}\label{eq:rfc_s1xs2}
			RFC_i\left(S^1\times\mathbb{R}^3, S^1\times S^2, L_{0};[\text{pt.}]\right)=\begin{cases} 
				\mathbb{Z}_2\big\langle(\gamma^i_1, i\pi),(\gamma^i_2, i\pi)\big\rangle \qquad & i\in\mathbb{Z}\setminus\{0,1\}\\[2ex]
				\mathbb{Z}_2\big\langle(\gamma_\mathrm{const,1}^+ ,0),(\gamma_\mathrm{const,2}^+ ,0)\big\rangle & i=1\\[2ex]
				\mathbb{Z}_2\big\langle(\gamma_\mathrm{const,1}^- ,0),(\gamma_\mathrm{const,2}^- ,0)\big\rangle & i=0\,.
			\end{cases}	
		\end{equation}
		Note that the $\mathbb{Z}_2$-action induced by $\sigma$ maps one generator to the other one in each degree. Moreover, the boundary operators $\partial_i$ are equivariant with respect to the $\mathbb{Z}_2$-action. 
		By \eqref{eq:rfc_s1xs2}, for a degree reason, $\partial_1$ is just the Morse boundary operator for $h$ on $\Lambda_0\cong S^1$. Therefore, we know that
		\[
		\partial_1(\gamma_\mathrm{const,1}^+,0)=\partial_1(\gamma_\mathrm{const,2}^+,0)= (\gamma_\mathrm{const,1}^-,0)+(\gamma_\mathrm{const,2}^-,0)\,.
		\]
		The facts that $\partial_i\circ \partial_{i+1}=0$ for all $i\in\mathbb{Z}$ and that the chain complex in \eqref{eq:rfc_s1xs2} is acyclic by \eqref{eq:vanishing} imply that 
		\[
		\partial_k(\gamma_1^k,k\pi)=\partial_k(\gamma_2^k,k\pi)=(\gamma_1^{k-1}, (k-1)\pi)+(\gamma_2^{k-1},(k-1)\pi) \qquad \forall k\in\mathbb{Z}.
		\]
		Therefore, the equivariant complex $RFC_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, S^1\times S^2, L_{0};[\text{pt.}]\right)$ has rank one in each degree, and the boundary operators in this equivariant complex vanish. Note that we use $\mathbb{Z}_2$-coefficients. This proves \eqref{eq:rfh_s1xs2}.
		%Let us abbreviate $\Lambda_0:=(S^1\times S^2)\cap L_0$. 
		%We recall from equation \eqref{index1} that every Reeb chord on $(S^1\times S^2,\Lambda_0)$ with the point homotopy class has Robbin-Salamon index greater then $1$. Therefore, we can apply \cite[Theorem~5.6]{ruck2024a} which yields the isomorphism 
		%\[
		%RFH_*^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, S^1\times S^2, L_{0};[\text{pt.}]\right)\cong TH_*(\mathbb{Z}_2,\mathbb{Z}_2).
		%\] 
		%For reader's convenience, we briefly recall the argument. The Tate homology of $TH_*(\mathbb{Z}_2,\mathbb{Z}_2)$ is the homology of a complete resolution of the finite cyclic group $\mathbb{Z}_2$ with $\mathbb{Z}_2$-coefficients. A complete resolution is an acyclic chain complex $F=(F_i)_{i\in\mathbb{Z}}$ of projective $\mathbb{Z}_2[\mathbb{Z}_2]$-modules, together with a $\mathbb{Z}_2[\mathbb{Z}_2]$-linear map $\varepsilon: F_1\to \mathbb{Z}_2$ such that 
		%\[
		%\cdots \stackrel{\partial_3}{\longrightarrow} F_2 \stackrel{\partial_2}{\longrightarrow} F_1 \stackrel{\partial_1}{\longrightarrow} F_0\stackrel{\varepsilon}{\longrightarrow} \mathbb{Z}_2
		%\]
		%is an exact sequence. Here $\mathbb{Z}_2$ has a trivial $\mathbb{Z}_2[\mathbb{Z}_2]$-module structure. It suffices to show that the chain complex $RFC_i=RFC_i\left(S^1\times\mathbb{R}^3, S^1\times S^2, L_{0};[\text{pt.}]\right)$ is a complete resolution of $\mathbb{Z}_2$. The involution $\sigma$ allows us to view $RFC_i$  as $\mathbb{Z}_2[\mathbb{Z}_2]$-projective modules. We know that it is acyclic by \eqref{eq:vanishing}. Moreover, by \eqref{index1}, 
		%\[
		%RFC_1 =\mathbb{Z}_2\langle  (\gamma_{\text{const}}^+,0)\rangle,\qquad RFC_0 =\mathbb{Z}_2\langle  (\gamma_{\text{const}}^-,0)\rangle,
		%\]
		%and the boundary operator $\partial_1$ is a zero map since it is the boundary operator of the Morse complex of a perfect Morse function on $\Lambda_0$. Thus the isomorphism $\epsilon:RFC_0\to\mathbb{Z}_2$ satisfies the last requirement for being a complete resolution. This proves the proposition. 
	\end{proof}





	%in the restricted three-body problem there are infinitely many orbits starting and ending in the collision point with the Earth. However if there is  a periodic consecutive collision orbit, then its iterates also contribute to $RFH_i^{\rho}\left(S^1\times\mathbb{R}^3, \Sigma, L_{0};[\text{pt.}]\right)$. This fact prevents us from concluding that there are infinitely many geometrically distinct consecutive collision orbits. We address this drawback by showing that periodic consecutive collision orbit in the planar circular R3BP generically do not exist for a generic choice of mass and energy if it is also a symmetric orbit (cf.~\cite[Theorem~5.1.2]{ruck24b}). 

	\subsection{Perturbed LRFH and symmetric consecutive collision orbits}
	\label{sec:perturb_RFH}
	Proposition \ref{prop:equiv_rfh} implies the existence of infinitely many Reeb chords on $\Sigma$ that begin and end in $\Lambda_0^\Sigma$. However, if there is a Reeb chord that is also periodic, it produces infinitely many Reeb chords through iterations. This issue will be partially addressed in the context of the R3BP in Proposition \ref{noP}. Before that, we introduce a perturbed version of Rabinowitz Floer homology that can be used to detect Reeb chords between two Hamiltonian isotopic Legendrians.


	We continue to assume that $\Sigma\subset S^1\times \mathbb{R}^3$ is invariant under the symplectic involution $\sigma$. Let us denote by
	\[
	L_{\varphi_0}:=\{0\}\times \{(r\sin\theta \cos\varphi_0, r\sin\theta\sin\varphi_0,r\cos\theta) \mid 0\leq r,\,0\leq\theta<2\pi\}\subset S^1\times\mathbb{R}^3
	\]
	the plane obtained by rotating the $xz$-plane by an angle $\varphi_0\in [0,\pi)$. We seek  Reeb chords that start on $\Lambda_0^\Sigma$ and end on $\Lambda_{\varphi_0}^\Sigma:=\Sigma \cap L_{\varphi_0}$.

	We use a perturbed version of the Rabinowitz action functional, originally introduced in  \cite{albers2010leaf} to detect leaf-wise intersections. The Lagrangian analogue, which we employ here, is due to \cite{merry2014a}. We consider the Hamiltonian 
	\[
	G: S^1\times \mathbb{R}^3\to \mathbb{R},\qquad  (\eta, x,y,z)\mapsto \varphi_0 \left(x^2+ y^2\right).
	\]
	The time one-map $\phi_G^1$ of its Hamiltonian flow maps $L_{\varphi_0}$ to $L_0$. By multiplying with a suitable cutoff function, we may assume that $G$ is compactly supported and 
	\begin{equation}\label{eq:time_one_map_G}
		\phi_G^{-1}(L_0)\cap \Sigma=\Lambda^\Sigma_{\varphi_0}	
	\end{equation} 
	We further modify $G$ to  depend on time in such a way that it is 1-periodic in time with support in the time interval $(\frac{1}{2},1)$, while ensuring that the time-one map of the Hamiltonian flow remains unchanged, see \cite[Lemma 2.3]{albers2010leaf}. Abusing notation, we continue to denote the modified function by $G$. We now define the perturbed Rabinowitz action functional
	\[
	\begin{aligned}
		&\mathcal{A}_G^H: P\left(S^1\times \mathbb{R}^3,L_{0};[\text{pt.}]\right)\times\mathbb{R}\longrightarrow \mathbb{R},\\
		&\mathcal{A}_G^H(x,\tau):=\int\limits_0^1 x^*\lambda  - \tau \int\limits_0^1\beta(t)H(x(t))\D t - \int\limits_0^1 G(x(t),t)\D t,
	\end{aligned}
	\]
	where $H:S^1\times\mathbb{R}^3\to\mathbb{R}$ is the smooth function associated to the hypersurface $\Sigma$ used in the previous section, and  $\beta:[0,1]\to\mathbb{R}$ is a smooth function supported in $\left(0,\frac{1}{2}\right)$ with total integral equal to $1$. 	 A critical point of this functional is  a pair $(x,\tau)$ with
	\[
	\begin{aligned}
		\del_t x(t)=\tau\beta(t)X_H(x(t))&+X_G(x(t),t),\\
		\int\limits_0^1 \beta(t)H(x(t))\D t&=0.
	\end{aligned}
	\]
	Recall that $X_H$ and $X_G$ have disjoint support in time, namely $(0,\frac{1}{2})$ and $(\frac{1}{2},1)$, respectively. One can readily see that a critical point $(x,\tau)$ of $\mathcal{A}_G^H$ corresponds to a relative leaf-wise intersection point of $\phi_G^1$, meaning that 
	\[
	x(0)\in\Lambda^\Sigma_0=\Sigma\cap L_0,\qquad \phi_G^1(\phi_R^\tau(x(0)))\in L_0.
	\] 
	The latter property together with \eqref{eq:time_one_map_G} implies $\phi_R^\tau(x(0))\in \Lambda^\Sigma_{\varphi_0}$. Hence, a critical point $(x,\tau)$  gives rise to a Reeb chord $\gamma(t):=\phi_R^t(x(0))$ on $\Sigma$ that starts at $\gamma(0)\in\Lambda^\Sigma_0$ and ends at $\gamma(\tau)\in \Lambda^\Sigma_{\varphi_0}$. 

	\medskip
	We now consider the chain complex $RFC_i\left(S^1\times\mathbb{R}^3,\Sigma, L_{0}, G, [\text{pt.}]\right)$, which are $\mathbb{Z}_2$-modules generated by the critical points of $\mathcal{A}_G^H$ and graded by the Robbin-Salamon index. The boundary operator is defined by counting $L^2$-gradient flow lines of $\mathcal{A}_G^H$.
	We may assume that $G$ is invariant under the symplectic involution $\sigma$ in \eqref{eq:sym} since the original form of $G$ prior to multiplication by a cutoff function is invariant.  We can therefore  define the $\mathbb{Z}_2$-equivariant chain complex $RFC^{\mathbb{Z}_2}_i\left(S^1\times\mathbb{R}^3,\Sigma, L_{0}, G, [\text{pt.}]\right)$ and its homology $RFH^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, \Sigma , L_{0}, G, [\text{pt.}]\right)$. A $\sigma$-invariant homotopy between $G$ and the zero function induces a continuation isomorphism 
	\begin{equation}\label{RFH3}
		RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, \Sigma , L_{0}, G, [\text{pt.}]\right)\cong RFH_i^{\mathbb{Z}_2}\left(S^1\times\mathbb{R}^3, \Sigma, L_{0}, [\text{pt.}]\right)\cong \mathbb{Z}_2
	\end{equation}
	for every $i\in\mathbb{Z}$, where the last isomorphism was proved in Proposition \ref{prop:equiv_rfh}. 


	\medskip


	We now apply our general discussion to establish the existence of symmetric consecutive collision orbits in the R3BP for energy levels slightly above the first critical energy value. 

	\begin{corollary}\label{cor2}
		Let $\epsilon>0$ be as in Theorem \ref{thm:moser2}. Then, for every  $d\in(H(L_1),H(L_1)+\epsilon)$, the unregularized energy hypersurface $\left(\Sigma_d,X_{H}\right)$ admits either a symmetric periodic collision orbit or infinitely many consecutive collision orbits with the Earth. The same statement holds for the Moon.
	\end{corollary}
	\begin{proof}
		Recall from Proposition~\ref{cansubst} that we have a contactomorphism
		\[
		F:(\overline{\Sigma}_d^\mathfrak{B},\xi^\mathfrak{B}=\ker\alpha^\mathfrak{B}) \longrightarrow (S^1\times S^2,\xi=\ker\alpha).
		\]
		Thus, $(F^{-1})^*\alpha^{\mathfrak B}=e^{f_{\mathfrak{B}}}\alpha$ for some $f_{\mathfrak{B}}\in C^\infty(S^1\times S^2)$. Thus, there is a hypersurface in $S^1\times\mathbb{R}^3$ corresponding the contact form $e^{f_{\mathfrak{B}}}\alpha$. Abusing notation, we denote this hypersurface by $\overline{\Sigma}_d^\mathfrak{B}$. Due to $F\circ \sigma^{\mathfrak{B}}= \sigma\circ F$ proved in Proposition~\ref{cansubst}, we know $\overline{\Sigma}_d^\mathfrak{B}\subset S^1\times \mathbb{R}^3$ is invariant under $\sigma$. Recall also that  $F(\Lambda_d^{\mathfrak{B},E})$ and $F(\Gamma_d^{\mathfrak{B},E})$ are meridians in  $\{0\}\times S^2$. Therefore 		
		\begin{equation}\label{eq:leg}
			\overline{\Sigma}_d^\mathfrak{B}\cap L_0 \quad \text{and}\quad  \overline{\Sigma}_d^\mathfrak{B}\cap L_{\varphi_0}
		\end{equation}
		for some $\varphi_0\in[0,\pi)$  correspond to $\Lambda_d^{\mathfrak{B},E}$ and $\Gamma_d^{\mathfrak{B},E}$, respectively. Let $G:S^1\times \mathbb{R}^3\to\mathbb{R}$ be as above so  that it has the property $\phi_G^{-1}(L_0)\cap \overline{\Sigma}_d^\mathfrak{B}=\overline{\Sigma}_d^\mathfrak{B}\cap L_{\varphi_0}$, cf.~\eqref{eq:time_one_map_G}. Assume that $(\overline{\Sigma}_d^\mathfrak{B},\Lambda_d^{\mathfrak{B},E},G)$ is nondegenerate so that the associated homologies are well-defined. Then, by \eqref{RFH3}, we have
		\[
		RFH_i^{\mathbb{Z}_2}\big(S^1\times\mathbb{R}^3, \overline{\Sigma}_d^\mathfrak{B} , L_{0}, G, [\text{pt.}]\big)\cong \mathbb{Z}_2.
		\]
		If $(\overline{\Sigma}_d^\mathfrak{B},\Lambda_d^{\mathfrak{B},E},G)$ is not nondegenerate, the homology is not well-defined. Nevertheless, using the continuity property of spectral invariants, we know that the action functional $\mathcal{A}^H_G$, where $H$ is the function  associated to $\overline{\Sigma}_d^\mathfrak{B}$, still has infinitely many critical points, see \cite[Section 4.3]{frauenfelder2019a}. 
		Therefore, we have  infinitely many Reeb chords on $\overline{\Sigma}_d^\mathfrak{B}$ joining two Legendrian knots in \eqref{eq:leg}. This yields infinitely many Reeb chords on the original $\overline{\Sigma}_d^\mathfrak{B}$ from $\Lambda_d^{\mathfrak{B},E}$ to $\Gamma_d^{\mathfrak{B},E}$, and in turn, infinitely many symmetric Reeb chords from $\Lambda_d^{\mathfrak{B},E}$ to itself, see Remark \ref{rem:double}. Since such a symmetric Reeb chord corresponds to a symmetric consecutive collision orbit with the Earth, the corollary follows.
	\end{proof}

	One weakness of this statement is that infinitely many symmetric Reeb chords obtained in the above proof may unfortunately arise as iterates of a single symmetric Reeb chord that is also periodic. Therefore we can only infer the existence of infinitely many symmetric consecutive collision orbits in the absence of periodic symmetric collision orbits. In the next section,  we improve the above result by showing that certain periodic symmetric collision orbits do not exist under a suitable genericity assumption.



	\subsection{The Existence of at least two Geometrically Distinct Symmetric Consecutive Collision Orbits}




	The rotating Kepler problem (i.e.~$\mu=0$ in \eqref{eq:unreg_H}) can be regularized in the same manner as the R3BP. Since the Hamiltonian of the Kepler problem and the Hamiltonian generating the rotation of the frame (i.e.~the angular momentum) Poisson-commute, every solution of the rotating Kepler problem is simply a rotating image of a solution of the Kepler problem. Therefore, a periodic solution passing through the Earth in the regularized Kepler problem can only occur if its period is a rational multiple of the rotation period of the system. The period $T$ of a periodic solution in the Kepler problem at the energy level $d\in\mathbb{R}$ is given by
	\begin{align*}
		T=\sqrt{\frac{\pi}{2d^3}}=2\pi\sqrt{\frac{1}{8\pi d^3}},
	\end{align*}   
	where the rotation period of the system is $2\pi$. Thus, for almost all energy levels $d\in\mathbb{R}$, no periodic solutions passing through the Earth exist. Adapting the proof of \cite[Theorem~5.1.2]{ruck24b}, we show that this nonexistence also holds for symmetric orbits in the R3BP for a generic mass ratio. 

	In the following proposition, in order to reflect the dependence on the mass ratio, we denote by $\Lambda_{d,\mu}^{\mathfrak{B},E}\subset \overline{\Sigma}^\mathfrak{B}_{d,\mu}$ the energy hypersurface and the Legendrian knot associated with mass ratio $\mu\in[0,1]$ at the energy level $d$. 

	\begin{proposition}
		Let $\epsilon>0$ be as in Theorem \ref{thm:moser2}. Let $d\in(H(L_1),H(L_1)+\epsilon)$ be such that the regularized rotating Kepler problem does not admit periodic solutions passing through the Earth. Then, for all except finitely many $\mu\in[0,1]$ the energy hypersurface $\overline{\Sigma}^\mathfrak{B}_{d,\mu}$  does not admit symmetric periodic Reeb orbits intersecting $\Lambda_{d,\mu}^{\mathfrak{B},E}$ an odd number of times.
		\label{noP}
	\end{proposition}
	\begin{proof}
		We begin by examining the constraints that arise from the condition that an orbit is a symmetric orbit with an odd number of intersections with the collision locus. 		
		%		we can assign to every intersection with the collision locus an oriented tangent line induced by the time derivative at that intersection. Since the orbits are symmetric these tangent lines need to appear in pairs and are mapped onto each other via the reflection at the $x$-axis and inverting the orientation. Therefore the only away to have an odd number of intersections is that one of the tangent lines is invariant under this action. In terms of a path in phase space this means the following:
		Let $\gamma(\mu,t)$ be such a symmetric periodic Reeb orbit on $\overline{\Sigma}_{d,\mu}^{\mathfrak{B}}$ intersecting  $\Lambda_{d,\mu}^{\mathfrak{B},E}$ an odd number of times. We write 		
		\begin{align*}
			\gamma(\mu,t)=\big(z_1(\mu,t),z_2(\mu,t),w_1(\mu,t),w_2(\mu,t)\big).
		\end{align*}
		In the position space, the projection $(z_1,z_2)$ of $\gamma$ intersects the Earth orthogonally to the axis spanned by the positions of the Earth and the Moon at least once - in fact, exactly once. Otherwise, it would intersect the Earth an even number of times. Therefore,	we may assume that $\gamma(\mu,t)$ is parametrized so that $\gamma(\mu,0)$ intersects the Earth orthgonally. Then, we have 
		\[
		z_1(\mu,0)=\frac{1}{2},\quad z_2(\mu,0)=0,\quad w_1(\mu,0)=0,\quad  w_2(\mu,0)= \pm 2\sqrt{2\mu}.
		\]
		Note that $w_1(\mu,0)=0$ due to the fact that the associated tangent line is symmetric, and $w_2(\mu,0)= \pm 2\sqrt{2\mu}$ follows from $\gamma(\mu,0)\in K^{-1}(0)$, where $K$ is the Hamiltonian in Section \ref{IntroBirk}. Note that two possiblities of the sign of $w_2(\mu,0)$ reflect the fact that both orientations of the $y$-axis are invariant under the symmetry action. We may assume that $w_2(\mu,0)= 2\sqrt{2\mu}$.

		Let $S\subset(0,1)$ be the set of masses $\mu$ such that there is  a symmetric periodic Reeb orbit $\gamma(\mu,t)$ on $\overline{\Sigma}_{d,\mu}^{\mathfrak{B}}$ intersecting  $\Lambda_{d,\mu}^{\mathfrak{B},E}$. Assume by contradiction that there is a sequence $(\mu_n)_{n\in\mathbb{N}}$ in $S$ such that $\mu_n$ converges to $\mu_*\in S$. Let $\tau_n$ and $\tau_*>0$ be the periods of the orbits $\gamma(\mu_n,t)$ and $\gamma(\mu_*,t)$, respectively. The Hamiltonian equation for $K$ implies that
		\begin{align*}
			\del_t z_2(\mu_*,\tau_*)=\frac{1}{4}w_2(\mu_*,\tau_*) = \frac{\sqrt{2\mu_*}}{2}\neq 0.
		\end{align*}
		Therefore, by the implicit function theorem, there exists  a unique smooth function 
		\[
		\tau:(\mu_*-\delta,\mu_*+\delta)\longrightarrow(0,\infty)
		\] 
		for some $\delta>0$ such that $\tau(\mu_*)=\tau_*$ and 
		\begin{equation}\label{eq:z_2}
			z_2(\mu,\tau(\mu))=0\qquad \forall\mu\in (\mu_*-\delta,\mu_*+\delta).
		\end{equation} 
		Moreover, for sufficiently large $n$, we also have $\tau(\mu_n)=\tau_n$, and therefore,
		\begin{equation}\label{eq:mu_n}
			z_1(\mu_n,\tau(\mu_n))=\frac{1}{2},\qquad   w_1(\mu_n,\tau(\mu_n))=0.	
		\end{equation}
		We consider the functions 
		\[
		f,g: (\mu_*-\delta_0,\mu_*+\delta_0)\longrightarrow \mathbb{R},\qquad f(\mu):=z_1(\mu,\tau(\mu)),\quad  g(\mu):=w_1(\mu,\tau(\mu)).
		\]
		Differentiating $z_2(\mu,\tau(\mu))=0$ with respect to $\mu$, we obtain 
		\begin{equation}\label{eq:d_mu}
			\frac{\D}{\D \mu}\tau(\mu)= -\frac{\del_{1}z_2(\mu,\tau(\mu))}{\del_{2}z_2(\mu,\tau(\mu))}		
		\end{equation}
		where $\partial_1$ and $\partial_2$ denote the partial derivatives with respect to the first and  second coordinates, respectively. The Hamiltonian equation for the restricted three-body problem is real analytic. Since $z_2$ is real analytic, the Cauchy-Kovalevskaya theorem  applied to \eqref{eq:d_mu} implies that $\tau$ is real analytic, and in turn $f$ and $g$ are also real analytic. Since $f-\frac{1}{2}$ and $g$ are zero at $\mu_n$ by \eqref{eq:mu_n}, due to the identity theorem,  they are identically zero. This together with \eqref{eq:z_2} proves that, for every $\mu\in(\mu_*-\delta,\mu_*+\delta)$, $\gamma(\mu,t)$ is a symmetric periodic Reeb orbit on $\overline{\Sigma}_{d,\mu}^{\mathfrak{B}}$ intersecting  $\Lambda_{d,\mu}^{\mathfrak{B},E}$. 

		Since $\overline{\Sigma}_{d,\mu}^{\mathfrak{B}}$ is of contact type for all $\mu$, the blue sky catastrophe does not occur for $\gamma(\mu,t)$ smoothly parametrized by $\mu\in(\mu_*-\delta,\mu_*+\delta)$, see \cite[Theorem~7.6.1]{frauenfelder2018a}. Therefore, the periods of $\gamma(\mu,t)$ are uniformly bounded, and as $\mu\to \mu_*-\delta$, $\gamma(\mu,t)$ converges to a symmetric periodic Reeb orbit  $\gamma(\mu_*-\delta,t)$ on $\overline{\Sigma}_{d,\mu_*-\delta}^{\mathfrak{B}}$ intersecting  $\Lambda_{d,\mu_*-\delta}^{\mathfrak{B},E}$.  
		Now we apply the preceding argument, based on the implicit function theorem, to $\gamma(\mu_*-\delta,t)$. By repeating this process, we can successively extend the interval $[\mu_*-\delta,\mu_*+\delta)$ all the way to $\mu=0$. This implies the existence of a symmetric periodic orbit intersecting the collision fiber over the Earth in the case  $\mu=0$, i.e.~in the regularized rotating Kepler problem. However, this contradicts our choice of energy level $d$. This completes the proof.	\end{proof}

	\begin{corollary}\label{cor3}
		Let $\epsilon>0$ be as in Theorem \ref{thm:moser2}. Let $d\in (H(L_1),H(L_1)+\epsilon)$ and $\mu\in(0,1)$ be generic in the sense of Proposition \ref{noP}. Then, $\left(\Sigma_{d,\mu},X_{H}\right)$ has at least two (geometrically distinct) symmetric consecutive collision orbits with the Earth that together form a periodic orbit. The same statement holds for the Moon.
	\end{corollary}
	\begin{proof}
		As shown in the proof of Corollary \ref{cor2}, there are 
		infinitely many symmetric Reeb chords on $\overline{\Sigma}_{d,\mu}^\mathfrak{B}$ with endpoints in  $\Lambda_{d,\mu}^{\mathfrak{B},E}$. If none of them is periodic, then they are all geometrically distinct. If this is not the case, due to Proposition \ref{noP}, there is a periodic symmetric collision orbit that intersects the Earth at least twice. Since such an orbit intersects the Earth at least twice, it contains at least two geometrically distinct symmetric consecutive collision orbits. This completes the proof.      
	\end{proof}

	\begin{remark}
		Note that the seemingly stronger result \cite[Corollary~5.1.3]{ruck24b} which asserts the existence of infinitely many symmetric consecutive collision orbits for energies below the first critical energy value is also only valid under the additional assumption that there are generically no symmetric periodic orbits that intersect the collision locus an even number of times.
	\end{remark}

