	\renewcommand{\arraystretch}{1.2}
	\begin{tabular}{c|c|c|c|c}
		\hline 
		$\gamma$ & 1/2 & 1/4 & 1/8 & 1/16\\ \hline 
	    $\epsilon$ & 10.70\% & 16.54\% & 25.89\% & 30.18\%   \\ \hline
	     $T_{est}$ & 55.37 & 29.06 & 16.8 & 9.6    \\	\hline 
