\end{eqnarray}

\subsection{Determination of $\mathcal{F}_d$ in Phase I} \label{sec_paraId}

With the required number of remaining unknown tags after Phase I, the number of frames needed to deactivate enough unknown tags can be calculated. Recalling the deactivation process of Phase I,  when an unknown tag is assigned to the expected empty slot indicated in $PV$, it will deactivate itself. Thus, in the $i\text{-th}$ frame of the deactivation process, number of newly deactivated unknown tags $\mathcal{U}_i^*$ is given by
\begin{eqnarray}\label{eq_deun}
\mathcal{U}_i^*=\mathcal{U}_i {f_i\choose 1} \frac{1}{f_i}  \bigg(1-\frac{1}{f_i}\bigg)^\mathcal{K}\approx \mathcal{U}_i  e^{-\mathcal{K}/f_i}=\mathcal{U}_i  ~e^{-1},
\end{eqnarray}
where $\mathcal{U}_i$ is the number of unknown tags participating in the  $i\text{-th}$ frame and the frame size $f_i=\mathcal{K}$. The initial value $\mathcal{U}_1$=$\mathcal{U}$. With recursive resolving, number of remaining unknown tags $\mathcal{U}_{d}$ after $\mathcal{F}_d$ frames  can be calculated as follows,
\begin{eqnarray}\label{eq_ui}
\mathcal{U}_{d}&=&\mathcal{U}_{\mathcal{F}_d}-\mathcal{U}_{\mathcal{F}_d}^*=\mathcal{U}_{\mathcal{F}_d}(1-  ~e^{-1})=\mathcal{U}_{\mathcal{F}_d-1}(1-~e^{1})^2 \nonumber \\
&=&\mathcal{U}_1\big (1-e^{-1}\big )^{\mathcal{F}_d} 
=\mathcal{U}\big (1-e^{-1}\big )^{\mathcal{F}_d}.
\end{eqnarray}

%To guarantee a predefined system reliability $\alpha$, $\mathcal{F}_d$ should be given appropriately. 
%With fewer unknown tags participating in Phase II, i.e., smaller $\mathcal{U}_{d}$, the false negative rate of missing tag identification is smaller. %Let $\mathcal{U}^*=\mu \mathcal{K}$, where $\mu$ is the ratio of unknown tags to known ones. 
%To reduce the false negative rate,  $\mathcal{U}_{d}$ should be as small as possible.  %With the estimated unknown tag number, the deactivation rate can be determined to meet the reliability requirement. 
With the estimated unknown tag number, $\mathcal{F}_d$ is obatined by,
\begin{eqnarray}\label{eq_fd}
\mathcal{F}_d \approx\frac{\ln \big(\mathcal{U}_d/\mathcal{U}_{est}\big)}{\ln \big(1-e^{-1}\big)}.
\end{eqnarray}
Substituting \eqref{eq_ud} into \eqref{eq_fd}, the number of frames needed in the deactivation process of Phase I is obtained, \textit{i.e.},
\begin{eqnarray} \label{eq_fdd}
\mathcal{F}_d\geq\left\{ \begin{array}{l}
\frac{\ln \left( \frac{0.1\mathcal{K}}{\mathcal{U}_{est}} \right)}{\ln(1-e^{-1})} ,~~\alpha \leq 0.9\\
\frac{\ln \left( \frac{0.05\mathcal{K}}{\mathcal{U}_{est}} \right)}{\ln(1-e^{-1})} ,~0.9<\alpha \leq 0.95\\
\frac{\ln \left( \frac{0.01\mathcal{K}}{\mathcal{U}_{est}} \right)}{\ln(1-e^{-1})} ,~0.95<\alpha \leq0.99\\
\end{array} \right. 
\end{eqnarray}

