%   [\alpha_3^u+\alpha_4^u-\frac{1}{2}\alpha_{3,EW}^u-\frac{1}{2}\alpha_{4,EW}^u+%\beta_3^u-\frac{1}{2}\beta_{3,EW}^u]\\
%&&P(\bar{B}_d\to \bar{K}^{*0}\phi)=A_{\bar{K}^*\phi}
 %  [\alpha_3^c+\alpha_4^c-\frac{1}{2}\alpha_{3,EW}^c-\frac{1}{2}\alpha_{4,EW}^c+%\beta_3^c-\frac{1}{2}\beta_{3,EW}^c]
 \end{eqnarray}
where the explicit definition of the parameters $\alpha_i^{c}$ and $\beta_i^c$ can be found in Ref.~\cite{Beneke:2003zv}.

\noindent
For the purpose of the discussion, we recall the definition of the normalization factor associated with the longitudinal amplitude
\begin{equation}
    A_{V_1 V_2}^q={ i}\frac{G_F}{\sqrt{2}}m^2_{B_q}f_{V_2}A_0^{B_q\to V_1}(0)\,,
\end{equation}
and the relation between  the weak annihilation parameters  $\beta_i^p$ and $b_i^p$
\begin{equation}
\beta_i^p=\frac{B(V_1 V_2)}{A(V_1 V_2)} b_i^p
\end{equation}
with 
\begin{equation} \label{eq:annihilation}
B(V_1 V_2)= i G_F f_{B_q} f_{V_1} f_{V_2} 
\end{equation}
which differs between a $B_d$ and a $B_s$ decay. 
By combining all previous expressions, one can identify three distinct sources of U-spin breaking in the SM prediction of the observable $L_{K^*\bar{K}^*}$, which, in order of decreasing importance, are:
%
\begin{itemize}
\item[i)] The dominant source of U-spin breaking that we will denote here by $\rho_1$, arises primarily from the ratio of form factors between $B_s$ and $B_d$ decays; with a subleading contribution coming from $B$-meson mass differences. Based on the previous discussion, the observables $L_{K^*\bar{K}^*}$ can be approximated as
\begin{equation}
L_{K^*\bar{K}^*}\simeq \kappa \rho_1^2
\end{equation}
where
\begin{equation}
\rho_1=\frac{m_{B_s}^2 A_0^{B_s \to K^*}(0)}{m_{B_d}^2 A_0^{B_d \to K^*}(0)}
\end{equation}
The limit $\rho_1=1$
 corresponds to exact U-spin symmetry, i.e, absence of U-spin breaking that would point to a value for $L_{K^*\bar{K}^*}\simeq \kappa$ in this limit. For convenience, we define the degree of U-spin breaking through the quantity 
$\Delta U=1-\rho_1^2$, where 
a small (large) and positive  value of $\Delta U$ indicates a small (large) deviation from exact U-spin symmetry. If instead $\Delta U$ becomes negative, its absolute value reflects the magnitude of U-spin breaking, with larger absolute values implying a stronger breaking.
A comparison between the SM prediction for $L_{{K}^*\bar{K}^*}$ 
%(and similarly for $L_{K\bar{K}}$)
and the corresponding experimental measurement reveals a preference of data for a positive and sizeable U-spin breaking, i.e., a large  positive $\Delta U$, which corresponds to a suppressed value of the 
$\rho_1^2$ factor.








