\begin{abstract} 
This note presents a simple criterion for the tightness of stochastic fragmentation processes.  Our work is motivated by an application to a fragmentation process derived from deleting edges in a conditioned Galton-Watson tree \cite{BOH2023}. In that paper, while finite-dimensional convergence was established, the claimed functional convergence relied on \cite[Lemma 22]{BroutinMarckert}, which is unfortunately incorrect. We show how our results can correct the proof in \cite{BOH2023}. 

Furthermore, we show the applicability of our results by establishing tightness for fragmentation processes derived from various random tree models previously studied in the literature, such as Cayley trees, trees with specified degree sequences, and $\mathbf{p}$-trees.
\end{abstract}

\maketitle

\section{Introduction}

We consider fragmentation processes. 
Intuitively, a (deterministic or random) fragmentation process describes how
a mass is split into smaller and smaller pieces as time increases.
We are only interested in the masses (or sizes) of the pieces, which are
positive real numbers that we arrange in decreasing order.
(We use ``positive'', ``increasing'' and ``decreasing'' in the weak sense.)
The number of pieces may be finite or (countably) infinite, but we will
always  write the masses as an infinite sequence $(x_i)\xoo$, extending a finite
sequence by zeroes.
The space of possible mass configurations
(at any given time $t\ge0$) is thus
\begin{align}\label{SSS}
  \SSS:=\bigset{(x_i)\xoo:x_1\ge x_2\ge \dots \ge0}.
\end{align}
(We are usually interested only in smaller subspaces of this space, see
\refS{Snot}, but we try to state results in great generality.)
We define also a partial order $\preceq$ on $\SSS$; the intuitive meaning
of $(y_i)\xoo\preceq(x_i)\xoo$ is that the fragmentation
$(y_i)\xoo$ can be obtained from $(x_i)\xoo$ by further fragmenting each
of the pieces in some way; see \eqref{preceq} for a formal definition.

A (deterministic or stochastic) \emph{fragmentation process} is a 
function $X(t)=(X_i(t))\xoo$ from $\bbR_+:=\ooo$ to $\SSS$, which is \cadlag{}
(for the product topology on $\SSS$, see \refS{Snot}), and furthermore is
decreasing for the order $\preceq$; in other words,
\begin{align}
  \label{preceq0}
X(t_2) \preceq X(t_1)
\qquad\text{when $0\le t_1\le t_2$}.
\end{align}
Note that we do not assume any other properties, such as, for example, Markov.
(We state all results for fragmentation processes
defined on $\ooo$; the results hold also for processes defined on $\oi$,
\emph{mutatis mutandis}.)


The purpose of this note is to state and prove a simple criterion for
tightness of a sequence of stochastic fragmentation processes, see
\refS{Smain}. The main purpose of this result is to use it in
applications where one can prove finite-dimensional convergence of 
the fragmentation processes;
if one also can show that our condition holds,
then one can conclude that the processes converge
in the Skorohod space $D(\bbR_+,\SSS)$
(\refT{T2}).

The motivation for this note is such an application to a certain
fragmentation process derived from deleting edges in a random tree
\cite[Lemma 5]{BOH2023}.
In that paper first finite-dimensional convergence was proved,
and then convergence in $D(\bbR_+,\SSS)$ was claimed 
using a general compactness result in  \cite[Lemma 22]{BroutinMarckert} --
however, this lemma in \cite{BroutinMarckert} 
is unfortunately incorrect (see \refS{Swrong}).
We therefore show in \refS{Scorrect} how the proof in \cite{BOH2023} can be
corrected using our results below.

We state our general results for fragmentation processes in \refS{Smain},
with proofs in \refS{Spf}.
In the remaining sections we apply the general results to fragmentations of
trees. We give general results in \refS{Stree}, with weighted versions in
\refS{Sweight}; \refSs{Scorrect}--\ref{Sfixed} and \ref{ptreesApp} give
applications to some specific random trees. 



\section{Notation}\label{Snot}

Recall the definition \eqref{SSS} of $\SSS$.
We equip $\SSS$ with the product topology, i.e., the topology as a subspace of
$\bbR^\infty$. 
Convergence $(x\nn_i)\xoo\to(x_i)\xoo$ is thus equivalent to $x\nn_i\to x_i$
for each $i$.
Then $\SSS$ is a Polish space, i.e., a complete separable metric space.
The choice of metric is (as usually) not important;
one convenient standard choice is
\begin{align}\label{vd1}
  d\bigpar{(x_i)\xoo,(y_i)\xoo}:=\sumi 2^{-i}\min\bigpar{|x_i-y_i|,1}.
\end{align}
(Note that $\SSS$ is a closed subset of $\bbR^\infty$, and thus complete for
this metric.)

We consider also the subspaces
\begin{align}\label{SSSoi}
  \SSSoi&:=\Bigset{(x_i)\xoo\in\SSS: 0\le\sumi x_i \le1},
\\\label{SSSi}
  \SSSi&:=\Bigset{(x_i)\xoo\in\SSS: \sumi x_i =1}.
\end{align}

We recall some well-known facts.
\begin{lemma}\label{L0}
  \begin{thmenumerate}
  \item \label{L0SSSoi}
On $\SSSoi$,  
the $\ell^q$ metric is equivalent to 
the product metric \eqref{vd1}
for any $q\in(1,\infty]$.
$\SSSoi$ is a compact metric space (for any of these equivalent metrics).

  \item \label{L0SSSi}
On $\SSSi$,  
the $\ell^1$ metric is equivalent to 
the product metric \eqref{vd1}.
(And hence so is the $\ell^q$ metric for any $q\in[1,\infty]$.)
$\SSSi$ 
is a non-compact Polish space;
the $\ell^1$ metric is a
complete separable metric.
  \end{thmenumerate}
\end{lemma}
\begin{proof}[Sketch of proof]
\pfitemref{L0SSSoi}  
Compactness follows since $\SSSoi$ is a closed subset of $\oi^\infty$.
Convergence in the metric \eqref{vd1}, and thus pointwise, implies
convergence in $\ell^q$ for any $q\in(1,\infty)$ by dominated convergence,
using the fact that $(x_i)\in\SSSoi$ implies $0\le x_i\le 1/i$ for every
$i$.

\pfitemref{L0SSSi}
Elements of $\SSSi$ can be regarded as probability measures on $\bbN$.
Hence pointwise convergence implies convergence in $\ell^1$ by 
Scheff{\'e}'s lemma \cite[Theorem 5.6.4]{Gut}.
Completeness follows since $\SSSi$ is a closed subset of
the Banach space $\ell^1$.

 If we define 
 \begin{align}\label{bad}
x\nn_i:=\frac{1}{n}\indic{i\le n}
\qquad\text{and}\qquad
x\nn:=(x\nn_i)\xoo\in\SSSi,   
 \end{align}
then $x\nn\to0$ in $\SSS$ (and thus in $\SSSoi$) 
in the product metric \eqref{vd1}, but not in $\ell^1$. 
This example shows that
$\SSSi$ is not a closed subset of $\SSSoi$ or $\SSS$, and hence
$\SSSi$ is not compact.
(It shows also that
the $\ell^1$ metric is not an equivalent metric on $\SSSoi$.)
\end{proof}

As said in the introduction, we define  a partial order on $\SSS$; the
formal definition is
\begin{align}
  \label{preceq}
(y_i)\xoo \preceq(x_i)\xoo
\iff
\exists\ga:\bbN\to\bbN 
\text{ such that }
\sum_{j:\ga(j)=i}y_j \le x_i 
\text{ for all }
i\in\bbN.
\end{align}
The intuitive interpretation is that the piece corresponding to $y_j$ is 
a fragment of the piece corresponding to $x_{\ga(j)}$;
in other words, the piece with mass $x_i$ is fragmented into pieces with
masses $(y_j:j\in\ga\qw(i))$.
Note the inequality in the definition \eqref{preceq}; we allow mass to
disappear (or, equivalently, becoming invisible dust); 
in particular, $\ga\qw(i)$ may be empty.
(For processes in $\SSSi$, strict inequality is not possible so
there is no dust.)


Recall that we define
a (deterministic or stochastic) \emph{fragmentation process} as a 
function $X(t)=(X_i(t))\xoo$ from $\bbR_+:=\ooo$ to $\SSS$, which is \cadlag{} 
in the topology above, and decreasing for the order $\preceq$, i.e.,
\eqref{preceq0} holds.

For any metric space $\SSSx$, the space $D(\bbR_+,\SSSx)$
consist of all \cadlag{} functions $\bbR_+\to\SSSx$, equipped with the Skorohod
$J_1$ topology;
if $\SSSx$ is complete and separable, then so is
$D(\bbR_+,\SSSx)$, see \eg{}
\cite[Chapter 3]{Billingsley2ed} 
or
\cite[Chapter 3]{EthierKurtz}.
Note that equivalent metrics in $\SSSx$ define equivalent metrics and thus
the same topology in  
$D(\bbR_+,\SSSx)$, \eg{} as a consequence of
\cite[Problem 3.11.13]{EthierKurtz}.

Given a stochastic process $X(t)$, $t\ge0$, we say 
that a random variable $\tau$ is an \emph{$X$-stopping time} if 
it is a stopping time with respect to the natural filtration 
generated by $X$, i.e., the filtration
$(\cF_t)_{t\ge0}$ with $\cF_t:=\gs\set{X(s): s\le t}$, $t\ge0$.
%completed and made right-continuous in the usual way)

We let $\bbN:=\set{1,2,3,\dots}$.

For stochastic processes $X\nn(t)$ and $X(t)$,
\emph{finite-dimensional convergence}, denoted $X_n(t)\fdto X(t)$,
means joint convergence in distribution $(X_n(t_i))_{i=1}^m\dto (X(t_i))_{i=1}^m$
for any fixed finite sequence $t_1,\dots,t_m$.
(In general, it suffices that this holds for $t_1,\dots t_m$ in the dense
set of times $t$ where $X(t)$ a.s.\ does not jump. In our applications
this is the entire $\bbR_+$.)

If $X_n$ are random variables and $a_n$ positive numbers, then
$X_n=\Op(a_n)$ means
that the variables $X_n/a_n$ are bounded in probability (tight).


Unspecified limits are as \ntoo.


\section{Main results}\label{Smain}

One of our main results is the following, which is proved in \refS{Spf},
based on Aldous's  criterion for tightness. 

\begin{theorem}\label{T1}
  Let $X\nn(t)=(X\nn_i(t))\ixoo$ be a sequence of
fragmentation processes,
and define
\begin{align}\label{qn}
  Q\nn(t):=\sumi \bigpar{X_i\nn(t)}^2.
\end{align}
Suppose that for every uniformly bounded sequence of
$X^n$-stopping times $\tau_n$ and every sequence $h_n$ of positive numbers
with $h_n\to0$, we have, as \ntoo,
\begin{align}
  \label{qn2p}
Q\nn(\tau_n) -Q\nn(\tau_n+h_n) \pto0.
\end{align}
Then,  the family of processes
$X\nn(t)$ is tight in $D(\bbR_+,\SSS)$.
\end{theorem}
It is easy to see, and verified in detail in \refL{L2} below,
that $Q\nn(t)$ is a decreasing function, and thus 
$Q\nn(\tau_n)\ge Q\nn(\tau_n+h_n)$.
\refT{T1} thus has the following corollary.

\begin{corollary}\label{CT1}
  With the notation in \refT{T1}, 
suppose that for every uniformly bounded sequence of
$X^n$-stopping times $\tau_n$ and every sequence $h_n$ of positive numbers
with $h_n\to0$, we have, as \ntoo,
\begin{align}
  \label{qn2}
\E Q\nn(\tau_n) -\E Q\nn(\tau_n+h_n) \to0.
\end{align}
Then,  the family of processes
$X\nn(t)$ is tight in $D(\bbR_+,\SSS)$.
\end{corollary}  
We assume tacitly that the \lhs{} of \eqref{qn2}
is not of the form $\infty-\infty$. 


As a simple consequence, we obtain the following, also proved in \refS{Spf}.

\begin{theorem}\label{T2}
  Let $X\nn(t)=(X\nn_i(t))\ixoo$ be a sequence of
fragmentation processes with $X\nn(t)\in\SSS$, and suppose that we have
finite-dimensional convergence
\begin{align}
  X\nn(t)\fdto X(t)
\end{align}
for some process $X(t)\in D(\bbR_+,\SSS)$.
Define $Q\nn(t)$ by \eqref{qn} and suppose that the condition 
\eqref{qn2p} (or the stronger \eqref{qn2}) holds
for every uniformly bounded sequence of
$X^n$-stopping times $\tau_n$ and every sequence $h_n$ of positive numbers
with $h_n\to0$.
Then,  
$X\nn(t)\dto X(t)$  in $D(\bbR_+,\SSS)$.
\end{theorem}

We have defined fragmentation processes as processes taking values in
$\SSS$, and therefore 
the results above are stated for $D(\bbR_+,\SSS)$. 
In applications we frequently have 
fragmentation processes taking values in $\SSSoi$ or $\SSSi$, and then the
results above often may be combined with the
following simple lemmas
to conclude the corresponding results in
$D(\bbR_+,\SSSoi)$ or $D(\bbR_+,\SSSi)$. 
Note that it is potentially more useful to use these spaces since, as shown
in \refL{L0}, we may use stronger metrics on  $\SSSoi$ and $\SSSi$ than on
$\SSS$, for example the $\ell^2$ and $\ell^1$ metrics, respectively.

\begin{lemma}\label{LSSSoi}
Let $X\nn(t)=(X\nn_i(t))\ixoo$ be a sequence of
fragmentation processes with $X\nn(t)\in\SSSoi$.
\begin{romenumerate}
  \item \label{LSSSoi1}
  The family of processes
$X\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$
if and only if it is tight in $D(\bbR_+,\SSS)$.
\item \label{LSSSoi2}
Suppose further that $X(t)$ is a process in $D(\bbR_+,\SSSoi)$.
Then
$X\nn(t)\dto X(t)$  in $D(\bbR_+,\SSSoi)$
if and only if
$X\nn(t)\dto X(t)$  in $D(\bbR_+,\SSS)$.
\end{romenumerate}
\end{lemma}
\begin{proof}
  Immediate, since $\SSSoi$ is a closed subspace of $\SSS$, 
and thus $D(\bbR_+,\SSSoi)$ is a closed subspace of $D(\bbR_+,\SSS)$
with the subspace topology.
(This is a consequence of e.g.\ \cite[Proposition 3.5.3]{EthierKurtz}.)
\end{proof}

\begin{lemma}\label{LSSSi}
Let $X\nn(t)=(X\nn_i(t))\ixoo$ be a sequence of
fragmentation processes with $X\nn(t)\in\SSSi$.
Suppose further that $X(t)$ is a process in $D(\bbR_+,\SSSi)$.
Then
$X\nn(t)\dto X(t)$  in $D(\bbR_+,\SSSi)$
if and only if
$X\nn(t)\dto X(t)$  in $D(\bbR_+,\SSS)$,
and also if and only if $X\nn(t)\dto X(t)$  in $D(\bbR_+,\SSSoi)$.
\end{lemma}
\begin{proof}
  Immediate, since $\SSSi$ is a subspace of $\SSSoi$ and $\SSS$, 
and thus $D(\bbR_+,\SSSi)$ is a  subspace of both $D(\bbR_+,\SSSoi)$
and $D(\bbR_+,\SSS)$, with the subspace topology.
(Again by e.g.\ \cite[Proposition 3.5.3]{EthierKurtz}.)
%% Billingsley, Theorem 16.1, Chapter 3 ?
%% \cite{Kallenberg} Theorem A2.2 Or Jacod and Shiryaev, Theorem VI.1.4
%% \cite{EthierKurtz} is more general; the others assume $\SSSx$ complete
%% and separable, and Jacod \& Shiryaev only $\bbR^d$
\end{proof}

\begin{remark}
Note that there is no result for $\SSSi$ corresponding to
\refL{LSSSoi}\ref{LSSSoi1}:
even if all $X\nn(t)\in\SSSi$, 
we cannot conclude tightness in $D(\bbR_+,\SSSi)$ without further assumptions.
(This is because $\SSSi$ is not a closed subspace of $\SSSoi$ and $\SSS$.)
A counterexample is provided by $X\nn(t):=x\nn$ in \eqref{bad} for all $t\ge0$,
or 
(if we want $X\nn(0)$ fixed)
by $X\nn(t):=x\nn$ for $t \ge U$ and $X\nn(t):=(1,0,0,\dots)$ for $0\le
t<U$, with $U\sim \Exp(1)$, say.
\end{remark}

\begin{remark}\label{RSSSoo}
  Yet another alternative, used in for example  \cite{BOH2023} 
is to consider fragmentation processes as taking values in the space 
\begin{align}\label{SSSoo}
\SSSoo := \Bigset{(x_i)\xoo\in\SSS: 0\le\sumi x_i < \infty},
\end{align}
equipped with the $\ell^1$ metric.
Note that $\SSSi$ is a closed subspace of $\SSSoo$.
(See \refL{L0}.)
Consequently, analogously to \refL{LSSSi},
for processes taking values in $\SSSi$,
tightness or convergence in $D(\bbR_+,\SSSi)$ 
is equivalent to
tightness or convergence in $D(\bbR_+,\SSSoo)$. 
\end{remark}

\section{Proof of  main results}\label{Spf}

We begin with two simple deterministic lemmas.

\begin{lemma}\label{L1}
Suppose that $(y_i)\xoo\in\SSS$ and that $x\ge\sum_i y_i$. Then
\begin{align}
  \label{l1}
x(x-y_1) \le x^2 -\sumi y_i^2.
\end{align}
\end{lemma}
\begin{proof}
  We have
  \begin{align}
    x^2-x(x-y_1) 
= xy_1 \ge \sumi y_iy_1 \ge \sumi y_i^2.
  \end{align}
\end{proof}

\begin{lemma}\label{L2}
Suppose that $X(t)=(X_i(t)) \ixoo$, $t\ge0$,  is a fragmentation process, and 
let, for $k\ge1$,
\begin{align}\label{qsk}
  S_k(t):=\sumik X_i(t)
\end{align}
be the sum of the $k$ largest masses.
Define
\begin{align}\label{qt}
Q(t):=\sumi [X_i(t)]^2.
\end{align}
Then, for any two times $0\le t_1\le t_2$ 
we have
\begin{align}\label{l2q}
  Q(t_1)\ge Q(t_2)
\end{align}
and, for every $k\ge1$, 
\begin{align}\label{l2}
0\le  S_k(t_1)-S_k(t_2) 
\le
2\sqrt{k\xpar{Q(t_1)-Q(t_2)}}.
\end{align}
 \end{lemma}
 \begin{proof}
By our definition of a fragmentation process,
we have $(X_i(t_2))\xoo \preceq (X_i(t_1))\xoo$.
Let $\ga:\bbN\to\bbN$ be a corresponding function as in the definition
\eqref{preceq} and let $J_i:=\ga\qw(i)$, $i\ge1$.
Then $(J_i)$ is a partition of $\bbN$, and
\begin{align}\label{vd2}
\sum_{j\in J_i} X_j(t_2)\le X_i(t_1).  
\end{align}

For the first inequality in \eqref{l2}, let
$I_k:=\set{\ga(j):j\le k}$.
Then $\set{1,\dots,k}\subseteq\bigcup_{i\in I_k}J_i$, and thus by summing
\eqref{vd2} for $i\in I_k$,
\begin{align}\label{vd22}
  S_k(t_2) 
\le \sum_{i\in I_k} \sum_{j\in J_i} X_j(t_2)
\le \sum_{i\in I_k}  X_i(t_1)
.\end{align}
The set $I_k$ has at most $k$ elements, and thus the 
\rhs{} of \eqref{vd22} is the sum of at most $k$ masses at time $t_1$,
whence it is at most $S_k(t_1)$. 
Hence $S_k(t_2)\le S_k(t_1)$ as we wanted to show.

We turn to the second inequality in \eqref{l2}.
Let, for each $i\ge1$,
\begin{align}\label{vd3}
    \YY_i := \max_{j\in J_i} X_j(t_2),
\end{align}
interpreted as $0$ if $J_i=\emptyset$.
Note that the sets $J_i$ are disjoint; thus $\YY_1,\dots,\YY_k$ are the
masses of $k$ different fragments at time $t_2$, and thus
$\sumik \YY_i \le S_k(t_2)$.
Consequently,
\begin{align}\label{vd4}
  S_k(t_1)-S_k(t_2) \le S_k(t_1) -\sumik \YY_i = \sumik (X_i(t_1)-\YY_i).
\end{align}
Furthermore, 
by \refL{L1} applied to $(X_j(t_2):j\in J_i)$, 
using \eqref{vd2} and \eqref{vd3},
\begin{align}\label{vd5}
  X_i(t_1)\bigpar{X_i(t_1)-\YY_i}
\le X_i(t_1)^2-\sum_{j\in J_i} X_j(t_2)^2.
\end{align}
Summing over all $i$ yields
\begin{align}\label{vd6}
0 \leq \sumi  X_i(t_1)\bigpar{X_i(t_1)-\YY_i}
\le \sumi X_i(t_1)^2-\sumi\sum_{j\in J_i} X_j(t_2)^2 
=Q(t_1)-Q(t_2).
\end{align}
This implies \eqref{l2q}. Moreover, 
let $a>0$. Then \eqref{vd6} implies
\begin{align}\label{vd7}
\sum_{i:X_i(t_{1})\ge a} \bigpar{X_i(t_1)-\YY_i}
\le
a\qw\sum_{i:X_i(t_{1})\ge a}  X_i(t_1)\bigpar{X_i(t_1)-\YY_i}
\le
a\qw\bigpar{Q(t_1)-Q(t_2)}.
\end{align}
Furthermore, obviously
\begin{align}\label{vd8}
\sum_{i\le k:X_i(t_{1})< a} \bigpar{X_i(t_1)-\YY_i}
\le
\sum_{i\le k:X_i(t_{1})< a} X_i(t_1)
\le ka.
\end{align}
Consequently, by combining \eqref{vd7} and \eqref{vd8}, for every $a>0$,
\begin{align}\label{vd9}
\sumik \bigpar{X_i(t_1)-\YY_i}
\le
a\qw\bigpar{Q(t_1)-Q(t_2)}+ka.
\end{align}
Optimizing by choosing
$a:=\sqrt{(Q(t_1)-Q(t_2))/k}$ yields
the second inequality in \eqref{l2}.
\end{proof}

\begin{proof}[Proof of \refT{T1}]
Let, similarly to \eqref{qsk}, $S_k\nn:=\sumik X_i\nn(t)$.
Let stopping times $\tau_n$ and positive $h_n$ be as in the statement.
Then \eqref{qn2p} holds by assumption
and thus \refL{L2} implies that for every fixed $k\ge1$,
\begin{align}\label{kq1}
  S_k\nn(\tau_n) - S_k\nn(\tau_n+h_n)\pto0.
\end{align}
Since $X\nn_i(t)=S\nn_i(t)-S\nn_{i-1}(t)$ (with $S\nn_0(t):=0$),
it follows that
\begin{align}\label{kq2}
  \bigabs{X_i\nn(\tau_n) - X_i\nn(\tau_n+h_n)}\pto0
\end{align}
for every $i$.
The definition \eqref{vd1} implies that for every $k\ge1$
\begin{align}\label{kq3}
  d\bigpar{X\nn(\tau_n),X\nn(\tau_n+h_n)}
\le \sumik 2^{-i}   \bigabs{X_i\nn(\tau_n) - X_i\nn(\tau_n+h_n)}
+2^{-k},
\end{align}
and consequently it follows easily from \eqref{kq2} that
\begin{align}\label{kq4}
  d\bigpar{X\nn(\tau_n),X\nn(\tau_n+h_n)}
\pto0.
\end{align}
This shows that $X\nn(t)$ satisfies Aldous's criterion
\cite{Aldous}
(see also e.g.\ \cite[Theorem 16.11]{Kallenberg}, or
\cite[Theorem 16.10]{Billingsley2ed} for a slightly different
formulation), and thus
the family $X\nn(t)$ is tight in $D(\bbR_+,\SSS)$. 
\end{proof}



\begin{proof}[Proof of \refC{CT1}]
We have $Q\nn(\tau_n)-Q\nn(\tau_n+h_n)\ge0$ by \eqref{l2q} in \refL{L2}.
Thus \eqref{qn2}  is equivalent to 
$\E|Q\nn(\tau_n)-Q\nn(\tau_n+h_n)|\to0$, which implies \eqref{qn2p}.
\end{proof}

\begin{proof}[Proof of \refT{T2}]
The family $X^{(n)}(t)$ is tight in $D(\bbR_+,\SSS)$ by \refT{T1} 
(or \refC{CT1}),
which together with the assumed finite-dimensional convergence implies
convergence in distribution in $D(\bbR_+,\SSS)$, see \eg{} \cite[Theorem
13.1]{Billingsley2ed}. 
\end{proof}

\section{An application: fragmentation of a tree}
\label{Stree}

Consider now the special case of a fragmentation process of a (random) tree, 
where edges are deleted sequentially one by one in random order. 
More precisely, we assume that we are given a random tree
$\cT\nn$ of size $n$ for each $n\ge1$
and 
we assume that conditioned on the tree, each edge $e$ is deleted at some
random time $T_e$, independent of all other edges.
(The results extend to trees with arbitrary sizes $|\cT\nn|\to\infty$
with only notational changes.)
We further assume, for convenience, that the random times
$T_e$ are i.i.d.\ with a common $\Exp(r_n)$ distribution, for some given
rates $r_n$. 
(The argument works with a minor modification also for $T_e\sim U(0,t_n)$
with $t_n\to\infty$; 
alternatively this case follows easily from the exponential case studied below,
see \refC{CoroFixI}.)

Let $\cT\nn(t)$ be the fragmented forest at time $t$, so $\cT\nn(0)=\cT\nn$,
and denote its components by $\cT\nn_i(t)$, $i=1,\dots,\nu\nn(t)$,
arranged in order of decreasing size. Here, $\nu\nn(t)$ denotes the number of components at time $t$. 
We define a fragmentation process $X\nn(t)=(X_i\nn(t))\ixoo$
as the normalized component sizes, i.e.,
formally by  
$X\nn_i(t):=|\cT\nn_i(t)|/n$, with $X\nn_i(t):=0$ for $i>\nu\nn(t)$.
Note that $X\nn(t)\in\SSSi$ for all $t\ge0$, with $X\nn(0)=(1,0,0,\dots)$.


\begin{theorem}\label{TT}
  Let\/ $\cT\nn(t)$ and $X\nn(t)$ be as above 
and suppose that, with $Q\nn(t)$ given by \eqref{qn},
\begin{align}\label{uj4}
 \limsup_{\ntoo}\bigpar{1- \E Q\nn(t)}\to0
\qquad\text{as $t\downto 0$}.
\end{align}
Then,  the family of processes
$X\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$.
\end{theorem}

\begin{proof}
When an edge $e$ is deleted at the
time $T_e$, some component $\bft$ of $\cT\nn(T_e-)$ is split into two $\bft'$
and $\bft''$. Thus, assuming as we may that all $T_e$ are distinct, 
\begin{align}\label{uj1}
  Q\nn(T_e-)&-Q\nn(T_e) 
=\frac{1}{n^2}\bigpar{|\bft|^2-|\bft'|^2-|\bft''|^2}
=\frac{2}{n^2}|\bft'||\bft''|
\notag\\&
=
\frac{1}{n^2}\sum_{v,w\in \cT\nn}\indic{\text{$v$ and $w$ are connected in
  $\cT\nn(T_e-)$ but not in $\cT\nn(T_e)$}}
\notag\\&
=
\frac{1}{n^2}\sum_{v,w\in \cT\nn}\etta\bigl\{
\text{$e$ lies in the path between $v$ and $w$ in $\cT\nn(0)$},
\notag\\&\hskip9 em\text{and this path remains  intact in $\cT\nn(T_e-)$}\bigr\}.
\end{align}
Conditioning on $\cT^{(n)}$ and all $T_{e'}$, $e'\neq e$, 
each term in the final sum in  \eqref{uj1} is a decreasing
function of $T_e$, and since $T_e$ 
is independent of the past (unless it already has occured), 
it follows that for any stopping time $\tau_n$
and constant $h_n>0$, 
\begin{multline}
\E\Bigpar{ \bigpar{Q\nn(T_e-)-Q\nn(T_e)}\indic{\tau_n< T_e\le \tau_n+h_n}   }
\\
\le
\E\Bigpar{\bigpar{Q\nn(T_e-)-Q\nn(T_e)}\indic{0< T_e\le h_n}   }.
\end{multline}
Summing over all edges $e$ yields
\begin{align}\label{uj2}
  \E \bigsqpar{Q\nn(\tau_n)-Q\nn(\tau_n+h_n)}
\le
  \E \bigsqpar{Q\nn(0)-Q\nn(h_n)}
=1 - \E Q\nn(h_n).
\end{align}
Hence, the condition \eqref{qn2} reduces to
\begin{align}\label{uj3}
  \E Q\nn(h_n)\to1
\qquad\text{for any sequence $h_n\to0$}.
\end{align}
This follows easily from \eqref{uj4}.
In fact, let $\eps>0$. Then \eqref{uj4} shows that there exists $t_0>0$ such
that $\limsup_{\ntoo}(1-\E Q\nn(t_0))<\eps$.
Hence, for some $n_0$, if $n>n_0$ then $1-\E Q\nn(t_0)<\eps$.
Consequently, if $n$ is so large that $n\ge n_0$ and $h_n<t_0$, then
$Q\nn(h_n)\ge Q\nn(t_0)>1-\eps$, and thus \eqref{uj3} follows.
(In fact, it is easy to see that 
\eqref{uj3} and \eqref{uj4} are equivalent, and also 
$ \sup_{n\ge 1}\bigpar{1- \E Q\nn(t)}\to0$ as $t\downto 0$,
using that trivially $\cT\nn(t)\to\cT\nn(0)$ 
and thus $Q\nn(t)\to 1$ 
as $t\downto0$,
for every fixed $n$.)

Thus, by Corollary \ref{CT1}, the sequence of processes $X_n(t)$ is tight in
$D(\bbR_+,\SSS)$. This, in turn, implies tightness in $D(\bbR_+,\SSSoi)$
by \refL{LSSSoi}, 
since $X_n(t)\in\SSSoi$.
\end{proof}


\begin{theorem}\label{TT2}
  Let\/ $\cT\nn(t)$ and $X\nn(t)$ be as above 
and suppose that we have finite-dimensional convergence
$X\nn(t)\fdto X(t)$ to some stochastic process $X(t)$ in $D(\bbR_+,\SSS)$.
Then
$X\nn(t)\dto X(t)$ in $D(\bbR_+,\SSSoi)$. 
\end{theorem}

\begin{proof}
For each fixed $t\ge0$ we have by assumption $X\nn(t)\dto X(t)$,
where $X\nn(t)\in\SSSi\subseteq\SSSoi$. Since $\SSSoi$ is a closed subset of
$\SSS$, this implies $X(t)\in\SSSoi$ a.s.\
and
$X\nn(t)\dto X(t)$ in $\SSSoi$.
Moreover, by \refL{L0}, the $\ell^2$ metric is an equivalent metric on
$\SSSoi$; in particular, the $\ell^2$ norm is a continuous function on
$\SSSoi$, and thus we obtain, for every fixed $t\ge0$,
\begin{align}\label{sw4}
  Q\nn(t)=\sumi\bigpar{X\nn_i(t)}^2\dto 
  \sumi\bigpar{X_i(t)}^2
=Q(t).
\end{align}
Since $Q\nn(t)\le1$, we obtain by \eqref{sw4} and dominated convergence, 
\begin{align}\label{sw5}
\E  Q\nn(t)
\to\E Q(t).
\end{align}

By definition, 
$X\nn(0)=(1,0,0,\dots)$ and thus $Q\nn(0)=1$ for every $n$.
Hence \eqref{sw4} implies $Q(0)=1$ a.s.
We assume that $X(t)\in D(\bbR_+,\SSS)$, and in particular $X(t)\to X(0)$
a.s.\ as $t\downto0$.
By the same argument as above, this implies $X(t)\to X(0)$ in $\ell^2$ and
$Q(t)\to Q(0)$ a.s., and thus $\E Q(t)\to\E Q(0)=1$ as $t\downto0$.
Consequently, using \eqref{sw5},
\begin{align}
\lim_{t\to0} \limsup_{\ntoo}\bigpar{1- \E Q\nn(t)}
=
\lim_{t\to0} \bigpar{1- \E Q(t)}
=0,
\end{align}
which shows that \eqref{uj4} holds.
Thus \refT{TT} applies and yields tightness of the family $X^{(n)}(t)$ in
$D(\bbR_+,\SSSoi)$.  
This and the finite-dimensional convergence yield 
convergence in $D(\bbR_+,\SSSoi)$ (as in the proof of \refT{T2}).
\end{proof}

We may also sometimes estimate $Q\nn(t)$ directly.
\begin{theorem}\label{Td}
With notation as in \refT{TT}, 
let $d\nn(v,w)$ denote the graph distance between vertices $v$ and $w$ in
$\cT\nn$. 
Then,  for every $t\ge0$,
\begin{align}
  \label{sof3}
1-\E Q\nn(t)
\le
t\,r_n \E d\nn(V_1,V_2),
\end{align}
where $V_1$ and $V_2$ are two independent uniformly random vertices of\/ 
$\cT\nn$.

Consequently, if 
\begin{align}
  \label{sof4}
r_n \E d\nn(V_1,V_2)=O(1),
\end{align}
then 
the family of processes $X\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$.
\end{theorem}
\begin{proof}
  Fix a time $t\ge0$.
Then, similary to \eqref{uj1},
\begin{align}\label{sof1}
Q\nn(t) &
=
\frac{1}{n^2}\sum_{v,w\in \cT\nn}\indic{\text{$v$ and $w$ are connected in
  $\cT\nn(t)$}}
\notag\\&
=
\frac{1}{n^2}\sum_{v,w\in \cT\nn}\indic{
\text{$T_e>t$ for every $e$ in the path between $v$ and $w$ in $\cT\nn$}},
\end{align}
and thus
\begin{align}\label{sof2}
&1-\E\bigpar{Q\nn(t) \mid \cT\nn}
=\E\bigpar{Q\nn(0)-Q\nn(t) \mid \cT\nn}
\notag\\&\hskip2em
=
\frac{1}{n^2}\sum_{v,w\in \cT\nn}\P\bigpar{
\text{$T_e\le t$ for some $e$ in the path between $v$ and $w$ in $\cT\nn$} \mid \cT\nn} 
\notag\\&\hskip2em
\le
\frac{1}{n^2}\sum_{v,w\in \cT\nn} r_n t d\nn(v,w)
= r_n t \E \bigpar{d\nn(V_1,V_2)\mid\cT\nn},
\end{align} 
which shows \eqref{sof3}.
The final statement follows from \eqref{sof3} and \refT{TT}.
\end{proof}

The following corollary, shows that 
we can replace the condition \eqref{sof4} on the average distance
by corresponding conditions on the diameter or (in a rooted tree) 
the total path-length;
it shows  also that 
we then can weaken the condition from bounded in expectation to bounded in
probability. 
If $\cT\nn$ is  a rooted tree, with root denoted by $\rho$,
then its \emph{total path length} is defined as
\begin{align}\label{tpl}
\TPLn:=
\TPL(\cT\nn):=
\sum_{v\in\cT\nn} d\nn(\rho,v)=n\E\bigpar{d\nn(\rho,V)\mid\cT\nn},  
\end{align}
where $V$ is a uniformly random vertex in $\cT\nn$.

For convenience in applications, we state the corollary with
several versions of the conditions
although some are redundant.

\begin{corollary}\label{CD}
Let $\cT\nn$, $r_n$, and $X\nn(t)$ be as above.
Let $D\nn$ be the diameter of $\cT\nn$ and,
provided the tree $\cT\nn$ is rooted,
let $\TPLn$ be its total pathlength.
Suppose that one of the following conditions holds:
\begin{romenumerate}

\item \label{CDed}
$r_n\E D\nn=O(1)$.

\item \label{CDod}
$r_nD\nn =\Op(1)$.
(I.e.,  the sequence $r_nD\nn$ is tight.) 
\item \label{CDel}
$r_n\E\TPLn =O(n)$.

\item \label{CDol}
$r_n\TPLn =\Op(n)$.
(I.e.,  the sequence $\frac{r_n}{n}\TPLn$ is tight.) 
\end{romenumerate}
Then,  the family of processes
$X\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$.
\end{corollary}

\begin{proof}
\ref{CDed}: 
Let $V_1$ and $V_2$ be independent random vertices as in \refT{Td}. 
Then $d\nn(V_1,V_2)\le D\nn$, and thus \ref{CDed} implies \eqref{sof4}
and the tightness follows by \refT{Td}.

\ref{CDel}: 
Similarly, if $\cT\nn$ has the root $\rho$, then \eqref{tpl} implies
\begin{align}\label{sof8}
  \E\bigpar{d\nn(V_1,V_2)\mid\cT\nn}
\le
\E\bigpar{d\nn(V_1,\rho)+d\nn(\rho,V_2)\mid\cT\nn}
=\frac{2}{n}\TPLn.
\end{align}
Consequently, 
$\E{d\nn(V_1,V_2)}\le \frac{2}{n}\E\TPLn$, and thus \eqref{sof4} follows
from \ref{CDel}.

\ref{CDod}:
  Let $\eps>0$. By \ref{CDod} there exists a constant $C$ such that
$\P(r_nD\nn>C) < \eps$ for every $n$.
We may apply \ref{CDed} to the conditioned trees 
$(\cT\nn\mid r_nD\nn\le C)$,
and conclude that the conditioned processes 
$(X\nn(t)\mid r_nD\nn\le C)$
form a tight family in $D(\bbR_+,\SSSoi)$.
Hence, there exists a compact set $K$ in $D(\bbR_+,\SSSoi)$
such that, for every $n$,
$\P\bigpar{X\nn(t)\notin K\mid r_nD\nn\le C}\le \eps$,
and consequently
\begin{align}\label{sof9}
\P\bigpar{X\nn(t)\notin K}
\le
\P\bigpar{X\nn(t)\notin K\mid r_nD\nn\le C}
+\P\bigpar{ r_nD\nn> C}
\le 2\eps.
\end{align}
This implies that the family $X^{(n)}(t)$ is tight.

\ref{CDol}: Similar, now using \ref{CDel}.
\end{proof}
Now, let us consider the case where each edge $e$ in $\mathcal{T}^{(n)}$ is
deleted at a random time 
$\hT_e \sim U(0, t_{n})$,
independently for all edges. 
Let
$\widehat{\cT}\nn(t)$ be the fragmented forest at time $t$, and let
$\widehat{X}\nn(t)=(\widehat{X}_i\nn(t))_{i \geq 1}$ be the corresponding
fragmentation process of normalized component sizes, defined analogously as
before in this section.

\begin{corollary} \label{CoroFixI}
With notations as above,
suppose that $t_n\to\infty$ and that
one of the following conditions holds:
\begin{romenumerate}
\item \label{CFId}
$\E d\nn(V_1,V_2)=O(t_{n})$.   
\item \label{CFIed}
$\E D^{(n)}=O(t_{n})$.
\item \label{CFIel}
$\E \TPLn=O(nt_{n})$.
\item \label{CFIod}
$D^{(n)}=\Op(t_{n})$.
\item \label{CFIol}
$\TPLn=\Op(nt_{n})$.
\end{romenumerate}
Then, the family of processes $\widehat{X}\nn(t)$ is tight in
$D(\bbR_+,\SSSoi)$.
\end{corollary}

\begin{proof}
Define $a_{n}(t) := t_{n}(1-e^{-t/t_{n}})$. Observe that
$\widehat{\cT}\nn(a_{n}(t))$ represents the fragmented forest at time $t$
resulting from independently deleting each edge $e$ in $\mathcal{T}^{(n)}$
at a random time $T_e:=-t_n\log(1-\hT_e/t_n)\sim\Exp(r_n)$, 
where $r_n:=t_n\qw$ and the $T_e$'s are i.i.d. 
In particular,
$X\nn(t) = \widehat{X}\nn(a_{n}(t))$. 
If \ref{CFId} holds, then
we have $r_{n}\E d\nn(V_1,V_2)=O(1)$, and thus
\refT{Td} 
implies that the family of processes $X\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$. 
Similarly, if one of the other conditions holds, then the same conclusion
holds by \refC{CD}.

Define $b_{n}(t) := -t_{n} \ln (\max(1-t/t_{n}, 0))$. Observe that
$b_{n}(t)$ converges to the identity function uniformly on each compact
interval $[0,s]$, $s \in \mathbb{R}_{+}$. 
Thus, since $\widehat{X}\nn(t) = X\nn(b_{n}(t))$
for $t< t_n$, 
our claim follows.
\end{proof}

%%%%%%%%%%%%%%
\section{Fixing the proof of tightness in \cite{BOH2023}}
\label{Scorrect}
%%%%%%%%%%%%%

Let $\mu = (\mu(k), k \geq 0)$ be a probability distribution on the
non-negative integers satisfying $\sum_{k = 0}^{\infty} k \mu(k) = 1$. In
addition, we always implicitly assume that $\mu(0) + \mu(1) < 1$ (or
equivalently, $\mu(0) >0$), and that $\mu$ is aperiodic. We say that $\mu$
belong to the domain of attraction of a stable law of index $\alpha \in
(1,2]$ if for a sequence $(Y_{i})_{i \geq 1}$ of i.i.d.\ random variables
with distribution $\mu$,  there exists a sequence of positive real numbers
$(B_{n})_{n \geq 1}$ such that $B_{n} \rightarrow \infty$ and
\begin{eqnarray}\label{da} 
\frac{Y_{1} + Y_{2} + \cdots + Y_{n} - n}{B_{n}}  \dto Z_{\alpha}, \quad \text{as} \quad n \rightarrow \infty,
\end{eqnarray}
where $Z_{\alpha}$  is a random variable with Laplace transform
$\mathbb{E}[\exp(-\lambda Z_{\alpha})] = \exp(\lambda^{\alpha})$
whenever
$\alpha \in (1,2)$, and $\mathbb{E}[\exp(-\lambda Z_{2})] =
\exp(\lambda^{2}/2)$ if $\alpha=2$, for every  $\lambda > 0$.
(See \cite[Section XVII.5]{FellerII}, and note that  
since $Y_i\ge0$, 
we may normalize $B_n$ such that \eqref{da} holds.)
In particular, for $\alpha =2$,
we have that $Z_{2}$ is distributed as a standard Gaussian random variable.
Furthermore, if \eqref{da} holds, then
$B_{n}$ is of order about $n^{1/\alpha}$; more precisely, $B_{n}/n^{1/\alpha}$
is a slowly varying sequence.


Let $\mathcal{T}^{(n)}_{\rm GW}$ be a critical Galton--Watson tree
conditioned on having $n$ vertices and whose offspring distribution $\mu$
belongs to the domain of attraction of a stable law. Conditioned on the
tree, each edge $e$ is deleted at some random time 
$\hT_e=\frac{n}{B_{n}}(1-U_e)$,
independent of all other edges, 
where as in \cite[Section 1]{BOH2023}, we assume
that the 
$U_e$ are i.i.d.\ with a common $U(0, 1)$ distribution;
hence $\hT_e\sim U(0,n/B_n)$.
Let
$\widehat{X}\nn(t)=(\widehat{X}_i\nn(t))_{i \geq 1}$ be the associated
fragmentation process of normalized component sizes, as defined before
Corollary \ref{CoroFixI}. In the notation of \cite[(3)]{BOH2023},
$\widehat{X}\nn(t) = \mathbf{F}_{n}^{(\alpha)}(t)$. 


\begin{corollary} \label{CoroFixII}
The family of processes $\widehat{X}\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$. 
\end{corollary}

\begin{proof}
$H^{(n)}$ be the height of $\mathcal{T}^{(n)}_{\rm GW}$. 
Then, $D^{(n)} \leq 2 H^{(n)}$, where $D^{(n)} $ is the diameter of
$\mathcal{T}^{(n)}_{\rm GW}$. It follows from \cite[Theorem 2]{Kortchemski}
that $\mathbb{E}[D^{(n)} ] =
O(n/B_{n})$. Therefore, our claim follows from 
Corollary \ref{CoroFixI}\ref{CFIed}
(with $t_n=n/B_n$).
Alternatively, it follows in the same way from
\refC{CoroFixI}\ref{CFIod}
that is suffices to show that
$(B_n/n)H\nn = \Op(1)$, which follows from the 
convergence in distribution of the height process 
(or of the contour process)
\cite[Theorem 3.1]{Duquesne}, see also \cite[Theorem 3]{Kortchemski2013}.
Or from \refC{CoroFixI}\ref{CFIol}, since the total path length $\TPLn$ of
$\mathcal{T}^{(n)}$ satisfies $\TPLn=\Op(n^{2}/B_{n})$, by \cite[Corollary
4.11]{Delmas2018}.
\end{proof}

\begin{remark}\label{RBOH2023}
Corollary \ref{CoroFixII} addresses a gap in the tightness argument of \cite[Theorem 1]{BOH2023}. Specifically, this issue originated from \cite[Lemma 5]{BOH2023}, which is used in the proof of Theorem \cite[Theorem 1]{BOH2023}. While the convergence of the finite-dimensional distributions in \cite[Lemma 5]{BOH2023} (and consequently in Theorem \cite[Theorem 1]{BOH2023}) is correct, the tightness proof within \cite[Lemma 5]{BOH2023} contains a gap due to the application of the unfortunately incorrect \cite[Lemma 22]{BroutinMarckert}.
We may now instead use \refC{CoroFixII}.

Note that \cite{BOH2023} considers the space $\SSSoo$ defined in \eqref{SSSoo}.
However, in this particular case, since
$\widehat{X}\nn(t)\in\SSSi$ 
for every
$t\ge0$
(a.s.)
and \cite{BOH2023} shows the existence of a finite-dimensional
limit $\widehat{X}(t)\in\SSSi$, 
tightness in $D(\bbR_+,\SSSoi)$ implies 
convergence $\hX_n(t)\to \hX(t)$ 
in $D(\bbR_+,\SSSoi)$,
which by \refL{LSSSi} and \refR{RSSSoo} implies convergence in
$D(\bbR_+,\SSSi)$ and in
$D(\bbR_+,\SSS_{<\infty})$.
\end{remark}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Fixing the proof of \cite[(2) of Theorem 3]{BroutinMarckert}}
\label{Swrong}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
As we said in the introduction, one motivation for the present note is that a 
compactness lemma in \cite{BroutinMarckert} is incorrect.
The lemma concerns subsets of $D(I,\ell^p_{\ge0})$, where $I$ is an interval,
but the problem remains for functions with values in a finite-dimensional
space,
as seen by the following counterexample.

\begin{example}
  For $n\ge2$,
let $g_n$ be the distribution function of a uniform distribution on 
$[\frac12-\frac1n,\frac12]$, i.e., 
$g_n(\frac12-\frac1n)=0$,
$g_n(\frac12)=1$ with $g_n$ linear in between and constant outside  
this interval.
Let $f_n(x)$ be the vector $(g_n(x), 1-g_n(x), 0,0,\dots)$.
It is then easy to see that the set $\set{f_n,n\ge2}$
satisfies the assumptions of \cite[Lemma 22]{BroutinMarckert}
(with $I=[0,1]$, $p=1$, and $M=2$ for every $\eps$).
Nevertheless, the set is not relatively compact since no subsequence of $(f_n)$
converges. To see this it suffices to consider the first components
$g_n(x)$; it is easy to see that 
no subsequence can converge since the set of continuous functions is closed
in $D(I,\bbR)$, and on this subset, convergence in the Skorohod topology is
equivalent to uniform convergence.
(The error in the proof 
in \cite{BroutinMarckert} 
is the assertion that any sequence of 
[uniformly] bounded non-decreasing functions on $I$ has an accumulation
point in $D(I,\bbR)$. 
This is correct for the weaker $M_1$ topology, 
see e.g.\ \cite[Corollary 12.5.1]{Whitt},
but not for the standard $J_1$ topology;
a counterexample is provided by $g_n$ above.)
\end{example}


We now provide a corrected proof for the claim made in \cite[(2) of Theorem 3]{BroutinMarckert}. Let $\mathcal{T}^{(n)}_{\rm Cayley}$ be a uniform Cayley tree with $n$ vertices (uniformly labelled tree on $\{1, \dots, n\}$).  Conditioned on the tree, each edge $e$ is deleted at some random time $\hT_e=\sqrt{n}(1-U_e)$, independent of all other edges. As in \cite[Section 3.2.3]{BroutinMarckert}, we assume that the $U_e$ are i.i.d.\ with a common $U(0, 1)$ distribution. Let $\widehat{X}\nn(t)=(\widehat{X}_i\nn(t))_{i \geq 1}$ be the associated fragmentation process of normalized component sizes, as defined before Corollary \ref{CoroFixI}. 

In \cite{BroutinMarckert}, the process $\widehat{X}\nn(t)=(\widehat{X}_i\nn(t))_{i \geq 1}$ is encoded using a process $\mathbf{y}_{+}^{n, (t)} = (\mathbf{y}_{+}^{n, (t)}(x))_{x \in [0,1]}$,  as defined in \cite[(7)]{BroutinMarckert}. More precisely, $\widehat{X}\nn(t)$ is precisely the sequence of excursion lengths of $\mathbf{y}_{+}^{n, (t)}$ above its minimum sorted in decreasing order as time $t$ evolves. Let $\mathbf{y}_{+}^{(t)}(x) := \mathbf{e}(x)-tx$, for $x \in [0,1]$ and $t \geq 0$, where $\mathbf{e}$ is the normalised Brownian excursion (with unit length). Let $\widehat{X}(t)$ be the sequence of excursion lengths of $\mathbf{y}_{+}^{(t)}$ above its minimum sorted in decreasing order. Following the notation of \cite{BOH2023}, $\widehat{X}\nn(t) = \pmb{\gamma}^{+,n}(t)$ and $\widehat{X}(t) = \pmb{\gamma}^{+}(t)$. 
\begin{theorem}
$\widehat{X}\nn(t)\dto \widehat{X}(t)$ in $D(\bbR_+,\SSSi)$.
\end{theorem}
\begin{proof}
Define $\overline{\mathbf{y}}_{+}^{n, (t)}(x) := \sup_{s \in [0,x]} (-\mathbf{y}_{+}^{n, (t)}(s))$ and $\overline{\mathbf{y}}_{+}^{(t)}(x) := \sup_{s \in [0,x]}(- \mathbf{y}_{+}^{(t)}(s))$, for $x \in [0,1]$. Following \cite[Section 3.1]{Bertoin}, given an increasing path $g$ in $D([0,1], \mathbb{R})$, we write $\mathbf{F}(g)$ for the sequence of the lengths of the intervals components of the complement of the support of the Stieltjes measure $\mathrm{d} g$, arranged in the decreasing order. In particular, 
$\widehat{X}\nn(t) = \mathbf{F}(\overline{\mathbf{y}}_{+}^{n, (t)})$ and $\widehat{X}(t) = \mathbf{F}(\overline{\mathbf{y}}_{+}^{(t)})$. 
Then, using \cite[Theorem 10]{BroutinMarckert} together with \cite[Lemma 4
and Lemma 7]{Bertoin}, one can show the finite-dimensional convergence
$\widehat{X}\nn(t)\fdto \widehat{X}(t)$ in $D(\bbR_+,\SSSi)$. 

On the other hand, 
Corollary \ref{CoroFixI} (with $t_n=\sqrt n$), 
shows that the family of processes
$\widehat{X}\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$,
because
it was shown by \cite{Renyi1967} that  
the diameter $D^{(n)}$ of $\mathcal{T}^{(n)}$ satisfies
$\mathbb{E}[D^{(n)}] = O(\sqrt{n})$,
see also \cite[Corollary 1.3]{Svante}.
Alternatively, we can use that
$D\nn=\Op(\sqrt n)$ by \cite{AldousII,AldousIII},
or that
the total path length $\TPLn$ of $\mathcal{T}^{(n)}$ satisfies
$\mathbb{E}[\TPLn]=O(n^{3/2})$
by \cite{Takacs1992,Takacs1993},
see also \cite[Theorem 3.4]{Svante2003};
furthermore, we
may also use 
$\E d\nn(V_1,V_2)=O(n\qq)$
which was proved in 
\cite{MeirMoon1970};
again see also \cite[Theorem 3.4]{Svante2003}.
Combining this and finite-dimensional convergence,
we obtain  $\widehat{X}\nn(t)\dto \widehat{X}(t)$ in $D(\bbR_+,\SSSoi)$.
Finally, since
$\widehat{X}(t)\in\SSSi$ for every $t$ a.s.\ (see \cite[Lemma 7]{Bertoin}),
our claim follows by \refL{LSSSi}.
\end{proof}






%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Application to the fragmentation of trees with a specified degree sequence} \label{Sfixed}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


For $n \in \mathbb{N}$, a sequence $\mathbf{s}_{n} = (N_{n}(i))_{i \geq 0}$
of non-negative integers is the degree sequence of some finite rooted plane
tree if and only if $\sum_{i \geq 0} N_{n}(i)= 1 + \sum_{i \geq 0} i
N_{n}(i) < \infty$. Then, a random tree $\mathcal{T}^{(n)}_{\mathbf{s}}$
with given degree sequence $\mathbf{s}_{n}$ is a random variable whose law
is uniform on the set of rooted plane trees with $|\mathbf{s}_{n}| := \sum_{i \geq 0}
N_{n}(i)$ vertices amongst which $N_{n}(i)$ have $i$ offspring for every $i
\geq 0$, and therefore with
$\sum_{i \geq 0} i N_{n}(i)$ edges. 

Define $\sigma^2_{n} := \sum_{i \geq 1} i(i-1)N_{n}(i)$ and let $b_{n}$ be a sequence of non-negative real number such that $b_{n} \rightarrow \infty$, $|\mathbf{s}_{n}|/b_{n} \rightarrow \infty$ and $b_{n}/\sigma_{n} \rightarrow 1$. Conditioned on the tree, each edge $e$ is deleted at some random time $\hT_e=\frac{|\mathbf{s}_{n}|}{b_{n}}(1-U_e)$, independent of all other edges. We assume that the $U_e$ are i.i.d.\ with a uniform $U(0, 1)$ distribution. Let $\widehat{X}\nn(t)=(\widehat{X}_i\nn(t))_{i \geq 1}$ denote the associated fragmentation process of normalized component sizes, as defined prior to Corollary \ref{CoroFixI}.

\begin{corollary} \label{CoroFixIII}
The family of processes $\widehat{X}\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$. 
\end{corollary}

\begin{proof}
For a vertex $v$ in  $\mathcal{T}^{(n)}_{\mathbf{s}}$, we denote its height
by $h\nn(v)$. Without loss of generality, by considering $n$ large enough if
necessary, we assume that 
$|\mathbf{s}_{n}| \geq b_{n}$ and $\sigma_{n} >0$.
Let $\Delta_{n} := \max\{i \geq 0: N_{n}(i)>0 \}$. 
Then, since $\sigma_{n} >0$, we have
$\Delta_{n} \geq 2$ and 
$\sigma_n \ge \Delta_{n}$.
Let $V_1$ and $V_2$ be two independent uniformly random
vertices of $\mathcal{T}^{(n)}_{\mathbf{s}}$. Observe that $d^{(n)}(V_{1},
V_{2}) \leq h^{(n)}(V_{1}) + h^{(n)}(V_{2})$. It follows from
\cite[Proposition 4.5]{Marzouk} 
that there exists two universal constants
$c_{1}, c_{2}>0$ such that  
\begin{align}
\mathbb{P}\bigpar{h^{(n)}(V_{1}) \geq x |\mathbf{s}_{n}|/b_{n}  } \leq c_{1}e^{-c_{2}x \frac{\sigma_{n}}{b_{n}}}
\end{align}
\noindent uniformly for $x >0$ 
and $n \in \mathbb{N}$. 
(See also \cite[Theorem 1.1]{Louigi} for a similar bound.)
Thus, $\mathbb{E}d^{(n)}(V_{1}, V_{2}) \le 2\E h\nn(V_1)= O(|\mathbf{s}_{n}|/b_{n})$ and
our claim follows from Corollary \ref{CoroFixI}\ref{CFId}.
\end{proof}

\begin{remark}\label{RBHP2025} 
Recently, the fragmentation process of trees with a given degree sequence has been studied in \cite{BHP2025}, where the convergence $\widehat{X}\nn(t)=(\widehat{X}_i\nn(t))_{i \geq 1}$ was established. However, at the time of writing this note, a problem existed in the tightness argument, specifically originating from the unfortunately incorrect \cite[Lemma 22]{BroutinMarckert}. Now, Corollary \ref{CoroFixIII} completes the proof. 
As in \refR{RBOH2023}, the result holds also in 
$D(\bbR_+,\SSSi)$ and $D(\bbR_+,\SSS_{<\infty})$
by \refL{LSSSi} and \refR{RSSSoo}.
\end{remark} 



