\section{Weighted fragmentations of a tree}\label{Sweight}
In \refSs{Stree}--\ref{Sfixed} we have studied fragmentations of trees,
where we have measured the sizes of components by their number of vertices.
More generally, we may assume that we are given, for each $n$,  
a random tree $\cT\nn$ with a nonrandom vertex set
$\cV\nn=\cV(\cT\nn)$ (finite or infinite), and
a family of nonnegative weights $\bw\nn=(w\nn_j:j\in \cV\nn)$ with total mass
$\sum_j w\nn_j<\infty$.
We consider random fragmentation of the tree $\cT\nn$ as above, with edges
$e$ deleted at i.i.d.\ times $T_e$ that are either $\Exp(r_n)$ or $U(0,t_n)$.
We then define the fragmentation process $Y\nn(t)=(Y_i\nn(t))\ixoo$ by letting
\begin{align}
  Y\nn_i(t):=\sum_{j\in \cT\nn_i(t)} w_j\nn,
\end{align}
the total weight of the component $\cT\nn_i(t)$, for $i=1,\dots,\nu\nn(t)$, where we now arrange the
components in order of decreasing weight.

For simplicity we will only consider the case when the weight sequence 
$\bw\nn$ is a probability distribution on $\cV\nn$, i.e.,
$\sum_j w\nn_j=1$. To stress this we use the notation $\bp\nn=(p\nn_j:j \in \cV\nn)$
instead of $\bw\nn$. 
(We leave the modifications for the general case to the reader.)

\begin{theorem}
  \label{TTW}
With assumptions as above, 
\refTs{TT} and \ref{TT2} still hold (with $Y\nn$ and $Y$ instead of $X\nn$ and $X$), and \refT{Td} holds if $V_1$ and $V_2$
now are independent vertices of $\cT\nn$ with the distribution $\bp\nn$.
\end{theorem}
\begin{proof}
  The proofs are essentially the same.

First, for \refT{TT},
instead of \eqref{uj1} we obtain, in the same way,
\begin{multline}\label{uj1w}
  Q\nn(T_e-)-Q\nn(T_e) 
=
\sum_{v,w\in \cV\nn}p\nn_vp\nn_w\etta\bigl\{
\text{$e$ lies in the path between $v$ and $w$ in}
\\\text{$\cT\nn(0)$,
and this path remains  intact in $\cT\nn(T_e-)$}\bigr\}.
\end{multline}
The rest of the proof is the same as before.

The proof of \refT{TT2} is unchanged.

In the proof of \refT{Td}, we obtain, arguing as in \eqref{sof1}--\eqref{sof2},
\begin{align}\label{sof2w}
&1-\E\bigpar{Q\nn(t) \mid \cT\nn}
\le
\sum_{v,w\in \cV\nn} p_v^{(n)}p_w^{(n)}r_n t d\nn(v,w)
= r_n t \E \bigpar{d\nn(V_1,V_2)\mid\cT\nn},
\end{align}
which shows \eqref{sof3}.
\end{proof}


\begin{remark} \label{RemarkExtI}
The parts of \refCs{CD} and \ref{CoroFixI} that use $D\nn$ still hold. 
%State as theorem?
However, the parts involving the total path length $\gU\nn$ require us to instead consider the weighted path length $\sum_{v\in V\nn}p\nn_vd\nn(\rho,v)$. Equivalently, these parts can be stated in terms of the average depth
$\E d\nn(\rho,V)$, where $V$ is a random vertex with distribution $\bp\nn$. The part involving $\E d\nn(V_1,V_2)$ also holds, but we must consider two independent random vertices $V_{1}$ and $V_{2}$  of $\mathcal{T}^{(n)}$ chosen according to the distribution $\mathbf{p}\nn$. The details are left to the reader.
%We might add a remark on average depth to \refS{Stree}
\end{remark}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Application to the fragmentation of $\mathbf{p}$-trees} \label{ptreesApp}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

For $n \geq 1$, let $\mathbf{p}\nn = (p_{ni}: i \geq 1)$ be a ranked
probability distribution on the positive integers. That is, $p_{n1}
\geq p_{n2} \geq 0$ and $\sum_{i \geq 1} p_{ni} =1$. The support of
$\mathbf{p}\nn$ is $\mathcal{V}\nn :=\{i \geq 1: p_{ni}>0 \}$. Let
$Y_{n,0}, Y_{n,1}, \dots$  be i.i.d.\ random variables with common
distribution $\mathbf{p}\nn$. Define a random discrete tree
$\mathcal{T}_{\mathbf{p}}^{(n)}$ to have vertex set $\mathcal{V}\nn$ and
undirected edges $\{ \{Y_{n,j-1}, Y_{n,j} \}: Y_{n,j} \not \in \{Y_{n,0},
\dots, Y_{n,j-1} \}, \, j \geq 1 \}$. The tree
$\mathcal{T}_{\mathbf{p}}^{(n)}$ is known as the birthday tree with
parameter $\mathbf{p}\nn$, or simply as the $\mathbf{p}\nn$-tree (see,
e.g., \cite{Camarri}, \cite[Section 3.1]{Aldous2000},
\cite[Section 10.2]{Pitman}, 
and references
therein). Observe that when $p_{ni}=1/n$, for $1 \leq i \leq n$, the
$\mathbf{p}\nn$-tree is a uniform random rooted tree with $n$ vertices (the
Cayley tree of size $n$), discussed above in \refS{Swrong}.

Define $\sigma_{\mathbf{p}\nn} := \sqrt{\sum_{i \geq 1}  p_{ni}^{2}}$. 
Following \cite[Section 3.1]{Aldous2000},
conditioned on
$\mathcal{T}_{\mathbf{p}}^{(n)}$, we delete each edge $e$ at some random
time  
$\hT_e=\sigma_{\mathbf{p}\nn}^{-1}(1-U_e)$, independent of all other edges, 
where we assume that the $U_e$ are i.i.d.\ with a common $U(0, 1)$
distribution. 
We define as in \refS{Sweight}
the fragmentation process $\widehat{Y}\nn(t) =
(\widehat{Y}_i\nn(t))_{i \geq 1}$ as the sequence of
$\mathbf{p}\nn$-measures of the tree-components of the fragmented forest at
time $t$, arranged in decreasing order.  
So,
$\widehat{Y}\nn(t)$ records the $\mathbf{p}\nn$-measures of components
obtained when each edge is deleted with probability
$t\sigma_{\mathbf{p}\nn}$.  


\begin{corollary} \label{CorPtrees}
Suppose that $\sigma_{\mathbf{p}\nn} \rightarrow 0$. Then, the family of processes $\widehat{Y}\nn(t)$ is tight in $D(\bbR_+,\SSSoi)$. 
\end{corollary}

\begin{proof}
This follows from the weighted version of \refC{CoroFixI} (see Remark
\ref{RemarkExtI}) provided that $\mathbb{E}d^{(n)}(V_{1},
V_{2}) = O(\sigma_{\mathbf{p}\nn}^{-1})$, where $V_{1}$ and $V_{2}$ are two
independent random vertices of $\mathcal{T}_{\mathbf{p}}^{(n)}$ chosen
according to the distribution $\mathbf{p}\nn$. But this last claim follows
from Proposition \ref{ProTailDist}
in \refApp{App},
thus concluding our proof. 
\end{proof}


\begin{remark}
Define 
\begin{align}
\SSS_{2} := \Bigset{(x_i)\xoo\in\SSS: 0 \leq \sumi x_i^{2} \leq 1 }
\end{align}
\noindent and
\begin{align}
\Theta := \Bigset{(x_i)\xoo\in\SSS_{2}: \sumi x_i^{2} <1 \, \, \text{or} \, \,  \sumi x_i = \infty}.
\end{align}
\noindent Aldous and Pitman \cite[Proposition 13]{Aldous2000} 
proved that if there exists a sequence $\boldsymbol{\theta} = (\theta_i)\xoo \in \Theta$ such that
\begin{align}
\sigma_{\mathbf{p}\nn} \rightarrow 0 \quad \text{and} \quad \frac{p_{ni}}{\sigma_{\mathbf{p}\nn}} \rightarrow \theta_{i}, \quad i \geq 1,
\end{align}
then, $\widehat{Y}\nn(t)\fdto \widehat{Y}(t)$ to some stochastic process $\widehat{Y}(t)$ in $D(\bbR_+,\SSSi)$. On the other hand, we have that $\widehat{Y}\nn(t)\in\SSSi$ and $\widehat{Y}(t)\in\SSSi$ for every
$t\ge0$ (a.s.) (\cite[Lemma 12]{Aldous2000}). Then, tightness in
$D(\bbR_+,\SSSoi)$ (Corollary \ref{CorPtrees}) implies 
$\widehat{Y}\nn(t)\dto \widehat{Y}(t)$ in $D(\bbR_+,\SSSi)$
by \refL{LSSSi}.
The limit $\widehat{Y}(t)$ is the fragmentation process of the so-called 
\emph{Inhomogeneous continuum random tree} with parameter $\boldsymbol{\theta}$; see \cite[Section 4]{Aldous2000} for its definition. 
\end{remark}

\begin{remark}
Define $M\nn(t) := \widehat{Y}\nn(\sigma_{\mathbf{p}_{n}}^{-1}e^{-t})$, for $0 \leq t < \infty$. Then, $M\nn(t)$ is an additive coalescent with initial state $\mathbf{p}_{n}$; see \cite[Proposition 1]{Aldous2000}. Indeed, if we define $M(t) := \widehat{Y}(e^{-t})$, for $-\infty < t < \infty$, then $M(t)$ is an ({\sl eternal}) additive coalescent; see \cite[Theorem 10]{Aldous2000}.

In \cite{Bertoin}, a specific case is analysed where $p_{nn} > 0$ and $p_{ni} = 0$ for $i > n$. \cite[Theorem 1]{Bertoin} proves that the process $(M\nn(-\log \sigma_{\mathbf{p}_{n}} - \log t), 0 < t < \sigma_{\mathbf{p}_{n}}^{-1})$ converges in the sense of finite dimensional distributions, as $n \rightarrow \infty$, in $D(\bbR_+,\SSSi)$, to a fragmentation process associated with certain bridges with exchangeable increments. Observe that $M\nn(-\log \sigma_{\mathbf{p}_{n}} - \log t) = \widehat{Y}\nn(t)$. Then, Corollary \ref{CorPtrees} and \refL{LSSSi} imply the tightness of this sequence of processes in $D(\bbR_+,\SSSi)$. As a consequence, the convergence in \cite[Theorem 1]{Bertoin} can be strengthened to convergence in distribution in $D(\bbR_+,\SSSi)$. 
\end{remark} 


\appendix
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{An exponential tail bound} \label{App}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this appendix, we prove an exponential tail bound, used above,
on the distance between two independent random vertices of a  $\mathbf{p}_{n}$-tree, chosen independently according to the distribution $\mathbf{p}_{n}$. For notational simplicity, we will drop the $n$ dependence from the notation introduced in Section \ref{ptreesApp} and write $\mathbf{p} = (p_{i}: i \geq 1)$ for a ranked  probability distribution on the positive integers, and $\mathcal{T}_{\mathbf{p}}$ for the associated $\mathbf{p}$-tree.

\begin{proposition} \label{ProTailDist}
Let\/ $V_{1}$ and $V_{2}$ be two independent random vertices of $\mathcal{T}_{\mathbf{p}}$ chosen according to the distribution $\mathbf{p}$. Then, for all $x \geq 8$,
\begin{align}
\mathbb{P}(d(V_{1}, V_{2}) \geq x \sigma_{\mathbf{p}}^{-1} ) \leq e^{-\frac{x^{1/3}}{3\sigma_{\mathbf{p}}}} + 6e^{-\frac{x^{2/3}}{6}}. 
\end{align} 
\end{proposition}

The proof of Proposition \ref{ProTailDist} is based on the Poisson embedding described in \cite[Section 4.1]{Camarri}. Let $N$ be a homogeneous Poisson process on $[0, \infty) \times[0,1]$ of rate $1$ per unit area, with atoms $((S_{j}, U_{j}))_{j \geq 0}$ such that $0<S_{0}<S_{1}<\cdots$. Then, $(S_{j})_{j \geq 0}$ are the atoms of a homogeneous Poisson process on $[0, \infty)$ of rate $1$ per unit length, and the $(U_{j})_{j \geq 0}$ are i.i.d.\ with uniform distribution on $[0,1]$, independent of the $(S_{j})_{j \geq 0}$. Define
\begin{align}
N(t):=N([0, t] \times[0,1]) \quad \text { and } \quad N(t-):=N([0, t) \times[0,1]).
\end{align}
\noindent Then, partition the interval $[0,1]$ into sub-intervals $I_{1}, I_{2}, \ldots$ such that the length of $I_{i}$ is $p_{i}$, for $i \geq 0$. For $j \geq 0$ define
\begin{align}
Y_{j}:=\sum_{i \geq 1} i \mathbf{1}_{\{U_{j} \in I_{i}\}}.
\end{align}
\noindent So, $Y_{0}, Y_{1}, \dots$ are i.i.d.\ random variables with common distribution $\mathbf{p}$. 

From now on, assume that the $\mathbf{p}$-tree $\mathcal{T}_{\mathbf{p}}$ is constructed using the random variables defined above; see Section \ref{ptreesApp}. Let $R_{1}$ be the index of the first repeated value in the sequence $(Y_{j})_{j \geq 0}$ and let $T_{1 }:=\inf \{t \geq 0: N(t)>R_{1}\}$. Then,
as a consequence of \cite[Corollary 3]{Camarri},
\begin{align} \label{IdenDisI}
N(T_{1}-) = R_{1} \eqd d(V_{1}, V_{2})+1,
\end{align}
\noindent where $V_{1}$ and $V_{2}$ are two independent random vertices of
$\mathcal{T}_{\mathbf{p}}$ chosen according to the distribution $\mathbf{p}$. 


The proof of Proposition \ref{ProTailDist} makes use of the following result, which is a straightforward consequence of \cite[(26) and (29) in Lemma 9]{Camarri}. 
\begin{lemma} \label{LemmaTail}
For $0 \leq t < (2p_{1})^{-1}$, 
we have $\mathbb{P}(T_{1} > t) \leq e^{-\frac{t^{2}}{6}\sigma_{\mathbf{p}}^{2} }$.
\end{lemma}

\begin{proof}
Note that the right-hand side of \cite[(29) in Lemma 9]{Camarri} (with
$\boldsymbol{\theta}=\mathbf{p}$) can be written as
$(t\sigma_{\mathbf{p}})^{2} \frac{tp_{1}}{3(1-tp_{1})} \leq
\frac{t^{2}}{3}\sigma_{\mathbf{p}}^{2}$ because $0 \leq t <
(2p_{1})^{-1}$. Thus, our claim follows from \cite[(26) and (29)]{Camarri}.
\end{proof}

\begin{proof}[Proof of Proposition \ref{ProTailDist}]
It follows from \eqref{IdenDisI} that, for 
$h \ge 0$ and 
$0\le t\le h$,
\begin{align} \label{eq1Tail}
\mathbb{P}(d(V_{1}, V_{2}) \ge h) \leq  \mathbb{P}(N(t) \geq h) + \mathbb{P}(T_{1} > t).
\end{align}
\noindent On the other hand, recalling the following Chernoff-type
inequality (see, e.g., 
\cite[Corollary 2.4 and Remark 2.6]{JLR}
or
\cite[Section 2.2, particularly page 23]{Boucheron}),
we have that, for $t \leq h$,
\begin{align} \label{eq2Tail}
\mathbb{P}(N(t) \geq h) \leq e^{-t ((h/t) \log(h/t)-h/t+1)}.
\end{align}
\noindent In particular, if $h = 2t$, we have that $t ((h/t) \log(h/t)-h/t+1) = t (2 \log 2-1) \ge t/3$ and thus
\begin{align} \label{eq3Tail}
\mathbb{P}(N(t) \geq 2t) \leq e^{-\frac{t}{3}}.
\end{align}

Fix $c \geq 2$. If $0 \leq c\sigma_{\mathbf{p}}^{-1}  < (2p_{1})^{-1}$, then taking $t = c\sigma_{\mathbf{p}}^{-1}$ and $h =2t$, by Lemma \ref{LemmaTail}, \eqref{eq1Tail} and \eqref{eq3Tail} we have that
\begin{align} \label{eq4Tail}
\mathbb{P}(d(V_{1}, V_{2}) > 2c\sigma_{\mathbf{p}}^{-1}  )  \leq  e^{-\frac{c}{3\sigma_{\mathbf{p}}}} + e^{-\frac{c^{2}}{6}}.
\end{align}

Now assume that $c\sigma_{\mathbf{p}}^{-1} \geq (2p_{1})^{-1}$. For any positive real $k\geq 2$, if at least two of the variables $U_{0}, \dots, U_{\floor{k}}$ lie in the interval $I_{1}$ then $N(T_{1}-) \leq k+1$. Thus, by \eqref{IdenDisI},
\begin{align} \label{eq5Tail}
\mathbb{P}(d(V_{1}, V_{2}) \ge k) & \leq \mathbb{P}(\# \{ j \in \{0, \dots, \floor{k} \}: U_{j} \in I_{1} \} \leq 1) \nonumber \\
& = (1-p_{1})^{\floor{k}} (1-p_{1}+ (\floor{k}+1)p_{1}) \nonumber \\
& \leq e^{-p_{1}\floor{k}}(1+\floor{k}p_{1}),
\end{align}
\noindent where we have used that $\# \{ j \in \{0, \dots, \floor{k} \}: U_{j} \in I_{1} \} \sim \mathrm{Binomial}(\floor{k}+1, p_{1})$ and that $1-p_{1} \leq e^{-p_{1}}$. Since $\sigma_{\mathbf{p}} \leq 1$, it follows that for $k \geq 2c\sigma_{\mathbf{p}}^{-1} \geq 4$,
\begin{align} \label{eq6Tail}
\mathbb{P}(d(V_{1}, V_{2}) \ge k) & \leq  2kp_{1}e^{-\frac{kp_{1}}{2}},
\end{align}
\noindent where we have used the lower bound on $k$ to deduce that
$\floor{k}> k/2$ and that  
$kp_1 \geq 2p_1c\sigma_{\mathbf{p}}^{-1} \geq 1$
and so $1+\floor{k}p_{1}\leq 2kp_{1}$.  

Next, take $k = yc\sigma_{\mathbf{p}}^{-1}$, for $y \geq 4$. Recall that we
have assumed that $c\sigma_{\mathbf{p}}^{-1} \geq (2p_{1})^{-1}$ and thus,
$kp_{1} \geq y/2$. Since $z \mapsto 2ze^{-z/2}$ is decreasing for $z \geq
2$, the bound \eqref{eq6Tail} then implies that
\begin{align} \label{eq7Tail}
\mathbb{P}(d(V_{1}, V_{2}) \ge yc\sigma_{\mathbf{p}}^{-1}) & \leq  ye^{-\frac{y}{4}}.
\end{align}

To conclude the proof, we combine \eqref{eq4Tail} and \eqref{eq7Tail} to obtain a bound that does not depend on the value of $p_{1}$. Take $x \geq 8$, let $c=x^{1/3}\geq 2$ and $y = x^{2/3}\geq 4$. Then, $2c \leq x$ and $yc=x$. Thus, regardless of the value of $p_{1}$, either \eqref{eq4Tail} or \eqref{eq7Tail} applies, so we obtain that
\begin{align} \label{eq8Tail}
\mathbb{P}(d(V_{1}, V_{2}) \ge x\sigma_{\mathbf{p}}^{-1}) & =  \mathbb{P}(d(V_{1}, V_{2}) \ge yc\sigma_{\mathbf{p}}^{-1}) \nonumber \\
& \leq  e^{-\frac{c}{3\sigma_{\mathbf{p}}}} + e^{-\frac{c^{2}}{6}} + ye^{-\frac{y}{4}} \nonumber \\
& = e^{-\frac{x^{1/3}}{3\sigma_{\mathbf{p}}}} + e^{-\frac{x^{2/3}}{6}} + x^{2/3}e^{-\frac{x^{2/3}}{4}}.
\end{align}
\noindent Finally, our claim follows from \eqref{eq8Tail} and the
observation that  
$ze^{-z/4} \leq 5 e^{-z/6}$
for all $z \geq 0$. 
\end{proof}



