			\section{Congruences for ${ \bar B}_{2,9}(n)$ }
				In this section, we derive some congruences for the counting sequence $\bar{B}_{2,9}(n)$. By setting $( \ell_1,\ell_2)= (4,3)$ in \eqref{def 1}, we obtain the expression 
				\begin{equation}\label{eq11}
					\sum_{n\geq0}\bar{B}_{2,9}(n)q^n= \frac{f_2 f_2^2 f_9^2 f_{36}}{f_1^2 f_4 f_{18} f^2_{18}} .
					\end{equation}
					\begin{prop}\label{prop1}
						For all integers $n\geq0$, we have
					 \begin{equation}\label{prop1.1}
					 \bar{B}_{2,9}(6n +3)\equiv0 \pmod{4},
					 	 	 \end{equation}
					 	 	 \begin{equation}\label{prop1.2}
					 	 	  \bar{B}_{2,9}(6n +5)\equiv0 \pmod{8}.
					 	 	 \end{equation}
					\end{prop} 
		\begin{proof}[Proof of Proposition \ref{prop1}] 
				Substituting \eqref{eq5} in \eqref{eq11}, we get
				\begin{equation}\label{eq11a}
				\sum_{n\geq0}\bar{B}_{2,9}(n)q^n=\frac{f_{12}^6}{f_2 f_4 f_6^2 f_{18} f_{36}}+2q\frac{f_4 f^2_{12} f_{36}}{f_2^2 f_{18}^2}+q^2\frac{f_4^3 f_6^2 f^3_{36} }{f^3_2 f_{12}^2 f_{18}^3}. 
				\end{equation} 
				 Extracting the terms of the form $q^{2n}$ from both sides of \eqref{eq11a} and replace $q^2$ by $q$ we obtain
				\begin{equation}\label{eq12}
				\sum_{n\geq0}\bar{B}_{2,9}(2n)q^n=\frac{f_6^6}{f_1 f_2 f_3^2 f_9 f_{18}}+q\frac{f_2^3 f_3^2 f^3_{18} }{f^3_1 f_6^2 f_9^3},
			\end{equation}
		Similarly, by extracting the terms of the form  $q^{2n+1}$ from both sides of \eqref{eq11a}, dividing by $q$, and then replacing $q^2$ by $q$, we get 
		\begin{equation}\label{eq12a}
				\sum_{n\geq0}\bar{B}_{2,9}(2n +1)q^n=2\frac{f_2 f^2_6 f_{18}}{f_1^2 f_9^2}.
			\end{equation}
			 Now, substituting \eqref{eq7} in \eqref{eq12a}, we find that 
			 \begin{equation}\label{eq12b}
			 	\sum_{n\geq0}\bar{B}_{2,9}(2n +1)q^n=2\frac{f_6^6 f_9^4}{f_3^8 f_{18}^2}+4q\frac{f_6^5 f_9 f_{18}}{f_3^7} +8q^2\frac{f_2^4 f_6^4}{f_1^6 f_3^2}.
			 \end{equation} 
			 Again, extracting the terms of the form $q^{3n+i}$ where $i=0,1,2$, from both sides of \eqref{eq12b} and further   simplification, we have
			\begin{equation}\label{eq13}
				\sum_{n\geq0}\bar{B}_{2,9}(6n +1)q^n=2\frac{f_2^6 f_3^4}{f_1^8 f_6^2},
			\end{equation}
			\begin{equation}\label{eq14}
				\sum_{n\geq0}\bar{B}_{2,9}(6n +3)q^n=4\frac{f_2^5 f_3 f_6}{f_1^7},
			\end{equation}
			\begin{equation}\label{eq15}
				\sum_{n\geq0}\bar{B}_{2,9}(6n +5)q^n=8\frac{f_2^4 f_6^4}{f_1^6 f_3^2}.
			\end{equation} 
				Now, the congruence \eqref{prop1.1}  follows from \eqref{eq14} and the congruence \eqref{prop1.2} follows from \eqref{eq15}. 

		 	\end{proof} 
		 	Now, using equation \eqref{lem2.9}, we can rewrite \eqref{eq13} as
		 	\begin{equation}\label{eq13a}
		 		\sum_{n\geq0}\bar{B}_{2,9}(6n +1)q^n\equiv2 f^4_1\pmod{8}.
		 	\end{equation}


			\begin{theorem}\label{thm1}
			Let $k$ and $n$ be non-negative integers. For each $1 \leq i \leq k+1,$ let $p_1, p_2,\ldots,p_{k+1}$ be primes such that $p_i \geq 5$ and $p_i \not \equiv 1 \pmod6$. Then for any integer $j \not \equiv 0 \pmod {p_{k+1}},$ we have
			$$\bar	B_{2,9} \left( 6p_1^2 p_2^2 \cdots p_{k+1}^2 n  + (6j+ p_{k+1})p_1^2 p_2^2 \cdots p_k^2 p_{k+1} \right) \equiv0\pmod{8}.$$
		\end{theorem}

		\begin{proof}[Proof of Theorem \ref{thm1}] 
			From equation \eqref{eq13a}, we have
			\begin{equation}\label{eq800}
			\sum_{n\geq0}\bar{B}_{2,9}(6n +1)q^n\equiv2 f^4_1\pmod{8}.
		\end{equation}
		Thus, we have 
			\begin{equation}\label{eq801}
				\sum_{n=0}^{\infty} \bar{B}_{2,9}(6n+1)q^{6n+1} \equiv 2q f_6^4  \equiv2 \eta^4(6z)\pmod8 .
			\end{equation}

			%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

			By using Theorem \ref{thm2.3}, we obtain $\eta^4(6z) \in S_2(\Gamma_{0}(36), \left(\frac{6^4}{\bullet}\right)). $ Thus $\eta^4(6z) $ has a Fourier expansion i.e.
			\begin{equation}\label{eq802}
				\eta^4(6z)= q-4q^7+ 2 q^{13}+ \cdots= \sum_{n=1}^{\infty}  a(n) q^n .
			\end{equation}
			Thus, $a(n)=0$ if $n \not \equiv 1 \pmod 6,$ for all $n \geq 0.$ From \eqref{eq801} and \eqref{eq802}, comparing the coefficient of $q^{6n+1}$, we get
			\begin{equation}\label{eq803}
			\bar B_{2,9}(6n+1) \equiv 2 a(6n+1) \pmod 8.
			\end{equation}
			Since $ \eta^4(6z)$ is an Hecke eigenform (see \cite{Martin1996}), it gives
			$$\eta^4(6z)|T_p= \sum_{n=1}^{\infty} \left(a(pn)+ p \cdot  \left(\frac{6^4}{p}\right) a\left(\frac{n}{p}\right)\right) q^n = \lambda(p)\sum_{n=1}^{\infty} a(n)q^n.$$ Note that the Legendre symbol $ \left(\frac{6^4}{p}\right) = 1.$ Comparing the coefficients of $q^n$ on both sides of the above equation, we get
			\begin{equation}\label{eq804}
				a(pn)+ p \cdot a\left(\frac{n}{p}\right) = \lambda(p) a(n).
			\end{equation}
			Since $a(1)=1$ and $a(\frac{1}{p})=0,$ if we put $n=1$ in the above expression, we get $a(p)=\lambda(p).$ As $a(p)=0$ for all $p \not \equiv 1 \pmod 6$ this implies that $\lambda(p)=0$ for all $p \not \equiv 1 \pmod 6.$ From \eqref{eq804} we get that for all $p \not \equiv 1 \pmod 6 $  
			\begin{equation}\label{eq805}
				a(pn)+ p \cdot a\left(\frac{n}{p}\right) =0.
			\end{equation}
			Now, we consider two cases here. If $p \not| n,$ then 
			replacing $n$ by $pn+r$ with $\gcd(r,p)=1$ in \eqref{eq805}, we get
				\begin{equation}\label{eq806}
				a(p^2n+ pr)=0 .
			\end{equation}

		 Now, substituting $n$ by $6n-pr+1$ in \eqref{eq806} and using \eqref{eq803}, we have
		\begin{equation}\label{eq807}
			\bar	B_{2,9}\left(6p^2n +p^2 +pr(1-p^2)\right) \equiv 0 \pmod8.
		\end{equation}

			Now, we consider the second case, when $p |n.$ Here replacing $n$ by $pn$ in \eqref{eq805}, we get
			\begin{equation}\label{eq808}
				a(p^2n) =  -p \cdot a\left(n\right).
			\end{equation}
			Using \eqref{eq803} in \eqref{eq808}, we get
			\begin{equation}\label{eq809}
			\bar	B_{2,9}\left(6p^2n +p^2\right) \equiv (-p)  \bar B_{2,9} \left(6n+1\right)\pmod{8}.
			\end{equation}
		  Since $\gcd(\frac{1-p^2}{6},p) =1$, when r runs over a residue system excluding the multiples of $p$, so does $\frac{(1-p^2)r}{6}$.Thus for $p \not| j$, we can rewrite \eqref{eq807} as 
		  \begin{equation}\label{eq810}
		  	\bar	B_{2,9}\left(6p^2n +p^2 +6pj\right) \equiv 0 \pmod8.
		  \end{equation}
		  Let $p_i \geq 5$ be primes such that $p_i \not\equiv1 \pmod 6$ Further note that
		  $$ 6p_1^2 p_2^2 \cdots p_k^2 n + p_1^2 p_2^2 \cdots p_k^2 = 6p_1^2 \left(p_2^2 \cdots p_k^2 n +\frac{p_2^2\cdots p_k^2 -1}{6}\right) +p_1^2.$$
		  Repeatedly using \eqref{eq809} we get
		  \begin{equation}\label{eq811}
		  	\bar	B_{2,9} \left( 6p_1^2 p_2^2 \cdots p_k^2 n  +p_1^2 p_2^2 \cdots p_k^2  \right) 
		  	\equiv (-1)^k p_1 p_2\cdots p_k	\bar B_{2,9}(6n+1)\pmod{8}.
		  \end{equation}
		  Let $j\not \equiv 0 \pmod{ p_{k+1}}.$ Thus \eqref{eq810} and \eqref{eq811} yield
		  \begin{equation}
		  	\bar	B_{2,9} \left( 6p_1^2 p_2^2 \cdots p_{k+1}^2 n  + (6j+ p_{k+1})p_1^2 p_2^2 \cdots p_k^2 p_{k+1} \right) \equiv0\pmod{8}.
		  \end{equation}
		  This proves our claim.

		\end{proof}
