   		\bar{B}_{2,9}\left(18p^{k+1}n+18pr+ 15p \right)\equiv  (-p) \cdot \bar{B}_{2,9}\left(18p^{k-1}n+ \frac{18r+15}{p} \right) \pmod3.
   	\end{equation}
   \end{proof}



   \begin{proof}[Proof of Corollary \ref{coro4a}]Let $p$ be a prime such that $p \equiv 5 \pmod 6.$ Choose a non negative integer $r$ such that $6r+5=p^{2k-1}.$ Substituting $ k$ by $2k-1$ in \eqref{eq815a}, we obtain
   	\begin{align*}
   		\bar{B}_{2,9}\left(18p^{2k}n+ 3p^{2k} \right)&\equiv  (-p)  \bar{B}_{2,9}\left(18p^{2k-2}n+ 3p^{2k-2} \right)\\
   		& \equiv \cdots \equiv \left(-p\right)^k  \bar{B}_{2,9}(6n+1) \pmod3.
   	\end{align*}
   \end{proof}
    Next, we will use an identity due to Newman \cite{Newman1959} and will derive some results for $\bar{B}_{2,9}\left(n\right)$.
   \begin{theorem}\label{thm10a}
   	Let k be an non-negative integer.Let p be a prime number with $p$$\equiv$$1$$\pmod{6}$. If $\bar{B}_{2,9}(3p)$$\equiv$ $0$$\pmod{3}$,then for $n\geq0$ satisfying $p\nmid(6n+1)$,we have
   	\begin{align*}
   		\bar{B}_{2,9}\left( 18p^{2k+1}n +3p^{2k+1}\right)\equiv0\pmod{3}.
   	\end{align*} 
   \end{theorem}
   \begin{proof}[Proof of theorem \ref{thm10a}]
   	Equation\eqref{eq3.19} can be rewritten as 
   	\begin{equation}\label{eq815a1}
   		\sum_{n\geq0}\bar{B}_{2,9}(18n+3)q^n \equiv  f_1f_3 \pmod3.
   	\end{equation}
   	Define
   	\begin{equation}\label{eq816a}
   		\sum_{n\geq0}u(n)q^n:=f_1 f_3.
   	\end{equation}
   	Using Newman result,we find that if $p$ is a prime with p$\equiv$1$\pmod{6}$, then
   	\begin{equation}\label{eq817a}
   		u\left(pn+\frac{p-1}{6}\right)=u\left(\frac{p-1}{6}\right)u(n) - (-1)^{\frac{p-1}{2}}\left(\frac{3}{p}\right)u\left(\frac{n-\frac{p-1}{6}}{p}\right).
   	\end{equation}
   	Therefore, if  $p\nmid(6n+1)$,then $\frac{n-\frac{p-1}{6}}{p}$ is not an integer and this means
   	 \begin{equation}\label{eq818a}
   		u\left(\frac{n-\frac{p-1}{6}}{p}\right)=0.
   	\end{equation}
   	Now, from \eqref{eq817a} and \eqref{eq818a} we get that if $p\nmid(6n+1)$,then
   	\begin{equation}\label{eq819a}
   		u\left(pn+\frac{p-1}{6}\right)=u\left(\frac{p-1}{6}\right)u(n).
   	\end{equation} 
   	Hence,if $p\nmid(6n+1)$ and $u\left(\frac{p-1}{6}\right)$$\equiv0\pmod{3}$ then for $n\geq0$,
   	\begin{equation}\label{eq820a}
   		u\left(pn+\frac{p-1}{6}\right)\equiv0\pmod{3}.
   	\end{equation}
   	Replacing $n$ by $ pn+\frac{p-1}{6}$ in \eqref{eq817a}, we get
   	\begin{equation}\label{eq821a}
   		u\left(p^2n+\frac{p^2-1}{6}\right)=u\left(\frac{p-1}{6}\right)u\left(pn+\frac{p-1}{6}\right)- (-1)^{\frac{p-1}{2}}\left(\frac{3}{p}\right) u(n).
   	\end{equation}
   	From \eqref{eq821a}, we see that if $u\left(\frac{p-1}{6}\right)\equiv0\pmod{3}$, then for $n\geq0$,
   	\begin{equation}\label{eq822a}
   		u\left(p^2n+\frac{p^2-1}{6}\right)\equiv - (-1)^{\frac{p-1}{2}}\left(\frac{3}{p}\right)u(n)\pmod{3}.
   	\end{equation}
   	Now, in view of \eqref{eq822a} and mathematical induction, we find that if $u\left(\frac{p-1}{6}\right)\equiv0\pmod{3}$, then for $n\geq0$ and $k\geq0$,
   	\begin{equation}\label{eq823a}
   		u\left(p^{2k}n+\frac{p^{2k}-1}{6}\right)\equiv \left( - (-1)^{\frac{p-1}{2}}\left(\frac{3}{p}\right)\right)^ku(n)\pmod{3}.
   	\end{equation}
   	Replacing $n$ by $ pn+\frac{p-1}{6}$ in\eqref{eq823a} and using \eqref{eq820a},we deduce that if  $p\nmid(6n+1)$ and $u\left(\frac{p-1}{6}\right)$$\equiv0\pmod{3}$ then for $n\geq0$ and $k\geq0$,
   	\begin{equation}\label{eq824a}
   		u\left(p^{2k+1}n+\frac{p^{2k+1}-1}{6}\right)\equiv0\pmod{3}.
   	\end{equation}
   	Now from \eqref{eq815a1} and \eqref{eq816a} we see that for $n\geq0$,
   	\begin{equation}\label{eq825a}
   		\bar{B}_{2,9}(18n+3)\equiv u(n)\pmod{3}.
   	\end{equation}
   	Hence, the theorem \eqref{thm10a} follows from \eqref{eq825a} and \eqref{eq824a}.


   \end{proof}

