    Next we will be discussing about a more general function 
   ${ \bar B}_{5,2^{t}}(n)$ for $t\geq3$ and studying some properties of  ${ \bar B}_{5,2^{t}}(n)$.

   \section{Congruences for ${ \bar B}_{5,2^{t}}(n)$}  In this section,we derive some new congruences for the counting sequence $\bar{B}_{5,2^{t}}(n)$.By setting $(\ell_1,\ell_2)= (5,2^{t})$ in \eqref{def 1},we get an expression of the form 
   \begin{equation} \label{eq4.1}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(n)q^n=\frac{ f_2 f_5^2 f^2_{2^t}f_{5.2^{t+1}}}{f_1^2 f_{10} f_{2^{t+1}} f^2_{5.2^t}}.
   \end{equation}
   Employing \eqref{eq10} into \eqref{eq4.1} we find that
   \begin{equation}\label{eq4.2}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(n)q^n=\frac{ f^2_{2^t} f_{5.2^{t+1}} f^2_8 f_{20}^4 }{f_2^3 f_{10} f_{2^{t+1}} f^2_{5.2^t} f^2_{40}} +2q\frac{f_4^3 f^2_{2^t} f_{5.2^{t+1}}f_{20} }{f_2^4 f_{2^{t+1}}f^2_{5.2^t}}+q^2\frac{f_4^6 f_{10} f^2_{2^t}f_{5.2^{t+1}} f^2_{40} }{f_2^5 f_{2^{t+1}} f_8^2 f^2_{5.2^t} f^2_{20}}.
   \end{equation}
   Now, extracting the even and odd powers from both sides of \eqref{eq4.2} we arrive at
   \begin{equation}\label{eq4.3}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(2n)q^n=\frac{ f^2_{2^{t-1}} f_{5.2^{t}} f^2_4 f_{10}^4 }{f_1^3 f_{5} f_{2^{t}} f^2_{5.2^{t-1}} f^2_{20}} +q\frac{f_2^6 f_{5} f^2_{2^{t-1}}f_{5.2^{t}} f^2_{20} }{f_1^5 f_{2^{t}} f_4^2 f^2_{5.2^{t-1}} f^2_{10}},
   \end{equation}
   \begin{equation}\label{eq4.4}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(2n+1)q^n=2\frac{f_2^3 f^2_{2^{t-1}} f_{5.2^{t}}f_{10} }{f_1^4 f_{2^{t}}f^2_{5.2^{t-1}}}.
   \end{equation}
   Applying \eqref{eq2} in \eqref{eq4.4} and extracting the even and odd powers from both sides of the resulting equation, we find respectively
   \begin{equation}\label{eq4.5}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(4n+1)q^n=2\frac{f_2^{14} f^2_{2^{t-2}} f_{5.2^{t-1}}f_{5} }{f_1^{11} f_{2^{t-1}}f^2_{5.2^{t-2}} f_4^4},
   \end{equation}

   \begin{equation}\label{eq4.6}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(4n+3)q^n=8\frac{f_2^2 f^2_{2^{t-2}} f_{5.2^{t-1}}f_4^4 }{f_1^7 f_{2^{t-1}}f^2_{5.2^{t-2}} }.
   \end{equation}
   Now using equation \eqref{lem2.9}, \eqref{eq4.5} can be rewritten as
   \begin{equation}\label{eq4.7}
   	\sum_{n\geq0}\bar{B}_{5,2^{t}}(4n+1)q^n \equiv 2 f_1f_5 \pmod8. 
   \end{equation} 
   \begin{theorem}\label{thm4.8}
   	Let $k$ and $n$ be non-negative integers. For each $1 \leq i \leq k+1,$ let $p_1, p_2,\ldots,p_{k+1}$ be primes such that $p_i \not \equiv 1 \pmod4$. Then for any integer $j \not \equiv 0 \pmod {p_{k+1}},$ we have
   	$$\bar{B}_{5,2^{t}} \left( 4p_1^2 p_2^2 \cdots p_k^2 p_{k+1}^2 n + (4j+p_{k+1}) p_1^2 p_2^2 \cdots p_k^2 p_{k+1}  \right) \equiv 0 \pmod8 .$$
   \end{theorem}

   \begin{proof}[Proof of Theorem \ref{thm4.8}]
   		From equation \eqref{eq4.7}, we have
   		\begin{equation}\label{eq800b}
   			\sum_{n\geq0}\bar{B}_{5,2^t}(4n +1)q^n\equiv2 f_1 f_5\pmod{8}.
   		\end{equation}
   		Thus, we have
   		\begin{equation}\label{eq801b}
   			\sum_{n=0}^{\infty} \bar{B}_{5,2^t}(4n+1)q^{4n+1} \equiv 2\eta(4z) \eta(20z)\pmod8 .
   		\end{equation}

   		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

   		By using Theorem \ref{thm2.3}, we obtain $\eta(4z)\eta(20z) \in S_1(\Gamma_{0}(80), \left(\frac{-20}{\bullet}\right)). $ Thus $\eta(4z)\eta(20z) $ has a Fourier expansion i.e.
   		\begin{equation}\label{eq802b}
   			\eta(4z)\eta(20z)= q-q^5-q^{9}+q^{25} \cdots= \sum_{n=1}^{\infty}  b(n) q^n .
   		\end{equation}
   		Thus, $b(n)=0$ if $n \not \equiv 1 \pmod 4,$ for all $n \geq 0.$ From \eqref{eq801b} and \eqref{eq802b}, comparing the coefficient of $q^{4n+1}$, we get
   		\begin{equation}\label{eq803b}
   			\bar B_{5,2}(4n+1) \equiv 2 b(4n+1) \pmod 4.
   		\end{equation}
   		Since $ \eta(4z)\eta(20z)$ is a Hecke eigenform (see \cite{Martin1996}), it gives
   		$$\eta(4z)\eta(20z)|T_p= \sum_{n=1}^{\infty} \left(b(pn)+    \left(\frac{-20}{p}\right) b\left(\frac{n}{p}\right)\right) q^n = \lambda(p)\sum_{n=1}^{\infty} b(n)q^n.$$ Note that the Legendre symbol $ \left(\frac{6^4}{p}\right) = 1.$ Comparing the coefficients of $q^n$ on both sides of the above equation, we get
   		\begin{equation}\label{eq804b}
   			b(pn)+  \left(\frac{-20}{p}\right)b\left(\frac{n}{p}\right) = \lambda(p) b(n).
   		\end{equation}
   		Since $b(1)=1$ and $b(\frac{1}{p})=0,$ if we put $n=1$ in the above expression, we get $b(p)=\lambda(p).$ As $b(p)=0$ for all $p \not \equiv 1 \pmod 4$ this implies that $\lambda(p)=0$ for all $p \not \equiv 1 \pmod 4.$ From \eqref{eq804b} we get that for all $p \not \equiv 1 \pmod 4 $  
   		\begin{equation}\label{eq805b}
   			b(pn)+ \left(\frac{-20}{p}\right) b\left(\frac{n}{p}\right) =0.
   		\end{equation}
   		Now, we consider two cases here. If $p \not| n,$ then 
   		replacing $n$ by $pn+r$ with $\gcd(r,p)=1$ in \eqref{eq805b}, we get
   		\begin{equation}\label{eq806b}
   			b(p^2n+ pr)=0 .
   		\end{equation}


   		Now substituting $n$ by $4n-pr+1$ in\eqref{eq806b} and using\eqref{eq803b}, we have
   		\begin{equation}\label{eq807b}
   			\bar	B_{5,2^t}\left(4p^2n +p^2 +pr(1-p^2)\right) \equiv 0 \pmod8.
   		\end{equation}

   		Now, we consider the second case, when $p |n.$ Here replacing $n$ by $pn$ in \eqref{eq805b}, we get
   		\begin{equation}\label{eq808b}
   			b(p^2n) =  -p \left(\frac{-20}{p}\right) b\left(n\right).
   		\end{equation}
   		Similarly, substituting $n$ by $4n+1$ in \eqref{eq808b} and using \eqref{eq803b}, we get
   		\begin{equation}\label{eq809b}
   			\bar B_{5,2^t}\left(4p^2n + p^2\right) \equiv(-1) \left(\frac{-20}{p}\right) \bar B_{5,2^t} \left(4n+1\right)\pmod{8}.
   		\end{equation}
   		Since $\gcd(\frac{1-p^2}{4},p) =1$, when r runs over a residue system excluding the multiples of $p$, so does $\frac{(1-p^2)r}{4}$.Thus for $p \not| j$ ,we can rewrite \eqref{eq807b} as 
   		\begin{equation}\label{eq810b}
   			\bar	B_{5,2^t}\left(4p^2n +p^2 +4pj\right) \equiv 0 \pmod8.
   		\end{equation}
   		Let $p_i \geq 5$ be primes such that $p_i \not\equiv1 \pmod 4$ Further note that
   		$$ 4p_1^2 p_2^2 \cdots p_k^2 n = 4p_1^2 \left(p_2^2 \cdots p_k^2 n +\frac{p_2^2\cdots p_k^2 -1}{4}\right) +p_1^2.$$
   		Repeatedly using \eqref{eq810b} we get
   		\begin{equation}\label{eq811b}
   			\bar	B_{5,2^t} \left( 4p_1^2 p_2^2 \cdots p_k^2 n  +p_1^2 p_2^2 \cdots p_k^2  \right) 
   			\equiv \left((-1)\left( \frac{-20}{p}\right)\right)^k 	\bar B_{5,2^t}(4n+1)\pmod{8}.
   		\end{equation}
   		Let $j\not \equiv 0 \pmod{ p_{k+1}}.$ Thus \eqref{eq810b} and \eqref{eq811b} yield
   		\begin{equation}
   			\bar	B_{5,2^t} \left( 4p_1^2 p_2^2 \cdots p_{k+1}^2 n  + (4j+ p_{k+1})p_1^2 p_2^2 \cdots p_k^2 p_{k+1} \right) \equiv0\pmod{8}.
   		\end{equation}
   		This proves our claim.

   	\end{proof}





   If we put $p_1= p_2= \cdots= p_{k+1}= p$ in Theorem \ref{thm4.8}, then we obtain the following corollary. 
   \begin{coro}\label{coro4.9}
   	Let $k$ and $n$ be non-negative integers. Let $p \geq 5$ be a prime such that $p \equiv 3 \pmod4.$ Then we have
   	$$\bar{B}_{5,2^{t}}\left(4p^{2k+2}n +4p^{2k+1}j +p^{2k+2} \right) \equiv 0 \pmod 8$$ whenever $ j \not \equiv 0 \pmod p.$
   \end{coro}
   Further, if we substitute $p=7,$ $j\not \equiv 0 \pmod 7$ and $k=0$ in Corollary \ref{coro4.9}, we get
   $$\bar{B}_{5,2^{t}}\left(196n +28j+49 \right) \equiv 0 \pmod 8.$$ If we put $j=1$ in the above congruence,then we get $$\bar{B}_{5,2^t}\left(196n+77 \right) \equiv 0 \pmod 8.$$
   Furthermore, we prove the following multiplicative formulae for $\bar{B}_{5,2^{t}}(n)$  modulo $8$.
   \begin{theorem}\label{thm4.10}
   	Let $k$ be a positive integer and $p$ be a prime number such that $ p\equiv3\pmod 4.$ Let $r$ be a non-negative integer such that $p$ divides $4r+3,$ then
   	\begin{align*}
   		\bar{B}_{5,2^{t}}\left(4p^{k+1}n+4pr+ 3p \right)\equiv f(p) \cdot \bar{B}_{5,2^t}\left(4p^{k-1}n+ \frac{4r+3}{p} \right) \pmod8.
   	\end{align*}
 Where $f(p)$ is define by \begin{align*}
   		f(p)= \begin{cases}
   			-1 & \hbox{if} \quad  p\equiv3,7\pmod{20}; \\
   			1 & \hbox{if} \quad  p\equiv11,19\pmod{20}.
   		\end{cases}
   	\end{align*}
   \end{theorem}
   \begin{proof}[Proof of theorem \ref{thm4.10}]
 From \eqref{eq805b}, we get that for any prime $p \equiv 3\pmod 4$
\begin{equation}\label{eq812b}
	b(pn)=(-1)\left(\frac{-20}{p}\right) b\left(\frac{n}{p}\right) 
\end{equation}  Replacing $n$ by $4n+3,$ we obtain
\begin{equation}\label{eq813b}
	b(4pn+3p)=(-1)\left(\frac{-20}{p}\right) b\left(\frac{4n+3}{p}\right). 
\end{equation}
Next replacing $n$ by $p^kn+r$ with $p \nmid r$ in \eqref{eq813b}, we obtain
\begin{equation}\label{eq814b}
	b\left(4\left(p^{k+1}n+pr+\frac{3p-1}{4}\right)+1 \right)=(-1)\left(\frac{-20}{p}\right) b\left(4\left(p^{k-1}n+\frac{4r+3-p}{4p}\right)+1 \right).
\end{equation}
Note that $\frac{3p-1}{4}$ and $\frac{4r+3-p}{4p}$are integers. Using \eqref{eq814b} and \eqref{eq803b}, we get
\begin{equation}\label{eq815b}
	\bar{B}_{5,2^t}\left(4p^{k+1}n+p(4r+3) \right)\equiv (-1)\left(\frac{-20}{p}\right)  \bar{B}_{5,2^t}\left(4p^{k-1}n+ \frac{4r+3}{p} \right) \pmod8.
\end{equation}
\end{proof}





   \begin{coro}\label{coro4.11} 
   	Let $k$ be a positive integer and $p$ be a prime number such that $p \equiv 3\pmod 4.$ Then
   	\begin{align*}
   		\bar{B}_{5,2^{t}}\left(p^{2k}(4n+1) \right) \equiv f(p)^k  \bar{B}_{5,2^{t}}(4n+1) \pmod8.
   	\end{align*}
   \end{coro}


   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



   \begin{proof}[Proof of Corollary \ref{coro4.11}] Let $p$ be a prime such that $p \equiv 3 \pmod 4.$ Choose a non negative integer $r$ such that $4r+3=p^{2k-1}.$ Substituting $ k$ by $2k-1$ in \eqref{eq815b}, we obtain
   		\begin{align*}
   			\bar{B}_{5,2^t}\left(p^{2k}(4n+1) \right)&\equiv  (-1)\left(\frac{-20}{p}\right)  \bar{B}_{5,2^t}\left(p^{2k-2}(4n+1) \right)\\
   			& \equiv \cdots \equiv \left( (-1)\left(\frac{-20}{p}\right)\right)^k \bar{B}_{5,2^t}(4n+1) \pmod8.
   		\end{align*}
   		Now the corollary \eqref{coro4.11} follows from the above congruence.
   	\end{proof}

   Next, we will use an identity due to Newman and will derive congruence relation for $\bar{B}_{5,2^t}\left(n\right)$
   \begin{theorem}\label{thm4.12} 
   	Let k be an non-negative integer.Let p be a prime number with $p\equiv1\pmod{4}$. If $\bar{B}_{5,2^t}(p)$$\equiv0\pmod{8}$, then for $n\geq0$ satisfying $p\nmid(4n+1)$, we have
   	\begin{align*}
   		\bar{B}_{5,2^t}\left( 4p^{2k+1}n +p^{2k+1}\right)\equiv0\pmod{8}.
   	\end{align*} 
   \end{theorem}
   \begin{proof}[Proof of theorem \ref{thm4.12}]
   	Recall the equation \eqref{eq4.7}
   	\begin{equation}\label{eq4.7a}
   		\sum_{n\geq0}\bar{B}_{5,2^{t}}(4n+1)q^n \equiv 2 f_1f_5 \pmod8. 
   	\end{equation}
   	Define
   	\begin{equation}\label{eq4.8}
   		\sum_{n\geq0}g(n)q^n:=f_1 f_5
   	\end{equation}
   	Using Newman result, we find that if $p$ is a prime with p$\equiv$1$\pmod{4}$, then
   	\begin{equation}\label{eq4.9}
   		g\left(pn+\frac{p-1}{4}\right)=g\left(\frac{p-1}{4}\right)g(n) - (-1)^{\frac{p-1}{2}}\left(\frac{5}{p}\right)g\left(\frac{n-\frac{p-1}{4}}{p}\right).
   	\end{equation}
   	Therefore, if  $p\nmid(4n+1)$, then $\frac{n-\frac{p-1}{4}}{p}$ is not an integer and this means
   	 \begin{equation}\label{eq4.10}
   		g\left(\frac{n-\frac{p-1}{4}}{p}\right)=0.
   	\end{equation}
   	Now, from \eqref{eq4.9} and \eqref{eq4.10} we get that if $p$$\nmid$$(4n+1)$,then
   	\begin{equation}\label{eq4.11}
   		g\left(pn+\frac{p-1}{4}\right)=g\left(\frac{p-1}{4}\right)g(n). 
   	\end{equation} 
   	Hence,if $p\nmid(4n+1)$ and $g\left(\frac{p-1}{4}\right)$$\equiv0\pmod{8}$, then for $n\geq0$ we have 
   	\begin{equation}\label{eq4.12}
   		g\left(pn+\frac{p-1}{4}\right)\equiv0\pmod{8}.
   	\end{equation}
   	Replacing $n$ by $ pn+\frac{p-1}{4}$ in \eqref{eq4.9},we get
   	\begin{equation}\label{eq4.13}
   		g\left(p^2n+\frac{p^2-1}{4}\right)=g\left(\frac{p-1}{4}\right)g\left(pn+\frac{p-1}{4}\right)- (-1)^{\frac{p-1}{2}}\left(\frac{5}{p}\right) g(n).
   	\end{equation}
   	From \eqref{eq4.13},we see that if $g\left(\frac{p-1}{4}\right)\equiv0\pmod{8}$, then for $n\geq0$
   	\begin{equation}\label{eq4.14}
   		g\left(p^2n+\frac{p^2-1}{4}\right)\equiv - (-1)^{\frac{p-1}{2}}\left(\frac{5}{p}\right)g(n)\pmod{8}.
   	\end{equation}
   	Now, in view of \eqref{eq4.14} and mathematical induction, we find that if $g\left(\frac{p-1}{4}\right)\equiv0\pmod{8}$, then for $n\geq0$ and $k\geq0$,
   	\begin{equation}\label{eq4.15}
   		g\left(p^{2k}n+\frac{p^{2k}-1}{4}\right)\equiv \left( - (-1)^{\frac{p-1}{2}}\left(\frac{5}{p}\right)\right)^kg(n)\pmod{8}.
   	\end{equation}
   	Replacing $n$ by $ pn+\frac{p-1}{4}$ in \eqref{eq4.15} and using \eqref{eq4.12},we deduce that if  $p\nmid(4n+1)$ and $g\left(\frac{p-1}{4}\right)$$\equiv0\pmod{4}$, then for $n\geq0$ and $k\geq0$,
   	\begin{equation}\label{eq4.16}
   		g\left(p^{2k+1}n+\frac{p^{2k+1}-1}{4}\right)\equiv0\pmod{8}.
   	\end{equation}
   	Now, from \eqref{eq4.7a} and \eqref{eq4.8} we see that for $n\geq0$,
   	\begin{equation}\label{eq4.17}
   		\bar{B}_{5,2^{t}}(4n+1)\equiv2g(n)\pmod{8}.
   	\end{equation}
   	Hence, the theorem \eqref{thm4.12} follows from \eqref{eq4.17} and \eqref{eq4.16}.


   \end{proof}




    	\section{Congruences for ${ \bar B}_{5,2}(n)$}  In this section,we derive some congruences for the counting sequence $\bar{B}_{5,2}(n)$.By setting $(\ell_1,\ell_2)= (5,2)$ in \eqref{def 1}, we get an expression of the form 
    	\begin{equation}\label{eq16}
    	\sum_{n\geq0}\bar{B}_{5,2}(n)q^n=\frac{ f_2^3 f_5^2 f_{20}}{f_1^2 f_4  f^3_{10}}. 
    \end{equation}
    \begin{prop}\label{prop5}
    	\begin{equation}\label{eq16.1}
    		\bar{B}_{5,2}(4n+3)\equiv 0 \pmod{4}.
    	\end{equation}
     \end{prop}
    \begin{proof}[Proof of Theorem \ref{prop5}] 
    	 Using \eqref{eq10} in \eqref{eq16}, we get 
    	\begin{equation}\label{eq17}
    	\sum_{n\geq0}\bar{B}_{5,2}(n)q^n=\frac{f_8^2 f^5_{20}}{f_2 f_4 f^3_{10} f^2_{40}} +2q \frac{f^2_4 f^2_{20}}{f^2_2 f^2_{10}}+q^2 \frac{f^5_4 f^2_{40}}{f^3_2 f^2_8 f_{10} f_{20}}.
    	\end{equation} Now,  extracting terms of the form $q^{2n+i} $ for $i=0,1$ and replace $q^2$ by $q$, we obtain the following generating functions:
    	\begin{equation}
    		\sum_{n\geq0}\bar{B}_{5,2}(2n)q^n=\frac{f_4^2 f^5_{10}}{f_1 f_2 f^3_5 f^2_{20}} +q\frac{f^5_2 f^2_{20}}{f^3_1 f^2_4 f_{5} f_{10}},
    	\end{equation}
    	\begin{equation}\label{eq4.4b1}
    		\sum_{n\geq0}\bar{B}_{5,2}(2n+1)q^n= 2 \frac{f^2_2 f^2_{10}}{f^2_1 f^2_{5}}.
    	\end{equation}
    	Using equation \eqref{lem2.9}, \eqref{eq4.4b1} can be written as
    	\begin{equation}\label{eq4.4a}
    		\sum_{n\geq0}\bar{B}_{5,2}(2n+1)q^n\equiv 2 f_2 f_{10} \pmod{4}.
    	\end{equation}
    	Now, extracting terms of the form $q^{2n+i} $ for $i=0,1$ and replace $q^2$ by $q$, we obtain the following generating function
    	\begin{equation}\label{eq4.4b}
    		\sum_{n\geq0}\bar{B}_{5,2}(4n+1)q^n\equiv 2 f_1 f_{5} \pmod{4}.
    	\end{equation}
    	\begin{equation}\label{eq4.4c}
    		\sum_{n\geq0}\bar{B}_{5,2}(4n+3)\equiv 0 \pmod{4}.
    	\end{equation}
    	Hence, proposition \eqref{prop5} follows from \eqref{eq4.4c}.
    \end{proof}.
    		\begin{theorem}\label{thm18}
    		Let $k$ and $n$ be non-negative integers. For each $1 \leq i \leq k+1,$ let $p_1, p_2,\ldots,p_{k+1}$ be primes such that $p_i \not \equiv 1 \pmod4$. Then for any integer $j \not \equiv 0 \pmod {p_{k+1}},$ we have
    		$$\bar{B}_{5,2} \left(4 p_1^2 p_2^2 \cdots p_k^2 p_{k+1}^2 n + (4j+p_{k+1}) p_1^2 p_2^2 \cdots p_k^2 p_{k+1}  \right) \equiv 0 \pmod4 .$$
    	\end{theorem}

    	\begin{proof}[Proof of Theorem \ref{thm18}] 
    		From equation \eqref{eq4.4b}, we have
    		\begin{equation}\label{eq800b1}
    			\sum_{n\geq0}\bar{B}_{5,2}(4n +1)q^n\equiv2 f_1 f_5\pmod{4}.
    		\end{equation}
    		Thus, we have
    		\begin{equation}\label{eq801b1}
    			\sum_{n=0}^{\infty} \bar{B}_{5,2}(4n+1)q^{4n+1} \equiv 2\eta(4z) \eta(20z)\pmod4 .
    		\end{equation}

    		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    		By using Theorem \ref{thm2.3}, we obtain $\eta(4z)\eta(20z) \in S_1(\Gamma_{0}(80), \left(\frac{-20}{\bullet}\right)). $ Thus $\eta(4z)\eta(20z) $ has a Fourier expansion i.e.
    		\begin{equation}\label{eq802b1}
    		\eta(4z)\eta(20z)= q-q^5-q^{9}+q^{25} \cdots= \sum_{n=1}^{\infty}  a(n) q^n .
    		\end{equation}
    		Thus, $a(n)=0$ if $n \not \equiv 1 \pmod 4,$ for all $n \geq 0.$ From \eqref{eq801b} and \eqref{eq802b1}, comparing the coefficient of $q^{4n+1}$, we get
    		\begin{equation}\label{eq803b1}
    			\bar B_{5,2}(4n+1) \equiv 2 a(4n+1) \pmod 4.
    		\end{equation}
    		Since $ \eta(4z)\eta(20z)$ is a Hecke eigenform (see \cite{Martin1996}), it gives
    		$$\eta(4z)\eta(20z)|T_p= \sum_{n=1}^{\infty} \left(a(pn)+    \left(\frac{-20}{p}\right) a\left(\frac{n}{p}\right)\right) q^n = \lambda(p)\sum_{n=1}^{\infty} a(n)q^n.$$  Comparing the coefficients of $q^n$ on both sides of the above equation, we get
    		\begin{equation}\label{eq804b1}
    			a(pn)+  \left(\frac{-20}{p}\right)a\left(\frac{n}{p}\right) = \lambda(p) a(n).
    		\end{equation}
    		Since $a(1)=1$ and $a(\frac{1}{p})=0,$ if we put $n=1$ in the above expression, we get $a(p)=\lambda(p).$ As $a(p)=0$ for all $p \not \equiv 1 \pmod 4$ this implies that $\lambda(p)=0$ for all $p \not \equiv 1 \pmod 4.$ From \eqref{eq804b1} we get that for all $p \not \equiv 1 \pmod 4 $  
    		\begin{equation}\label{eq805b1}
    			a(pn)+ \left(\frac{-20}{p}\right) a\left(\frac{n}{p}\right) =0.
    		\end{equation}
    		Now, we consider two cases here. If $p \not| n,$ then 
    		replacing $n$ by $pn+r$ with $\gcd(r,p)=1$ in \eqref{eq805b1}, we get
    		\begin{equation}\label{eq806b1}
    			a(p^2n+ pr)=0 .
    		\end{equation}


    		 Substituting $n$ by $4n-pr+1$ in \eqref{eq806b1} and using \eqref{eq803b1}, we have
    		\begin{equation}\label{eq807b1}
    		 \bar	B_{5,2}\left(4p^2n +p^2 +pr(1-p^2)\right) \equiv 0 \pmod4.
    		\end{equation}

    		Now, we consider the second case, when $p |n.$ Here replacing $n$ by $pn$ in \eqref{eq805b1}, we get
    		\begin{equation}\label{eq808b1}
    			a(p^2n) =  -\left(\frac{-20}{p}\right) a\left(n\right).
    		\end{equation}
    		Similarly, substituting $n$ by $4n+1$ in \eqref{eq808b1} and using \eqref{eq803b1}, we get
    		\begin{equation}\label{eq809b1}
    		\bar B_{5,2}\left(4p^2n + p^2\right) \equiv(-1) \left(\frac{-20}{p}\right) \bar B_{5,2} \left(4n+1\right)\pmod{4}.
    		\end{equation}
    		Since $\gcd(\frac{1-p^2}{4},p) =1$, when r runs over a residue system excluding the multiples of $p$, so does $\frac{(1-p^2)r}{4}$.Thus for $p \not| j$ ,we can rewrite \eqref{eq807b1} as 
    		\begin{equation}\label{eq810b1}
    			 \bar	B_{5,2}\left(4p^2n +p^2 +4pj\right) \equiv 0 \pmod4.
    		\end{equation}
    		Let $p_i \geq 5$ be primes such that $p_i \not\equiv1 \pmod 4$ Further note that
    		$$ 4p_1^2 p_2^2 \cdots p_k^2 n +p_1^2 p_2^2 \cdots p_k^2 = 4p_1^2 \left(p_2^2 \cdots p_k^2 n +\frac{p_2^2\cdots p_k^2 -1}{4}\right) +p_1^2.$$
    		Repeatedly using \eqref{eq809b1} we get
    			\begin{equation}\label{eq811b1}
    			\bar	B_{5,2} \left( 4p_1^2 p_2^2 \cdots p_k^2 n  +p_1^2 p_2^2 \cdots p_k^2  \right) 
    			\equiv \left((-1)\left( \frac{-20}{p}\right)\right)^k 	\bar B_{5,2}(4n+1)\pmod{4}.
    		\end{equation}
    		Let $j\not \equiv 0 \pmod{ p_{k+1}}.$ Thus \eqref{eq810b1} and \eqref{eq811b1} yield
    		\begin{equation}
    				\bar	B_{5,2} \left( 4p_1^2 p_2^2 \cdots p_{k+1}^2 n  + (4j+ p_{k+1})p_1^2 p_2^2 \cdots p_k^2 p_{k+1} \right) \equiv0\pmod{4}.
    		\end{equation}
    		This proves our claim.

    		\end{proof}
    		If we put $p_1= p_2= \cdots= p_{k+1}= p$ in Theorem \ref{thm18}, then we obtain the following corollary. 
    		\begin{coro}\label{coro3b}
    			Let $k$ and $n$ be non-negative integers. Let $p \geq 5$ be a prime such that $p \equiv 3 \pmod4.$ Then we have
    			$$\bar{B}_{5,2}\left(4p^{2k+2}n +4p^{2k+1}j +p^{2k+2} \right) \equiv 0 \pmod 4$$ whenever $ j \not \equiv 0 \pmod p.$
    		\end{coro}
    		Further, if we substitute $p=7,$ $j\not \equiv 0 \pmod 7$  and $k=0$ in Corollary \ref{coro3b}, we get
    		$$\bar{B}_{5,2}\left(196n +28j+49 \right) \equiv 0 \pmod 4.$$ If we put $j=1,$ then we get $$\bar{B}_{5,2}\left(196n+77 \right) \equiv 0 \pmod 4.$$
    		Furthermore, we prove the following multiplicative formulae for $\bar{B}_{5,2}(n)$  modulo $4$.
    		\begin{theorem}\label{thm9b}
    			Let $k$ be a positive integer and $p$ be a prime number such that $ p \equiv 3 \pmod 4.$ Let $r$ be a non-negative integer such that $p$ divides $4r+3,$ then
    			\begin{align*}
    				\bar{B}_{5,2}\left(4p^{k+1}n+4pr+ 3p \right)\equiv f(p) \cdot \bar{B}_{5,2}\left(4p^{k-1}n+ \frac{4r+3}{p} \right) \pmod4.
    			\end{align*}
    			Where $f(p)$ is defined by \begin{align*}
    				f(p)= \begin{cases}
    					-1 & \hbox{if} \quad  p\equiv3,7\pmod{20}; \\
    					 1 & \hbox{if} \quad  p\equiv11,19\pmod{20}.
    				\end{cases}
    				\end{align*}
    		\end{theorem}

    		\begin{coro}\label{coro4b} 
    			Let $k$ be a positive integer and $p$ be a prime number such that $p \equiv 3\pmod 4.$ Then
    			\begin{align*}
    				\bar{B}_{5,2}\left(p^{2k}(4n+1) \right) \equiv f(p)^k  \bar{B}_{5,2}(4n+1) \pmod4.
    			\end{align*}
    		\end{coro}


    		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    		\begin{proof}[Proof of Theorem \ref{thm9b}] From \eqref{eq805b1}, we get that for any prime $p \equiv 3\pmod 4$
    			\begin{equation}\label{eq812b1}
    					a(pn)=(-1)\left(\frac{-20}{p}\right) a\left(\frac{n}{p}\right) 
    			\end{equation}  Replacing $n$ by $4n+3,$ we obtain
    			\begin{equation}\label{eq813b1}
    				a(4pn+3p)=(-1)\left(\frac{-20}{p}\right) a\left(\frac{4n+3}{p}\right). 
    			\end{equation}
    			Next replacing $n$ by $p^kn+r$ with $p \nmid r$ in \eqref{eq813b1}, we obtain
    			\begin{equation}\label{eq814b1}
    				a\left(4\left(p^{k+1}n+pr+\frac{3p-1}{4}\right)+1 \right)=(-1)\left(\frac{-20}{p}\right) a\left(4\left(p^{k-1}n+\frac{4r+3-p}{4p}\right)+1 \right).
    			\end{equation}
    			Note that $\frac{3p-1}{4}$ and $\frac{4r+3-p}{4p}$are integers. Using \eqref{eq814b1} and \eqref{eq803b1}, we get
    			\begin{equation}\label{eq815b1}
    				\bar{B}_{5,2}\left(4p^{k+1}n+p(4r+3) \right)\equiv (-1)\left(\frac{-20}{p}\right)  \bar{B}_{5,2}\left(4p^{k-1}n+ \frac{4r+3}{p} \right) \pmod4.
    			\end{equation}
    		\end{proof}



    		\begin{proof}[Proof of Corollary \ref{coro4b}]Let $p$ be a prime such that $p \equiv 3 \pmod 4.$ Choose a non negative integer $r$ such that $4r+3=p^{2k-1}.$ Substituting $ k$ by $2k-1$ in \eqref{eq815b1}, we obtain
    			\begin{align*}
    				\bar{B}_{5,2}\left(p^{2k}(4n+1) \right)&\equiv  (-1)\left(\frac{-20}{p}\right)  \bar{B}_{5,2}\left(p^{2k-2}(4n+1) \right)\\
    				& \equiv \cdots \equiv \left( (-1)\left(\frac{-20}{p}\right)\right)^k \bar{B}_{5,2}(4n+1) \pmod4.
    			\end{align*}
    			Now the corollary \eqref{coro4b} follows from the above congruence.
    		\end{proof}






























