		   \section{Congruences for ${ \bar B}_{8,3}(n)$}  In this section, we derive some new congruences for the counting sequence $\bar{B}_{8,3}(n)$. By setting $(\ell_1,\ell_2)= (8,3)$ in \eqref{def 1},we get an expression of the form 
		  \begin{equation} \label{eq23}
		  	\sum_{n\geq0}\bar{B}_{8,3}(n)q^n=\frac{ f_2 f_3^2 f_8^2 f_{48}}{f_1^2 f_6 f_{16} f^2_{24}}.
		  \end{equation}
		  \begin{theorem}\label{thm7.1}
		  		For all integers $n\geq0$,we have
		  	\begin{equation}\label{subthm7.2}
		  		\bar{B}_{8,3}(36n +33)\equiv0 \pmod{3}.
		  	\end{equation}

		  \end{theorem}
		 \begin{proof}[Proof of theorem \ref{thm7.1}]

		  Employing \eqref{eq10b} in equation \eqref{eq23}, we get an equation of the form
		  \begin{equation}\label{eq24}
		  	\sum_{n\geq0}\bar{B}_{8,3}(n)q^n=\frac{f^4_4 f_8 f^2_{12} f_{48}}{f^4_2 f_{16} f^3_{24}} +2q\frac{f_4 f_6 f^3_8 f_{48}}{f^3_2 f_{12} f_{16} f_{24}}.
		  \end{equation}
		  Now, extracting the terms of the form $q^{2n+i} $ for $i=0,1$ and replacing $q^2$ by $ q$, we obtain the following:
		  \begin{equation}
		  	\sum_{n\geq0}\bar{B}_{8,3}(2n)q^n=\frac{f^4_2 f_4 f^2_6 f_{24}}{f^4_1 f_{8} f^3_{12}},
		  \end{equation} and
		  \begin{equation}\label{eq25}
		  	\sum_{n\geq0}\bar{B}_{8,3}(2n+1)q^n=2\frac{f_2 f_3 f^3_4 f_{24}}{f^3_1 f_{6} f_{8} f_{12}}.
		  \end{equation}
		  Now, using \eqref{lem2.9} with $p=3,k=1,m=1,4,8$ respectively in \eqref{eq25}, we find that:
		  \begin{equation}
	    	\sum_{n\geq0}\bar{B}_{8,3}(2n+1)q^n\equiv2\frac{f_2 f_3 f^3_4 f^3_8}{f^3_1 f^3_2 f_{8} f^3_4}\pmod{3}.
		  \end{equation}
		  Therefore, we can say that
		  \begin{equation}\label{eq26}
		  		\sum_{n\geq0}\bar{B}_{8,3}(2n+1)q^n\equiv2\frac{f^2_8}{ f^2_2 }\pmod{3}.
		  \end{equation}
		  Again, extracting the terms of the form $q^{2n+i} $ for $i=0,1$ and replace $q^2$ by $ q$, we obtain the following:
		  \begin{equation}\label{eq27}
		  	\sum_{n\geq0}\bar{B}_{8,3}(4n+1)q^n\equiv2\frac{f^2_4}{ f^2_1 }\pmod{3}.
		  \end{equation}
		  \begin{equation}\label{eq28}
		  	\sum_{n\geq0}\bar{B}_{8,3}(4n+3)q^n\equiv0\pmod{3}.
		  \end{equation}

		  Now, equation \eqref{eq27} can be rewritten as
		  \begin{equation}\label{eq30}
		  	\sum_{n\geq0}\bar{B}_{8,3}(4n+1)q^n\equiv2\frac{f^3_4}{ f^3_1 } \frac{f_1}{f_4}\equiv\frac{f_{12}}{ f_3 } \frac{f_1}{f_4}\pmod{3}.
		  \end{equation}
		  Using \eqref{eq10d} in \eqref{eq30}, we derive
		  \begin{equation}\label{eq31}
		  		\sum_{n\geq0}\bar{B}_{8,3}(4n+1)q^n\equiv2\frac{f_6 f_9 f_{18}}{ f_3 f^2_{12}}-2q\frac{ f^4_{18}}{f^2_9 f^2_{12}}-2q^2\frac{f^2_6 f_9 f^3_{36}}{ f_3 f^3_{12} f^2_{18}}\pmod{3}. 
		  \end{equation}
		  Now, extracting terms of the form $q^{3n +i} $ where $i=0,1,2$ and replacing $q^3$ by $q$, we get
		  \begin{equation}\label{eq32}
		  	\sum_{n\geq0}\bar{B}_{8,3}(12n+1)q^n\equiv2\frac{f_2 f_3 f_6 }{ f_1 f^2_4}\pmod{3},
		  \end{equation} and
		  \begin{equation}
		  	\sum_{n\geq0}\bar{B}_{8,3}(12n+5)q^n\equiv \frac{ f^4_6 }{ f^2_3 f^2_4}\pmod{3},
		  \end{equation} and
		  \begin{equation}\label{eq6.14}
		  	\sum_{n\geq0}\bar{B}_{8,3}(12n+9)q^n\equiv \frac{ f^2_2 f_3 f^3_{12} }{ f_1 f^3_4 f^2_6}\pmod{3}.
		  \end{equation}
		    Employing \eqref{lem2.9} in \eqref{eq6.14}, we see that

		   \begin{equation}\label{eq6.15}
		  	\sum_{n\geq0}\bar{B}_{8,3}(12n+9)q^n\equiv \frac{ f^2_2 f_3 f^2_{12} }{ f_1 f^2_6}\pmod{3}.
		  \end{equation}
		  Now, substituting \eqref{eq8} in \eqref{eq6.15}, we get
		  \begin{equation}\label{eq6.16}
		  	\sum_{n\geq0}\bar{B}_{8,3}(12n+9)q^n\equiv \frac{ f^2_9  f^2_{12} }{ f_6 f_{18}} +q\frac{f_3 f^2_{12} f^2_{18}}{f^2_6 f_9}\pmod{3},
		  \end{equation}
		  Again, extracting  the terms of the form $q^{3n+i}$ with $i=0,1,2$ and replacing $q^3$ by $ q,$ we see that
		  \begin{equation}\label{eq6.17}
		  		\sum_{n\geq0}\bar{B}_{8,3}(36n+9)q^n\equiv \frac{ f^2_3  f^2_{4} }{ f_2 f_{6}}\pmod{3}, 
		  \end{equation}
		  \begin{equation}\label{eq6.18}
		  		\sum_{n\geq0}\bar{B}_{8,3}(36n+21)q^n\equiv \frac{f_1 f^2_{4} f^2_{6}}{f^2_2 f_3}\pmod{3},
		  \end{equation}
		  \begin{equation}\label{eq6.19}
		  		\sum_{n\geq0}\bar{B}_{8,3}(36n+33)q^n\equiv0\pmod{3}.
		  \end{equation}
		  Hence, \eqref{subthm7.2} follows from \eqref{eq6.19}.

		\end{proof}




	  \section{Congruences for ${ \bar B}_{4,3^{t}}(n)$}  In this section,we derive some new congruences for the counting sequence $\bar{B}_{4,3^{t}}(n)$, $\forall t\geq2$. By setting $(\ell_1,\ell_2)= (4,3^{t})$ in \eqref{def 1},we get an expression of the form 
	 \begin{equation} \label{eq9.1}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(n)q^n=\frac{ f_2 f_4^2 f^2_{3^t}f_{8.3^{t}}}{f_1^2 f_{8} f_{2.3^{t}} f^2_{4.3^t}}.
	 \end{equation}
	  \begin{theorem}\label{thm8.1}
	 	For all integers $n\geq1$,we have
	 	\begin{equation}\label{subthm8.2}
	 		\bar{B}_{4,3^{t}}(3n)\equiv0 \pmod{8}.
	 	\end{equation}
	 	and for all integers $n\geq0$,we have
	 	\begin{equation}\label{subthm8.3}
	 		\bar{B}_{4,3^{t}}(6n+4)\equiv0 \pmod{4},
	 	\end{equation}
	 	\begin{equation}\label{subthm8.4}
	 		\bar{B}_{4,3^{t}}(12n+7)\equiv0 \pmod{4},
	 	\end{equation}
	 		\begin{equation}\label{subthm8.5}
	 		\sum_{n\geq0}\bar{B}_{4,3^{t}}(12n+1)q^n\equiv2f_1^2 \pmod{4},
	 	\end{equation}
	 	\begin{equation}\label{subthm8.6}
	      \bar{B}_{4,3^{t}}(3n+2)\equiv0 \pmod{4}.
	 	\end{equation}
	 \end{theorem}
	 \begin{proof}[Proof of theorem \ref{thm8.1}]

	 Employing \eqref{eq7} and \eqref{eq8.2} in \eqref{eq9.1} and extracting the terms of the form  $q^{3n+i} $ for $i=0,1,2$ and replace $q^3$ by $q$, we obtain the followings:

	 \begin{equation} \label{eq9.2}
	 		\sum_{n\geq0}\bar{B}_{4,3^{t}}(3n)q^n=\frac{ f^4_2 f_3^6 f^2_{12} f^2_{3^{t-1}}f_{8.3^{t-1}}}{f_1^8 f^3_{6} f_{24} f_{2.3^{t-1}} f^2_{4.3^{t-1}}}-8q^2\frac{f_2^2 f_4 f_6^3 f_{24}^2 f^2_{3^{t-1}} f_ {8.3^{t-1}}}{f_1^6 f_8 f_{12} f_{2.3^{t-1}}f^2_{4.3^{t-1}} },
	\end{equation}
	 \begin{equation}\label{eq9.3}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(3n +1)q^n=2\frac{ f^3_2 f_3^3 f^2_{12} f^2_{3^{t-1}}f_{8.3^{t-1}}}{f_1^7 f_{24} f_{2.3^{t-1}} f^2_{4.3^{t-1}}}-2q\frac{f_2^4 f_3^6 f_4  f_{24}^2 f^2_{3^{t-1}} f_ {8.3^{t-1}}}{f_1^8 f_6^3 f_8 f_{12} f_{2.3^{t-1}}f^2_{4.3^{t-1}} },
	 \end{equation}
	 \begin{equation}\label{eq9.4}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(3n +2)q^n=4\frac{ f^2_2 f_6^3 f^2_{12} f^2_{3^{t-1}}f_{8.3^{t-1}}}{f_1^6 f_{24} f_{2.3^{t-1}} f^2_{4.3^{t-1}}}-4q\frac{f_2^3 f_3^3 f_4  f_{24}^2 f^2_{3^{t-1}} f_ {8.3^{t-1}}}{f_1^7 f_8 f_{12} f_{2.3^{t-1}}f^2_{4.3^{t-1}} }.
	 \end{equation}
	 Hence, equation \eqref{subthm8.6} follows from \eqref{eq9.4}.
	 Using equation \eqref{lem2.9} , the equation \eqref{eq9.2} can be rewritten as
	 \begin{equation}\label{eq9.5}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(3n)q^n\equiv1\pmod{8}.
	 \end{equation}
	 Therefore, we obtain
	 \begin{equation}\label{eq9.6}
 	 	\bar{B}_{4,3^{t}}(3n)\equiv0\pmod{8}  \forall n\geq1.
	 \end{equation}
	 Hence, the proof of \eqref{subthm8.2} is done from \eqref{eq9.6}.

    	Using equation \eqref{lem2.9} in \eqref{eq9.3}, we find that
	 \begin{equation}\label{eq9.7}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(3n +1)q^n\equiv2\frac{f_3^3}{f_1} -2q\frac{f^3_{12}}{f_4}\pmod{4}.
	 \end{equation}
	 Employing \eqref{eq10f} in \eqref{eq9.7}, we get   
	 \begin{equation}\label{eq9.7a}
	 		\sum_{n\geq0}\bar{B}_{4,3^{t}}(3n +1)q^n\equiv2\frac{f_4^3 f_6^2}{f_2^2 f_{12}}\equiv2f_4^2\pmod{4}.
	 \end{equation}
	 Extracting odd and even terms from both sides of equation \eqref{eq9.7a} we get
	 \begin{equation}\label{eq9.8}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(6n +4)q^n\equiv0\pmod{4},
	 \end{equation}
	 and \begin{equation}\label{eq9.9}
	 	\sum_{n\geq0}\bar{B}_{4,3^{t}}(6n +1)q^n\equiv2 f_2^2\pmod{4}.
	 \end{equation}
	Again, extracting odd and even terms from \eqref{eq9.9}, we find that
	\begin{equation}\label{eq9.10}
		\bar{B}_{4,3^{t}}(12n +7)\equiv0\pmod{4},
	\end{equation}
	and \begin{equation}\label{eq9.11}
			\sum_{n\geq0}\bar{B}_{4,3^{t}}(12n +1)q^n\equiv2 f_1^2\pmod{4}.
	\end{equation}
	Therefore, theorem \eqref{subthm8.3}, \eqref{subthm8.4} and \eqref{subthm8.5} follows from equation \eqref{eq9.8}, \eqref{eq9.10} and \eqref{eq9.11} respectively.
	\end{proof}
	 \section{Congruences for ${ \bar B}_{3,2^{t}}(n)$}  In this section, we derive some new congruences for the counting sequence $\bar{B}_{3,2^{t}}(n)$,$\forall t\geq2$. By setting $(\ell_1,\ell_2)= (3,2^{t})$, in \eqref{def 1},we get an expression of the form 
	\begin{equation} \label{eq10.1}
		\sum_{n\geq0}\bar{B}_{3,2^{t}}(n)q^n=\frac{ f_2 f_3^2 f^2_{2^t}f_{3.2^{t+1}}}{f_1^2 f_{6} f_{2^{t+1}} f^2_{3.2^t}}.
	\end{equation}
	\begin{theorem}\label{thm9.1}
		For all integers $n\geq0$,we have
		\begin{equation}\label{eq9.1a}
			 \bar{B}_{3,2^{t}}(16n+6)\equiv0\pmod{8},
		\end{equation}
		\begin{equation}\label{eq9.2a}
	    \bar{B}_{3,2^{t}}(16n+10)\equiv0\pmod{8},
		\end{equation}
		\begin{equation}\label{eq9.3a}
	   	\bar{B}_{3,2^{t}}(16n+14)\equiv0\pmod{8}.
		\end{equation}
	\end{theorem}
	\begin{proof}[Proof of theorem \ref{thm9.1}]
	Employing \eqref{eq10b} into \eqref{eq10.1}, we find that
	\begin{equation}\label{eq10.2}
		\sum_{n\geq0}\bar{B}_{3,2^{t}}(n)q^n=\frac{ f_4^4 f^2_{12} f^2_{2^t} f_{3.2^{t+1}} }{f_2^4 f_8 f_{24} f_{2^{t+1}} f^2_{3.2^t} } +2q\frac{f_4 f_6 f_8 f_{24} f^2_{2^t} f_{3.2^{t+1}} }{f_2^3 f_{12} f_{2^{t+1}}f^2_{3.2^t}}.
	\end{equation}
	Extracting terms of the form $q^{2n+i}$ where $i=0,1$ from \eqref{eq10.2}, we can see that-
	\begin{equation}\label{eq10.3}
		\sum_{n\geq0}\bar{B}_{3,2^{t}}(2n)q^n=\frac{ f_2^4 f^2_{6} f^2_{2^{t-1}} f_{3.2^{t}} }{f_1^4 f_4 f_{12} f_{2^{t}} f^2_{3.2^{t-1}} },
	\end{equation} and
	\begin{equation}\label{eq10.4}
			\sum_{n\geq0}\bar{B}_{3,2^{t}}(2n+1)q^n=2\frac{f_2 f_3 f_4 f_{12} f^2_{2^{t-1}} f_{3.2^{t}} }{f_1^3 f_{6} f_{2^{t}}f^2_{3.2^{t-1}}}.
	\end{equation}
	Now, if we substitute equation \eqref{eq2} in \eqref{eq10.3} and extract  terms of the form $q^{2n+i}$ where $i=0,1$ we will get

	\begin{equation}\label{eq10.5}
			\sum_{n\geq0}\bar{B}_{3,2^{t}}(4n)q^n=\frac{f_2^{13} f^2_3  f^2_{2^{t-2}} f_{3.2^{t-1}} }{f_1^{10} f_4^4 f_{6} f_{2^{t-1}}f^2_{3.2^{t-2}}},
	\end{equation}
	\begin{equation}\label{eq10.6}
			\sum_{n\geq0}\bar{B}_{3,2^{t}}(4n+2)q^n=4\frac{f_2 f^2_3 f_4^4 f^2_{2^{t-2}} f_{3.2^{t-1}} }{f_1^{6}  f_{6} f_{2^{t-1}}f^2_{3.2^{t-2}}}.
	\end{equation}
	Using equation \eqref{lem2.9} in \eqref{eq10.6}, we will get 
	\begin{equation}\label{eq10.7}
		\sum_{n\geq0}\bar{B}_{3,2^{t}}(4n+2)q^n\equiv4f_4^3\pmod{8}.
	\end{equation}
	Again,if we extract  terms of the form $q^{4n+i}$ where $i=0,1,2,3$ we will get 
	\begin{equation}\label{eq10.8}
		\sum_{n\geq0}\bar{B}_{3,2^{t}}(16n+2)q^n\equiv4f_1^3\pmod{8},
	\end{equation}
	\begin{equation}\label{eq10.9}
	 \bar{B}_{3,2^{t}}(16n+6)\equiv0\pmod{8},
	\end{equation}
	 \begin{equation}\label{eq10.10}
	 \bar{B}_{3,2^{t}}(16n+10)\equiv0\pmod{8},
	 \end{equation}
	\begin{equation}\label{eq10.11}
		\bar{B}_{3,2^{t}}(16n+14)\equiv0\pmod{8}.
	\end{equation}
	Hence, the theorem \eqref{thm9.1} follows directly from \eqref{eq10.9}, \eqref{eq10.10} and \eqref{eq10.11}.

\end{proof}	 


