In the following, we will use the notation 
$A\lesssim B$ (respectively $A\gtrsim B$, $A\simeq B$) whenever there exists a uniform constant $C>0$ such that $A\le CB$ (respectively $A\ge CB$, respectively $A\lesssim B$ and $A\gtrsim B$).  When $A\lesssim B$ and $A\gtrsim B$, we write $A\simeq B$.

We will use the notation ``$\log $"  for the holomorphic logarithm, and the notation ``$\ln$" for the real one.



\section{Theorem \ref{Bergman}: Proof and related statements}

We refer to \cite{BGS1} for the proof of the sufficiency of Conditions \eqref{meanB} and \eqref{logB}. We start with a lemma, which completes Lemma 2 of \cite{BGS1}, and which will have as corollary that the theorem is sharp for $P$ and $P^+$. \\
We recall the definition of the weight $\omega.$
\begin{equation}
\omega(z):=1+\ln_+\left(\frac 1{\Im m(z)}\right)+ \ln_+(|z|),\quad z\in\C_+.\end{equation}
\begin{lemma}\label{ineq-fund}
Let $\zeta\in \C_+$. For $|\zeta-i|>1,$, the following inequality holds:
 \begin{equation}
    I(\zeta):= \int_{\C_+} \left||z-\overline \zeta|^{-2} -|z+i|^{-2}\right|dV(z)\simeq \omega(\zeta).
 \end{equation}
\end{lemma}
  \begin{proof}
  The above bound has been proved in \cite{BGS1}. We come back to the proof in order to give the bound below. We write $z=x+iy$ and $\zeta=\xi+i\lambda.$
From the continuity of the integral as a function of $\zeta$, it is bounded below on any compact set of $\C_+$. So it is sufficient to prove the inequality for $\lambda<\varepsilon<1$ and for $|\zeta|>M.$ We have two cases to consider.
 \begin{enumerate}
      \item 
If $\zeta$ is such that $\lambda<1/4$: we  write that $I(\zeta)$ is bounded below by the integral over the domain $E_0:=\{z\in \C_+, |x-\xi|<y+\lambda, y<1/4.\}$ On this set, the inequality  $|z-\overline \zeta|^{2}\leq 2(y+\lambda)^2<1/2$ holds so that
 $$\int_{E_0} |z-\overline \zeta|^{-2} dV(z)\geq \int_0^{1/4} \frac{dy}{y+\lambda}=\ln\left(1+\frac 1{4\lambda}\right),$$
 while  $$\int_{E_0} |z+i|^{-2} dV\leq  1/4.$$
So, for $\lambda<1/4$, we have
  $$I(\zeta)\gtrsim 1+\ln_+(\lambda^{-1}).$$

   \item If $|\zeta|>M:$ we  write that $I(\zeta)$ is bounded below by the integral on the domain $E_1:=\{z\in \C_+, |z+i|<\frac 14|\zeta-i|, |z|>1\}$. 
      The function to integrate is bounded below by $c|z+i|^{-2},$ so that
      $$I(\zeta)\gtrsim \int_{E_1}|z|^{-2} dV (z)\gtrsim \ln(\frac 14|\zeta|-2).$$
        Here, we used the fact that the half disc $\{|z|<\frac 14|\zeta|-2, y>0\}$ is contained in $E_1$. So finally, we find that 
       $I(\zeta)\gtrsim 1+ \ln_+(|\zeta|)$
      for $|\zeta|\geq M$ large enough. This completes the proof of the lemma.
  \end{enumerate}
  \end{proof}
  \begin{remark}\label{LemmaKmod}
  The same is valid for the kernel $K_{\mod}(z,\zeta)$ as well.
  \end{remark}
 As a corollary, we find a family of functions $f$ non negative outside a fixed compact set and  for which the $L^1$ norm of $Pf$ is equivalent to the  norm of $f$ in the weighted  space $L^1_\omega(\C_+)$. This is given in the following proposition.

 \begin{proposition}
For each $\zeta=\xi+i\lambda \in \C_+$ such that $|\zeta-i|>1,$ let $$f_\zeta:=\frac{4}{\pi \lambda^2}\chi_{B(\zeta, \lambda/2)}-\frac {4}{\pi}\chi_{B(i, 1/2)}.$$ 
Here $\chi_E$ stands for the characteristic function of $E$.
Then $$\|f_\zeta\|_1=2,\;\text{ while }\;
\|Pf_\zeta\|_1\simeq \omega(\zeta).$$
In particular,
$$\|Pf_\zeta\|_1\simeq \|f_\zeta\|_{L^1_\omega}.$$
Constants may be chosen independent of $\zeta.$
\end{proposition}
\begin{proof}
As a consequence of the mean value property of holomorphic functions $Pf_\zeta (z)=\frac 1 \pi\left[(z-\overline \zeta)^{-2} -(z+i)^{-2}\right].$ The result follows from Lemma \ref{ineq-fund}.  
\end{proof}
This proposition proves that Condition \eqref{logB} is optimal.\\

We have the same proposition with $P^+$ in place of $P$.
\begin{proposition}
We have 
$\|f_\zeta\|_1+\|P^+f_\zeta\|_1\simeq \omega(\zeta).$
Constants may be chosen independent of $\zeta.$
\end{proposition}
\begin{proof}
We use again Remark \ref{LemmaKmod}. We prove that the difference between $P^+f_\zeta$ and $P_{\mod} f_\zeta$ is bounded in $L^1$-norm. We prove that $\frac 4{\pi \lambda^2 }P^+(\chi_{B(\zeta, \lambda/2)})-|K(z, \zeta)|$ has an $L^1$ norm bounded by a uniform constant. As the other  terms in $f_\zeta$ is analogous, it will give the result.
But for $\zeta'\in B(\zeta, \lambda/2),$ the function  $|K(\cdot, \zeta)|-|K(\cdot, \zeta')|$ is bounded, up to a constant,  by $\frac{\lambda}{|z-\overline \zeta|^3}, $. This quantity  is uniformly in $L^1$. It ends the proof.
\end{proof}


Next, we prove that the condition \eqref{meanB} is necessary for $Pf$ to be integrable. 
 \begin{proposition} \label{zeroP}
Let $f\in L^1(\mathbb C_+) $ 
 such that $Pf$ (resp. $P^+f$) is in $L^1(\C_+)$.  Then $f$ has integral $0$.
\end{proposition}
\begin{proof}
We prove it for $Pf$ in $L^1$. The same proof works when $P^+f$ is in $L^1$. We write 
$$z ^2 Pf(z)=c\int_{\C_+} \frac{f(\zeta) dV(\zeta)}{(1-\overline \zeta/z)^2}$$
and we use Lebesgue Dominated Convergence Theorem. When $|x|<y$, as $|1- \overline \zeta/z|>y/|z|>1/2 $, we get for $|z|$ tending to $\infty$ with $|x|<y$
$$z ^2 Pf(z) \longrightarrow \int _{\C_+} f(\zeta) dV(\zeta).$$
Since $z\mapsto z^{-2}$ is not integrable over this domain, this forces the integral to be $0$ if $Pf$ is integrable.
\end{proof}




\begin{remark} As $z\mapsto \frac{\omega^k(z)}{z^2}$ is not integrable, Proposition \ref{zeroP} remains valid when the assumptions are weakened and only assume that $Pf$ (resp. $P^+f$) is integrable for the weighted measure $\omega^{k} dV$  for $k\geq -1$.  
\end{remark}


We are now ready to finish the proof of the necessity conditions of Theorem \ref{Bergman}.  Let $f\in L^1(\C_+)$ be a non negative function outside a compact set of $\C_+$ such that 
 $P^+(f)$ belongs to $L^1(\C_+)$. Without loss of generality, we can assume  that $f$ is non negative for $\zeta\notin B(i, 1/2)$ and has norm in $L^1$ equal to $1.$ We already know that $f$ has integral $0$ so that
 $$P^+f(z)=\int (|K(z, \zeta)|-|K(z, i)|) f(\zeta) dV(\zeta).$$ 
 Moreover, since 
 $\displaystyle \int (|K(z, \zeta)|-|K(z, i)|) f(\zeta) dV(\zeta)$ is in $L^1$ and $f_{-}$ has compact support, we can replace $f$ by $f_{+}. $ So the question becomes: {\sl Let $f\in L^1$ be a non negative function such that $$P^+_{\mod} f=\int (|K(\cdot, \zeta)|-|K(\cdot, i)|) f(\zeta) dV(\zeta)\in L^1(\C_+)$$ then prove that $f$ satisfies \eqref{logB}.}  The proof is given in the next two lemmas

 The first step mimics the proof of Lemma \ref{ineq-fund}. We give its proof for completeness, even if the proof is already  given in \cite{BGS1}.
 \begin{lemma}\label{boundary}
Under the assumptions that $f$ is non negative and $P^+_\mod f$ is in $L^1$, we have $$\int_{\C_+ } f(\zeta) \ln_+\left(\frac{1}{\Im m\zeta}\right)dV(\zeta)<\infty.$$
\end{lemma}
\begin{proof}
 If we reduce the integral of $|P_{\mod}^+f(z)|$ to the one over the set $y<1,$ then the integral coming from the second term is bounded since 
 $$\int_{\{x+iy\in \C_+ ; y<1\}}\int_{\C_+} |K(z, i)| f(\zeta) dV(\zeta)dV(z)\lesssim \int_0^1 (y+1)^{-1}dy \leq \ln (2).$$
 Finally by difference, we get that 
 $$\int_{\{x+iy\in \C_+ ; y<1\}} \int_{\C_+} |K(z, \zeta)| f(\zeta) dV(\zeta)dV(z)<\infty.$$
We integrate first in $z$ and find that
$$\int_{\C_+} f(\zeta) \ln\left(1+\frac{1}{\Im m\zeta}\right)dV(\zeta)<\infty.$$
 \end{proof}
 \begin{lemma}\label{far}
Under the previous assumptions on $f$, we have $$\int_{\C_+ } |f(\zeta)| \ln_+(|\zeta|)dV(\zeta)<\infty.$$
\end{lemma}
\begin{proof}
 We only consider the integral of $P^+_{\mod} f$ over the set $$F:=\{z=x+iy ; |x|\leq y, y>1\}.$$ We write for $z\in F$, 
$$P^+_{\mod} f(z):=I_1(z)+I_2(z)+I_3(z),$$
where $$I_j(z):=\int_{E_j}K^+_{\mod}(z, \zeta)f(\zeta) dV(\zeta).$$ We will choose $E_j, j=1,2, 3$ so that $\int_F |I_j(z)|dV(z)\lesssim 1$ for $j=2, 3$, while 
$K^+_{mod}(z, \zeta)$ is non positive on $E_1$. More precisely, we take 
\begin{eqnarray*}
E_1&:=&\left\{|z+i|< \frac 14 |\zeta-i|\right\}\\
E_2&:=&\left\{\frac 14 |\zeta-i|<|z+i|<4|\zeta-i|\right\}\\  E_3&:=&\left\{ |z+i|>4|\zeta-i|\right\}.
\end{eqnarray*}
Under the first condition, the second term of $K^+_{\mod}$ is the largest one, which gives the non positivity. Under the second condition, since $|K^+_{\mod}(z, \zeta)|\lesssim y^{-2},$ its integral in $z$ on a domain of the form $R\leq |z+i|\leq CR$ is uniformly bounded. Finally, in the third domain, we use the fact that the kernel is given by a difference, which  is bounded, up to a constant,  by $|\zeta-i|\times |z+i|^{-3}.$ Its integral in $z$ is uniformly bounded. So these last two terms are bounded under the unique assumption that $f$ is integrable. Finally, under the assumption that $P^+_{\mod} f$ is integrable, we get 
 \begin{equation}\label{crucial}\int_{F}\int_{|z+i|< \frac 14 |\zeta-i|}|z+i|^{-2} f(\zeta)dV(\zeta)dV(z)<\infty.\end{equation}
We integrate first in $z$ to find that
$$\int_{\C_+} f(\zeta) \ln_+(|\zeta-i|)dV(\zeta)<\infty.$$
This finishes the proof.
 \end{proof}


