\begin{proposition}\label{prop:factor}
Let $f$ be an atom given by (\ref{eq:atom}). There exist $g\in A_{\omega^{l}}^1(\C_+)$ and $\theta \in \mathcal{B}_{\omega^{k}}(\mathbb{C}_+)$, $k<1$ such that $$f=g\times \theta$$
with 
$$\Vert g\Vert_{A_{\omega^{l}}^1}\times \Vert \theta\Vert_{\mathcal B_{\omega^{k}}}\lesssim 1.$$
\end{proposition}
\begin{proof}
We choose $\theta=\theta_w^{-k+1}$ where the function $\theta_w$ is defined in Lemma \ref{lem: testTheta}. In this case, the function $g$ is given as follows.

$$g:z\mapsto \frac{(\Im m (w))\omega^{1-(l+k)} (w)}{(z-\overline w)^3\theta(z)}$$ which is a well defined holomorphic function in the upper half plane. It remains to prove that the inequality $\|g\|_{L_{\omega^l}^1}\lesssim 1$ holds. When $\omega(w)\simeq 1,$ then $\theta\simeq 1$ and there is nothing to prove.  We will now use the two notations
$\omega_1(z)=\ln\left(e+\frac{1}{\Im mz}\right)$ and $\omega_2(z)=\ln(e+|z|)$ and use Lemma \ref{lem:weightforellirudin} for these weights. We distinguish two cases.
\begin{itemize}
    \item [(i)] Case $v<1/2$ and $\ln(v^{-1})\simeq \omega(w)\simeq \omega_1(w)$  We proceed as in \cite{BGS1}. We
cover the upper half plane by the union of $E_j'$s, with $E_0:=Q_w$ the Carleson square centered at $w$, and $E_j:=Q_{w_{j}}\setminus Q_{w_{j-1}}, j\geq 1.$ Here $w=u+iv$ and $w_j=u+i2^j v$.

We recall that for $z\in E_j,$ we have $|z-\overline   w|\leq 2\Im m(w_j)$. Hence using Lemma \ref{lem: testTheta}, we obtain
\begin{eqnarray*}
     \left|\theta(z)\right|&\gtrsim& \left(1-\ln 2+\ln_+\left(\frac{1}{|z-\overline w|} \right)\right)^{-k+1}\\
    &\gtrsim& \left(\ln\left(e+\frac 1{\Im m(w_j)} \right)\right)^{-k+1} =\omega_1^{-k+1}(w_j).
\end{eqnarray*}  
Lemma  \ref{lem:weightforellirudin} allows to get
$$\int|g(z)|\omega^l(z)dV(z)\lesssim\sum_j \frac{\omega_1^{1-(l+k)}(w)}{\omega_1^{1-(l+k)}(w_j)}2^{-2j}.$$
To conclude, in the case $1-(l+k)>0$, we use the fact that $\omega_1(w_j)\geq\omega_1(w)-j\ln 2$, and in the case $1-(l+k)\leq 0$, the fact that $\omega_1(w)\geq \omega_1(w_j)$.
\item [(ii)]\; Case $\omega(w)\simeq \ln(e+|w|)=\omega_2(w)$.\\ As $|\theta(z)|\gtrsim \left(\ln(e+|z|)\right)^{-k+1}=\omega_2^{-k+1}(z)$, the estimate follows as in the previous case.
\end{itemize}
\end{proof}

This factorization of atoms can be used to have a weak factorization of the space $A^1_{\omega^{l+k-1}}(\C_+)$ as well, as in \cite{BGS1}.
