\section{Introduction}
In this paper we study the asymptotics of the induced
Fubini\textendash Study metrics by Kodaira maps of high tensor powers
of a singular Hermitian line bundle over a Riemann surface
under the assumption that the curvature has singularities
of Poincar\'e type at a finite set.
We show namely that the {\it quotient} of the induced
Fubini\textendash Study metrics by Kodaira maps of high tensor powers
of the line bundle and the Poincar\'e model near
the singularity grows polynomially uniformly on
a neighborhood of the singularity as the tensor power
tends to infinity.
In \cite{AMM16,AMM21}, Auvray, Ma and Marinescu obtained
a weighted estimate in the $C^m$-norm near the punctures
for the difference of the global Bergman kernel and of the
 Bergman kernel of the Poincar\'e model near the singularity,
 uniformly in the tensor power $p$ of the given line bundle;
and an application in arithmetic geometry 
is the sharp uniform asymptotics %with the leading term $p^{3/2}$,
of the sup-norm of automorphic (cusp) forms 
associated with a Fuchsian group of the first
kind which was studied by Ullmo, Kramer $\dots$
\cite{MiUll98, JK04, fjk}.
%the precise coefficient of the leading term $p^{3/2}$ and is sharp
Moreover, in \cite{AMM22} they also show that the quotient
of the global Bergman kernel and the Bergman kernel of
the Poincar\'e model near the singularity tends to one
up to $\mathcal{O}(p^{-\infty})$.
This paper is an application of the results and the method
of \cite{AMM21, AMM22}.


Following \cite{Tian}, an important application of the
expansion of the Bergman kernel is the convergence of
the induced Fubini\textendash Study forms by Kodaira maps.
For more works on Bergman kernels,
cf. \cite{Catlin, DLM06, MM08, Zeld, Finski24}, and  we refer the readers
  to the book \cite{MM07} for a comprehensive study of
  Bergman kernels.
Donaldson \cite{Donaldson} uses the expansion of
the Bergman kernel to study the relation between constant
scalar curvature K\"ahler metrics and Chow stability.
Coming to our context, an interesting problem is the
relation between the existence of special complete/singular
metrics and the stability of the pair $(X,D)$ where
$D$ is a smooth divisor of a compact K\"ahler manifold $X$;
 see e.g. the suggestions of \cite[Section 3.1.2]{Szeke}
 and \cite{LW},  for the case of ``asymptotically hyperbolic
  K\"ahler metrics'', which naturally generalize to higher
  dimensions the complete metrics $\omega$ studied here.

\vskip 10pt
We place ourselves in the setting of \cite{AMM21}
which we describe now.
Let $\overline\Sigma$ be a compact Riemann surface and let
$D=\{a_1,\ldots,a_N\}\subset\overline\Sigma$ be a finite set.
We consider the punctured Riemann surface
$\Sigma = \overline{\Sigma}\smallsetminus D$ and a Hermitian
 form
$\omega_{\Sigma}$ on $\Sigma$.
Let $L$ be a holomorphic line bundle on $\overline{\Sigma}$,
and let $h$ be a singular Hermitian metric on $L$ such that:

   \begin{enumerate}[label = (\greek*)]
    \item\label{alpha} $h$ is smooth over $\Sigma$,
and for all $j=1,\ldots,N$, there is a trivialization of $L$
 in the complex neighborhood $\overline{V_j}$ of $a_j$ in
 $\overline{\Sigma}$, with associated coordinate $z_j$
 such that $|1|_{h}^2(z_{j})= \big|\!\log(|z_j|^2)\big|$;
                    %
    \item\label{beta} there exists $\varepsilon>0$ such that the
(smooth) curvature $R^L$ of $h$ satisfies
$iR^L\geq\varepsilon\omega_{\Sigma}$ over $\Sigma$
and moreover, $iR^L=\omega_{\Sigma}$
on $V_j:=\overline{V_j}\smallsetminus\{a_j\}$;
in particular, $\omega_{\Sigma} = \omega_{\D^*}$
in the local coordinate $z_j$ on $V_j$
and $(\Sigma, \omega_{\Sigma})$ is complete.
   \end{enumerate}
Here $\omega_{\D^*}$ denotes the Poincar\'{e} metric on the
punctured unit disc $\D^* = \D \setminus\{0\}$, where $\D$
is the unit disc, normalized as follows:
%---
\begin{equation}   \label{eq1}
\omega_{\D^*} := \frac{idz\wedge d\overline{z}}
{|z|^2\log^2(|z|^2)}\,\cdot
\end{equation}
%---
For $p\geq1$, let $h^p:=h^{\otimes p}$ be the metric induced
 by $h$ on $L^p\vert_{\Sigma}$,
where $L^p:=L^{\otimes p}$. We denote by
$H^0_{(2)}(\Sigma,L^p)$
the space of ${\bL}^2$-holomorphic sections of $L^p$
relative to the metrics $h^p$ and $\omega_\Sigma$
endowed with the obvious inner product.
By \cite[(6.2.17)]{MM07}, the sections from
$H^0_{(2)}(\Sigma, L^p)$ extend to holomorphic sections of
$L^p$ over $\overline\Sigma$ which vanish on $D$.
In particular, the dimension $d_p$ of $H^0_{(2)}(\Sigma, L^p)$
is finite.


%The sections from
%$H^0_{(2)}(\Sigma,L^p)$
%extend to holomorphic sections of $L^p$ over $\overline\Sigma$,
%i.\,e.,  (see \cite[(6.2.17)]{MM07})
%%---
%\begin{equation}\label{eq3}
%H^0_{(2)}(\Sigma,L^p)\subset
%H^0\big(\overline\Sigma,L^p\big).
%\end{equation}
%%---
%In particular, the dimension $d_p$ of
%$H^0_{(2)}(\Sigma,L^p)$ is finite.

We denote by $B_p(\LargerCdot)$ the Bergman kernel function
of the orthogonal projection $B_{p}$ from the space
of $\bL^{2}$-sections of $L^{p}$ over $\Sigma$ onto
$H^0_{(2)}(\Sigma,L^p)$.
If $\{S_\ell^p\}_{\ell=1}^{d_p}$ is an orthonormal
basis of $H^0_{(2)}(\Sigma,L^p)$, then
%---
\begin{equation}\label{eq4}
B_p(x):=\sum_{\ell=1}^{d_p}|S^p_\ell(x)|_{h^p}^2\,.
\end{equation}
%---
Note that these are independent of the choice of basis (see
\cite[(6.1.10)]{MM07}).
Similarly, let $B_p^{\D^*}(x)$ be the Bergman kernel function of
$\big(\D^*, \omega_{\D^*},
\C,\big|\!\log(|z|^2)\big|^p\, h_{0})$ %\LargerCdot\,| \big)$,
with $h_{0}$ the flat Hermitian metric on the trivial line
 bundle $\C$.



We fix a point $\mathbf{a}\in D$ and work in coordinates
centered at $\mathbf{a}$.
Let $\mathfrak{e}_L$ be the holomorphic frame of $L$ near
 $\mathbf{a}$ corresponding to the trivialization in the
 condition \ref{alpha}.
By the assumptions \ref{alpha} and \ref{beta} we have the
following identification of the geometric data in the coordinate
 $z$ on the punctured disc $\mathbb{D}^*_{4r}$ of radius $4r$
 centered at $\mathbf{a}$, via the trivialization
 $\mathfrak{e}_L$ of $L$,
\begin{equation}\label{eq8}
\big(  \Sigma, \omega_{\Sigma}, L,h \big)
 \big|_{\mathbb{D}^*_{4r} }
= \big( \mathbb{D}^*, \omega_{\mathbb{D}^*},
\mathbb{C}, h_{\mathbb{D}^*} = \big| \log(|z|^2) \big|
\cdot h_0 \big)  \big|_{\mathbb{D}^*_{4r} }, \;\;\;
\text{with} \; \; 0< r < (4e)^{-1}.
\end{equation}
In \cite{AMM22},
Auvray, Ma and Marinescu proved the following estimates.

\begin{thm}\cite[Theorems 1.2 and 1.3]{AMM22}
  \label{thm_prevThm}
If $(\Sigma, \omega_\Sigma, L, h)$ fulfill conditions
 \ref{alpha} and \ref{beta},
then for all $k\in \mathbb{N}$, $l\in \mathbb{N}^*$ and
$D_1,\cdots, D_k \in \Big\{ \frac{\partial}{\partial z},
\frac{\partial}{\partial \bar{z}} \Big\}$,
%we have
%\begin{equation}   \label{eq1.6}
%\sup_{z\in V_1\cup\ldots\cup V_N}
%\bigg|(D_1 \cdots D_k) \Big( \frac{B_p}{B_p^{\D^*}}(z)
% - 1 \Big) \bigg| =\mathcal{O}(p^{-\infty})\,,
%%\qquad\text{as }p\to \infty.
%\end{equation}
there exists $C>0$ such that for any
$p\in\N^{*}$ we have
\begin{equation}\label{eq1.7}
\sup_{z\in V_1\cup\ldots\cup V_N}
\left|(D_1 \cdots D_k) \bigg( \frac{B_p}{B_p^{\D^*}}(z) - 1 \bigg)
\right| \leq C p^{-\ell}.
\end{equation}
\end{thm}

\vskip 10pt

Let us consider the Kodaira map at level $p\geq 2$ induced
by $H^0_{(2)}(\Sigma, L^p)$, which is a meromorphic map
defined by
\begin{equation}\label{eq5}
J_{p,(2)}: \Sigma \dashrightarrow
\mathbb{P}(H^0_{(2)}(\Sigma, L^p)^*)
 \cong \mathbb{CP}^{d_p-1}, \;\;\; x\mapsto
 \{ \sigma \in H^0_{(2)}(\Sigma, L^p): \sigma(x) = 0\}.
\end{equation}
By \cite[p2364]{AMM22}, $J_{p,(2)}$ is an embedding for $p\gg 1$. 

The ${\bL}^2$-metric on $H^0_{(2)}(\Sigma, L^p)$ induces
 a Fubini\textendash Study form $\omega_{FS, p}$ on the
 projective space
$\mathbb{P}(H^0_{(2)}(\Sigma, L^p)^*) $.
We have by  \cite[Theorem 5.1.3, (5.1.21)]{MM07}
\begin{equation}\label{eq6}
\frac{1}{p} J^*_{p,(2)} \omega_{FS,p} = \frac{i}{2\pi} R^L
+ \frac{i}{2\pi p} \partial \bar{\partial} \log (B_p).
\end{equation}
From (\ref{eq1.7}) and (\ref{eq6})
 (cf. \cite[Theorem 4.1]{AMM22}),  we have, as
 $p\rightarrow +\infty$,
\begin{equation}\label{eq7}
\frac{1}{p} J^*_{p,(2)} \omega_{FS,p}
= \frac{1}{2\pi} \omega_{\Sigma}
 + \frac{i}{2\pi p} \partial \bar{\partial}
 \log (B_p^{\mathbb{D}^* }) + \mathcal{O}(p^{-\infty}),
\end{equation}
uniformly on $V_1 \cup V_2 \cup \cdots \cup V_N$.
Note that, by condition \ref{beta}, we have
\begin{equation}\label{eq001}
  \omega_{\D^*} = \omega_{\Sigma} = i R^L
  = - i\partial\bar{\partial} \log \big| \log(|z|^2) \big| \;\;\;
  \text{on} \;\; V_j.
\end{equation}




\vskip 10pt
The main result of the present paper is the following estimate
of the quotient of the induced Fubini\textendash Study forms
 $\frac{1}{p} J^*_{p,(2)} \omega_{FS,p}$ by Kodaira maps
 of $L^p$ and the Poincar\'e form
 $\omega_{\mathbb{D}^*}(z)$:



\begin{thm} \label{thm_MainThm}
If $(\Sigma, \omega_{\Sigma}, L, h)$ fulfill conditions
\ref{alpha} and \ref{beta}, then
\begin{equation}\label{eq9}
\sup_{z\in V_1 \cup \cdots \cup V_N }
\Bigg | \frac{  J^*_{p,(2)} \omega_{FS,p}(z) }
{p \; \omega_{\mathbb{D}^*} (z)  } \Bigg |
 = \mathcal{O}(p^3) \qquad \text{as }p\to +\infty.
\end{equation}
\end{thm}




Let us mention that the difficulty of the estimate (\ref{eq9})
consists in the fact that $B_p^{\mathbb{D}^*}(\cdot)$ vanishes 
at $0$.
Moreover, by \cite[Theorem 6.1.1]{MM07} and (\ref{eq6}), for any
$K \subset \Sigma$ compact,
\begin{equation}\label{eq0006}
\frac{1}{p} J^*_{p,(2)} \omega_{FS,p} - \frac{i}{2\pi} R^L
= \mathcal{O}(p^{-1}) \;\;\;\;\; \text{on} \;\; K.
\end{equation}



\vskip 10pt
We give an important example where Theorem \ref{thm_MainThm}
applies.
Let $\Gamma \subset PSL(2, \mathbb{R})$ be a geometrically
finite Fuchsian group of the first kind without elliptic
 elements. Then $\Sigma: = \Gamma \backslash \mathbb{H}$
 can be compactified by finitely many points
 $D= \{a_1, \cdots, a_N\}$ into a compact Riemann surface
 $\overline{\Sigma}$ \cite[p956]{AMM21}.
Let $\omega_{\Sigma}$ be the K\"ahler\textendash Einstein metric on
$\Sigma$ induced by the Poincar\'e metric
$\omega_{\mathbb{H}} = \frac{ idz \wedge d\bar{z}}{ 4|{\rm Im} z|^2}$
on the upper-half plane $\mathbb{H}$.

Let $\mathcal{S}^{\Gamma}_{2p}$ be the space of cusp forms
(Spitzenformen) of weight $2p$ of $\Gamma$ endowed with
the Petersson inner product (cf. \cite[p995]{AMM21}).
We can form the Bergman kernel function of
$\mathcal{S}_{2p}^{\Gamma}$ as in (\ref{eq4}),
denoted by $S_{p}^{\Gamma}$\cite[p995]{AMM21},
then
\begin{equation}\label{eq10a}
  S_{p}^{\Gamma}(z) = \sum_j |f_j(z)|^2 (2 \text{Im}z)^{2p}
\end{equation}
with $\{f_j\}$ any orthonormal basis of $\mathcal{S}^{\Gamma}_{2p}$.
For any $p>0$ and $z\in \Sigma$, define
\begin{equation}\label{eq.berg}
  \omega_{\Sigma}^{Ber, p} : =
  \frac{i}{2\pi} \partial \bar{\partial}
  \log (S_{p}^{\Gamma}(z)) .
\end{equation}
%We know that it is not a metric, in particular
%if $\Gamma\setminus \mathbb{H}$ is compact, then
%$\mathcal{S}_p^{\Gamma}(z) = \frac{p}{2\pi} + O(1)$.
As a corollary of Theorem \ref{thm_MainThm}, we get the
following:

\begin{crl}\label{cor}
Let $\Gamma \subset PSL(2, \mathbb{R})$ be a geometrically
finite Fuchsian group of the first kind without elliptic
elements and $\Sigma : =\Gamma \backslash \mathbb{H}$.
Then
\begin{equation}\label{eq10}
\sup_{z\in \Sigma}  \left| \frac{ \omega_{\Sigma}^{Ber, p}(z) }
{ p \; \omega_{\Sigma}(z)} \right|
= \mathcal{O}(p^3) \quad \text{as} \;\; p\rightarrow +\infty.
\end{equation}
\end{crl}


\begin{rmk}
Corollary \ref{cor} still holds if $\Gamma$ has elliptic elements.
In this case, the quotient $\Sigma = \Gamma \backslash \mathbb{H}$
is an orbifold, by the result of Dai\textendash Liu\textendash Ma \cite[(5.25)]{DLM06},
Ma\textendash Marinescu \cite[Section 5.4.3]{MM07} on the Bergman kernel on orbifolds
and the localization of the asymptotics of the Bergman kernel on compact
part of $\Sigma$, from \cite[(1.15), p998]{AMM21}, we know near
the orbifold points, $\mathcal{O}(p^3)$ in (\ref{eq10}) can
be estimated as $\mathcal{O}(1)$.

\end{rmk}


