\section{Proof of Theorem \ref{thm_MainThm} and Corollary \ref{cor}}
In this section,  we establish Theorem \ref{thm_MainThm} and
Corollary \ref{cor}  by using the techniques in \cite{AMM22}.
Our starting point is (\ref{eq7}), and thus we only need to work on
 the punctured unit disc $\mathbb{D}^*$.
The key part in our proof of Theorem \ref{thm_MainThm}
in Section \ref{s2.1}
is Lemma \ref{lem} which is established in Section \ref{s2.2}:
For the four terms in (\ref{eq26}) and (\ref{eq27}),
we get $\mathcal{O}(p^{-\infty})$.
The main estimate $\mathcal{O}(p^3)$
is from (\ref{eq28}) as $B_p^{\D^*}(z)$ oscillates
 too violently near $|z|=e^{-p}$
  (cf.  \cite[Section 3.2]{AMM21}).
In Section \ref{s2.3}, we explain the proof of Corollary \ref{cor}.

%(\ref{eq28}) is the main part for us to get only $\mathcal{O}(p^3)$.
%The main reason for that is that $B_p^{\D^*}(z)$ oscillates too
%violently near $|z|=e^{-p}$ (cf.  \cite[Section 3.2]{AMM21}).


\subsection{Proof of Theorem \ref{thm_MainThm}} \label{s2.1}
From \cite[(2.6) and (2.7)]{AMM22}, we have
\begin{equation}\label{eq15}
B_p^{\mathbb{D}^*}(z) = |\log(|z|^2) |^p\beta_p^{\mathbb{D}^*}(z),
 \;\;\; \text{for} \;\; z\in \mathbb{D}^*,
\end{equation}
where
\begin{equation}\label{eq16}
\begin{split}
 \beta_p^{\mathbb{D}^*}(z) = \sum_{l=1}^{\infty}
 (c_l^{(p)})^2 |z|^{2l} , \;\;\;
 \text{with} \;\;\;
 c_l^{(p)} = \bigg( \frac{l^{p-1}}{2\pi(p-2)!} \bigg)^{1/2}.
\end{split}
\end{equation}
From (\ref{eq15}) and (\ref{eq16}), we know
$\displaystyle\lim_{z\rightarrow 0} B_p^{\D^*}(z) =0$ for any $p$.
Thus, $B_p^{\D^*}$ has no strictly positive lower bound.
 This is the main difficulty to establish Theorem 1.2.

By \cite[Proposition 3.3]{AMM21}, for any
$m\in \mathbb{N}, 0<b <1$ and $0<\gamma <\frac{1}{2}$, there exists
 $\varepsilon = \varepsilon(b,\gamma) >0$ such that
\begin{equation}\label{eq12}
\bigg \| B_p^{\mathbb{D}^*} (z)
- \frac{p-1}{2\pi} \bigg\|_{ C^m( \{be^{- p^{\gamma}}
\leq |z| <1\}, \omega_{\mathbb{D}^*} ) }
= \mathcal{O}(e^{-\varepsilon p^{1-2\gamma}}) \;\; \text{as} \;
p\rightarrow +\infty.
\end{equation}


After reducing to some $V_j$ and identifying the geometric data on
$\mathbb{D}^*_{4r}$ and $\Sigma$ via (\ref{eq8}),
by (\ref{eq1}) and (\ref{eq7}),
we have
\begin{equation}\label{eq11}
\begin{split}
& \frac{ J^*_{p,(2)} \omega_{FS,p}(z) } { p \;
\omega_{\mathbb{D}^*} (z)  }  - \frac{1}{2\pi}
  =  \frac{ i \partial\bar{\partial}
   \log (B^{\mathbb{D}^*}_p(z) )}{ 2\pi p \;
   \omega_{\mathbb{D}^*}(z) }  + \mathcal{O}(p^{-\infty}) \\
& = \frac{1}{2\pi p} |z|^2 \big( \log(|z|^2) \big)^2
\frac{ B_p^{\mathbb{D}^*}(z) \cdot
\frac{\partial^2}{\partial z \partial\bar{z}}
B^{\mathbb{D}^*}_p(z) - \frac{\partial}{\partial z}
B_p^{\mathbb{D}^*}(z) \cdot  \frac{\partial}{\partial \bar{z}}
B^{\mathbb{D}^*}_p(z) }{(B_p^{\mathbb{D}^*}(z))^2}
  + \mathcal{O}(p^{-\infty}) .
\end{split}
\end{equation}
As $|z|\log|z|^2 \frac{\partial}{\partial z}$ is an orthonormal frame of $(T^{(1,0)} \D^*, \omega_{\D^*})$,
from  (\ref{eq12}) with $m=1,2$, we have
\begin{equation}\label{eq003}
\begin{split}
&\sup_{  be^{- p^{\gamma}} \leq |z| <1 }  |z|^2
\big( \log(|z|^2) \big)^2 \bigg|\frac{\partial^2}
{\partial z \partial\bar{z}} B^{\mathbb{D}^*}_p(z)\bigg|
= \mathcal{O}(e^{-\varepsilon p^{1-2\gamma}}) \;\; \text{as} \;
 p\rightarrow +\infty. \\
&\sup_{ be^{- p^{\gamma}} \leq |z| <1 } |z|
   \big| \log(|z|^2) \big| \bigg|\frac{\partial}{\partial z}
   B_p^{\mathbb{D}^*}(z)\bigg|
= \mathcal{O}(e^{-\varepsilon p^{1-2\gamma}}) \;\; \text{as} \;
p\rightarrow +\infty.
\end{split}
\end{equation}
From  (\ref{eq12}) with $m=0$, (\ref{eq11}) and (\ref{eq003}),  we get
\begin{equation}\label{eq13}
\sup_{  be^{- p^{\gamma}} \leq |z| <1 }  \Bigg | \frac{ J^*_{p,(2)}
\omega_{FS,p}(z) } { p\; \omega_{\mathbb{D}^*} (z)  }
 - \frac{1}{2\pi} \Bigg | = \mathcal{O}(p^{-\infty}).
\end{equation}
Thus, in order to prove Theorem \ref{thm_MainThm} it suffices to show that
\begin{equation}\label{eq14}
\sup_{ 0 < |z| < be^{- p^{\gamma}} }
\Bigg | \frac{ J^*_{p,(2)} \omega_{FS,p}(z) }
{ p\; \omega_{\mathbb{D}^*} (z)  }   \Bigg | = \mathcal{O}(p^3 ).
\end{equation}
From (\ref{eq1}), (\ref{eq7}), (\ref{eq001}) and (\ref{eq15}),
we get
\begin{equation}\label{eq19}
\frac{ J^*_{p,(2)} \omega_{FS,p} (z) }{ p\;
\omega_{\mathbb{D}^*}(z) }
= |z|^2 \big( \log |z|^2 \big)^2 \cdot
 \frac{ \frac{\partial^2}{\partial z\partial\bar{z}}
 \beta_p^{\mathbb{D}^*}(z)  \cdot \beta_p^{\mathbb{D}^*} (z)
- \frac{\partial}{\partial z} \beta_p^{\mathbb{D}^*}(z)
\frac{\partial}{\partial \bar{z}} \beta_p^{\mathbb{D}^*}(z) }
{2\pi p\; \big(\beta_p^{\mathbb{D}^*}(z) \big)^2 }
+ \mathcal{O}(p^{-\infty}) .
\end{equation}

A key idea of \cite{AMM22} is that we use the precise formula
(\ref{eq16}), and only the lower degree (i.e., $l=\mathcal{O}(p)$) part
of (\ref{eq16}) plays the essential contribution in (\ref{eq19}).
We define $\delta_p$ as follows,
\begin{equation}\label{eq22}
\delta_p  = \bigg\lfloor  \frac{(p-2) }{ 2 |\log r|} \bigg \rfloor ,
\end{equation}
and $\lfloor x\rfloor$ is the integral part of $x\in \mathbb{R}$. Set
\begin{equation}\label{eq21}
\begin{split}
 & I_{1,p} : =  \sum_{l=1}^{\delta_p} \sum_{m=1}^{\delta_p} l(l-m)
  ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m},  \\
 & I_{2,p} : =  \sum_{l=1}^{\delta_p} \sum_{m=\delta_p +1}^{\infty}  l(l-m) ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m},  \\
 & I_{3,p} : =  \sum_{l=\delta_p +1}^{\infty} \sum_{m=1}^{\delta_p}  l(l-m) ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m},  \\
 & I_{4,p} : =  \sum_{l=\delta_p+1}^{\infty}
 \sum_{m=\delta_p+1}^{\infty}
 l(l-m) ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m} .
\end{split}
\end{equation}
From (\ref{eq16}) and (\ref{eq21}), we have
\begin{equation}\label{eq20}
\begin{split}
 & |z|^2 \bigg( \frac{\partial^2}{\partial z\partial\bar{z}}
 \beta_p^{\mathbb{D}^*}(z)  \cdot \beta_p^{\mathbb{D}^*} (z)
 - \frac{\partial}{\partial z} \beta_p^{\mathbb{D}^*}(z)
 \frac{\partial}{\partial \bar{z}} \beta_p^{\mathbb{D}^*}(z)
  \bigg) \\
 & = |z|^2 \sum_{l,m=1}^{\infty} l^2 (c_l^{(p)})^2
 (c_m^{(p)})^2 |z|^{2l+2m-2}
   - |z|^2 \sum_{l,m=1}^{\infty} lm( c_l^{(p)} )^2
   (c_m^{(p)} )^2 |z|^{2l+2m-2}  \\
 & = \sum_{l,m=1}^{\infty} l(l-m) ( c_l^{(p)} )^2
 (c_m^{(p)} )^2 |z|^{2l+2m} \\
 & = I_{1,p} + I_{2,p} + I_{3,p} + I_{4,p}.
\end{split}
\end{equation}
Thus, by (\ref{eq19}) and (\ref{eq20}) we get
\begin{equation}\label{eq24}
\frac{ J^*_{p,(2)} \omega_{FS,p} (z) }{ p \;
 \omega_{\mathbb{D}^*}(z) }
=  \big( \log |z|^2 \big)^2 \cdot  \frac{ I_{1,p}
+ I_{2,p} + I_{3,p} + I_{4,p} } { 2\pi p\;
\big(\beta_p^{\mathbb{D}^*}(z) \big)^2} +\mathcal{O}(p^{-\infty}).
\end{equation}
We will show the following result.

\begin{lem}\label{lem}
  (1) For $j=2,3,4$, we have
\begin{equation}\label{eq26}
\sup_{  0 < |z| < be^{- p^{\gamma}} }
\Bigg | \big( \log |z|^2 \big)^2 \cdot
\frac{I_{j,p} }{ \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
 = \mathcal{O}(p^{-\infty} ).
\end{equation}

(2) We have
\begin{subequations}
\begin{equation}\label{eq27}
\sup_{ 0 < |z| < 2 e^{-p} }  \Bigg | \big( \log |z|^2 \big)^2
\cdot \frac{I_{1,p} }{ \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }
 \Bigg | = \mathcal{O}(p^{-\infty} ),
\end{equation}
\begin{equation}\label{eq28}
\sup_{ e^{-p} < |z| < be^{- p^{\gamma}} }
\Bigg | \big( \log |z|^2 \big)^2 \cdot \frac{I_{1,p} }{ \big(
  \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg | = \mathcal{O}(p^4 ).
\end{equation}
\end{subequations}
\end{lem}

\vskip 10pt
\noindent
{\bf How to get Theorem \ref{thm_MainThm} for Lemma \ref{lem}.}
Since
$\{z\in \mathbb{C}: 0<|z| < be^{-p^{\gamma}} \}
= \{z \in \mathbb{C}: 0<|z| < 2e^{-p}\} \cup \{z\in \mathbb{C}:
e^{-p} < |z| < be^{-p^{\gamma}} \}$, from (\ref{eq27})
and (\ref{eq28}), we get
\begin{equation}\label{eq006}
\sup_{ 0 < |z| < be^{- p^{\gamma}} }
\Bigg | \big( \log |z|^2 \big)^2 \cdot \frac{I_{1,p}}{
  \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
   = \mathcal{O}(p^4 ).
\end{equation}
From (\ref{eq24}), (\ref{eq26}) and (\ref{eq006}),
we get (\ref{eq14}).
The proof of Theorem \ref{thm_MainThm} is completed.

\subsection{Proof of Lemma \ref{lem}.}\label{s2.2}
\vskip 10pt
\noindent
From (\ref{eq21}), we have
\begin{equation}\label{eq29}
\begin{split}
 & | I_{1,p} | \leq \sum_{m=2}^{\delta_p} \big| 1-m \big|
 ( c_1^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2+2m}
  + \sum_{l=2}^{\delta_p} \sum_{m=2}^{\delta_p }
  l\big|l-m \big| ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m}.
\end{split}
\end{equation}

We first estimate the first term on the right hand side of
(\ref{eq29}).
By (\ref{eq16}), we have
\begin{equation}\label{eq30}
  (c^{(p)}_1)^2 |z|^2 < \beta_p^{\mathbb{D}^*}(z),
\end{equation}
and
\begin{equation}\label{eq31}
  (c^{(p)}_m)^2 = \frac{ m^{p-1} }{ 2\pi(p-2)! }
  = \bigg( \frac{m}{m-1}\bigg)^{p-1} \cdot
  \frac{ (m-1)^{p-1} }{ 2\pi(p-2)! }
  = \bigg( \frac{m}{m-1}\bigg)^{p-1} (c^{(p)}_{m-1})^2 .
\end{equation}
From (\ref{eq16}) and (\ref{eq31}),
as $\frac{l}{l-1} \leq 2$ for $l\geq 2$, we have
\begin{equation}\label{eq0038}
\begin{split}
\sum_{l=2}^{\delta_p}   \big(c_l^{(p)} \big)^2  |z|^{2(l-1)}
& = \sum_{l=2}^{\delta_p}  \bigg( \frac{l}{l-1}\bigg)^{p-1}
\big(c_{l-1}^{(p)} \big)^2 |z|^{2(l-1)} \\
& \leq  2^{p-1}   \sum_{l=2}^{\delta_p}
 \big(c_{l-1}^{(p)} \big)^2 |z|^{2(l-1)}
\leq 2^{p-1} \beta_p^{\mathbb{D}^*} (z).
\end{split}
\end{equation}
From (\ref{eq22}), (\ref{eq30}) and (\ref{eq0038}), we have
\begin{equation}\label{eq38}
\begin{split}
\sum_{m=2}^{\delta_p} \big|1-m \big| ( c_1^{(p)} )^2
(c_m^{(p)} )^2 |z|^{2+2m}
&\leq (\delta_p-1) (c_1^{(p)})^2 |z|^2 \sum_{m=2}^{\delta_p}
(c_m^{(p)})^2 |z|^{2(m-1)} \cdot |z|^2  \\
& \leq (\delta_p -1) 2^{p-1} |z|^2  \; \beta_p^{\mathbb{D}^*}(z)^2 \\
&\leq p 2^{p-1} |z|^2 \beta_p^{\mathbb{D}^*}(z)^2 .
\end{split}
\end{equation}

\noindent
{\bf Proof of (\ref{eq27})}:
For $0<|z|<2 e^{-p}$, we have
\begin{equation}\label{eq35}
2^{p-1} |z| < 2^p e^{-p} = \bigg( \frac{2}{e} \bigg)^p.
\end{equation}
Thus, by (\ref{eq38}) and (\ref{eq35}), for $|z| < 2 e^{-p}$,
we get
\begin{equation}\label{eq36}
\begin{split}
 \sum_{m=2}^{\delta_p} \big| 1-m \big| ( c_1^{(p)} )^2
 (c_m^{(p)} )^2 |z|^{2+2m}
 \leq p \bigg( \frac{2}{e} \bigg)^p \; |z| \;
 \beta_p^{\mathbb{D}^*}(z)^2.
\end{split}
\end{equation}
Next we estimate the second term on the right hand side of
 (\ref{eq29}):
\begin{equation}\label{eq37}
\begin{split}
& \sum_{l=2}^{\delta_p} \sum_{m=2}^{\delta_p }  l\big|l-m\big|
 ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m} \\
& \leq \delta_p \cdot \delta_p \sum_{l=2}^{\delta_p}
\sum_{m=2}^{\delta_p} (c_l^{(p)} )^2 (c_m^{(p)})^2 |z|^{2l+2m}
\;\;\;\;\;\; (\text{as}\; |l-m|<\delta_p)\\
& = \delta_p^2 \; |z|^4 \; \sum_{l=2}^{\delta_p} (c_l^{(p)} )^2
 |z|^{2(l-1)} \cdot \sum_{m=2}^{\delta_p} (c_m^{(p)})^2
  |z|^{2(m-1)} .
\end{split}
\end{equation}
By (\ref{eq22}), (\ref{eq0038}), (\ref{eq35}) and (\ref{eq37}),
for $|z|<2e^{-p}$, as in (\ref{eq36}), we get
\begin{equation}\label{eq39}
\begin{split}
\sum_{l=2}^{\delta_p} \sum_{m=2}^{\delta_p } l\big|l-m\big|
 ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m}
& \leq  \delta_p^2 \; |z|^4 \cdot 2^{p-1}  \beta_p^{\mathbb{D}^*}
(z) \cdot 2^{p-1}  \beta_p^{\mathbb{D}^*} (z)  \\
& \leq  p^2 \cdot \bigg( \frac{2}{e} \bigg)^{2p} \; |z|^2 \;
 \beta_p^{\mathbb{D}^*}(z)^2 .
\end{split}
\end{equation}
Combining (\ref{eq29}), (\ref{eq36}) and (\ref{eq39}), we obtain
\begin{equation}\label{eq41}
\begin{split}
\Bigg| \big( \log |z|^2 \big)^2 \cdot \frac{I_{1,p}}{
  \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 } \Bigg|
    \leq  p \bigg(\frac{2}{e}\bigg)^p \; |z| \big(\log |z|^2 \big)^2
+ p^2 \;\bigg(\frac{2}{e}\bigg)^{2p} \; |z|^2
\big(\log |z|^2 \big)^2 .
\end{split}
\end{equation}
Since the functions $f(x) = x(\log x^2)^2$ and $g(x)
= x^2(\log x^2)^2$ are bounded on the interval
$]0, 2 e^{-p}[ \subset ]0,e^{-2}[$, by (\ref{eq41}),
we get that there exists $C_1 >0$ such that
\begin{equation}\label{eq42}
\begin{split}
\sup_{  0<|z|< 2 e^{-p} } \Bigg| \big( \log |z|^2 \big)^2 \cdot
 \frac{I_{1,p}}{ \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 } \Bigg|
 \leq C_1 \Bigg[ p\bigg(\frac{2}{e} \bigg)^p
 + p^2 \bigg(\frac{2}{e}\bigg)^{2p}  \Bigg] .
\end{split}
\end{equation}
By (\ref{eq42}), we get (\ref{eq27}).


\vskip 10pt
\noindent
{\bf Proof of (\ref{eq28}).}
From (\ref{eq16}), (\ref{eq22}) and (\ref{eq21}), we have
\begin{equation}\label{eq43}
\begin{split}
 |I_{1,p}| & \leq \sum_{l=1}^{\delta_p} \sum_{m=1}^{\delta_p }
 l\big|l-m \big| ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m}  \\
& \leq  \delta_p \cdot \delta_p
\sum_{l=1}^{\delta_p}
\sum_{m=1}^{\delta_p }  ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m}\\
& \leq  p^2 \;\beta_p^{\mathbb{D}^*}(z)^2.
\end{split}
\end{equation}
Therefore,
\begin{equation}\label{eq44}
\begin{split}
 \Bigg | \big( \log |z|^2 \big)^2 \cdot \frac{I_{1,p}}{
   \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
 \leq p^2 \big(\log|z|^2 \big)^2.
\end{split}
\end{equation}
For $z \in \{u \in \mathbb{C} : e^{-p} <|u|< b e^{-p^{\gamma}} \}$,
 we have $e^{-2p} < |z|^2 <1$. Thus, $-2p < \log |z|^2 <0$.
 Therefore, $\big(\log |z|^2 \big)^2 < 4p^2$.
Hence, by (\ref{eq44}), we have
\begin{equation}\label{eq45}
\begin{split}
 \sup_{ e^{-p} < |z| < b e^{-p^{\gamma}} } \Bigg |
 \big( \log |z|^2 \big)^2 \cdot \frac{I_{1,p}}{
  \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
 \leq p^2 \cdot 4p^2 = 4 p^4.
\end{split}
\end{equation}
From (\ref{eq45}), we get (\ref{eq28}).


\vskip 10pt
\noindent
{\bf Proof of Lemma \ref{lem}(1) for $j=2$.}
From (\ref{eq21}), we have
\begin{equation}\label{eq46}
\begin{split}
| I_{2,p} | &\leq    \sum_{l=1}^{\delta_p}
\sum_{m=\delta_p +1}^{\infty} l\big|l-m\big| ( c_l^{(p)} )^2
(c_m^{(p)} )^2 |z|^{2l+2m}  \\
& < \sum_{l=1}^{\delta_p} l (c_l^{(p)})^2 |z|^{2l} \cdot
\sum_{m=\delta_p +1}^{\infty} m (c_m^{(p)} )^2 |z|^{2m} ,
\end{split}
\end{equation}
as $l|l-m| =l(m-l) < lm$.

From  \cite[(3.70)]{AMM22}, there exists $C>0$ such that for
any $s\in\mathbb{N}^*$, $p\geq 2$, we have
\begin{equation}\label{eq48}
|c_s^{(p)} | \leq C p^{\frac{1}{2}} \frac{1}{(2r)^s}
\frac{1}{ \big( \log |2r|^2 \big)^{p/2} }.
\end{equation}


Next, we need the following

\begin{lem}\label{lem2}(\cite[(3.60)]{AMM22}).
For any $\tau \in \mathbb{N}$ fixed, we have
\begin{equation}\label{eq52}
\frac{1}{ \big| \log(|2r|^2) \big|^{p/2} }
\bigg( \frac{|z|}{ 2r }\bigg)^{\delta_p -\tau +1}
\leq C p^{-\frac{1}{2}} \frac{1}{2^{\alpha' p}}
\beta_p^{\mathbb{D}^*}(z)^{\frac{1}{2} }
\end{equation}
for all $p\gg 1$ and $|z| \leq c' p^{-A'}$, where $c'$ and
$A'$ are constants defined as follows:
\begin{equation}\label{eq-lem1}
  A' =\frac{1}{2\alpha'}, \;\;\; \alpha'
  =\frac{1}{4|\log r|} \;\;\; \text{and} \;\;\;
  c'= r e^{1/2\alpha'} \big| \log(|2r|^2) \big|^{1/2\alpha'} .
\end{equation}
\end{lem}

\noindent
\begin{proof} For the sake of completeness, we include
   a proof here.
By (\ref{eq22}), for any $\tau \in \mathbb{N}$ fixed, we obtain
\begin{equation}\label{eq-lem2}
  \alpha' p \leq \delta_p - \tau  \;\;\; \text{for} \; p \gg 1.
\end{equation}
Thus, by (\ref{eq-lem1}) and (\ref{eq-lem2}) for
 $\tau \in \mathbb{N}$ fixed, we have
\begin{equation}\label{eq-lem3}
  \bigg( \frac{|z|}{2r} \bigg)^{2(\delta_p -\tau)/p}
  \frac{1} {\big| \log(|2r|^2)\big|}
  \leq \bigg( \frac{|z|}{2r} \bigg)^{2\alpha'}
  \frac{1} {\big| \log(|2r|^2)\big|}
  \leq 2^{-2\alpha'} \frac{e}{p}
\end{equation}
for $p\gg 1$, $|z| \leq c' p^{-A'}$.
Recall that the Stirling formula states
\begin{equation}\label{eq-lem4}
  \frac{p^p}{p!} = (2\pi p)^{-1/2} e^p
  \big( 1 + \mathcal{O}(p^{-1}) \big) \;\;\;
   \text{as} \;\; p\rightarrow + \infty.
\end{equation}
By (\ref{eq16}), (\ref{eq-lem3}) and (\ref{eq-lem4}),
for any $\tau \in \mathbb{N}$ fixed, we have
\begin{equation}
  \begin{split}
    \frac{1}{ \big| \log(|2r|^2) \big|^{p/2} }
    \bigg( \frac{|z|}{ 2r }\bigg)^{\delta_p -\tau +1} &= \frac{1}{2r} \Bigg(  \bigg( \frac{|z|}{2r}
\bigg)^{2(\delta_p -\tau)/p} \frac{1} {\big|
     \log(|2r|^2)\big|} \Bigg)^{p/2} \big( 2\pi (p-2)!
     \big)^{1/2} c_1^{(p)}|z|  \\
    &\leq C p^{-\frac{1}{2}} \frac{1}{2^{\alpha' p}}
    \beta_p^{\mathbb{D}^*}(z)^{\frac{1}{2} }
  \end{split}
\end{equation}
for $p\gg 1$, $|z| \leq c' p^{-A'}$.
\end{proof}


\vskip 10pt
From now on, we assume $|z|\leq c' p^{-A'}$, $p \gg 1$.
By (\ref{eq16}) and (\ref{eq22}) we get
\begin{equation}\label{eq55}
\begin{split}
\sum_{l=1}^{\delta_p}  l  (c_l^{(p)})^2  |z|^{2l}
\leq   \delta_p \sum_{l=1}^{\delta_p} (c_l^{(p)})^2 |z|^{2l}
\leq   \delta_p \beta_p^{\mathbb{D}^*}(z)
\leq   p \beta_p^{\mathbb{D}^*}(z) .
\end{split}
\end{equation}
On the other hand, by (\ref{eq48}), we have
\begin{equation}\label{eq56}
\begin{split}
\sum_{m=\delta_p+1}^{\infty}  m (c_m^{(p)})^2 |z|^{2m}
& \leq \sum_{m=\delta_p +1}^{\infty}   m C p \frac{1}{(2r)^{2m}}
\frac{1}{ \big| \log(|2r|^2) \big|^p } |z|^{2m} \\
& =  C p  \frac{1}{ \big| \log(|2r|^2) \big|^p }
\sum_{m=\delta_p +1}^{\infty}  m \bigg( \frac{|z|}{ 2r }\bigg)^{2m} .
\end{split}
\end{equation}
Since for $0 \leq \xi <1$,
\begin{equation*}
\begin{split}
\sum_{q=N+1}^{\infty} q \xi^{q-1}
= \Bigg( \sum_{q=N+1}^{\infty} \xi^q \Bigg)'
 = \bigg( \frac{ \xi^{N+1} }{ 1 -\xi } \bigg)'
 = \frac{ (N+1) \xi^N - N \xi^{N+1}  }{ (1-\xi)^2  }
 \leq \frac{ (N+1) \xi^N } { (1-\xi)^2 },
\end{split}
\end{equation*}
we have
\begin{equation}\label{eq57}
\begin{split}
\sum_{m=\delta_p +1}^{\infty} m \bigg( \frac{|z|}{2r}\bigg)^{2m}
  &=  \bigg( \frac{|z|}{2r} \bigg)^2  \sum_{m=\delta_p +1}^{\infty}
  m \bigg( \frac{|z|}{ 2r }\bigg)^{2(m-1)}  \\
& \leq  \bigg( \frac{|z|}{ 2r }\bigg)^2  (\delta_p + 1)
  \frac{  \Big(\frac{|z|}{2r} \Big)^{2\delta_p} } {
    \Big( 1 - \big( \frac{|z|}{2r} \big)^2 \Big)^2 } \\
 &\leq     \bigg( \frac{|z|}{ 2r }\bigg)^2  (\delta_p + 1)
  \cdot \bigg( \frac{4}{3} \bigg)^2 \bigg(\frac{|z|}{2r}
   \bigg)^{2\delta_p} .
\end{split}
\end{equation}
Therefore, by (\ref{eq22}), (\ref{eq52}) for $\tau=1$, (\ref{eq56}) and (\ref{eq57}), we obtain
\begin{equation}\label{eq58}
\begin{split}
\sum_{m=\delta_p+1}^{\infty}  m (c_m^{(p)})^2 |z|^{2m}
& \leq   \bigg( \frac{4}{3} \bigg)^2  \bigg( \frac{|z|}{ 2r }\bigg)^2
 (\delta_p + 1)\cdot C p \frac{1}{ \big| \log(|2r|^2) \big|^p }
    \bigg(\frac{|z|}{2r} \bigg)^{2\delta_p}  \\
& \leq  \bigg( \frac{4}{3} \bigg)^2   \bigg( \frac{|z|}{ 2r }\bigg)^2
 (p + 1)  C'  \frac{1}{2^{2\alpha' p}} \beta_p^{\mathbb{D}^*}(z).
\end{split}
\end{equation}
%Therefore, by (\ref{eq55}) and (\ref{eq59}), we get
%\begin{equation}\label{eq60}\begin{split}
% \sum_{l=1}^{\delta_p}  l  (c_l^{(p)})^2  |z|^{2l}  \cdot
% \sum_{m=\delta_p +1}^{\infty} m (c_m^{(p)} )^2 |z|^{2m}
%\leq  \big( \frac{4}{3} \big)^2 \Big( \frac{|z|}{ 2r }\Big)^2
% p (p + 1) C' \frac{1}{2^{2\alpha' p}} \beta_p^{\mathbb{D}^*}(z)^2.
%\end{split}\end{equation}
From (\ref{eq46}), (\ref{eq55}) and (\ref{eq58}), %and (\ref{eq60}),
 we get
\begin{equation}\label{eq61}
\begin{split}
 \Bigg | \big( \log |z|^2 \big)^2 \cdot \frac{ I_{2,p} }{
   \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
& \leq
\Big( \log |z|^2 \Big)^2    \bigg( \frac{|z|}{ 2r }\bigg)^2  \;
\bigg( \frac{4}{3} \bigg)^2  C'    p (p + 1)
\frac{1}{2^{2\alpha' p}} .
\end{split}
\end{equation}
Since the function $f(x) = x^2(\log x^2)^2$ is bounded on the
interval $]0,1[$, from (\ref{eq61}), we get
\begin{equation}\label{eq62}
\begin{split}
 \sup_{  0<|z| \leq c' p^{-A'}  } \Bigg | \big( \log |z|^2 \big)^2
  \cdot \frac{I_{2,p}}{ \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }
    \Bigg |
 \leq C'' p^2 \frac{1}{2^{2\alpha' p}} .
\end{split}
\end{equation}
Since $c' p^{-A'} > b e^{-p^{\gamma}}$ for
$p\gg 1$, we get (\ref{eq26}) for $j=2$ from (\ref{eq62}).


\vskip 10pt
\noindent
{\bf Proof of Lemma \ref{lem}(1) for $j=3$.}
We assume $|z|\leq c' p^{-A'}$, $p \gg 1$ as in Lemma \ref{lem2}.
From (\ref{eq21}), we have
\begin{equation}\label{eq63}
\begin{split}
|I_{3,p}|   & \leq   \sum_{l=\delta_p +1}^{\infty}
\sum_{m=1}^{\delta_p} l\big| l-m \big| ( c_l^{(p)} )^2
(c_m^{(p)} )^2 |z|^{2l+2m}   \\
& \leq \sum_{l=\delta_p + 1}^{\infty} l^2  (c_l^{(p)} )^2 |z|^{2l}
 \cdot \sum_{m=1}^{\delta_p}  (c_m^{(p)})^2 |z|^{2m},
\end{split}
\end{equation}
as $l|l-m| =l(l-m) <l^2$.

From (\ref{eq48}), we have
\begin{equation}\label{eq65}
\begin{split}
\sum_{l=\delta_p+1}^{\infty}  l^2 (c_l^{(p)})^2 |z|^{2l}
& \leq \sum_{l=\delta_p +1}^{\infty}   l^2 \; C p
\frac{1}{(2r)^{2l}} \frac{1}{ \big| \log(|2r|^2) \big|^p } \;
 |z|^{2l } \\
& =   C p  \frac{1}{ \big| \log(|2r|^2) \big|^p }
\sum_{l=\delta_p +1}^{\infty}  l^2 \bigg(
  \frac{|z|}{ 2r }\bigg)^{2l}  .
\end{split}
\end{equation}
By a simple computation, we get for $0\leq \xi <1$,
\begin{equation*}
\begin{split}
\sum_{q=N+1}^{\infty} q(q+1) \xi^{q-1}
&= \Bigg( \sum_{q=N+1}^{\infty} \xi^{q+1} \Bigg)'' \\
&= \bigg( \frac{ \xi^{N+2} }{ 1 -\xi } \bigg)'' \\
%= \Big(  \frac{ (N+2) \xi^{N+1} - (N+1) \xi^{N+2}  }{ (1-\xi)^2  }   \Big)'
&=  \frac{ (N+2)(N+1) \xi^N - 2N(N+2)\xi^{N+1}
+ N(N+1) \xi^{N+2} }{ (1-\xi)^3 }   \\
& \leq \frac{(N+2) (N+1) \xi^N } { (1-\xi)^3 }.
\end{split}
\end{equation*}
Thus,
\begin{equation}\label{eq66}
\begin{split}
\sum_{l=\delta_p +1}^{\infty}l^2 \bigg( \frac{|z|}{ 2r }\bigg)^{2l}
& \leq  \bigg( \frac{|z|}{2r} \bigg)^2 \sum_{l=\delta_p +1}^{\infty}
 l(l+1) \bigg( \frac{|z|}{ 2r }\bigg)^{2(l-1)}  \\
& \leq  \bigg( \frac{|z|}{ 2r }\bigg)^2  (\delta_p+2) (\delta_p + 1)
  \frac{  \Big(\frac{|z|}{2r} \Big)^{2\delta_p} } {\Big( 1
  - \big( \frac{|z|}{2r} \big)^2 \Big)^3 }  \\
& \leq \bigg( \frac{|z|}{ 2r }\bigg)^2  (\delta_p + 2)
(\delta_p + 1)    \cdot   \bigg( \frac{4}{3} \bigg)^3
\bigg( \frac{|z|}{ 2r }\bigg)^{2 \delta_p }  .
\end{split}
\end{equation}
Therefore, by (\ref{eq65}) and (\ref{eq66}), we get
\begin{equation}\label{eq67}
\begin{split}
\sum_{l=\delta_p+1}^{\infty}  l^2 (c_l^{(p)})^2 |z|^{2l}
\leq   C  \bigg( \frac{|z|}{ 2r }\bigg)^2  (\delta_p + 2)
(\delta_p + 1) \bigg( \frac{4}{3} \bigg)^3   \cdot
p  \frac{1}{ \big| \log(|2r|^2) \big|^p }
\bigg( \frac{|z|}{ 2r }\bigg)^{2 \delta_p } .
\end{split}
\end{equation}
By (\ref{eq22}), (\ref{eq52}) for $\tau=1$ and (\ref{eq67}), we get
\begin{equation}\label{eq68}
\begin{split}
\sum_{l=\delta_p+1}^{\infty}  l^2 (c_l^{(p)})^2 |z|^{2l}
& \leq  C  \bigg( \frac{|z|}{ 2r }\bigg)^2  (\delta_p + 2)
(\delta_p + 1) \bigg( \frac{4}{3} \bigg)^3   \cdot C^2
\frac{1}{2^{2\alpha' p}}  \beta_p^{\mathbb{D}^*}(z)  \\
& \leq  C'  \bigg( \frac{|z|}{ 2r }\bigg)^2  (p+2) (p + 1)
 \frac{1}{2^{2\alpha' p}} \beta_p^{\mathbb{D}^*}(z) .
\end{split}
\end{equation}
%Therefore, by (\ref{eq16}) and (\ref{eq68}), we get
%\begin{equation}\label{eq69}\begin{split}
%   \sum_{l=\delta_p +1}^{\infty} l^2 (c_l^{(p)} )^2 |z|^{2l}
 %  \cdot \sum_{m=1}^{\delta_p}   (c_m^{(p)})^2  |z|^{2m}
 %  \leq   C'  \Big( \frac{|z|}{ 2r }\Big)^2   (p+2) (p + 1)
 %  \frac{1}{2^{2\alpha' p}} \beta_p^{\mathbb{D}^*}(z)^2 .
%\end{split}\end{equation}
From   (\ref{eq16}),
 (\ref{eq63}) and (\ref{eq68}), we get
\begin{equation}\label{eq70}
\begin{split}
\Bigg | \big( \log |z|^2 \big)^2 \cdot \frac{ I_{3,p} }{
  \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
\leq
\Big( \log |z|^2 \Big)^2    \bigg( \frac{|z|}{ 2r }\bigg)^2
\;\bigg[    C' (p+2)(p+1)   \frac{1}{2^{ 2\alpha' p} }  \bigg] .
\end{split}
\end{equation}
Since the function $f(x) = x^2(\log x^2)^2$ is bounded on the
interval $]0,1[$, from (\ref{eq70}), we get
\begin{equation}\label{eq71}
\begin{split}
& \sup_{ 0<|z| \leq c' p^{-A'} } \Bigg | \big( \log |z|^2 \big)^2
\cdot \frac{I_{3,p}}{ \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }
 \Bigg |
 \leq C_2 \; p^2 \frac{1}{2^{2\alpha' p}} .
\end{split}
\end{equation}
Since $c' p^{-A'} > b e^{-p^{\gamma}}$ for
$p\gg 1$, we get (\ref{eq26}) for $j=3$ from (\ref{eq71}).


\vskip 10pt
\noindent
{\bf Proof of Lemma \ref{lem}(1) for $j=4$.}
We assume $|z|\leq c' p^{-A'}$, $p \gg 1$ as in Lemma \ref{lem2}.
By (\ref{eq21}), we have
\begin{equation}\label{eq72}
\begin{split}
  | I_{4,p} |
& \leq  \sum_{l=\delta_p+1}^{\infty}  \sum_{m=\delta_p+1}^{\infty}
 l \big|l-m\big| ( c_l^{(p)} )^2 (c_m^{(p)} )^2 |z|^{2l+2m}  \\
& \leq \sum_{l=\delta_p + 1}^{\infty} l^2  (c_l^{(p)} )^2 |z|^{2l}
\cdot \sum_{m=\delta_p + 1 }^{ \infty}  (c_m^{(p)})^2 |z|^{2m}  \\
& \quad + \sum_{l=\delta_p +1}^{\infty} l (c_l^{(p)} )^2 |z|^{2l}
 \cdot \sum_{m=\delta_p + 1}^{\infty} m (c_m^{(p)} )^2 |z|^{2m} .
\end{split}
\end{equation}
From (\ref{eq48}),
as in (\ref{eq58}), we get
\begin{equation}\label{eq51}
\begin{split}
\sum_{m=\delta_p+1}^{\infty} (c_m^{(p)})^2 |z|^{2m}
& \leq \sum_{m=\delta_p +1}^{\infty} C p \frac{1}{(2r)^{2m}}
\frac{1}{ \big| \log(|2r|^2) \big|^p } |z|^{2m} \\
%& \leq   C p  \frac{1}{ \big| \log(|2r|^2) \big|^p }
%\sum_{m=\delta_p +1}^{\infty}  \Big( \frac{|z|}{ 2r }\Big)^{2m} .
&\leq Cp \frac{1}{ \big| \log(|2r|^2) \big|^p }
4\cdot  \bigg( \frac{|z|}{ 2r }\bigg)^{2\delta_p +2} .
\end{split}
\end{equation}
From (\ref{eq52}) for $\tau =1$ and (\ref{eq51}), we get
\begin{equation}\label{eq53}
\begin{split}
\sum_{m=\delta_p+1}^{\infty} (c_m^{(p)})^2 |z|^{2m}
& \leq 4C \frac{1}{2^{ 2\alpha' p} } \beta_p^{\mathbb{D}^*}(z)
\bigg( \frac{|z|}{ 2r }\bigg)^2  .
\end{split}
\end{equation}
From (\ref{eq58}), (\ref{eq68}), (\ref{eq72}) and (\ref{eq53}), we get
\begin{equation}\label{eq73}
\begin{split}
|I_{4,p}| \leq  & C' \bigg(\frac{|z|}{2r} \bigg)^2 (p+2)(p+1)
\frac{1}{2^{2\alpha' p }} \beta_p^{\mathbb{D}^*}(z) \cdot
4C \frac{1}{2^{2\alpha' p} } \beta_p^{\mathbb{D}^*}(z)
 \bigg(\frac{|z|}{2r} \bigg)^2   \\
& + \Bigg[ \bigg(\frac{4}{3}\bigg)^2 C' \bigg( \frac{|z|}{2r} \bigg)^2
 (p + 1) \frac{1}{2^{2\alpha' p}}
 \beta_p^{\mathbb{D}^*}(z) \Bigg]^2  \\
\leq & C'' p^2 \frac{1}{2^{4\alpha' p}}
\bigg(\frac{|z|}{2r} \bigg)^4 \beta_p^{\mathbb{D}^*}(z)^2 .
\end{split}
\end{equation}
Thus, by (\ref{eq73}) we obtain
\begin{equation}\label{eq74}
\begin{split}
\Bigg | \big( \log |z|^2 \big)^2 \cdot \frac{I_{4,p} }{
  \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }  \Bigg |
& \leq C'' p^2 \frac{1}{2^{4\alpha' p}}
\bigg(\frac{|z|}{2r} \bigg)^4 \Big( \log |z|^2 \Big)^2 .
\end{split}
\end{equation}
Since the function $f(x) = x^4 (\log x^2)^2$ is bounded on
the interval $]0,1[$, from (\ref{eq74}), we get
\begin{equation}\label{eq75}
\begin{split}
\sup_{  0<|z| \leq c' p^{-A'} } \Bigg | \big( \log |z|^2 \big)^2
\cdot \frac{I_{4,p} }{ \big( \beta_p^{\mathbb{D}^*}(z) \big)^2 }
 \Bigg |
\leq C''' p^2 \frac{1}{2^{4\alpha' p}} .
\end{split}
\end{equation}
Since $c' p^{-A'} > b e^{-p^{\gamma}}$
 for $p\gg 1$, we get (\ref{eq26}) for $j=4$ from (\ref{eq75}).

The proof of Lemma \ref{lem} is completed.


\subsection{Proof of Corollary \ref{cor}}\label{s2.3}
Let $\Gamma$ be a geometrically finite Fuchsian group of the
 first kind, without elliptic elements,
then as explained in \cite[p956]{AMM21},
$\Sigma:= \Gamma \backslash \mathbb{H}$ can be compactified
by finitely many points $D=\{a_1,\cdots, a_N\}$
into a compact Riemann surface $\overline{\Sigma}$ with genus $g$
such that the following equivalent conditions (i)-(iv)
 are fulfilled:

\vskip 5pt
(i) $\Sigma = \overline{\Sigma} \setminus D$ admits a complete
K\"ahler\textendash Einstein metric $\omega_{\Sigma}$ with
$Ric_{\omega_{\Sigma}} = - \omega_{\Sigma}$,

(ii) $2g-2+N >0$,

(iii) the universal cover of $\Sigma$ is the upper-half plane
$\mathbb{H}$,

(iv) $L=K_{\overline{\Sigma}} \otimes
\mathcal{O}_{\overline{\Sigma}}(D)$ is ample,
 where $K_{\overline{\Sigma}} = T^{*(1,0)} \overline{\Sigma}$
  is the canonical line bundle on $\overline{\Sigma}$.

\vskip 5pt
\noindent
From \cite[Lemma 6.2]{AMM21}, there exists a singular Hermitian
metric on $L$ such that $(\Sigma, \omega_{\Sigma})$ and the formal
 square root of $(L,h)$ satisfy the condition \ref{alpha}
  and \ref{beta}.

From \cite[the proof of Lemma 6.2]{AMM21}, $\omega_{\Sigma}$ is
the K\"ahler\textendash Einstein form of constant negative curvature $-4$,
 induced by the Poincar\'e form
 $\omega_{\mathbb{H}} = \frac{ idz \wedge d\bar{z}}{ 4|{\rm Im} z|^2}$
 on $\mathbb{H}$,
and every $a\in D$ has a coordinate neighborhood
$(\overline{U}_a, z)$ in $\overline{\Sigma}$ such that
in this coordinate $\omega_{\Sigma}$ is exactly given by
 $\omega_{\mathbb{D}^*}(z)$ on
  $U_a = \overline{U}_a \setminus \{a\}$. Moreover, the curvature
  of the line bundle $(L|_{\Sigma}, h)$ is given by
  $-2i\omega_{\Sigma}$ and thus the curvature of the
  (formal) square root of $(L,h)$ is $-i\omega_{\Sigma}$.
Therefore, from \cite[Corollary 2.4]{AMM21}, we get that for any
 $k,m\in \mathbb{N}$ and any compact set $K\subset \Sigma$,
\begin{equation}\label{eq76}
B_p(x) = \frac{1}{\pi} p - \frac{1}{2\pi} + \mathcal{O}(p^{-k}), \;\;\;\;
\text{in} \;\; C^m(K) \;\; \text{as} \;\;
p\rightarrow +\infty.
\end{equation}
Hence, from (\ref{eq6}), we get
\begin{equation}\label{eq77}
\sup_{  K }  \Bigg | \frac{ J^*_{p,(2)} \omega_{FS,p}(z) } {
  2p \; \omega_{\Sigma} (z)  }  - \frac{1}{2\pi} \Bigg |
   = \mathcal{O}(p^{-\infty}) .
\end{equation}
On the coordinate neighborhood $U_a$ of $a\in D$, we have
$\omega_{\Sigma} = \omega_{\mathbb{D}^*}$.
%Thus, from Theorem \ref{thm_MainThm}, we get
%\begin{equation}\label{eq78}
%\sup_{  U_a }  \Big | \frac{  \frac{1}{p} J^*_{p,(2)}
%\omega_{FS,p}(z) } {\omega_{\Sigma} (z)  }  \Big |
%= \mathcal{O}(p^4).    \end{equation}
Combine Theorem \ref{thm_MainThm} and (\ref{eq77}), we get
\begin{equation}\label{eq79}
\sup_{ \Sigma }  \Bigg | \frac{ J^*_{p,(2)} \omega_{FS,p}(z) } {
  p \; \omega_{\Sigma} (z)  } \Bigg | = \mathcal{O}(p^3).
\end{equation}

As explained in \cite[(6.36)]{AMM21},
 the space $\mathcal{S}_{2p}^{\Gamma}$ of cusp forms (Spitzenformen)
  of weight $2p$ of $\Gamma$ endowed with the Petersson scalar
  product is isometric with the space of ${\bL}^2$ holomorphic
  sections of $L^p$ over $\Sigma$ (cf. (1.2)) with respect to
  the volume form $\omega_{\Sigma}$ and the metric $h^p$ on $L^p$.
The Bergman kernel $B_p$ of $H^0_{(2)}(\Sigma, L^p)$ can
be identified to the Bergman kernel $S_p^{\Gamma}$
of $\mathcal{S}_{2p}^{\Gamma}$ (cf.  \cite[(6.37)]{AMM21}).
Thus, by (\ref{eq6}) and (\ref{eq.berg}), we get
\begin{equation}\label{eq.berg1}
\omega_{\Sigma}^{Ber,p} = \frac{i}{2\pi} \partial \bar{\partial} \log (B_p(z)),
\qquad 
\frac{1}{p} J^*_{p,(2)} \omega_{FS,p}
= \frac{1}{\pi} \omega_{\Sigma} + \frac{1}{ p} \omega_{\Sigma}^{Ber,p}.
\end{equation}
From (\ref{eq79}) and (\ref{eq.berg1}), we get (\ref{eq10}). 
The proof of Corollary \ref{cor} is completed.


