\section{Logical independence of the axioms}\label{App:indpendence}

In this appendix we study the logical independence of the axioms characterizing each of the toll allocation methods described along the paper.

\subsection{Logical independence of the axioms for the SPS method}\label{appA1}
\setcounter{theorem}{0} % Set it to the number before the desired theorem number
\renewcommand{\thetheorem}{4.1} % Manually set the numbering
\begin{theorem}
The SPS method is the only method satisfying efficiency, the inessential segment property, the weighted segment symmetry property and the covariance property.
\end{theorem}

Logical independence of the axioms in Theorem \ref{th:tauvalue} can be shown by the following alternative methods. 
\begin{enumerate}
\item Let $f$ be the method which allocates to each segment the toll collected from all the highway trips that use that segment.
\begin{equation*}
f_{i}(N,T) = \sum_{h=1}^{i}\sum_{k=i}^{n}t_{hk}, \hspace{0.2cm} \mbox{ for all } i \in N \hspace{0.2cm} \text{and for all } \hspace{0.2cm} T \in \mathcal{T}^{N}.
\end{equation*}

This method satisfies all properties with the exception of efficiency property.

\item Let $f$ be the combined method defined as 
\begin{equation*}
f(N,T) = \begin{cases} f'(N,T), \hspace{0.2cm} &\text{if} \hspace{0.2cm} T=T'; \\
f^{Sp}(N,T), \hspace{0.2cm} &\text{otherwise.}
\end{cases}
\end{equation*}
It suffices to take the toll allocation problem $(N,T')$, with $N=\{1, 2\}$, $t_{11}=1$, $t_{22}=2$, $t_{12}=0$ and   $f'(N,T')=(2,1)$, to state that this method verifies all properties except covariance.

\item Consider the SES method for toll allocation problems specified by
\begin{equation*}
f^{Se}_{i}(N,T) = \sum_{h=1}^{i}\sum_{k=i}^{n}\frac{t_{hk}}{k-h+1}, \hspace{0.2cm} \forall i \in N \hspace{0.2cm} \text{and} \hspace{0.2cm} T \in \mathcal{T}^{N}.
\end{equation*}
This method satisfies all properties except weighted segment symmetry.
\item  Let $f$ be the combined method defined as 
\begin{equation*}
f(N,T) = \begin{cases} f'(N,T), \hspace{0.2cm} &\text{if} \hspace{0.2cm} T\in \widetilde{T}^{N}; \\
f^{Sp}(N,T), \hspace{0.2cm} &\text{otherwise,}
\end{cases}
\end{equation*}

where $\widetilde{T}^{N}=\{T\in T^N\, :\, N=\{1,2,3\},\, t_{12}=t_{13}=0\ {\rm and}\ t_{23}>0\}$ and $f'_i(N,T)=t_{ii}+t_{23}/3$ for all $i\in N.$
This method satisfies all properties except the inessential segment property.
\end{enumerate}

\clearpage
\subsection{Logical independence of the axioms for the SCS method}\label{appA2}
\renewcommand{\thetheorem}{5.1} % Manually set the numbering
\begin{theorem}
The SCS method is the only method satisfying efficiency, linearity, the inessential segment property, weak segment symmetry and indifference to individual extensions. 
\end{theorem}

We will show that the axioms used in Theorem \ref{th:ax1AT} are independent.

\begin{enumerate}
    \item The SES method
    \begin{equation*}
    f_{i}(N,T) = \sum_{h=1}^{i}\sum_{k=i}^{n}\frac{t_{hk}}{k-h+1}, \hspace{0.2cm} \text{for every} \hspace{0.1cm} i \in N \hspace{0.2cm} \text{and for every} \hspace{0.2cm} T \in \mathcal{T}^{N}.
    \end{equation*}
    satisfies efficiency, the inessential segment property, weak segment symmetry and linearity, but fails indifference to individual extensions. This follows from the fact that for any unitary toll matrix, $\delta^{hk}$, the SES method assigns to every segment $i \in \mathcal{P}([h,k])$, $1/(k-h+1)$, while segments outside $\mathcal{P}([h,k])$ receive a payoff of zero. Thus, for trip $[j,k]$, with $|[j,k]| > |[h,k]|$ and $i \in \mathcal{P}([h,k])$ such that $i \neq h$, we will always have that $f_{i}(N, \delta^{hk}) \neq f_{i}(N, \delta^{jk})$.

    \item The method 
    \begin{equation*}
    f_{i}(N,T) = \frac{1}{n}\sum_{h=1}^{n}\sum_{k=h}^{n}t_{hk}, \hspace{0.2cm} \text{for every} \hspace{0.1cm} i \in N \hspace{0.2cm} \text{and  for every} \hspace{0.2cm} T \in \mathcal{T}^{N},
    \end{equation*}
    satisfies efficiency, weak segment symmetry, linearity and indifference to individual extensions, but does not verify the inessential segment property.

    \item The method
    \begin{equation*}
    f_{i}(N,T) = 0, \hspace{0.2cm} \text{for every} \hspace{0.1cm} i \in N \hspace{0.2cm} \text{and  for every} \hspace{0.2cm} T \in \mathcal{T}^{N},
    \end{equation*}
    satisfies weak segment symmetry, linearity, the inessential segment property and indifference to individual extensions, but fails efficiency.

    \item The method 
    \begin{equation*}
    f_{i}(N,T) = \sum_{k=i}^{n}t_{ik}, \hspace{0.2cm} \text{for every} \hspace{0.1cm} i \in N \hspace{0.2cm} \text{and  for every} \hspace{0.2cm} T \in \mathcal{T}^{N}, 
    \end{equation*}
    satisfies efficiency, the inessential segment property, linearity and indifference to individual extensions, but fails weak segment symmetry.

    \item The method \begin{equation*} f_{i}(N,T) = 
    \begin{cases}
    f_{i}^{Sc}(N,T), \hspace{0.2cm} \text{for} \hspace{0.2cm} T = \delta^{hk}, \hspace{0.1cm} h, k \in N;  \\
    f_{i}^{Se}(N,T), \hspace{0.2cm} \text{otherwise}, 
    \end{cases}
    \end{equation*}
    for every $i \in N$ and  for every $T \in \mathcal{T}^{N}$, satisfies efficiency, the inessential segment property, indifference to individual extensions and weak segment symmetry, yet fails linearity (take $T = \delta^{hk}$ and $T' = \delta^{h'k'}$, then $T + T'$ is not a unitary toll matrix, so $f(N, T+T') = f^{Se}(N, T+T')$, whereas $f(N,T) = f^{Sc}(N,T)$ and $f(N,T') = f^{Sc}(N,T')$).
\end{enumerate}

\renewcommand{\thetheorem}{5.2} % Manually set the numbering
\begin{theorem}
The SCS method is the only method satisfying toll component fairness and sub-highway efficiency. 
\end{theorem}

We show logical independence of the properties stated in Theorem \ref{th:atsol} by presenting two alternatives methods for highway toll allocation problems $T\in \mathcal{T}^N$.
\begin{enumerate}
\item Let $f$ be the method  in which no toll is allocated to any segment,
\begin{equation*}
f_{i}(N,T) = 0, \hspace{0.2cm} \text{for every} \hspace{0.1cm} i \in N \hspace{0.2cm} \text{and} \hspace{0.2cm} T \in \mathcal{T}^{N}.
\end{equation*}

Thus, $f$ satisfies toll component fairness, but not sub-highway efficiency.

\item Let $f$ be the SES method  
\begin{equation*}
f_{i}(N,T) = \sum_{h=1}^{i}\sum_{k=i}^{n}\frac{t_{hk}}{k-h+1}, \hspace{0.2cm} \text{for every} \hspace{0.1cm} i \in N \hspace{0.2cm} \text{and} \hspace{0.2cm} T \in \mathcal{T}^{N}.
\end{equation*}

This method satisfies sub-highway efficiency, but not toll component fairness.
\end{enumerate}

