\section{Proofs}
\label{sec:app:proofs}

\subsection{Algorithmic Part}

The discrete \Frechet distance and the \DTW{q} distance between two curves of complexity $m',m''$ can be computed using dynamic programming in $\Oh{m'm''}$ time~\citep{eiter1994computing, dtw1, dtw2}. Here we show how to efficiently compute the $k$-DTW distance.

First, we prove the correctness and the running time of \cref{alg:compute:exact}, that computes the $k$-DTW distance of two given curves.

\begin{theorem}[Restatement of \cref{thm:computing:kdtw}]
     \label{thm:computing:kdtw:app}
    Given two curves $\sigma$ and $\tau$, $|\sigma|=m'$ and $|\tau|=m''$, and a parameter $k$, \cref{alg:compute:exact} returns $\distkDTW{\sigma}{\tau}$ in $\Oh{m'm''z}$ time, where $z$ is the number of distinct distances between any pair of vertices in $\sigma$ and $\tau$. 
\end{theorem}
\begin{proof}[Proof of \cref{thm:computing:kdtw}/\ref{thm:computing:kdtw:app}]
    Consider an arbitrary but fixed traversal $T$. We prove that there exists an iteration $l^*$ where the cost considered by \cref{alg:compute:exact} equals the exact $k$-DTW cost of $T$, i.e., the sum of the largest $k$ distances in the traversal $T$, which we denote $DTW_k(T)$.

    Consider iteration $l= l^*$ where $E[l^*]$ is the smallest element that appears in the sum of largest $k$ elements $DTW_k(T)$. Let $k_{l}$ be the number of elements of the matrix $D$ that appear in $T$ such that $D[i,j] > E[l]$. Note, that in iteration $l^*$ it holds that $k_{l^*}< k \leq k_{l^*+1}$. We note that the margin case where $k>|T|$ implies, similarly to \cref{def:kdtw}, that some distances will be filled with zeros. This in turn implies that $E[l^*]=0$ and thus $l^* = z+1$ is the largest possible index that occurs in \cref{alg:compute:exact}. Therefore the upper bound $k_{l^*+1}=k_{z+2}$ is undefined and does not apply in this case.

    Further, we have that
    \begin{align*}
        \text{cost}(T,l^*)&\coloneqq k\cdot E[l^*]+\sum_{(i,j)\in T} \max \lbrace D[i,j]-E[l^*], 0\rbrace \\
        &= (k-k_{l^*}) \cdot E[l^*] + \sum_{\substack{(i,j)\in T,\\D[i,j] > E[l^*]}} (D[i,j]-E[l^*]+E[l^*]) = \mathrm{DTW}_k(T),
    \end{align*}
    since the sum ranges exactly over the $k_{l^*}$ largest elements and no matter how often $E[l^*]$ appears along $T$, it is added exactly $k-k_{l^*}$ times, i.e., the required number of times to complete the sum of $k$ largest elements, which equals $\text{DTW}_k(T)$.

    Next, we prove that in all other iterations, the considered $\text{cost}(T,l)$ cannot be smaller than the actual $k$-DTW cost $\text{DTW}_k(T)$. To this end, we make a case distinction below. We define $T_k\subseteq T$ to be an arbitrary but fixed subset indexing $|T_k|=k$ largest elements $D[i,j]$ in $T$, where ties are broken arbitrarily. In the margin case that $k>|T|$, we set $T_k=T$ (the remaining elements are filled with zeros anyway, cf. \cref{def:kdtw}). Similarly to the discussion above, if $k>|T|$, no iteration $l>l^*$ exists, and we can proceed directly with the second case where $l<l^*$.

    \begin{description}
    \item[$l > l^*$:] Note that for all elements $(i,j)\in T_k$ it holds that $D[i,j] > E[l]$, since $k_l\geq k$.
Then we have that
    \begin{align*}
        \text{cost}(T,l) & = k\cdot E[l]+\sum_{(i,j)\in T} \max \lbrace D[i,j]-E[l], 0\rbrace\\
        & =k \cdot E[l]+\sum_{\substack{(i,j)\in T_k}} \max \lbrace D[i,j]-E[l], 0\rbrace + \sum_{(i,j)\notin T_k} \max \lbrace D[i,j]-E[l], 0\rbrace\\
        &= \sum_{(i,j)\in T_k}  D[i,j] + \sum_{(i,j)\notin T_k} \max \lbrace D[i,j]-E[l], 0\rbrace\\
        &= DTW_k(T) + \sum_{(i,j)\notin T_k} \max \lbrace D[i,j]-E[l], 0\rbrace \geq DTW_k(T),
    \end{align*}
    since the sum over $(i,j)\notin T_k$ is non-negative.

    \item[$l < l^*$:] In this case, we have $k_l<k$ and for all $(i,j)\in T_k\setminus T_{k_l}$ it holds that $E[l]>D[i,j]$. Thus, the sum is taken over less than $k$ elements, and we have that
    \begin{align*}
        \text{cost}(T,l) & = k\cdot E[l]+\sum_{(i,j)\in T} \max \lbrace D[i,j]-E[l], 0\rbrace\\
        & = (k-k_l)\cdot E[l]+\sum_{(i,j)\in T_{k_l}}  D[i,j] 
        > \sum_{(i,j)\in T_k}  D[i,j] = DTW_k(T).
    \end{align*}
    \end{description}

    Now, we consider an optimal $k$-DTW traversal $T^*$. By the above arguments the cheapest cost for $T^*$ across all iterations equals the exact $k$-DTW cost $DTW_k(T^*)=OPT$.
    We also have that the considered cost for any suboptimal $T'$ is never smaller than the actual $k$-DTW cost $DTW_k(T')$. By suboptimality of $T'$, its actual $k$-DTW cost is strictly larger than the optimal $k$-DTW cost of $T^*$. Thus, we have that
    \[
        \min_{l\in[z+1]} \text{cost}(T',l)\geq DTW_k(T')>DTW_k(T^*)=OPT.
    \]
    Consequently, the cost returned by \cref{alg:compute:exact} equals the optimal $k$-DTW cost of the optimal traversal $T^*$, since it corresponds to the smallest cost considered in the $DTW(D')+k\cdot E[l]$ minimization across all iterations $l\in[z+1]$.

    The running time follows since the initialization can be completed by computing all $m'm''$ pairwise distances $D[i,j]$ and inserting them into a binary search tree, skipping duplicates. We thus only keep the $z+1$ distinct items in $O(m'm''\log(z))$ time and read them in the sorted order in another $O(z)$ time to build the array $E$.
    Then, \cref{alg:compute:exact} runs $z+1\leq m'm''+1$ iterations and in each iteration it updates all distances in the matrix $D'$, which takes time $O(m'm'')$, and runs one DTW calculation in time $O(m'm'')$. The final cost update takes only constant time. The total time is thus $O(m'm''\log (z) + z + m'm''z)= O( m'm''z)$.
\end{proof}

We next provide a quadratic time $(1+\eps)$-approximation. As an ingredient towards this goal, we first show how to obtain a simple $k$-approximation for $k$-DTW by calculating the discrete \Frechet distance in quadratic time. 

\begin{lemma}[Restatement of \cref{lem:kdtw:kapprox}]
\label{lem:app:kdtw:kapprox}
    Given two curves $\sigma=(v_1,\ldots, v_{m'})$ and $\tau=(w_1,\ldots,w_{m''})$, and a parameter $k$, it holds that $\distDF{\sigma}{\tau}$ is a $k$-approximation for $\distkDTW{\sigma}{\tau}$, which can be computed in time $O(m'm'')$. In particular, it holds that $\distDF{\sigma}{\tau} \leq \distkDTW{\sigma}{\tau} \leq k\cdot \distDF{\sigma}{\tau}$.
\end{lemma}
\begin{proof}[Proof of \cref{lem:kdtw:kapprox}/\ref{lem:app:kdtw:kapprox}]
    Let $T_F$ and $T_k$ be traversals of $\sigma$ and $\tau$ realizing their discrete \Frechet and $k$-DTW distances, respectively. Using the notation of \cref{def:kdtw} we have
    \begin{align*}
        \distDF{\sigma}{\tau} &= s_1^{(T_F)} \leq s_1^{(T_k)} \leq \sum_{l=1}^k s_l^{(T_k)} = \distkDTW{\sigma}{\tau}  \leq \sum_{l=1}^k s_l^{(T_F)} \leq k\cdot s_1^{(T_F)} = k\cdot \distDF{\sigma}{\tau}, 
    \end{align*}
    The running time of $O(m'm'')$ for computing $\distDF{\sigma}{\tau}$ was proven in \citep{eiter1994computing}.
\end{proof}

Using the $k$-approximation and rounding of distances, we can adapt \cref{alg:compute:exact} to produce a $(1+\varepsilon)$-approximation for the $k$-DTW distance.

\begin{theorem}[Restatement of \cref{col:approx:kdtw}]
    \label{col:approx:kdtw:app}
    Given two curves $\sigma$ and $\tau$, $|\sigma|=m'$ and $|\tau|=m''$, and a parameter $k$, there exists a $(1+\eps)$-approximation algorithm for any $0 < \eps \leq 1$ that runs in $O(m'm''\frac{\log(k/\eps)}{\eps})$ time.
\end{theorem}

\begin{proof}[Proof of \cref{col:approx:kdtw}/\ref{col:approx:kdtw:app}]
    Let $\eps'=\eps/2$. 
    We perform the following modifications of \cref{alg:compute:exact}:
    \begin{enumerate}[1)]
        \item We first compute $\distDF{\sigma}{\tau}$, which gives a $k$-approximation for $\distkDTW{\sigma}{\tau}$ in time $O(m'm'')$ by \cref{lem:kdtw:kapprox}/\ref{lem:app:kdtw:kapprox}.
        Now, set $d_{\min}=\frac{\eps'\cdot  \distDF{\sigma}{\tau}}{k}$, and $d_{\max} = \distDF{\sigma}{\tau}$.  

        When we build the initial distance matrix $D$, we round all non-zero distances $D[i,j]$ with $0< D[i,j] < d_{\max}$ to their next higher power of $(1+\eps')^i\cdot d_{\min}$, for 
        \begin{align*}
            i\in\left\{0,\ldots,\left\lceil \log_{1+\eps'} \left(\frac{d_{\max}}{d_{\min}}\right) \right\rceil\right\} = \left\{0,\ldots,\left\lceil \log_{1+\eps'} \left(\frac{k}{\eps'}\right) \right\rceil\right\}.
        \end{align*}

        Through this modification, the cost of each edge and thus of any traversal cannot decrease. However, increasing the costs induces an additive as well as a multiplicative error, which we bound as follows:
        \begin{enumerate}[i)]
            \item The sum of up to $k$ distances $0 < D[i,j] \leq d_{\min}$ along any traversal $T$ can only increase by at most 
            \begin{align*}
                k \cdot d_{\min} = k\cdot \frac{\eps' \cdot \distDF{\sigma}{\tau}}{k} =\eps'\cdot \distDF{\sigma}{\tau}, 
            \end{align*}
            since their next power in the progression is $(1+\eps')^0\cdot d_{\min}=d_{\min}$.

            \item Any distance $d_{\min} < D[i,j] < d_{\max}$ can only increase by at most a factor $(1+\eps')$ by construction. By linearity, this also holds for any sum of these distances.
        \end{enumerate}
        Using these bounds and \cref{lem:kdtw:kapprox}/\ref{lem:app:kdtw:kapprox}, the cost of the optimal traversal after rounding the distances is bounded by 
        \[
            (1+\eps') \cdot \distkDTW{\sigma}{\tau} + \eps' \cdot \distDF{\sigma}{\tau} \leq (1+2\eps') \cdot \distkDTW{\sigma}{\tau} = (1+\eps) \cdot \distkDTW{\sigma}{\tau}.
        \]        

        \item When we set up the array $E[1..z+1]$, we can omit all indices $l$ where $E[l]>d_{\max}=\distDF{\sigma}{\tau}$. To see this, recall from the proof of \cref{thm:computing:kdtw}/\ref{thm:computing:kdtw:app} that the cost of any traversal $T$ in iteration $l$ is lower bounded by $k\cdot E[l]$, since we add this amount to a sum of further non-negative costs. Using this fact together with \cref{lem:kdtw:kapprox}/\ref{lem:app:kdtw:kapprox} again, the cost of $T$ in iteration $l$ is lower bounded by 
        \begin{align*}
            k\cdot E[l] > k \cdot \distDF{\sigma}{\tau} \geq \distkDTW{\sigma}{\tau},
        \end{align*}
        which implies that the cost of $T$ is not optimal in iteration $l$.
    \end{enumerate}

    All modifications can be performed initially in $O(m'm'')$ time. Further, $E[1..z+1]$ contains only $z\in O({\log_{1+\eps'}(k/\eps')}) = O(\frac{\log(k/\eps)}{\eps})$ distinct distances. The running time follows by plugging this into the $O(m'm''z)$ running time bound of \cref{thm:computing:kdtw}/\ref{thm:computing:kdtw:app}.
\end{proof}


Next, we show that the $k$-DTW distance between two curves is not equal to taking the largest $k$ distances from the sum that yields their DTW distance. This precludes the option of simply applying the standard DTW algorithm for the computation of $k$-DTW. We also show that the length of the traversals may differ significantly in both directions, which also precludes using a standard DTW algorithm to estimate the size of a $k$-DTW traversal. 


\begin{lemma}[Full version of \cref{lem:different:short}]\label{lem:different:kdtw}
    Given a parameter $m\in \mathbb{N}$, it holds that:
    \begin{enumerate}[i)]
        \item There exist two curves $\sigma$ and $\tau$ 
        {of complexity $m$}
        in Euclidean space $\REAL^d$, such that 
        the difference $\left||T_{(k-DTW)}|-|T_{(DTW)}|\right|$ of
        the lengths of the optimal $k$-DTW and the optimal DTW traversals of $\sigma$ and $\tau$, denoted $|T_{(k-DTW)}|$ resp. $|T_{(DTW)}|$, 
        is linear in $m$.
        It can hold both, $|T_{(k-DTW)}|<|T_{(DTW)}|$, or $|T_{(k-DTW)}|>|T_{(DTW)}|$.

        \item Assume that $m\geq 5$. Then for any $k$, $1 \leq k \leq 4\lfloor \frac{m}{5} \rfloor$ there exist curves $\sigma$ and $\tau$ of complexity $m$, s.t. $\distkDTW{\sigma}{\tau}$ is not equal to the sum of the largest $k$ distances contributing to $\distDT{\sigma}{\tau}$.
    \end{enumerate} 
\end{lemma}

