\subsection{Learning Theory}
Using a more involved application of the chaining technique, we are able to reduce the dependence on $d$, at the cost of an increased dependence on $m$ and $k$.
To this end, we require terminal embeddings defined as follows.
\begin{definition}[Terminal Embeddings]
For a point set $P\subset \mathbb R^d$, an $\varepsilon$-terminal embedding is a mapping $f:\mathbb{R}^d\rightarrow \mathbb{R}^{h}$ such that for all $p\in P$ and all $q\in \mathbb{R}^d$
\[(1-\varepsilon)\cdot\|p-q\|\leq \|f(p)-f(q)\|\leq (1+\varepsilon)\|p-q\|.\]
\end{definition}
Terminal embeddings are similar to Johnson-Lindenstrauss type embeddings, albeit stronger in the sense that $q$ can be any point in $\mathbb{R}^d$, rather than just applying to pairwise distances. Nevertheless, the target dimensions of Johnson-Lindenstrauss embeddings and terminal embeddings are essentially identical, as proven by \citet{NarayananN19} and summarized in the following lemma.
\begin{lemma}
    There exist terminal embeddings of target dimension $h\in O(\varepsilon^{-2}\log |P|)$.
\end{lemma}
An immediate consequence of the terminal embedding guarantee is that both DTW and $k$-DTW are preserved up to $(1\pm \varepsilon)$ factors, if the target dimension is in $O(\varepsilon^{-2}\log (m n))$. In the following, we show that they also yield an alternative bound on the net size for median curves.

\begin{lemma}
    \label{lem:highdimnet}
For an absolute constant $c$, we have that
    \[|\mathcal{N}(V_{P,DTW},\|.\|_{\infty},\varepsilon)|\leq \exp(c\cdot m^3\log^2(mn/\varepsilon) \cdot \varepsilon^{-2})\] 
and
    \[|\mathcal{N}(V_{P,k\text{-}DTW},\|.\|_{\infty},\varepsilon)|\leq \exp(c\cdot  m \cdot k^2\cdot \log^2(mnk/\varepsilon) \cdot \varepsilon^{-2}).\] 
\end{lemma}
\begin{proof}
Let $z=m$ for DTW and $z=k$ for $k$-DTW.
We first apply a terminal embedding of target dimension $h\in O(z^2\cdot \varepsilon^{-2}\log(mn))$, which preserves DTW and $k$-DTW up to $(1\pm \varepsilon/z)$ factors, and hence both up to an additive error of $\varepsilon$ as all the points on the curves are assumed to have at most unit Euclidean norm. Subsequently, we apply \cref{lem:simplenet}, yielding $2\varepsilon$-nets of size 
    \[|\mathcal{N}(V_{P,DTW},\|.\|_{\infty},\varepsilon)|\leq \exp(c\cdot h\cdot m\cdot \log \frac{m}{\varepsilon})\] 
and
    \[|\mathcal{N}(V_{P,k\text{-}DTW},\|.\|_{\infty},\varepsilon)|\leq \exp(c\cdot h\cdot m\cdot \log \frac{k}{\varepsilon}).\] 
Inserting the appropriate bounds for $h$ and rescaling $\varepsilon$ yields the claim.
\end{proof}

With this lemma, we now give the dimension-free bound on the Rademacher and Gaussian complexity claimed in \cref{thm:gen*}.
\begin{proof}[Proof of Theorem \ref{thm:gen*} for high dimensions]
As with the proof of the low-dimensional case, we rely on the chaining technique. There is, however, a key difference. Let $j_{\max}$ be chosen such that $2^{-j_{\max}}= 1/\sqrt{n}$.
We then have due to the triangle inequality
\begin{align}
\label{eq:smallchain}
\mathcal G(P):=\mathbb{E} \sup_{\psi}\left\vert \frac{1}{n}\sum_{i=1}^n d(\sigma_i,\psi)g_i\right\vert 
&\leq \sum_{j=0}^{j_{\max}}\mathbb{E} \sup_{\psi} \left\vert \frac{1}{n} \sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)g_i\right\vert \\
\label{eq:largechain}
&+\!\!\sum_{j=j_{\max}}^{\infty}\!\!\mathbb{E} \sup_{\psi} \left\vert \frac{1}{n} \sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)g_i\right\vert.
\end{align}
We bound \cref{eq:smallchain} and \cref{eq:largechain} separately. For the latter, i.e., \cref{eq:largechain}, observe that 
\begin{align*}
    &\sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)^2 \leq n\cdot 2^{-2j}.
\end{align*}

Applying the Cauchy-Schwarz inequality to \cref{eq:largechain} and inserting this bound then yields
\begin{align*}
\sum_{j=j_{\max}}^{\infty}\mathbb{E} \sup_{\psi} \left\vert \frac{1}{n} \sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)g_i\right\vert 
&\leq \sum_{j=j_{\max}}^{\infty} \frac{1}{n}\,\mathbb{E}\sqrt{\sum_{i=1}^n g_i^2} \cdot \sqrt{\sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)^2} \\
& \leq \sum_{j=j_{\max}}^{\infty} 2^{-j} \leq 2\cdot 2^{-j_{\max}} \in O(1/\sqrt{n}).
\end{align*}
For the former, i.e., \cref{eq:smallchain}, we observe that the variance bounds 
derived in the proof of the low dimensional case are still valid. That is, we have that
\begin{align*}
\varsigma^2_j\coloneqq \sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)^2\leq 
 n\cdot \max\,&d(\sigma_i,\psi)^2
 \in \begin{cases}
    O(n\cdot m^2) & \text{for } j=0, \text{ and DTW} \\
    O(n\cdot k^2) & \text{for } j=0, \text{and }k\text{-DTW}\\
    O(n\cdot 2^{-2j}) & \text{otherwise.}
\end{cases}
\end{align*}


Thus for some absolute constant $c$, for every $j>0$
\begin{align*}
\mathbb{E} \sup_{\psi} \left\vert \frac{1}{n} \sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)g_i\right\vert 
&\leq \frac{1}{n}\sqrt{\varsigma^2_j \log(2|\mathcal N(V_P,\|.\|_{\infty},2^{-j})|)} \\
&\leq \sqrt{\frac{c\cdot  m \cdot z^2 \cdot 2^{-2j}\cdot \log^2(mnz2^j)\cdot 2^{2j}}{n}}.
\end{align*}
and for $j=0$
\begin{align*}
&\mathbb{E} \sup_{\psi} \left\vert \frac{1}{n} \sum_{i=1}^n (v^{\psi,1}_i-v^{\psi,0}_i)g_i\right\vert 
\leq \sqrt{\frac{c\cdot  m \cdot z^4\cdot \log^2(mnz)}{n}}.
\end{align*}

Thus, we have
\begin{align}
\nonumber
 \sum_{j=0}^{j_{\max}}\mathbb{E} \sup_{\psi} \left\vert \frac{1}{n} \sum_{i=1}^n (v^{\psi,j+1}_i-v^{\psi,j}_i)g_i\right\vert
&\leq (j_{\max}+1)\cdot \sqrt{\frac{c\cdot  m \cdot z^4\cdot \log^2(mnz2^{j_{\max}})}{n}} \\
\nonumber
&\in O\left(\sqrt{\frac{c\cdot  m \cdot z^4\cdot \log^4(mn)}{n}}\right),
\end{align}
since $z\in O(m)$.
Combining both bounds then yields the claim.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:lbrad*}]
We first recall the corresponding bounds for median queries, that is, for curves of complexity $1$. By tightness of Chernoff bounds (see for example Lemma 4 of \citet{KleinY15}), these queries have a Rademacher and Gaussian complexity of $\Omega(\sqrt{1/n})$. Now for every such query, consider a function space for which every point is duplicated $m$ times, that is the point (or complexity $1$ curve) $\sigma$ becomes a complexity $m$ curve $\sigma_m$. In this case $d_{DTW}(\sigma_m,\psi_m) = m\cdot \|\sigma-\psi\|$. Thus, every cost vector is scaled by exactly a factor $m$. By linearity of Rademacher and Gaussian complexity, this likewise increases these complexities by a factor of $m$, yielding the claimed bound of $\Omega(\sqrt{m^2/n})$.
\end{proof}

