    \item the $k$-DTW distance parameter $k=\lfloor2.5\cdot \log(m)\rfloor=17$;
    \item the number of ``peaks'' in the curves in $A_l$: $l\in  
    \lbrace 5,6,7,8\rbrace$;
    \item the size of the ``peaks'' in the $A_l$-type curves: $L=2\cdot \log(m) =13.816$;
    \item the ``small values'' bound $\varepsilon=0.2$; 
    \item the number of curves of each type $A_l$, $B$, $C$: $20$ ($n=60$).
