\section{Derivation of perturbation equations}
We start with the EC field equations for the Weysssenhoff fluid to the leading order without
small contributions of vorticity or acceleration \cite{Palle6,Palle9,Palle10,Palle11}:
\begin{eqnarray}
&&3\frac{\dot{R}^{2}}{R^{2}} = \kappa (\rho + \Lambda)-Q^{2},\hspace{50mm} \nonumber \\
&&2\frac{\ddot{R}}{R}+\frac{\dot{R}^{2}}{R^{2}}= \kappa (\Lambda-p)+Q^{2},
\ \kappa=8\pi G_{N}c^{-4} \nonumber \\
&&Q^{2}=\frac{1}{2}Q_{\mu\nu}Q^{\mu\nu},\ Q^{\mu}_{\ \nu\rho}=u^{\mu}Q_{\nu\rho},\
u^{\mu}Q_{\mu\rho}=0, \nonumber \\
&&Q^{\mu}_{\ ab}+2v^{\mu}_{[a}Q_{b]}=\kappa S^{\mu}_{\ ab},\ Q_{a}=v^{\mu}_{a}Q_{\mu},\
Q_{\mu}=Q^{\nu}_{\ \mu\nu}, \\
&&\rho=\rho_{(c)}+\rho_{(b)}+\rho_{(\gamma)}+\rho_{(\nu)},\
p=p_{(c)}+p_{(b)}+p_{(\gamma)}+p_{(\nu)}, \nonumber \\
&&g^{\mu\nu} = v^{\mu}_{a}v^{\nu}_{b}\eta^{a b},\
\eta_{a b}=diag(+1,-1,-1,-1),\
 \mu,\nu=0,1,2,3, \ a,b=\hat{0},\hat{1},\hat{2},\hat{3}. \nonumber
\end{eqnarray}

It is assumed that we include matter density and pressure of the CDM,
massless neutrinos, baryons and photons (denoted in brackets respectively as (c),($\nu$),(b),($\gamma$)).
The metric includes expansion, acceleration and vorticity:
\begin{eqnarray}
d s^{2}=d t^{2}-R^{2}(t)[d x^{2}+(1-\lambda^{2}(t))e^{2mx}d y^{2}]
-R^{2}(t)d z^{2}-2 R(t)\lambda(t)e^{mx}d y dt,
\end{eqnarray}
\begin{eqnarray*}
\frac{\dot{R}}{R}=H=\frac{\Theta}{3},\ a^{\mu}a_{\mu}=-(\lambda H+\dot{\lambda})^{2},
\ \omega^{2}=\frac{1}{2}\omega_{\mu\nu}\omega^{\mu\nu}=(\frac{\lambda m}{2 R})^{2},\
 m=const.
\end{eqnarray*}

We ignore vorticity ($\omega=m=0$) in this work because it is not essential
for the $\sigma_{8}$ problem, but we retain in our derivations $\tilde{\omega}_{\mu\nu}$ since it
contains torsion.

We use the Bianchi and Ricci identities (note the wrong sign in front of the Mathisson-Papapetrou term
of the Bianchi identity in \cite{Obukhov}):
\begin{eqnarray}
&&(\tilde{\nabla}_{\nu}-2 Q_{\nu})T^{\nu}_{. \mu}+2Q^{\alpha}_{.\mu\beta}T^{\beta}_{. \alpha}
-S^{\nu}_{.\alpha\beta}\tilde{R}^{\alpha\beta}_{. . \mu\nu}=0, \\
&&\tilde{\Gamma}^{\alpha}_{\beta\mu}\equiv\Gamma^{\alpha}_{\beta\mu}
+Q^{\alpha}_{. \beta\mu}+Q_{\beta\mu .}^{\ .  . \ \alpha}+
Q_{\mu\beta .}^{\ .  .  \ \alpha}, \nonumber \\
&&\tilde{R}^{\lambda}_{. \sigma\mu\nu} \equiv
\partial_{\mu} \tilde{\Gamma}^{\lambda}_{\sigma\nu}
-\partial_{\nu} \tilde{\Gamma}^{\lambda}_{\sigma\mu}
+\tilde{\Gamma}^{\lambda}_{\beta\mu}\tilde{\Gamma}^{\beta}_{\sigma\nu}
-\tilde{\Gamma}^{\lambda}_{\beta\nu}\tilde{\Gamma}^{\beta}_{\sigma\mu}, \nonumber \\
&&(\tilde{\nabla}_{\mu}\tilde{\nabla}_{\nu}
-\tilde{\nabla}_{\nu}\tilde{\nabla}_{\mu})u_{\lambda}=
-\tilde{R}^{\sigma}_{. \lambda\mu\nu}u_{\sigma}
-2 Q^{\sigma}_{. \nu\mu}\tilde{\nabla}_{\sigma}u_{\lambda}, \\
&&\tilde{\nabla}_{\alpha}u_{\beta}\equiv\partial_{\alpha}u_{\beta}
-\tilde{\Gamma}^{\nu}_{\beta\alpha}u_{\nu}. \nonumber
\end{eqnarray}

The following identity derived from the Ricci identity is employed (Frenkel's condition
is included $Q^{\mu\nu}u_{\mu}=0,\ \dot{V_{\mu}}\equiv u^{\nu}\tilde{\nabla}_{\nu}V_{\mu}$):
\begin{eqnarray}
&&^{(3)}\tilde{\nabla}_{\mu}(\dot{f})-h^{\nu}_{\mu}(^{(3)}\tilde{\nabla}_{\nu}
f)^{.}
=a_{\mu}\dot{f}+(\tilde{\omega}^{\lambda}_{. \mu}+
\sigma_{\mu .}^{\ \lambda}+\frac{1}{3}\Theta h_{\mu}^{\lambda})
^{(3)}\tilde{\nabla}_{\lambda}f, \\
&&^{(3)}\tilde{\nabla}_{\mu}f \equiv h^{\nu}_{\mu}\tilde{\nabla}_{\nu}f,
h_{\mu\nu}=g_{\mu\nu}-u_{\mu}u_{\nu},\ u^{\mu}u_{\mu}=1. \nonumber
\end{eqnarray}


We show in the Appendix A that the standard decomposition of the conformal tensor is not valid
for any Riemannian geometry. Thus, we do not refer to this decomposition in our derivation
of equations for perturbed quantities.

It is necessary to fix the form of the gauge invariant variables introduced by Ellis et al.
\cite{Ellis1,Ellis2,Challinor}.
This problem we address in the Appendix B.

All the equations are valid only to linear order in perturbed quantities.
The equation for the gauge invariant density contrast can now be derived from the Bianchi identity and
the identity Eq.(6) ((i)=(b) or (c), $w_{i}=\frac{p_{i}}{\rho_{i}}$):
\begin{eqnarray}
\dot{\cal D}_{(i)\mu}&=&-(1+w_{i})[Z_{\mu}+R ^{(3)}\tilde{\nabla}_{\mu}
(\tilde{\nabla}_{\lambda}v^{\lambda}_{(i)})]+R(1+w_{i})\Theta a_{\mu} \nonumber \\
&& -\tilde{\omega}^{\lambda}_{\ \mu}{\cal D}_{(i)\lambda}
-\rho^{-1}_{(i)}R\Theta ^{(3)}\tilde{\nabla}_{\mu}p_{(i)}+\Theta w_{i}{\cal D}_{(i)\mu}, \\
&&{\cal D}_{(i)\mu}\equiv \rho^{-1}_{(i)}R^{(3)}\tilde{\nabla}_{\mu}\rho_{(i)}, \
Z_{(i)\mu}\equiv R^{(3)}\tilde{\nabla}_{\mu}\Theta. \nonumber
\end{eqnarray}

Note that for any vector $X_{\mu}=(0,X_{i})$ the following relation holds to linear order
irrespective of the scalar, vector or tensor spatial perturbations \cite{Kodama}:
\begin{eqnarray}
\dot{X_{\mu}}\equiv u^{\nu}\tilde{\nabla}_{\nu}X_{\mu}=(0,\frac{\partial X_{1}}{\partial t}-H X_{1}
+Q X_{2},\frac{\partial X_{2}}{\partial t}-H X_{2}-Q X_{1},\frac{\partial X_{3}}{\partial t}-H X_{3}).
\end{eqnarray}

From the Eq.(6), EC field equations and Ricci identities, we derive the evolution equation
for $Z_{\mu}$:
\begin{eqnarray}
&&\dot{Z}_{\mu}=4 Q \Psi_{\mu}-\frac{2}{3}\Theta Z_{\mu}-\frac{1}{2}\sum_{i}\kappa \rho_{i}
(1+3w_{i}){\cal D}_{(i)\mu}-u_{\mu}Z_{\nu}a^{\nu} \nonumber \\
&&\ \ \ \ \ \ -\dot{\Theta}a_{\mu}R
-\tilde{\omega}^{\lambda}_{\ \mu}Z_{\lambda}, \\
&&\Psi_{\mu}\equiv R ^{(3)}\tilde{\nabla}_{\mu}Q,\ \dot{\Theta}=2 Q^{2}-\frac{1}{3}\Theta^{2}
+\kappa \Lambda -\frac{1}{2}\sum_{i}\kappa \rho_{i}(1+3w_{i}), \nonumber \\
&&Q\Psi_{\mu}=\frac{1}{2}\sum_{i}\kappa \rho_{i}{\cal D}_{(i)\mu}
-\frac{1}{3}\Theta Z_{\mu}, \ for\ Q\neq 0. \nonumber
\end{eqnarray}

We derive photon field perturbations form the geodesic equations (remembering that massless photons do not
interact with torsion \cite{Hehl}) \cite{Ellis3,Ma,Challinor}:
\begin{eqnarray}
&&{\cal L}f(x^{\mu},p^{\mu})=\frac{d x^{\mu}}{d\sigma}\frac{\partial f}{\partial x^{\mu}}
+\frac{d p^{\mu}}{d\sigma}\frac{\partial f}{\partial p^{\mu}}=C_{f}, \\
&& p^{\mu}\equiv\frac{d x^{\mu}}{d \sigma},\ p^{\mu}\nabla_{\mu}p^{\nu}=0,\
\frac{d p^{\mu}}{d \sigma}+\Gamma^{\mu}_{\nu\lambda}p^{\nu}p^{\lambda}=0, \nonumber \\
&& \Rightarrow p^{\mu}\frac{\partial f}{\partial x^{\mu}}-\Gamma^{\mu}_{\nu\lambda}
p^{\nu}p^{\lambda} \frac{\partial f}{\partial p^{\mu}}=C_{f}, \nonumber
\end{eqnarray}
\begin{eqnarray*}
p_{a}=E(u_{a}+e_{a}),\ p_{a}p^{a}=0,\ u_{a}u^{a}=1,\ e_{a}e^{a}=-1,\ e_{a}u^{a}=0, \\
p^{\mu}=v^{\mu}_{b}p^{b},\ \partial_{b}\equiv v^{\mu}_{b}\frac{\partial}
{\partial x^{\mu}},\ \Gamma^{a}_{bc}\equiv \Gamma^{\mu}_{\nu\lambda}
v^{a}_{\mu}v^{\nu}_{b}v^{\lambda}_{c} \\
\Rightarrow p^{b}\partial_{b}f-\Gamma^{a}_{bc}p^{b}p^{c}(u_{a}\frac{\partial f}{\partial E}
+E^{-1}\frac{\partial f}{\partial e^{a}})=C_{f}.
\end{eqnarray*}

With a definitions:
\begin{eqnarray*}
\rho^{(\gamma)}\equiv \int dEd\Omega E^{3}f(E,e^{b}),\
q^{(\gamma)}_{a}\equiv \int dEd\Omega E^{3}f(E,e^{b})e_{a},
\end{eqnarray*}

we get the equations in linear approximation:
\begin{eqnarray}
&&u^{b}\partial_{b}\rho^{(\gamma)}+\frac{4}{3}\Theta\rho^{(\gamma)}
+h^{ab}\partial_{b}q_{a}^{(\gamma)}=0 \nonumber \\
&&\Rightarrow \frac{\partial{\cal D}_{(\gamma)\mu}}{\partial t}
=H {\cal D}_{(\gamma)\mu}-\frac{4}{3}Z_{\mu}+\frac{4}{3}\Theta R a_{\mu}
-R\rho_{(\gamma)}^{-1\ (3)}\nabla_{\mu}(\partial_{\nu}q_{(\gamma)}^{\nu}), \\
&&u^{b}\partial_{b}q^{c}_{(\gamma)}+\frac{2}{3}\Theta q^{c}_{(\gamma)}
-\frac{1}{3}h^{cd}\partial_{d}\rho_{(\gamma)}=n_{e}\sigma_{T}
(\frac{4}{3}\rho_{(\gamma)}v^{c}_{(b)}-q^{c}_{(\gamma)}).
\end{eqnarray}

It is left to derive evolution equations for CDM and baryon velocities defined by
$u_{\mu}^{(i)}=u_{\mu}+v_{\mu}^{(i)}$ \cite{Challinor}. To linear approximation
in $v^{(b)\mu}$ the Bianchi identity is:
\begin{eqnarray}
2\tilde{\nabla}_{\nu}[(\rho^{(b)}+p^{(b)})u^{(\nu}v^{(b)}_{\mu)}
+2v^{(b)(\nu}u^{\alpha)}\tilde{\nabla}_{\beta}(u^{\beta}S_{\alpha\mu}) \nonumber \\
+u^{\nu}u^{\alpha}\tilde{\nabla}_{\beta}(v^{(b)\beta}S_{\alpha\mu})]
-S_{\alpha\beta}\tilde{R}^{\alpha\beta}_{..\mu\nu}v^{(b)\nu}=0
\end{eqnarray}

The spacelike vector $v^{(b)}_{\mu}=(0,v^{(b)}_{1},v^{(b)}_{2},v^{(b)}_{3})$ of the baryon velocity
evolves according to ($w_{b}=0$):
\begin{eqnarray}
\frac{\partial v_{1}^{(b)}}{\partial t}&=&(G_{1}^{2}+G_{2}^{2})^{-1}[(G_{2}G_{3}-G_{1}G_{4})v_{2}^{(b)}
-(G_{1}G_{3}+G_{2}G_{4})v_{1}^{(b)}+G_{2}H_{2}^{(b)}-G_{1}H_{1}^{(b)}], \nonumber \\
\frac{\partial v_{2}^{(b)}}{\partial t}&=&(G_{1}^{2}+G_{2}^{2})^{-1}[(G_{1}G_{4}-G_{2}G_{3})v_{1}^{(b)}
