\frac{\partial v_{3}^{(b)}}{\partial t}&=&\Theta c_{s}^{2}v_{3}^{(b)}
-\rho_{(b)}^{-1}n_{e}\sigma_{T}(\frac{4}{3}\rho_{(\gamma)}v_{3}^{(b)}-q_{3}^{(\gamma)}),
 \\
G_{1}&=&\kappa\rho_{(b)}+2Q^{2},\ G_{2}=2\dot{Q}+4Q H,\ G_{3}=-c_{s}^{2}\Theta \kappa \rho_{(b)}
+2Q\dot{Q}, \nonumber \\
G_{4}&=&2 Q \kappa\rho_{(b)}+2(4 H\dot{Q}+\ddot{Q}+Q H^{2}+2 \frac{\ddot{R}}{R}Q),\
H^{(b)}_{1,2}=\kappa n_{e}\sigma_{T}(\frac{4}{3}\rho_{(\gamma)}v_{1,2}^{(b)}-q_{1,2}^{(\gamma)}).
\nonumber
\end{eqnarray}

The acceleration function $\lambda (t)$ has evolution defined by the Bianchi identity
(however we use only the first derivative to fix the evolution):
\begin{eqnarray}
\dot{\lambda}&=&[2Q^{2}-\kappa (p+\rho)]^{-1}\lambda[\kappa (p+\rho)H+\kappa \dot{p}
-2(Q^{2}H+Q\dot{Q})], \\
\ddot{\lambda}&=&-\frac{\dot{Q}}{Q}(\dot{\lambda}+\lambda H)-3\lambda H^{2}-4\dot{\lambda}H.
\nonumber
\end{eqnarray}

The Thomson scattering term with $n_{e}=x_{e}n_{H}$ is evaluated using RECFAST code \cite{Seager}
(modified for the EC model),
as well as the other quantities necessary to evaluate $c_{s}^{2}$ \cite{Ma}. We include into the code
the reionization model based on the Planck data.
The CDM velocity vanishes like in the synchronous gauge \cite{Ma}.

\section{Results and discussion}
We restrict perturbations to the scalar spatial ones \cite{Kodama} and decompose our gauge invariant
quantities to the time and spatial parts \cite{Kodama,Ma,Challinor} acknowledging constraint
equations(for hypersurface with a flat metric the harmonic function is $Y^{(k)}(\vec{x})=
e^{\imath \vec{k}\cdot \vec{x}}$):
\begin{eqnarray}
&&{\cal D}^{(i)}_{\mu}(t,\vec{x})=\sum_{k} k \bar{{\cal D}}^{(i)}_{\mu}(t,k)Y^{(k)}(\vec{x}),\
i=c,b,\gamma ,\
Z_{\mu}(t,\vec{x})=\sum_{k} \frac{k^{2}}{R} \bar{Z}_{\mu}(t,k)Y^{(k)}(\vec{x}), \nonumber \\
&& q_{\mu}^{(\gamma)}(t,\vec{x})=\rho_{(\gamma)}\sum_{k} \bar{q}_{\mu}^{(\gamma)}(t,k)Y^{(k)}(\vec{x}),\
v_{\mu}^{(b)}(t,\vec{x})=\sum_{k} \bar{v}_{\mu}^{(b)}(t,k)Y^{(k)}(\vec{x}).
\end{eqnarray}

Including the above decompositions into the evolution equations we finally arrive to
the equations suitable for numerical computations (proper time variable t is replaced
by $y=\ln R$; all four-vectors are spacelike, hence we put zero to the time components):
\begin{eqnarray}
&&\frac{d \bar{{\cal D}}_{i}^{(\gamma)}}{d y}=\bar{{\cal D}}_{i}^{(\gamma)}-\frac{4}{3}\frac{k}{R H}
\bar{Z}_{i}+4 \frac{R}{k}a_{i}-\frac{k}{3 H R}\bar{q}_{i}^{(\gamma)}, \nonumber \\
&&\frac{d \bar{{\cal D}}_{i}^{(b)}}{d y}=\bar{{\cal D}}_{i}^{(b)}-\frac{k}{R H}
\bar{Z}_{i}+3 \frac{R}{k}a_{i}-\frac{k}{3 H R}\bar{v}_{i}^{(b)}, \nonumber \\
&&\frac{d \bar{{\cal D}}_{i}^{(c)}}{d y}=\bar{{\cal D}}_{i}^{(c)}-\frac{k}{R H}
\bar{Z}_{i}+3 \frac{R}{k}a_{i}, \nonumber \\
&&\frac{d \bar{Z}_{i}}{d y}=-\frac{R}{2Hk}\sum_{j}(1+3w_{j})\kappa \rho_{(j)}\bar{{\cal D}}_{i}^{(j)}
-\dot{\Theta}\frac{R^{2}}{k^{2} H}a_{i},\ for\ Q=0, \nonumber \\
&&\frac{d \bar{Z}_{i}}{d y}=-4 \bar{Z}_{i}
-\frac{3R}{2Hk}\sum_{j}(1-w_{j})\kappa \rho_{(j)}\bar{{\cal D}}_{i}^{(j)}
-\dot{\Theta}\frac{R^{2}}{k^{2} H}a_{i},\ for\ Q\neq0, \nonumber \\
&&\frac{d \bar{q}_{i}^{(\gamma)}}{d y}=3\bar{q}_{i}^{(\gamma)}
+\frac{1}{3}\frac{k}{R H}\bar{{\cal D}}_{i}^{(\gamma)}
+\frac{n_{e}\sigma_{T}}{H}(\frac{4}{3}\bar{v}^{(b)}_{i}-\bar{q}_{i}^{(\gamma)}), \nonumber
\end{eqnarray}
\begin{eqnarray}
&&\frac{d \bar{v_{1}}^{(b)}}{d y}=H^{-1}(G_{1}^{2}+G_{2}^{2})^{-1}[(G_{2}G_{3}-G_{1}G_{4})\bar{v}_{2}^{(b)}
-(G_{1}G_{3}+G_{2}G_{4})\bar{v}_{1}^{(b)}+G_{2}\bar{H}_{2}^{(b)}-G_{1}\bar{H}_{1}^{(b)}], \nonumber \\
&&\frac{d \bar{v}_{2}^{(b)}}{d y}=H^{-1}(G_{1}^{2}+G_{2}^{2})^{-1}[(G_{1}G_{4}-G_{2}G_{3})\bar{v}_{1}^{(b)}
-(G_{1}G_{3}+G_{2}G_{4})\bar{v}_{2}^{(b)}-G_{1}\bar{H}_{2}^{(b)}-G_{2}\bar{H}_{1}^{(b)}], \nonumber \\
&&\frac{d \bar{v}_{3}^{(b)}}{d y}=H^{-1}\Theta c_{s}^{2}\bar{v}_{3}^{(b)}
-H^{-1}\rho_{(b)}^{-1}n_{e}\sigma_{T}\rho_{(\gamma)}(\frac{4}{3}\bar{v}_{3}^{(b)}-\bar{q}_{3}^{(\gamma)}), \\
&&\bar{H}^{(b)}_{1,2}=\kappa n_{e}\sigma_{T}\rho_{(\gamma)}(\frac{4}{3}\bar{v}_{1,2}^{(b)}-\bar{q}_{1,2}^{(\gamma)}).
\nonumber
\end{eqnarray}

The initial conditions are the standard ones \cite{Ma,Challinor}:

\begin{eqnarray}
&&\bar{\cal D}^{(c)}_{i}=\bar{\cal D}^{(b)}_{i}=\frac{3}{4}\bar{\cal D}^{(\gamma)}_{i}
=\frac{3}{4}\bar{\cal D}^{(\nu)}_{i},\ \bar{v}^{(b)}_{i}=\frac{3}{4}\bar{q}^{(\gamma)}_{i},
 \\
&& \bar{\cal D}^{(\gamma)}_{i}=D x^{2},\ \bar{q}^{(\gamma)}_{i}=\frac{D}{9}x^{3},\
\bar{Z}_{i}=-\frac{3}{2}D(x-\frac{4R_{\nu}+5}{18(4R_{\nu}+15)}x^{3}), \nonumber \\
&& R_{\nu}=\frac{\rho^{(\nu})}{\rho^{(\nu)}+\rho^{(\gamma)}},\ x=\frac{k R}{H_{0}\sqrt{\Omega_{r}}}.
\nonumber
\end{eqnarray}

