&&\bar{Q}(R)=\sqrt{3}[1-c+c R^{-3}]^{\frac{1}{2}},\ for\ R_{0} \leq R \leq 1, \\
&&\Omega_{Q}= -1\ \Longleftrightarrow \ \bar{Q}(R=1)=\sqrt{3},\ \
\bar{Q}(R \leq R_{1}) = 0 ,
