% $\mathcal{C}=\{\domainParam\mid \text{KL}(\hat p(\domainParam)\|p_\domainParamSet)\le\tau_{\text{KL}}\}$,
% i.e. the region where the empirical density $\hat p$ stays within a
% small divergence $\tau_{\text{KL}}$ of the intended sampling density.
% Here, $\hat p(\domainParam)$ is the empirical density of $\domainParam$ estimated from the repulsive dataset $\mathcal{D}'$, 
% $p_{\domainParamSet}$ is the intended sampling density, and $\tau$ is the critic-variance threshold for deployment gating and $\tau_{\mathrm{KL}}>0$ is the maximum KL divergence tolerated for ID.
In practice, we define the coverage set as $\mathcal{C}=\{\domainParam\mid \text{KL}(\hat p(\domainParam)\|p_\domainParamSet)\le\tau_{\text{KL}}\}$, i.e. the subset of parameter space where the empirical density $\hat p(\domainParam)$ (estimated from the repulsive dataset $\dataset'$) deviates from the intended sampling density $p_{\domainParamSet}$ by at most $\tau_{\mathrm{KL}}>0$. Here, $\tau_{\mathrm{KL}}$ is the maximum KL-divergence we tolerate to call $\domainParam$ ``in-distribution,'' and $\tau$ denotes the critic-variance threshold used for deployment gating (more details in \autoref{sec:exp_uncertainty}).

\begin{proposition}[Critic gap under OOD]\label{proposition:critic}
If the target parameter $\domainParam_t\notin\domainParamSet$ (i.e. OOD), then
\begin{equation}
  \|Q^\pi_{\domainParam_t} - Q^\pi_{\domainParam}\|_\infty
  \ge\frac{\gamma\bigl(L_R + L_T\|Q^\pi_{\domainParam_t}\|_{\mathrm{Lip}}\bigr)}{1+\gamma}
         \|\domainParam_t - \domainParam\|
\end{equation}
In particular, this gap is strictly positive whenever $\domainParam_t\neq\domainParam$.
\end{proposition}
Thus, any nonzero shift $\|\domainParam_t-\domainParam\|$ forces at least a proportional change in the critic's fixed point, which our ensemble variance will reliably detect. Proof is provided at \aref{app:theory_effects} (\proofref{proof:critic}).




