\begin{align}\label{eq:denn_rl}
    \mathcal{L}^{\text{RL}}_{\text{div}} = \sum_{i} \exp \left( - || Q_i(s,a) - (r + \gamma Q_i(s',\pi(a'|s'))) ||^2 / 2 \delta^2 \right)
