\section{Introduction}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


Loop invariants are properties that hold before and after each iteration of a loop. They are key to automating program verification, which ensures that programs produce correct results before execution. Various well-established methods use loop invariants for safety verification, such as the Floyd-Hoare inductive assertion technique \cite{floyd1993assigning} and termination verification via standard ranking functions \cite{manna2012temporal}. When a loop invariant is a polynomial equation or inequality, it is called a polynomial invariant.

In this work, instead of generating polynomial invariants for a given loop, we address the reverse problem, that is synthesizing a loop that satisfies given polynomial invariants.

We consider polynomial loops $\mL(\ab, h, F)$ of the form
\begin{center}
  \programbox[0.7\linewidth]{
\State$\xb:=(x_{1},\ldots, x_n)\gets \ab:=(a_1,\ldots, a_n)$
\While{$h(\xb)\neq 0$}
\State $\begin{pmatrix}
x_1 \\
x_2 \\
\vdots \\
x_n
\end{pmatrix}
\xleftarrow{F}
\begin{pmatrix}
F_1\\
F_2\\
\vdots\\
F_n
\end{pmatrix}
$
\EndWhile
}\label{page:alg}
\end{center}
where $x_i$ are the program variables with initial values $a_i$, $h\in \C[\xb]$, and $F =(F_1,\ldots, F_n)$ is a sequence of polynomials in $\C[\xb]$. 
The inequation $h(\xb) \neq 0$, called the \emph{guard}, is assumed to be a single inequality for simplicity (we can replace $h_1 \neq 0, \ldots, h_k \neq 0$ with their product $h_1 \cdot \ldots \cdot h_k \neq 0$ without loss of generality). Where there is no $h$ we simply write $\mL(\ab, 1, F)$, which corresponds to an infinite loop.

Previous work~\cite{ISSAC2023Laura,hitarth_et_al:LIPIcs.STACS.2024.41,humenberger2022LoopSynthesis} has focused on update maps that are restricted to be linear. In this paper, we go beyond this limitation by allowing update maps to be arbitrary polynomial functions. We present a method for computing a system of equations whose common solutions characterize all coefficient assignments for update maps of loops that satisfy a given set of polynomial invariants. To illustrate our main objective, we now present a motivating example.


\begin{example}\label{ex:introduction}
Consider the following polynomial loop: 

\programboxappendix[0.5\linewidth]{
\State$(x_1, x_2, x_3)\gets(1,1,-1)$
\While{true}
\State $\begin{pmatrix}
x_1 \\
x_2\\
x_3
\end{pmatrix}
\xleftarrow{F}
\begin{pmatrix}
\lambda_1 x_1^3 + \lambda_2 x_2^2 \\
\lambda_3 x_1 + \lambda_4 x_2^2 \\
\lambda_5 x_1
\end{pmatrix}$
\EndWhile
}

\smallskip

\noindent By applying Algorithm~\ref{algo:generateloops}, we construct polynomials $P_1, \ldots, P_4$, %as detailed in Example~\ref{exa:algo2},
such that $(\lambda_1, \ldots, \lambda_5)$ is a common root of these polynomials if and only if the loop satisfies the polynomial invariants $g_1 = x_2^2 - x_1$ and $g_2 = x_3^3 + 2x_2^2 - x_1$.  For instance, $(-3, 3, 1, -1, 0)$ is a common root of $\{P_1, \ldots, P_4\}$. Thus, if the update map is $F(x_1, x_2, x_3) = (-3x_1^3 + 3x_2^2, x_1 - x_2^2, 0)$, the loop satisfies the invariants $g_1$ and $g_2$. See Example~\ref{exa:algo2} for further details.
\end{example}

\noindent\textbf{Related works.}
The computation of polynomial invariants for loops has been a prominent area of research over the past two decades \cite{bayarmagnai2024algebraic, de2017synthesizing, hrushovski2018polynomial, karr1976affine, kovacs2008reasoning, kovacs2023algebra, rodriguez2004automatic, rodriguez2007automatic, rodriguez2007generating}. However, computing invariant ideals is undecidable for general loops \cite{hrushovski2023strongest}. As a result, efficient methods have been developed for restricted classes of loops, particularly those where the assertions are linear or can be transformed into linear assertions.

The converse problem of synthesizing loops from given invariants has received less attention, primarily focusing on linear and affine loops. These studies vary in the types of invariants considered: linear invariants in \cite{saurabh2010}, a single quadratic polynomial in \cite{hitarth_et_al:LIPIcs.STACS.2024.41}, and pure difference binomials in \cite{ISSAC2023Laura}. In contrast, \cite{humenberger2022LoopSynthesis} explores general polynomial invariants but lacks the completeness properties of earlier work and does not address guard conditions.



Higher degree loops have been studied in a more general framework in \cite{synthesis2023algebro, Fatemeha}, which also takes polynomial inequalities as input. However, the loops synthesized by this algorithm are restricted to those where the input invariants are inductive, meaning that if the invariant holds after one iteration, it holds for all subsequent iterations.



\smallskip
\noindent\textbf{Our contributions.} 
We consider the problem of generating polynomial loops with guards from arbitrary polynomial invariants. As a first step, we construct a polynomial system whose solutions correspond precisely to loops with a given structure that satisfy the specified invariants. We then discuss strategies for solving this system. 
In practice, in most cases a satisfying solution is found using an SMT solver.

Section~\ref{section:preliminaries} recalls the definition of invariant sets and key results from \cite{bayarmagnaiIssac}. Section~\ref{section:generateloops} introduces a method for identifying multiple polynomial invariants (Proposition~\ref{prop:invarianttest}) and proves that the set $\CL(\ab, h, \fb; \gb)$ of coefficients of polynomial maps of loops satisfying the invariants $\gb$ forms an algebraic variety. We also present Algorithm~\ref{algo:generateloops}, which computes the polynomials defining $\CL(\ab, h, \fb; \gb)$. Section~\ref{sec:polysolve} discusses strategies for solving polynomial systems and their limitations, while Section~\ref{sec:implementation} presents our algorithm's implementation and experimental results.



\section{Preliminaries}\label{section:preliminaries}
In the following, we present some terminology from algebraic geometry. For further details, we refer the reader to \cite{cox2013ideals,kempf_1993, shafarevich1994basic}. 
We denote the field of complex numbers by $\mathbb{C}$. Throughout the paper, $\xb$ denotes indeterminates $x_1, \dots, x_n$, and $\C[\xb]$ the multivariate polynomial ring in these variables. 

\smallskip\noindent{\bf Ideals.} A polynomial ideal $I$ is a subset of $\mathbb{C}[\xb]$ that is closed under addition, $0\in I$ and for any $f\in \C[\xb]$ and $g\in I$, $fg\in I$. Given a subset $S$ of $\C[\xb]$, the ideal generated by $S$ is  
$$\langle S \rangle =\{a_1f_1+\ldots +a_mf_m\mid a_i\in \C[\xb], f_i\in S, m\in \N\}.$$
By Hilbert Basis Theorem~\cite[Theorem 4, Chap.~2]{cox2013ideals}, every ideal is finitely generated. For a subset $X \subset \Cn$, the defining ideal $I(X)$ consists of all polynomials vanishing on $X$. The radical of an ideal $I \subset \C[\xb]$ is defined as 
$$\sqrt{I}=\{f\in \C[\xb]| \,f^m\in I \text{ for some } m\in \N\}.$$

\smallskip\noindent{\bf Varieties.} For $S\subset \C[x]$, the algebraic variety $\V(S)$ is the common zero set of all polynomials in $S$. Moreover, $\V(S)=\V(\langle S\rangle)$ and so every algebraic variety is the vanishing locus of finitely many polynomials. 

\smallskip\noindent{\bf Polynomial maps.} A map $F:\C^n \longrightarrow \C^m$ is a polynomial map if there exist $f_1,\ldots, f_m\in \C[x_1,\ldots, x_m]$ such that $$F(x)=(f_1(x),\ldots, f_m(x))$$ for all $x\in \C^n$. For simplicity, we will identify polynomial maps and their corresponding polynomials.

Here, we introduce the main object of this paper and build upon key results from \cite{bayarmagnaiIssac} by recalling and extending them. 

\begin{definition}\label{def:invariantset}
Let $F : \Cn \longrightarrow \Cn$ be a  map and $X$ be a subset of $\Cn$.
The invariant set of $(F,X)$ is defined as:
\begin{center}
    $S_{(F,X)} = \{x \in X \mid \forall m\in \N, F^{(m)}(x) \in X\},$
\end{center}
where~$F^{(0)}(x)=x$~and~$F^{(m)}(x)= F(F^{(m-1)}(x))$~for~$m>1$.
\end{definition}

The following proposition enables the computation of invariant sets using tools from algebraic geometry, relying on the Hilbert Basis Theorem, which implies that descending chains of algebraic varieties eventually stabilize.

 \begin{proposition}\label{prop:stabilization}
Let $X\subseteq\Cn$ be an algebraic variety and consider a polynomial map $F : \Cn \longrightarrow \Cn$. We define $$X_m=X\cap F^{-1}(X)\cap \ldots \cap F^{-m}(X)$$ for all $m \in \N$. Then, there exists $N\in \N$ such that 
%$X_{N}= X_{m}$ for all $m\geq N$. Moreover, if 
$X_N=X_{N+1}$, and for any such index
%for some $N$, then  $X_N = X_m$ for all $m\geq N$ and the invariant set 
$X_N = S_{(F,X)}$.
\end{proposition}

Algorithm~\ref{algo1} computes invariant sets via an iterative outer approximation that converges in finitely many steps, based on Proposition~\ref{prop:stabilization}. It relies on the following procedures:
\begin{itemize}
    \item ``Compose'' takes as input two sequences of polynomials $\gb=(g_1,\ldots, g_m)$ and $F=(F_1,\ldots, F_n)$ in $\Q[\xb]$ and outputs the  polynomials $$\qquad g_1\big(F_1(\xb),\,\ldots,\, F_n(\xb)\big),\ldots, g_m\big(F_1(\xb),\ldots, F_n(\xb)\big).$$ 
    \item ``InRadical'' takes as input a sequence of polynomials $\widetilde{\gb}$ and a finite set $S$ in $\Q[\xb]$ and outputs ``\texttt{True}'' if $\widetilde{\gb}\subset \sqrt{\langle S\rangle}$; ``\texttt{False}'' otherwise.
\end{itemize}
These procedures are classic routines in symbolic computations, and can be performed using various efficient techniques such as Gr\"obner bases \cite{cox2013ideals}. %We do not detail these here, and refer to 
See \cite{bayarmagnai2024algebraic} for more details.
\begin{algorithm}[H]
\caption{\InvariantSet}\label{algo1}
\begin{algorithmic}[1]
\Require $\gb$ and~$F = (F_1,\ldots, F_n)$ are sequences in $\mathbb{Q}[\xb]$.
\Ensure Polynomials whose common zero-set is $S_{(F,{\V(\gb)})}$.
\State\label{Step:algo1.1} $S \gets \{\gb\};$
% \State $S_{GB} \gets \GB(\gb);$
\State\label{Step:algo1.2} $\gbt \gets \compose(\gb,\,F);$
\While{ $\InRadical(\gbt ,\,S)==\texttt{False}$}
\label{Step:algo1.3}\State\label{Step:algo1.4} $S \gets S \cup \{\gbt\};$
% \State $S_{GB} \gets \GB(S_{GB} \cup \{\gbt\});$
\State\label{Step:algo1.5} $\gbt \gets \compose(\gbt,\,F);$
\EndWhile
\State \Return $S$;
% \State \Return N
\end{algorithmic}
\end{algorithm}
The proof of the termination and correctness of Algorithm~\ref{algo1} follows from Proposition~\ref{prop:stabilization} and %can be found in~
\cite[Theorem 2.4]{bayarmagnaiIssac}.

\begin{example}
    Let us compute the invariant set of a polynomial map $F(x_1,x_2)=(2x_1-3x_2, x_1+x_2)$ and an algebraic variety $X=\V(x_1^2-x_2^2+x_1x_2)$. On input $F$ and $g=x_1^2-x_2^2+x_1x_2$, Algorithm~\ref{algo1} computes the invariant set of $F$ and $X$  through the following steps.
    \begin{itemize}
        \item At Step~\ref{Step:algo1.1}, $S$ gets $\{g\}$ and at Step~\ref{Step:algo1.2}, $\widetilde{g}$ gets $$\text{\compose}(g,F)=5x_1^2-15x_2x_2+5x_2^2.$$
    \item At Step~\ref{Step:algo1.3}, a Gr\"obner basis of the ideal $\langle g, 1 - t\widetilde{g} \rangle$ is computed to verify that  
\[
\InRadical(\widetilde{g}, S) = \texttt{False}.
\]
    \item At Step~\ref{Step:algo1.4}, $S$ gets $\{g,g\circ F\}$ and at Step~\ref{Step:algo1.5}, $\widetilde{g}$ is set to $$\compose(\widetilde{g},F)=-5x_1^2-35x_1x_2+95x_2^2$$
\item This time, $\InRadical(\widetilde{g}, F) = \texttt{True}$, so the while 
loop terminates.    
\end{itemize}
Therefore, the invariant set $S_{(F,\V(g))}$ is the vanishing locus of polynomials $\{g, g\circ F\}$.
\end{example}

\section{From loops to polynomial systems}\label{section:generateloops}
In this section, we present a method for identifying all loops that satisfy given polynomial invariants by formulating them as solutions of a polynomial system via invariant sets. This reduces the problem to solving a polynomial system, which we explore in the next section.

\begin{definition}\label{def:PI}
A~polynomial~$g$ is an invariant of the loop $\mathcal{L}(\ab, h, F)$~if,~for~any~$m \in \mathbb{Z}_{\geq 0}$, either:  
$$g(F^{(m)}(\ab)) = 0,$$  
or there exists $m\in \mathbb{Z}_{\geq 0}$ such that $g(F^{(m)}(\ab)) =h(F^{(m)}(\ab))=0$ and for every $l<m$:  
\[
g(F^{(l)}(\ab)) = 0 \text{ and }  h(F^{(l)}(\ab)) \neq 0.
\]
\end{definition}
\begin{definition}\label{def:InvId}
    Let $\mL(\ab, h, F)$ be a polynomial loop. The set of all polynomial invariants for $\mL(\ab, h, F)$  is called the invariant ideal of $\mL$ and is denoted by $I_{\mL(\ab, h, F)}$. 
\end{definition}

The invariant ideal is an ideal of the ring $\C[x_1,\ldots, x_n]$ where $x_1,\ldots, x_n$ are  program variables~\cite{rodriguez2004automatic}. Let $f_1,\ldots, f_n$ be polynomials in $\C[x_1,\ldots, x_n]$. We denote by $span\{f_1,\ldots, f_n\}$ the vector space they generate.

\begin{definition}\label{def:Ffb}
    Let $\fb_1 =(f_{1,1},\ldots, f_{1,l_1}),\ldots, \fb_n =(f_{n,1},\ldots, f_{n,l_n})$ and $(F_1,\ldots, F_n)$ be sequences of polynomials in $\C[\xb]$ %. Assume that $(F_1,\ldots, F_n)$  is a sequence of polynomials in $\C[\xb]$ 
    such that for every i, $$F_i =\displaystyle\sum_{j=1}^{l_i} b_{i,j}f_{i,j}$$ for some $b_{i,j}$'s $ \in \C$. Let $\fb=(\fb_1\ldots, \fb_n)$ and define the  map $$F_{\fb,\bb}:\Cn \longrightarrow \Cn$$ with $F_{\fb,\bb}(x)=(F_1(x),\ldots, F_n(x))$.

\end{definition}

The object defined below is the primary focus of this paper. We prove that it is an algebraic variety and compute the polynomial equations that define it.
\begin{definition}
    Using the notations of Definition~\ref{def:Ffb}, let 
        $h\in \C[\xb], \gb = (g_1,\ldots, g_m)$ be a sequence of polynomials in $\C[\xb]$, and  $\ab\in \Cn$.
    Then, the 
    polynomial loop, structured by $\fb$, with invariants including $\gb$,
    is defined by the coefficient set:
    \begin{align*}
       \CL(\ab,h, \fb; \gb) = \{\bb\in \C^{l_1+\ldots+l_n} \mid \gb \subset I_{\mL(\ab, h, F_{\fb,\bb})} \}.
    \end{align*}
\end{definition}
In simple words, $\CL(\ab,h, \fb; \gb)$ is the set of all vectors $\bb \in \C^{l_1+\cdots +l_n}$ such that all polynomials in $\gb$ are polynomial invariants of the following loop:
\begin{center}
  \programbox[0.55\linewidth]{
\State$\xb\gets\ab$
\While{$h(\xb) \neq 0$}
\State $\xb \gets F_{\fb,\bb}(\xb)
$
\EndWhile
}\label{page:alg}
\end{center}
We now give a necessary and sufficient condition for checking whether given polynomials are loop invariants. This extends~\cite[Proposition 2.7]{bayarmagnai2024algebraic}, where the following statement was proven for a single polynomial invariant. 
\begin{proposition}\label{prop:invarianttest}
    Let $h,g_1,\ldots, g_m$ be polynomials in $\C[\xb]$. Let $z$ be a new indeterminate and let $$X=\V(zg_1,\ldots, zg_m)\subset \C^{n+1}.$$ Let $F:\Cn \longrightarrow \Cn$ be a polynomial map and define $$G_{h}(\xb,z)=(F(\xb),zh(\xb)).$$ Then, for $\ab \in \Cn$, $\gb \subset  I_{\mL(\ab, h, F)}$ if and only if $(\ab,1)\in S_{(G_h,X)}$.
\end{proposition}
\begin{proof}
    Let $X_i=\V(zg_i)\subset \C^{n+1}$ be an algebraic variety for $i\in \{1,\ldots, m\}$. For any $i\in \{1,\ldots, m\}$, by~\cite[Proposition 2.7]{bayarmagnai2024algebraic}, $g_i \in I_{\mL(\ab, h, F)}$ if and only if $(\ab, 1)\in S_{(G_h, X_i)}$. Therefore, $g_1,\ldots, g_m\in I_{\mL(\ab, h, F)}$ if and only if $$(\ab,1)\in S_{(G_h, X_1)}\cap \ldots \cap S_{(G_h, X_m)}.$$ %By Lemma~\ref{prop:intersectioninv}, we obtain
 It follows directly from Definition~\ref{def:invariantset} that
    $$S_{(G_h, X)}=S_{(G_h, X_1)}\cap \ldots \cap S_{(G_h, X_m)}.$$
Thus, $g_1,\ldots, g_m\in I_{\mL(\ab, h, F)}$ if and only if $(\ab,1)\in S_{(G_h, X)}$.
\end{proof}

In the following proposition, we present a necessary and sufficient condition for loops with a given structure to satisfy specified polynomial invariants. 


\begin{proposition}\label{prop:loopgenerator}
    Let $\fb_1 =(f_{1,1},\ldots, f_{1,l_1}),\ldots, \fb_n =(f_{n,1},\ldots, f_{n,l_n})$ be sequences of polynomials in $\C[\xb]$ and define $\fb=(\fb_1,\ldots, \fb_n)$. Let $z, y_{1,1},\ldots, y_{1,l_1}, y_{n,1},\ldots, y_{n,l_n}$ be new indeterminates, let $h\in \C[\xb]$ and define the following polynomial map in $\C[\xb,\yb,z]$:
$$G_{\yb,h}(\xb,\yb,z)=\left(\displaystyle\sum_{i=1}^{l_1}y_{1,i}f_{1,i}(\xb),\ldots, \displaystyle\sum_{i=1}^{l_n}y_{n,i}f_{n,i}(\xb),\yb,zh(\xb)\right).$$
     Let $\gb=(g_1,\ldots, g_m)$ be a sequence of polynomials in $ \C[\xb]$, seen as elements of $\C[\xb,\yb,z]$, let $$X =\V(zg_1,\ldots, zg_m)\subset \C^{n+l_1+\ldots+l_n+1}.$$ Then, for any $\ab \in \Cn$, 
%$g_1,\ldots, g_m$ are polynomial invariants of $\mL(\ab, h, F_{\fb,\bb})$ if and only if $(\ab, \bb,1) \in S_{(F_{\yb,0},X)}$.
$$\CL(\ab,h,\fb;\gb)=\{\bb\in \C^{l_1+\ldots+l_n}\mid (\ab,\bb,1)\in S_{(G_{\yb,h},X)}\}.$$
\end{proposition}
\begin{proof}
    Write $G_{\yb,h}(\xb,\yb,z)=(G_{\yb}(\xb,\yb),zh(\xb))$ where
        $$G_{\yb}(\xb,\yb)=\left(\displaystyle\sum_{i=1}^{l_1}y_{1,i}f_{1,i}(\xb),\ldots, \displaystyle\sum_{i=1}^{l_n}y_{n,i}f_{n,i}(\xb),\yb\right).$$
    By Proposition~\ref{prop:invarianttest}, $g_1,\ldots, g_m$ are polynomial invariants of $\mL((\ab,\bb), h , G_{\yb})$ if and only if $(\ab,\bb,1)\in S_{(G_{\yb,h},X)}$. 
        Since the value of $\yb$ remains $\bb$ after any iteration, we know that $$F^N_{y}(\xb, \bb)= (F^N(\xb),\bb)$$
    for any $N\in \N$. Therefore, $\gb\subset I_{\mL(\ab, h, F_{\fb,\bb})}$ if and only if $\gb\subset  I_{\mL((\ab,\bb), h, G_{\yb})}$, that is $(\ab,\bb,1)\in S_{(G_{\yb,h},X)}$ by above.
\end{proof}
Since the invariant set is an algebraic variety,by~Proposition~\ref{prop:loopgenerator}, $\CL(\ab, h, \fb; \gb)$ is also an algebraic variety. Specifically, its defining equations are obtained by substituting $\xb = \ab$ and $z = 1$ into the system defining the invariant set. 

We now present our main algorithm for computing the polynomials that define $\CL(\ab, h, \fb; \gb)$.



\begin{algorithm}[H]
\caption{\GenerateLoops}\label{algo:generateloops}
\begin{algorithmic}[1]
\Require$ h, g_1,\ldots, g_m, f_{1,1},\ldots, f_{1, l_1},\ldots,f_{n,1},\ldots, f_{n, l_n}$ in $\Q[\xb]$ and $\ab\in \Q^n$.
\Ensure A set of polynomials $\{P_1,\ldots, P_s\}$ such that $\CL(\ab,h,\fb;g)$ is $\V(P_1,\ldots, P_s)$
\State$G_{\yb,h} \gets \left(\displaystyle\sum_{i=1}^{l_1}y_{1,i}f_{1,i}(\xb),\ldots, \displaystyle\sum_{i=1}^{l_n}y_{n,i}f_{n,i}(\xb),\yb, zh(\xb)\right)$;
\State\label{Step:A1.3}$\{Q_1,\ldots, Q_s\} \gets \InvariantSet((zg_1,\ldots, zg_m), G_{\yb,h});$
\State\label{Step:A1.4}$\{P_1(\yb),\ldots, P_s(\yb)\}\gets \{Q_1(\ab,\yb,1),\ldots, Q_s(\ab,\yb,1)\} $
\State\Return $\{P_1,\ldots, P_s\}$;
\end{algorithmic}
\end{algorithm}
We now prove the correctness of Algorithm~\ref{algo:generateloops}.
\begin{theorem}
    Let $h\in \C[\xb], \gb=(g_1,\ldots, g_m)$ and $\fb_1=(f_{1,1},\ldots, f_{1, l_1}),\ldots,\fb_n=(f_{n,1},\ldots, f_{n, l_n})$ be sequences of polynomials in 
    $\Q[\xb]$. Let $\ab\in \Q^n$ and define $\fb=(\fb_1,\ldots, \fb_n)$. On input $\ab,h, \fb,\gb$, Algorithm~\ref{algo:generateloops} outputs a set of polynomials such that the vanishing locus of the polynomials is $\CL(\ab,h,\fb; \gb)$.
\end{theorem}
\begin{proof}
Let $X=\V(zg_1,\ldots, zg_m)\subset \C^{n+l_1+\ldots+l_n+1}.$ At Step~\ref{Step:A1.3}, by \cite[Theorem 2.4]{bayarmagnaiIssac}, \InvariantSet outputs 
$$\{Q_1(\xb,\yb,z),\ldots, Q_s(\xb,\yb,z)\}$$ 
such that $S_{(G_{\yb,h},X)}$ is the common solution of $\{Q_1,\ldots, Q_s\}$. Therefore, by Proposition~\ref{prop:loopgenerator}, $g_1,\ldots, g_m$ are polynomial invariants of $\mL(\ab, h, F_{\fb,\bb})$ if and only if $$Q_1(\ab,\bb,1)=\ldots = Q_s(\ab,\bb,1)=0.
$$ Consequently, $g_1,\ldots, g_m\in I_{\mL(\ab,h, F_{\fb,\bb})}$ if and only if $$P_1(\bb)=\ldots=P_s(\bb)=0$$ which proves the correctness of Algorithm~\ref{algo:generateloops}.
\end{proof}


