\caption{Weights’ states in different stages.}
\label{tb:1}
\[
\begin{array}{@{}l*{6}{c}@{}}
\toprule
\text{stage} & \multicolumn{6}{c@{}}{\text{weight}}\\
    \cmidrule(l){2-7}
    & W[1] & W[2] & \ldots & W[n-2] & W[n-1]& W[n]\\
\midrule
L(n,-,\Phi) & init & init & \ldots & init & init& update\\
L(n-1,-,\Phi) & init & init & \ldots & init & update& update\\
