\begin{pro}\label{sdnil}
Let $S$ be a flat nil-semiring.
Then $S$ is subdirectly irreducible if and only if there exists an annihilator $\omega$ of $S$ such that $\omega\in S^1aS^1$ for all nonzero elements $a$ of $S$.
In this case, $\omega$ is the unique annihilator of $S$ and $\{0,\omega\}$ is the least nonzero multiplicative ideal of $S$.
\end{pro}
\begin{proof}
Suppose that there exists an annihilator $\omega$ of $S$ such that $\omega\in S^1aS^1$ for all nonzero elements $a$ of $S$.
It is easy to see that $\{0, \omega\}$ is a nonzero multiplicative ideal of $S$.
Let $J$ be an arbitrary nonzero multiplicative ideal of $S$. Take a nonzero element $a$ of $J$.
Then $\omega$ is in $S^1aS^1$. Since $S^1aS^1\subseteq J$, it follows that $\omega$ is in $J$
and so $\{0, \omega\}\subseteq J$. This shows that $\{0,\omega\}$ is the least nonzero multiplicative ideal of $S$.
So $S$ is subdirectly irreducible. Furthermore,
if $\omega'$ is an arbitrary annihilator of $S$,
then $\{0,\omega'\}$ is a multiplicative ideal of $S$ and so $\{0,\omega\}\subseteq \{0,\omega'\}$.
Thus $\omega=\omega'$ and so $\omega$ is the unique annihilator of $S$.

Conversely, suppose that $S$ is subdirectly irreducible.
Then $S$ has a least nonzero multiplicative ideal $I$.
Let $a$ and $b$ be nonzero elements of $I$.
Then $S^{1}aS^{1}=S^{1}bS^{1}=I$. This implies that $a=xby$ and $b=uav$ for some $x,y,u,v\in S^{1}$.
So
\[
a=(xu)a(vy)=(xu)^2a(vy)^2=\cdots.
\]
Since $(S, \cdot)$ is a nil-semigroup, it is not hard to prove that $x=u=v=y=1$.
Hence $a=b$ and so $|I|=2$. We may write $I=\{0,\omega\}$.
Next, we shall show that $\omega$ is an annihilator of $S$.
Indeed, let $s$ be an element of $S$. Then $s\omega\in I$ and so $s\omega$ ie equal to $0$ or $\omega$.
If $s\omega=\omega$ then $s^n\omega=\omega$ for all $n\geq 1$.
As $(S, \cdot)$ is a nil-semigroup, we have that $s^n=0$ for some $n\geq 1$.
Thus $\omega=0$, a contradiction.
So $s\omega = 0$. Similarly, $\omega s=0$.
We have shown that $\omega$ is an annihilator of $S$.
Since $\{0,\omega\}$ is the least nonzero multiplicative ideal of $S$,
it follows immediately that $\omega\in S^1aS^1$ for all nonzero elements $a$ of $S$.
\end{proof}




\begin{proposition}\label{sinilpotent}
A nilpotent flat semiring is subdirectly irreducible if and only if it has a unique annihilator.
\end{proposition}

\begin{proof}
Suppose that $S$ is a nilpotent flat semiring that has a unique annihilator $\omega$.
For any nonzero element $a$ of $S$, let $m$ denote the number
%\[
%\max\{k\geq 1 \mid  a_1\cdots a_k\neq 0\text{ for some $a_j\in S$ with $a\in \{a_1, \ldots, a_k\}$}\}.
%\]
\[
\max\{k\geq 1 \mid  (\exists a_1, a_2, \ldots, a_k\in S)~a_1\cdots a_k\neq 0, a\in \{a_1, \ldots, a_k\}\}.
\]
Then there exist $a_1, \ldots, a_{i-1}, a_{i+1}, \ldots, a_m\in S$ such that
$a_1\cdots a_{i-1}aa_{i+1}\cdots a_m$, which is denoted by $u$, is nonzero.
Now it is easy to see that $u$ is an annihilator of $S$ and so $u=\omega$, since $\omega$ is the unique annihilator of $S$.
Thus $\omega\in S^1aS^1$ and so is subdirectly irreducible by Proposition~\ref{sdnil}.
The converse part is a consequence of Proposition~\ref{sdnil}.
\end{proof}

The following example shows that a flat nil-semiring that has a unique annihilator need not be subdirectly irreducible.
\begin{example}
Let $W$ denote the set $\{x_1x_2\cdots x_n\mid n\geq 1\}\cup\{x_0\}$.
Then $S(W)$ is a flat nil-semiring that has the unique annihilator $\{x_0\}$, but is not subdirectly irreducible.
In fact, it is easy to see that $S(W)$ satisfies the identity $x^2 \approx 0$.
So $S(W)$ is a flat nil-semiring.
Observe that $x_0$ is the unique annihilator of $S(W)$.
However, the set $S(W)\backslash \{x_0\}$ is a multiplicative ideal of $S(W)$ that does not contain $x_0$.
This implies that $\{0,x_0\}$ is not the least nonzero multiplicative ideal of $S(W)$.
From Proposition~$\ref{sdnil}$ we know that $S(W)$ is not subdirectly irreducible.
\end{example}

\begin{lemma}\label{SkSk+1}
Let $S$ be a nilpotent flat semiring that has a unique annihilator $\omega$.
Then $S^{k}=\{0,\omega\}$ for some $k\geq 1$.
\end{lemma}
\begin{proof}
By assumption, there exists an integer $k\geq 1$ such that $S^{k}\neq \{0\}$ and $S^{k+1}= \{0\}$.
It is easy to see that every nonzero element of $S^{k}$ is an annihilator of $S$.
Since $\omega$ is the unique annihilator of $S$, it follow immediately that $S^{k}=\{0, \omega\}$.
\end{proof}

\begin{corollary}\label{coro25052801}
The variety $\mathbf{NF_2}$ is generated by $S(a)$ and is a minimal nontrivial ai-semiring variety.
\end{corollary}
\begin{proof}
Let $S$ be a nontrivial subdirectly irreducible member of $\mathbf{NF_2}$.
It follows from Lemma~\ref{lem24121301} and Proposition~\ref{sinilpotent} that $S$ has a unique annihilator $\omega$.
By Lemma~\ref{SkSk+1} we deduce that $S=\{0, \omega\}$.
Now it is a routine matter to verify that $S$ is isomorphic to $S(a)$.
This shows that up to isomorphism,
$S(a)$ is the only nontrivial subdirectly irreducible member of $\mathbf{NF_2}$.
So $\mathbf{NF_2}$ is generated by $S(a)$.
From \cite{sr} we know that $\mathsf{V}(S(a))$ is a minimal nontrivial ai-semiring variety.
This proves the required result.
\end{proof}

\begin{definition}
A flat semiring $S$ is the $0$-direct union of a family $(S_i)_{i\in I}$ of flat semirings,
denoted by $S=\bigcup_{i\in I}^{\bullet} S_i$,
if
\[
S=\bigcup_{i\in I} S_i'
\]
and
\[
S_i'\cong S_i, S_j'\cap S_k'=S_j'\cdot S_k'=\{0\}
\]
for all $i, j, k\in I$ with $j\neq k$.
\end{definition}

Let $\mathcal{K}$ be a class of ai-semirings.
Then $\mathsf{V}(\mathcal{K})$ denotes the variety generated by $\mathcal{K}$, that is,
the smallest variety that contains $\mathcal{K}$.
Let $(S_i)_{i\in I}$ be a class of flat semirings. Then
it is easy to verify that $\bigcup_{i\in I}^{\bullet} S_i$ is isomorphic to a subdirect product of $(S_i)_{i\in I}$.
So $\mathsf{V}(\{S_i\mid i\in I\})=\mathsf{V}(\bigcup_{i\in I}^{\bullet} S_i)$.
By Lemma~\ref{lem24121301} we now have

\begin{proposition}
Every subvariety of $\mathbf F$ can be generated by a single flat semiring.
In particular, every finitely generated subvariety of $\mathbf F$ can be generated by a finite flat semiring.
\end{proposition}

\begin{definition}
A flat semiring $S$ is the $\{0, \omega\}$-direct union of a family $(S_i)_{i\in I}$ of subdirectly irreducible flat nil-semirings,
denoted by $\bigcup_{i\in I}^{\omega} S_i$,
if
\[
S=\bigcup_{i\in I} S_i'
\]
and
\[
S_i'\cong S_i, S_j'\cap S_k'=\{0,\omega\}, S_j'\cdot S_k'=\{0\}
\]
for all $i, j, k\in I$ with $j \neq k$.
\end{definition}

It is easy to see that $\bigcup_{i\in I}^{\omega} S_i$ is a subalgebra of $\bigcup_{i\in I}^{\omega} T_i$
whenever $S_i$ is a subalgebra of $T_i$ for each $i\in I$.
In the sequel we sometimes denote by $S_1\circ S_2$ the $\{0, \omega\}$-direct union of
the subdirectly irreducible flat nil-semirings $S_1$ and $S_2$.
\begin{proposition}
The $\{0, \omega\}$-direct union of a family of subdirectly irreducible flat nil-semirings is also subdirectly irreducible.
\end{proposition}
\begin{proof}
Suppose that $S$ is the $\{0, \omega\}$-direct union of a family $(S_i)_{i\in I}$ of subdirectly irreducible flat nil-semirings.
Then $S$ is also a flat nil-semiring containing a unique annihilator $\omega$.
For each $a\in S\backslash \{0\}$, we have that  $a\in S_i$ for some $i\in I$.
It follows from Proposition~\ref{sdnil} that $\omega\in S_i^1aS_i^1\subseteq S^1aS^1$.
By Proposition~\ref{sdnil} again $S$ is subdirectly irreducible as required.
\end{proof}

The following example tells us that a subdirectly irreducible flat nil-semiring is not necessarily nilpotent.
\begin{example}
The $\{0, \omega\}$-direct union of $\{S_c(a_{1}\cdots a_{k})\mid k\geq 1\}$ is a subdirectly irreducible flat nil-semiring
but is not nilpotent.
\end{example}

Let $X^+$ denote the free semigroup over a countably infinite set $X$ of variables.
By distributivity, all ai-semiring terms over $X$ are finite sums of words in $X^+$.
An \emph{ai-semiring identity} over $X$ is a formal expression of the form
\[
\bu\approx \bv,
\]
where $\bu$ and $\bv$ are ai-semiring terms over $X$.
Let $S$ be an ai-semiring, and let $\bu\approx \bv$ be an ai-semiring identity over $\{x_1, x_2, \ldots, x_n\}$.
Then $S$ \emph{satisfies} $\bu\approx \bv$ if
$\bu(a_1, a_2, \ldots, a_n)=\bv(a_1, a_2, \ldots, a_n)$ for all $a_1, a_2, \ldots, a_n\in S$, where $\bu(a_1, a_2, \ldots, a_n)$ denotes the result of evaluating $\bu$ in $S$ under the assignment $x_i\mapsto a_i$, and similarly for $\bv(a_1, a_2, \ldots, a_n)$.

For other notations and terminology used in this paper, the reader is referred to
Jackson et al.~\cite{jrz} and Ren et al.~\cite{rjzl} for background on semirings,
and to Burris and Sankappanavar~\cite{bs} for information concerning the theory of varieties.
We shall assume that the reader is familiar with the basic results in these areas.


\section{The number of subvarieties of $\mathbf{NF}_3$}
In this section we prove that the variety $\mathbf{NF}_3$ has uncountably many subvarieties.
Throughout this paper, all graphs are directed, contain no isolated vertices,
and satisfy the condition that every vertex has both out-degree and in-degree at most $1$.
One can easily deduce that every connected component of such a graph is either a path or a cycle.
Let ${\mathbb G}=\langle V(\mathbb G), E(\mathbb G)\rangle$ be a graph, where $V(\mathbb G)$ is the vertex set
and $E(\mathbb G)$ is the edge set.
Let $S_{\mathbb G}$ denote the disjoint union of $V(\mathbb G)$ and $\{0, \omega\}$.
Define a multiplicative operation $\cdot$ on $S_{\mathbb G}$ by the rule
\[
x\cdot y=\begin{cases}
    \omega,& (x,y)\in E(\mathbb G),\\
    0,&\text{otherwise}.
  \end{cases}
\]
It is straightforward to verify that $(S_{\mathbb G},\cdot)$ forms a $0$-cancellative semigroup and is $3$-nilpotent,
and so $S_{\mathbb G}$ becomes a flat semiring in $\mathbf{NF}_3$.
We call $S_{\mathbb G}$ the \emph{graph semiring} induced by ${\mathbb G}$.
In particular, if the graph ${\mathbb G}$ is empty, then $S_{\mathbb G}$ is isomorphic to $S(a)$.
The following result demonstrates the importance of graph semirings.

\begin{thm}\label{siSg}
A nontrivial $3$-nilpotent flat semiring is subdirectly irreducible if and only if it is isomorphic to some graph semiring.
\end{thm}
\begin{proof}
Let $S_{\mathbb G}$ be a graph semiring.
Then $S_{\mathbb G}$ is a $3$-nilpotent flat semiring that has a unique annihilator $\omega$.
By Proposition~\ref{sinilpotent} we deduce that $S_{\mathbb G}$ is subdirectly irreducilbe.
Conversely, suppose that $S$ is a subdirectly irreducible $3$-nilpotent flat semiring.
By Proposition~\ref{sinilpotent} and Lemma~\ref{SkSk+1},
$S$ contains a unique annihilator $\omega$, and $S^2$ is contained in $\{0,\omega\}$.
Define a graph $\mathbb G$ with the vertx set $V(\mathbb G)=S\setminus\{0,\omega\}$
and the edge set $E(\mathbb G)=\{(x,y)\mid xy=\omega\}$.
Now it is easy to verify that $S$ is isomorphic to the graph semiring $S_{\mathbb G}$.
This proves the required result.
\end{proof}

\begin{definition}
Let $m\geq 2$ and $n\geq 1$ be integers, and let
\[
\bp_m=x_1x_2+x_2x_3+\cdots+x_{m-1}x_m
\]
and
\[
\bc_n=x_1x_2+x_2x_3+\cdots+x_{n-1}x_n+x_nx_1
\]
be ai-semiring terms.
Then the path graph semiring $S_{\bp_m}$ denotes
the graph semiring induced by the path graph
\[
\langle\{a_i \mid 1\leq i \leq m\}, \{(a_i, a_{i+1})\mid 1\leq i <m\}\rangle,
\]
and the cycle graph semiring $S_{\bc_n}$ denotes the graph semiring induced by
the cycle graph
\[
\langle\{a_i \mid 1\leq i \leq n\}, \{(a_i, a_{i+1})\mid 1\leq i <n\}\cup \{(a_n, a_1)\}\rangle.
\]
\end{definition}

\begin{remark}
$S_{\bp_2}\cong S(ab)$, $S_{\bc_1}\cong S(a^2)$, and $S_{\bc_2}\cong S_c(ab)$.
\end{remark}


Notice that every connected component of a graph is either a path or a cycle.
By the construction of graph semirings we immediately have the following result,
which will be repeatedly used in the sequel.
\begin{pro}\label{pro25061320}
The $\{0, \omega\}$-direct union of graph semirings is a graph semiring. Conversely,
if ${\mathbb G}$ is a graph and $\{{\mathbb G}_i\}_{i\in I}$ denotes the set of all connected components of ${\mathbb G}$,
then $S_{\mathbb G}$ is the $\{0, \omega\}$-direct union of $\{S_{\mathbb G_i}\}_ {i\in I}$,
where each $S_{\mathbb G_i}$ is either a path graph semiring or a cycle graph semiring.
\end{pro}

\begin{lemma}\label{Scnm}
Let $m$ and $n$ be positive integers. Then
$S_{\bc_n}$ satisfies $\bc_m\approx x^3$ if and only if $n$ does not divide $m$.
\end{lemma}
\begin{proof}
Suppose that $n$ divides $m$. Then $m=nk$ for some integer $k$.
Consider the substitution $\varphi: \{x, x_1, \ldots, x_m\} \to S_{\bc_n}$ such that
$\varphi(x)=0$ and $\varphi(x_{rn+s})=a_s$ for all $0\leq r<k$ and $1\leq s \leq n$.
It is easy to see that $\varphi(\bc_m)=\omega$ and $\varphi(x^3)=0$.
So $S_{\bc_m}$ does not satisfy $\bc_m\approx x^3$.

Conversely, assume that $S_{\bc_n}$ does not satisfy $\bc_m\approx x^3$.
Then there is a substitution $\psi: \{x, x_1, \ldots, x_m\} \to S_{\bc_n}$ such that
$\psi(\bc_m)\neq 0$, since $\psi(x^3)=0$. So we have
\[
\psi(x_1)\psi(x_2)=\cdots =\psi(x_{m-1})\psi(x_m)=\psi(x_m)\psi(x_1)=\omega.
\]
For any $1\leq i \leq m$, let $a_{j_i}$ denote $\psi(x_i)$, $1\leq j_i \leq n$. Then
\begin{equation}\label{eq25053001}
j_{k+1} \equiv j_k+1 \pmod n
\end{equation}
for all $1\leq k <m$ and
\begin{equation}\label{eq25053002}
j_1\equiv j_{m}+1 \pmod n.
\end{equation}
By \eqref{eq25053001} one can deduce that
\begin{equation}\label{eq25053003}
j_{m} \equiv j_1+m-1 \pmod n.
\end{equation}
Combining \eqref{eq25053002} and \eqref{eq25053003} we obtain that $n$ divides $m$ as required.
\end{proof}

In what follows we shall use $P$ to denote the set of all prime numbers.
\begin{thm}\label{cor:continuum}
The lattice $\mathcal{L}(\mathbf{NF}_3)$ of subvarieties of $\mathbf{NF}_3$ has cardinality of the continuum.
Moreover, it contains both a chain and an antichain of cardinality $2^{\aleph_0}$.
\end{thm}

\begin{proof}
Let $\mathcal{P}(P)$ denote the power set of $P$.
One can show that the mapping $\varphi: \mathcal{P}(P) \to \mathcal{L}(\mathbf{NF}_3)$ defined by
\[
\varphi(Q)=\mathsf{V}(\{S_{\bc_q}\mid q\in Q\}) \quad (Q\in \mathcal{P}(P)),
\]
is a lattice embedding mapping.
Indeed, let $Q$ a proper subset of $P$, and let $p$ be an element of $P\backslash Q$.
By Lemma~\ref{Scnm} we have that $\bc_p\approx x^3$ is satisfied by every semiring in $\{S_{\bc_q}\mid q\in Q\}$,
but does not hold in $S_{\bc_p}$.
By this observation, we can easily deduce that $\varphi$ is a lattice embedding mapping.
Since $\mathcal{P}(P)$ is uncountable, it follows immediately that $\mathcal{L}(\mathbf{NF}_3)$ has cardinality of the continuum.
From \cite[Chapter I, \S10]{ku2011} we know that $\mathcal{P}(P)$ has a chain and an antichain of size $2^{\aleph_0}$.
Consequently, $\mathcal{L}(\mathbf{NF}_3)$ inherits this property.
\end{proof}

As a consequence, we have
\begin{corollary}
Let $k\geq 4$ be an integer. Then
$\mathbf{NF}_k$ has uncountably many subvarieties.
\end{corollary}

Theorem \ref{cor:continuum} established the uncountable cardinality of $\mathcal{L}(\mathbf{NF}_3)$ via semantic methods.
In contrast, Proposition \ref{pro25053101} below provides a syntactic proof using equationally definable subvarieties.

\begin{proposition}\label{pro25053101}
Let $I$ be an arbitrary subset of $P$, and
let $\mathcal{V}_I$ denote the subvariety of $\mathbf{NF}_3$ defined by the identities
\[
\bc_q\approx x^3, q\in I.
\]
Then $\mathcal{V}_{I_1}\neq \mathcal{V}_{I_2}$
whenever $I_1$ and $I_2$ are distinct subsets of $P$.
\end{proposition}
\begin{proof}
Let $I_1$ and $I_2$ are distinct subsets of $P$.
Without loss of generality, we may assume that $I_1$ is not contained in $I_2$.
Then there exists an element $q$ of $I_1$ that is not in $I_2$.
By virtue of Lemma~\ref{Scnm}, we deduce that $S_{\bc_q}$ is a member of $\mathcal{V}_{I_2}$,
but does not lie in $\mathcal{V}_{I_1}$.
Thus $\mathcal{V}_{I_1} \neq \mathcal{V}_{I_2}$.
\end{proof}

\begin{corollary}
Let $I$ be a subset of $P$.
Then $\mathcal{V}_I$ is nonfinitely based if and only if $I$ is infinite.
In this case, $\mathcal{V}_I$ has an irredundant equational basis.
\end{corollary}
\begin{proof}
If $I$ is finite, then it follows from Proposition \ref{fkjidi}(2) that $\mathcal{V}_I$ is finitely based.
Now let $I$ be an infinite subset of $P$. Suppose by way of contradiction that $\mathcal{V}_I$ is finitely based.
By the Compactness Theorem for Equational Logic~\cite[Exercise 10 in \S14]{bs},
it follows that $\mathcal{V}_I=\mathcal{V}_J$ for some finite subset $J$ of $I$,
which contradicts Proposition~\ref{pro25053101}.
So $\mathcal{V}_I$ is nonfinitely based.
Moreover, Proposition~\ref{pro25053101} also implies that $\{\bc_q\approx x^3\mid q\in I\}$
is an irredundant equational basis of $\mathcal{V}_I$ within $\mathbf{NF}_3$.
\end{proof}

\section{The Cross subvarieties of $\mathbf{NF}_3$}
In this section we show that every finitely generated subvariety of $\mathbf{NF}_3$ is a Cross variety.
Recall that an algebra $D$ is a \emph{divisor} of an algebra $A$ is $D$ is a homomorphic image of
a subalgebra $B$ of $A$. The divisor $D$ is \emph{proper} if either $B$  is a proper
subalgebra of $A$ or the homomorphism from $B$ onto $D$ is not an isomorphism.
A finite algebra is \emph{critical} if it does not lie in the variety generated by all of its proper divisors.
It is easily verified that every critical algebra is subdirectly irreducible.
A \emph{Cross} variety is a variety that is locally finite, finitely based, and has finitely many critical algebras.
By \cite[Theorem 2.1]{mv}, a variety is a Cross variety if and only if it is finitely generated, finitely based,
and has finitely many subvarieties.
From~\cite[Proposition 1.4.35]{sapir14} we know that
every subvariety of a Cross variety is a Cross variety.
Let $\mathcal{V}_1$ and $\mathcal{V}_2$ be varieties. We write $\mathcal{V}_1 < \mathcal{V}_2$
if $\mathcal{V}_1$ is a proper subvariety of $\mathcal{V}_2$.

\begin{lemma}\label{scnsln1}
Let $m,n\geq 2$ be integers. Then

\begin{equation}\label{eq250602011}
\mathsf{V}(S_{\bp_{n}})<\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})
=\mathsf{V}\left(\bigcup_{1\leq i\leq m}^{\omega}S_{\bp_{n}}\right),\tag{1}
\end{equation}

\begin{equation}\label{eq250602012}
\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})<\mathsf{V}(S_{\bp_{n+1}})
=\mathsf{V}\left(S_{\bp_{n+1}}\circ \bigcup_{1\leq i\leq m}^{\omega}S_{\bp_{n}}\right),\tag{2}
\end{equation}

\begin{equation}\label{eq25060202}
\mathsf{V}(S_{\bc_1})<\mathsf{V}(S_{\bc_1}\circ S_{\bc_1})
=\mathsf{V}\left(\bigcup_{1\leq i\leq m}^{\omega}S_{\bc_1}\right),\tag{3}
\end{equation}

\begin{equation}\label{eq25060203}
\mathsf{V}\left(\bigcup_{1\leq i\leq m}^{\omega}S_{\bc_n}\right)\tag{4}
=\mathsf{V}(S_{\bc_n}),
\end{equation}

\end{lemma}


\begin{proof}
Since $S_{\bp_{n}}$ is a subalgebra of $S_{\bp_{n}}\circ S_{\bp_{n}}$,
it follows that $\mathsf{V}(S_{\bp_{n}})$ is a subvariety of $\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})$.
Let
\begin{equation}\label{id25060820}
\bp_n(x_1, \ldots, x_n)+\bp_n(y_1, \ldots, y_n)\approx \bp_n(x_1, \ldots, x_{n-1},y_n)+\bp_n(y_1, \ldots, y_{n-1},x_n)
\end{equation}
%\begin{align} \label{id25060820}
%&~\bp_n(x_1, \ldots, x_n)+\bp_n(y_1, \ldots, y_n) \notag
%\approx &~\bp_n(x_1, \ldots, x_{n-1},y_n)+\bp_n(y_1, \ldots, y_{n-1},x_n)
%\end{align}
be an ai-semiring identity.
It is easy to check that \eqref{id25060820} is satisfied by $S_{\bp_{n}}$,
but does not hold in $S_{\bp_{n}}\circ S_{\bp_n}$.
So $\mathsf{V}(S_{\bp_{n}})$ is a proper subvariety of $\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})$.

It is obvious that
$\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})$ is a subvariety of $\mathsf{V}\left(\bigcup_{1\leq i\leq m}^{\omega}S_{\bp_{n}}\right)$,
since $S_{\bp_{n}}\circ S_{\bp_n}$ is a subalgebra of $\bigcup_{1\leq i\leq m}^{\omega}S_{\bp_{n}}$.
In the following we shall show that $\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})$ contains $\bigcup_{1\leq i\leq m}^{\omega}S_{\bp_{n}}$.
Indeed, let $\{0, \omega, a_1, \ldots, a_n\}$ and $\{0, \omega, b_1, \ldots, b_n\}$ be copies of $S_{\bp_n}$.
Then their $\{0, \omega\}$-direct union $\{0, \omega, a_1, b_1, \ldots, a_n, b_n\}$,
denoted by $T$, is isomorphic to $S_{\bp_{n}}\circ S_{\bp_n}$.
Let $A$ denote the subalgebra of the direct product $T^m$ of $m$ copies of $T$ generated by the elements
\[
\sigma^k(a_i,b_i, \ldots, b_i),~1\leq i\leq n,~ 1\leq k\leq m,
\]
where $\sigma: T^m \to T^m$ is the right cyclic shift mapping defined by
\[
\sigma(x_1, x_2, \ldots, x_m)=(x_m, x_1, \ldots, x_{m-1}).
\]
If we denote by $J$ the set of all elements of $A$ with a $0$-coordinate,
then $J$ is both a multiplicative ideal and an order-theoretic filter of $A$.
Now it is a routine matter to verify that the quotient algebra $A/J$ is isomorphic to $\bigcup_{1\leq i\leq m}^{\omega} S_{\bp_n}$.
Thus
$\mathsf{V}(S_{\bp_{n}}\circ S_{\bp_n})=\mathsf{V}\left(\bigcup_{1\leq i\leq m}^{\omega}S_{\bp_{n}}\right)$.

Suppose that $S_{\bp_{n+1}}=\{0, \omega, a_1, \ldots, a_{n+1}\}$.
Let $A$ be the subalgebra of the direct product $S_{\bp_{n+1}}^{m}$ of $m$ copies of $S_{\bp_{n+1}}$
generated by
\[
(a_i,a_i,\ldots,a_i),~1\leq i\leq n+1,
\]
\[
\sigma^k(a_i,a_{i+1}, \ldots, a_{i+1}),~1\leq i\leq n,~ 1\leq k\leq m,
\]
where $\sigma$ is the right cyclic shift mapping defined by $S_{\bp_{n+1}}^{m}$ onto itself.
Let $J$ denote the set of all elements of $A$ with a $0$-coordinate.
Then $J$ is is both a multiplicative ideal and an order-theoretic filter of $A$.
It is easy to verify that $A/J$ is isomorphic to
$S_{\bp_{n+1}}\circ \bigcup_{1\leq i\leq m}^{\omega}S_{\bp_n}$.
Thus
\[
\mathsf{V}\left(S_{\bp_{n+1}}\circ \bigcup_{1\leq i\leq m}^{\omega}S_{\bp_n}\right)=\mathsf{V}(S_{\bp_{n+1}}),
\]
and so $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ is a subvariety of $\mathsf{V}(S_{\bp_{n+1}})$.
Notice that the identity is satisfied by $S_{\bp_n}\circ S_{\bp_n}$,
but does not hold in $S_{\bp_{n+1}}$.
Hence $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ is a proper subvariety of $\mathsf{V}(S_{\bp_{n+1}})$.
We have completed the proof of \eqref{eq250602011} and \eqref{eq250602012}.


We know that $S_{\bc_1}$ is a subalgebra of $S_{\bc_1}\circ S_{\bc_1}$.
So $\mathsf{V}(S_{\bc_1})$ is a subvariety of $\mathsf{V}(S_{\bc_1}\circ S_{\bc_1})$.
It is easy to check that the identity $x^2+xy\approx x^2+y^2$ is satisfied by $S_{\bc_1}$,
but does not hold in $S_{\bc_1}\circ S_{\bc_1}$.
Thus $\mathsf{V}(S_{\bc_1})$ is a proper subvariety of $\mathsf{V}(S_{\bc_1}\circ S_{\bc_1})$.

To show that $\mathsf{V}(S_{\bc_1}\circ S_{\bc_1})=\mathsf{V}\left(\bigcup_{1\leq i\leq m}^{\omega}S_{\bc_1}\right)$,
it suffices to prove that $\bigcup_{1\leq i\leq m}^{\omega}S_{\bc_1}$ lies in $\mathsf{V}(S_{\bc_1}\circ S_{\bc_1})$.
Let $\{0, \omega, a\}$ and $\{0, \omega, b\}$ be copies of $S_{\bc_1}$.
Then $\{0, \omega, a, b\}$ is isomorphic to $S_{\bc_1}\circ S_{\bc_1}$.
Let $A$ denote the subalgebra of the direct product $S_{\bc_1}^m$ of $m$ copies of $S_{\bc_1}$ generated by the elements
\[
\sigma^k(a,b, \ldots, b),~ 1\leq k\leq m,
\]
where $\sigma$ is the right cyclic shift mapping from $S_{\bc_1}^m$ to itself.
If we denote by $J$ the set of all elements of $A$ with a $0$-coordinate,
then $J$ is both a multiplicative ideal and an order-theoretic filter of $A$.
Now it is easy to see that $A/J$ is isomorphic to $\bigcup_{1\leq i\leq m}^{\omega} S_{\bc_1}$.
Hence $\mathsf{V}(S_{\bc_1}\circ S_{\bc_1}) =\mathsf{V}(\bigcup_{1\leq i\leq m}^{\omega}S_{\bc_{1}})$
and so \eqref{eq25060202} holds.

Finally, we shall show that \eqref{eq25060203} is true.
Indeed, let us write $S_{\bc_n}=\{0, \omega, a_1, \ldots, a_n\}$,
and let $A$ be the subalgebra of the direct product $S_{\bc_n}^m$ of $m$ copies of $S_{\bc_n}$ generated by the elements
\[
\sigma^k(a_i, a_{i+1}, \ldots, a_{i+1}), ~1\leq i\leq n,~ 1\leq k\leq m,
\]
where $\sigma$ is the right cyclic shift mapping from $S_{\bc_n}^m$ to itself.
If $J$ denotes the elements of $A$ with a $0$-coordinate, then
the quotient algebra $A/J$ is isomorphic to $\bigcup_{1\leq i\leq m}^{\omega} S_{\bc_n}$.
So $\mathsf{V}(S_{\bc_{n}})=\mathsf{V}(\bigcup_{1\leq i\leq m}^{\omega}S_{\bc_{n}})$.
\end{proof}

\begin{proposition}\label{scnsln11}
Let $I$ and $J$ be sets \up(possibly empty\up) of positive integers with $1\notin J$, and let $n\geq 2$ be a positive integer.
\begin{itemize}
\item[$(1)$]
If $I$ does not contain $1$, then
\[
\mathsf{V}\left(\bigcup_{1\leq k\leq n}^{\omega}\left(\bigcup_{i\in I}^{\omega}
S_{\mathbf{c}_i}\circ \bigcup_{j\in J}^{\omega} S_{\bp_i}
 \right)\right)
=\mathsf{V}\left(\bigcup_{i\in I}^{\omega} S_{\mathbf{c}_i}\circ \bigcup_{j\in J}^{\omega} S_{\bp_i}\circ \bigcup_{j\in J}^{\omega} S_{\bp_i}\right).
\]
\item[$(2)$] If $I$ contains $1$, then
\[
\mathsf{V}\left(\bigcup_{1\leq k\leq n}^{\omega}\left(\bigcup_{i\in I}^{\omega} S_{\mathbf{c}_i}\circ \bigcup_{j\in J}^{\omega} S_{\bp_i}\right)\right)=\mathsf{V}\left(S_{\bc_1}\circ\bigcup_{i\in I}^{\omega} S_{\mathbf{c}_i}\circ \bigcup_{j\in J}^{\omega} S_{\bp_i}\right).
\]
\end{itemize}
\end{proposition}
\begin{proof}
One can obtain this result by modifying $T$ appropriately in the proof of Lemma~\ref{scnsln1}.
\end{proof}

For each integer $n \geq 2$, let $\mathcal{V}_n$ denote the subvariety of $\mathbf{NF}_3$
defined by the identity
\begin{equation}\label{id26060101}
\bp_n\approx \bc_n.
\end{equation}

\begin{lemma}\label{lem25061422}
Let ${\mathbb G}$ be a graph. If the graph semiring $S_{\mathbb G}$ is a member of $\mathcal{V}_n$,
then
\begin{itemize}
\item[$(a)$] every path of ${\mathbb G}$ has length at most $n-2$;

\item[$(b)$] every cycle of ${\mathbb G}$ has length dividing $n$.
\end{itemize}
\end{lemma}
\begin{proof}
$(a)$ Suppose on the contrary that $\mathbb{G}$ contains a path of length $n-1$.
Then $S_{\bp_n}$ is a subalgebra of $S_{\mathbb{G}}$, and so $S_{\bp_n}$ belongs to $\mathcal{V}_n$.
This implies that $S_{\bp_n}$ satisfies the identity~\eqref{id26060101}.
Consider the substitution $\varphi \colon \{x_1,\ldots,x_n\} \to S_{\bp_n}$ defined by
$\varphi(x_i) = a_i$ for each $1 \leq i \leq n$.
Under this substitution, we have that $\varphi(\bp_n) = \omega$ but $\varphi(\bc_n) = 0$, which leads to a contradiction.
Therefore, every path in $\mathbb{G}$ has length at most $n-2$.

$(b)$ Assume that $\mathbb{G}$ contains a cycle of length $m$, where $m$ does not divide $n$.
Then $S_{\bc_m}$ is a subalgebra of $S_{\mathbb{G}}$, and so $S_{\bc_m}$ satisfies the identity~\eqref{id26060101}.
By Lemma~\ref{Scnm}, the algebra $S_{\bc_m}$ satisfies the identity $\bc_n \approx x^3$.
Consequently, $S_{\bc_m}$ satisfies the identity $\bp_n \approx x^3$.
Define the substitution $\varphi \colon \{x_1,\ldots,x_n\} \to S_{\bc_m}$ by setting $\varphi(x_i) = a_k$, where $1 \leq i \leq n$, $1 \leq k \leq m$, and $i \equiv k \pmod{m}$.
This substitution yields $\varphi(\bp_n) = \omega$ while $\varphi(x^3) = 0$, again resulting in a contradiction.
We conclude that every cycle in $\mathbb{G}$ must have length dividing $n$.
\end{proof}

\begin{lemma}\label{lemma250614001}
The variety $\mathcal{V}_n$ is generated by the finite flat semiring
\[
S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}
\]
for all $n \geq 2$.
\end{lemma}
\begin{proof}
We first show that $S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}$ satisfies the identity \eqref{id26060101}.
Indeed, let \[\varphi:\{x_1,\ldots, x_n\}\to S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}\]
be an arbitrary substitution.
If $\varphi(\bp_n)=0$ then $\varphi(\bc_n)=\varphi(\bp_n)+\varphi(x_{n}x_1)=0$.
If $\varphi(\bp_n)\neq 0$ then
\[
\varphi(x_1)\varphi(x_2)+\varphi(x_2)\varphi(x_3)\cdots \varphi(x_{n-1})\varphi(x_n)=\varphi(\bp_n)=\omega.
\]
This implies that $\{\varphi(x_1),\ldots,\varphi(x_n)\}$ is contained in some connected component of
$S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}$, say $S_{\bc_m}$, where $m$ is a divisor of $n$.
So $\varphi$ can be viewed as a substitution from $\{x_1,\ldots,x_n\}$ to $S_{\bc_m}$.
Let $a_{j_i}$ denote $\varphi(x_i)$, where $1\leq i\leq n$, $1\leq j_i\leq m$.
By \eqref{eq25053003} in the proof of Lemma \ref{Scnm}, we have
$$j_n\equiv j_1+n-1 \equiv j_1-1 \pmod{m}.$$
This implies that $\varphi(x_n)\varphi(x_1)=\omega$, and so $\varphi(\bc_n)=\omega$.
We have shown that the graph semiring $S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}$ satisfies~\eqref{id26060101}.
Thus $S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}$ lies in $\mathcal{V}_n$.

Conversely, suppose that $S$ is a finite subdirectly irreducible member of $\mathcal{V}_n$.
Then, by Theorem~\ref{siSg}, $S$ is isomorphic to a graph semiring $S_{\mathbb G}$ for some finite graph ${\mathbb G}$.
It follows from Lemma~\ref{lem25061422} that every path of ${\mathbb G}$ has length at most $n-2$,
and that every cycle of ${\mathbb G}$ has length that divides $n$.
Let $\{{\mathbb G}_i \mid 1\leq i \leq m\}$ denote the set of all connected components of ${\mathbb G}$.
Then every $S_{\mathbb G_i}$ is a subalgebra of $\bigcup_{k\mid n}^{\omega} S_{\bc_k}$.
By Proposition \ref{pro25061320}, $S_{\mathbb G}$ is the $\{0,\omega\}$-direct union of
$\{S_{\mathbb G_i} \mid 1\leq i\leq m\}$.
This implies that $S_{\mathbb G}$ is a subalgebra of the $\{0,\omega\}$-direct union
of $m$ copies of $\bigcup_{k\mid n}^{\omega} S_{\bc_k}$.
By Proposition~\ref{scnsln11}(2) one can deduce that $S_{\mathbb G}$ lies in the variety generated by $S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}$,
and so does $S$.
Thus $\mathcal{V}_n$ is generated by $S_{\bc_1}\circ \bigcup_{k\mid n}^{\omega}S_{\bc_k}$.
\end{proof}

\begin{proposition}\label{fgsubvariety}
The variety $\mathcal{V}_n$ is a Cross variety for all $n \geq 2$.
\end{proposition}
\begin{proof}
By Proposition~\ref{fkjidi}(2) and Lemma \ref{lemma250614001}, one can deduce that $\mathcal{V}_n$ is finitely based
and finitely generated.
In the reminder we shall show that $\mathcal{V}_n$ contains only finitely many critical algebras.
Indeed, let $S$ be a critical algebra in $\mathcal{V}_n$.
Then $S$ must be subdirectly irreducible.
By Theorem \ref{siSg}, $S$ is isomorphic to some finite graph semiring $S_{\mathbb G}$.
By Lemma~\ref{lem25061422}, every path of ${\mathbb G}$ has length at most $n-2$,
and that every cycle of ${\mathbb G}$ has length that divides $n$.
Since $S_{\mathbb{G}}$ is critical, Proposition~\ref{scnsln11} implies that in $\mathbb{G}$,
loops and paths of equal length appear at most twice, and cycles of length $>1$ are distinct.
Thus the number of such graphs is finite and so $\mathcal{V}_n$ contains only finitely many critical algebras.
Therefore, $\mathcal{V}_n$ is a Cross variety.
\end{proof}

%\textcolor{red}{\begin{remark}
%Let $m,n\geq 2$ be integers, and let $\mathcal{V}_m$ and $\mathcal{V}_n$ be varieties defined in Proposition~$\ref{fgsubvariety}$.
%Then $\mathcal{V}_m$ is a subvariety of $\mathcal{V}_n$ whenever $m$ is a divisor of $n$.
%\end{remark}}

\begin{proposition}\label{pro25061501}
Every finitely generated subvariety of $\mathbf{NF}_3$ is contained in
$\mathcal{V}_n$ for some integer $n\geq 2$.
\end{proposition}
\begin{proof}
We first show that every finite graph semiring belongs to the variety $\mathcal{V}_n$ for some integer $n\geq 2$.
Indeed, let $S_{\mathbb G}$ be an arbitrary finite graph semiring.
Suppose that the maximum length of paths and cycles in $\mathbb G$ is less than $m$.
Let $\{{\mathbb G}_i \mid 1\leq i \leq k\}$ denote the set of all connected components of ${\mathbb G}$.
Then $S_{\mathbb G_i}$ is a subalgebra of $\bigcup_{1\leq i\leq m}^{\omega} S_{\bc_i}$ for every $1\leq i \leq k$.
By Proposition \ref{pro25061320}, $S_{\mathbb G}$ is the $\{0,\omega\}$-direct union of
$\{S_{\mathbb G_i} \mid 1\leq i\leq k\}$.
This implies that $S_{\mathbb G}$ is a subalgebra of the $\{0,\omega\}$-direct union
of $k$ copies of $\bigcup_{1\leq i\leq m}^{\omega} S_{\bc_i}$.
Now it follows from Proposition \ref{scnsln11}(2) that $S_{\mathbb G}$ lies in the variety
$\mathsf{V}(S_{\bc_1}\circ \bigcup_{1\leq i\leq m}^{\omega} S_{\bc_i})$.
Take $n=m!$. By Lemma \ref{lemma250614001},
$S_{\bc_1}\circ \bigcup_{1\leq i\leq m}^{\omega} S_{\bc_i}$ is a member of $\mathcal{V}_{n}$.
So $S_{\mathbb G}$ is in $\mathcal{V}_{n}$.

Let $\mathcal{V}$ be a finitely generated subvariety of $\mathbf{NF}_3$.
It follows from Lemma~\ref{lem24121301} and Theorem~\ref{siSg} that
$\mathcal{V}$ is generated by finitely many finite graph semirings $S_1, \ldots, S_m$.
By the preceding result, there exists $n$ such that
the finite graph semiring $\bigcup^\omega_{1\leq i \leq m} S_{i}$
lies in $\mathcal{V}_n$.
This implies that $\mathcal{V}$ is a subvariety of $\mathcal{V}_n$.
\end{proof}

\begin{corollary}\label{fgsubkehua}
Let $\mathcal{V}$ be subvariety of $\mathbf{NF}_3$.
If $\mathcal{V}$ does not contain $S_{\bp_m}$ for some $m\geq 2$, then $\mathcal{V}$ is finitely generated.
\end{corollary}
\begin{proof}
Let $S_{\mathbb{G}}$ be an arbitrary graph semiring in $\mathcal{V}$.
Since $S_{\bp_m}$ is not a subalgebra of $S_{\mathbb{G}}$,
the maximum length of paths and cycles in $\mathbb{G}$ must be less than $m$.
From the proof of Proposition~\ref{pro25061501}, it follows that $S_{\mathbb{G}}$ is a member of $\mathcal{V}_{m!}$,
and so $\mathcal{V}$ is a subvariety of $\mathcal{V}_{m!}$.
By Proposition~\ref{fgsubvariety} we therefore conclude that $\mathcal{V}$ is finitely generated.
\end{proof}

\begin{thm}\label{coro25060115}
Every finitely generated subvariety of $\mathbf{NF}_3$ is a Cross variety.
\end{thm}
\begin{proof}
This follows from Propositions \ref{fgsubvariety} and \ref{pro25061501} immediately.
\end{proof}

\begin{corollary}\label{coro25060310}
Every finite $3$-nilpotent flat semiring is finitely based.
\end{corollary}
\begin{proof}
This is a consequence of Theorem~\ref{coro25060115}.
\end{proof}

%\begin{remark}
%In contrast to Corollary~$\ref{coro25060310}$,
%not every finite $4$-nilpotent flat semiring is finitely based.
%For example, the semiring $S_c(abc)$
%provides an example of a nonfinitely based
%finite $4$-nilpotent flat semiring, which can be deduced by~\cite[Theorem 4.9]{jrz}.
%\end{remark}

\begin{corollary}
The variety $\mathbf{NF}_3$ is not finitely generated.
\end{corollary}
\begin{proof}
Suppose by way of contradiction that $\mathbf{NF}_3$ is finitely generated.
By Theorem~\ref{coro25060115} we have that $\mathbf{NF}_3$ is a Cross variety.
This implies that $\mathbf{NF}_3$ has finitely many subvarieties, which contradicts Theorem~\ref{cor:continuum}.
Hence $\mathbf{NF}_3$ is not finitely generated as required.
\end{proof}


The following example shows that a finitely based subvariety of $\mathbf{NF}_3$ is not necessarily finitely generated.
\begin{example}
$\mathsf{V}(\bigcup_{n\geq 2}^{\omega}S_{c_n})$ is determined within the variety $\mathbf{NF}_3$
by the identity $x^2\approx x^3$, but is not finitely generated.
In fact, let $\mathcal W$ denote the subvariety of $\mathbf{NF}_3$ determined by the identity $x^2\approx x^3$.
It is easy to see that $\bigcup_{n\geq 2}^{\omega}S_{c_n}$ satisfies $x^2\approx x^3$,
and so $\mathsf{V}(\bigcup_{n\geq 2}^{\omega}S_{c_n})$ is a subvariety of $\mathcal W$.
Conversely, let $S$ be a finite nontrivial subdirectly irreducible member of $\mathcal W$.
It follows from Theorem $\ref{siSg}$ and Lemma $\ref{Scnm}$ that $S$ is isomorphic to a finite graph semiring $S_{\mathbb G}$,
where $\mathbb G$ is a finite loop-free graph.
So $S_{\mathbb G}$ is a subalgebra of $\{0,\omega\}$-direct union of $m$ copies of $\bigcup_{n\geq 2}^\omega S_{\bc_n}$,
where $m$ is the number of connected components of $\mathbb G$.
By Proposition $\ref{scnsln11}(1)$, we have that $S_{\mathbb G}$ is a member of
$\mathsf{V}(\bigcup_{n\geq 2}^{\omega}S_{c_n})$,
and so is $S$.
Thus $\mathsf{V}(\bigcup_{n\geq 2}^{\omega}S_{c_n})=\mathcal W$ as required.
\end{example}


