Proposition~\ref{pro25061501} essentially provides a general method for finding a finite equational basis of a finitely generated subvariety $\mathcal{V}$ of  $\mathbf{NF}_3$.
Firstly, determine $n$ such that $\mathcal{V}$ is a subvariety of $\mathcal{V}_n$.
Next, find a maximal chain from $\mathcal{V}$ to $\mathcal{V}_n$, which is denoted by
\[
\mathcal{V} = \mathcal{W}_0 < \mathcal{W}_1 < \cdots < \mathcal{W}_m = \mathcal{V}_n.
\]
For any $1 \leq k \leq m$, let us take an identity
$\bu_k \approx \bv_k$ that is satisfied by $\mathcal{W}_{k-1}$, but is not true in $\mathcal{W}_{k}$.
So $\mathcal{V}$ is the subvariety of $\mathbf{NF}_3$ determined by the following finitely many identities:
\[
\bp_n\approx \bc_n, \bu_1 \approx \bv_1, \ldots, \bu_m \approx \bv_m.
\]

We end this section by showing that finding the finite equational basis of $\mathsf{V}(S_{\bc_n})$
can also be addressed through \emph{forbidden identities}.

\begin{lemma}\label{sckk|njinqu}
Let $\mathcal{V}$ be a subvariety of $\mathbf{NF}_3$.
Then ${\mathcal V}$ satisfies the identity $\bc_n\approx x^3$ if and only if
${\mathcal V}$ does not contain $S_{\bc_k}$ for all divisors $k$ of $n$.
\end{lemma}

\begin{proof}
Suppose that ${\mathcal V}$ contains a graph semiring $S_{\bc_k}$ for some divisor $k$ of $n$.
Then by Lemma~\ref{Scnm}, we have that ${\mathcal V}$ does not satisfy $\bc_n\approx x^3$.

Conversely, assume that ${\mathcal V}$ does not satisfy $\bc_n\approx x^3$.
By Theorem~\ref{siSg}, there is a finite graph semiring $S_{\mathbb G}$ in $\mathcal{V}$
such that $\varphi(\bc_n)\neq \varphi(x^3)$ for some substitution  $\varphi:\{x, x_1, \ldots, x_n\}\to S_{\mathbb G}$.
Since $\varphi(x^3)=0$, we have
\[
\varphi(x_1)\varphi(x_2)+\varphi(x_2)\varphi(x_3)+\cdots+\varphi(x_{n-1})\varphi(x_n)+\varphi(x_{n})\varphi(x_1)=\varphi(\bc_n)=\omega.
\]
and so $\{\varphi(x_1), \ldots, \varphi(x_n)\}$ is contained in some connected component $\mathbb G_i$ of $\mathbb G$.
It is obvious that $\mathbb G_i$ is a circle graph, and so $S_{\mathbb G_i}$ is isomorphic to $S_{\bc_k}$ for some $k$.
Since $S_{\bc_k}$ does not satisfy the identity $\bc_n\approx x^3$, it follows from Lemma~\ref{Scnm} again that $k$ is a divisor of $n$.
So ${\mathcal V}$ contains $S_{\bc_k}$ for some divisor $k$ of $n$.
\end{proof}




\begin{proposition}
Let $n\geq 2$ be an integer. Then $\mathsf{V}(S_{\bc_n})$ is the subvariety of $\mathbf{NF}_3$
determined by the identities $\bp_n\approx \bc_n$ and $\bc_k\approx x^3$, where $k$ runs through the proper divisors of $n$.
\end{proposition}

\begin{proof}
Let $\mathcal{V}$ be the subvariety of $\mathbf{NF}_3$
determined by $\bp_n\approx \bc_n$ and $\bc_k\approx x^3$, where $k$ runs through the proper divisors of $n$.
It follows from Lemmas~\ref{Scnm} and \ref{lemma250614001}
that $S_{\bc_n}$ is a member of $\mathcal{V}$, and so $\mathsf{V}(S_{\bc_n})$ is a subvariety of $\mathcal{V}$.
Conversely, let $S_{\mathbb G}$ be a finite graph semiring in $\mathcal{V}$.
By Lemmas~\ref{lem25061422} and \ref{sckk|njinqu}, we have that every path in $\mathbb G$ has length at most $n-2$ and every cycle in $\mathbb G$ is of length $n$.
This implies that $S_{\mathbb G}$ is a subalgebra of the $\{0,\omega\}$-direct union of some copies of
$S_{\bc_{n}}$.
By Proposition~\ref{scnsln11}(1) we have that $S_{\mathbb G}$ is a member of $\mathsf{V}(S_{\bc_n})$.
Thus $\mathsf{V}(S_{\bc_n})=\mathcal{V}$.
\end{proof}



\section{The limit subvariety of $\mathbf{NF}_3$}
In this section we show that $\mathbf{NF}_3$ has a unique limit subvariety.
Let us denote by $S_{\bp_{\infty}}$ the graph semiring induced by a path graph of infinite length,
that is, a graph with the vertex set $\{a_k \mid k \geq 1\}$ and the edge set $\{(a_k, a_{k+1}) \mid k \geq 1\}$.
It is straightforward to verify that each $S_{\mathbf{p}_n}$ forms a subalgebra of $S_{\mathbf{p}_\infty}$.
Conversely, every finitely generated subalgebra of $S_{\mathbf{p}_\infty}$ is contained in some $S_{\mathbf{p}_n}$.
This implies that $S_{\mathbf{p}_\infty}$ and $\{S_{\bp_n}\mid n\geq 1\}$ satisfy the same identities.
So we have

\begin{pro}\label{pro25060725}
$\mathsf{V}(S_{\bp_{\infty}})=\mathsf{V}(\{S_{\bp_n}\mid n\geq 1\})$.
\end{pro}

A graph semiring $S_{\mathbb G}$ is \emph{acyclic} if the graph $\mathbb G$ is acyclic, that is, $\mathbb G$ contains no cycles.
One can easily see that $S_{\bp_{\infty}}$ is an example of an acyclic graph semiring.
We shall use $\mathcal{V}_{ac}$ to denote the subvariety of $\mathbf{NF}_3$ generated by all acyclic graph semirings.


%
%
%\begin{corollary}
%  Let $I$ be an infinite subset of $\mathbb N_{\geq 2}$.
%  Then $\mathcal{V}_{ac}$ is generated by $\{S_{\bc_n\mid n\in I}\}$.
%\end{corollary}
%
%\begin{proof}
%  Since
%\end{proof}



\begin{pro}\label{pro25060701}
The variety $\mathcal{V}_{ac}$ is generated by $S_{\bp_{\infty}}$.
\end{pro}
\begin{proof}
Let $S_{\mathbb G}$ be an acyclic graph semiring,
and let $\{\mathbb G_i\}_{i\in I}$ denote the set of all connected components of $\mathbb G$.
It is easy to see that $S_{\mathbb G}$ is a subalgebra of $\bigcup_{i\in I}^{\omega}S_{\bp_{\infty}}$.
Let $T$ be the algebra of the direct product $\prod_{i\in I} S_{\bp_{\infty}}$ generated by the subset $\{\alpha_{ik}\mid i\in I, k\geq 1\}$, where for each $j\in I$,
\[
\alpha_{ik}(j)=\begin{cases}
  a_k,& j=i,\\
  a_{k+1},& j\neq i.
\end{cases}
\]

If we denote by $J$ the set of all elements of $T$ with a $0$-coordinate,
then $J$ is both a multiplicative ideal and an order-theoretic filter of $T$.
Now it is a routine matter to verify that the quotient algebra $T/J$ is isomorphic to $\bigcup_{i\in I}^{\omega}S_{\bp_{\infty}}$,
and so $S_{\mathbb G}$ is a member of $\mathsf{V}(S_{\bp_{\infty}})$.
Thus $\mathcal{V}_{ac}$ is generated by $S_{\bp_{\infty}}$.
\end{proof}


\begin{lemma}\label{vacbasis}
The variety $\mathcal{V}_{ac}$ is determined within $\mathbf{NF}_3$ by the identities
\begin{equation} \label{bcnx3n1}
\bc_n\approx x^3,~n \geq 1.
\end{equation}
\end{lemma}
\begin{proof}
Let $\mathcal{W}$ be the subvariety of $\mathbf{NF}_3$ determined  by the identities \eqref{bcnx3n1}.
It is easy to see that $S_{\bp_{\infty}}$ satisfies the identities \eqref{bcnx3n1}.
By Proposition \ref{pro25060701} we have that $\mathcal{V}_{ac}$ is a subvariety of $\mathcal{W}$.
Conversely, let $S_{\mathbb G}$ be a finite graph semiring in $\mathcal{W}$.
Suppose by way of contradiction that $\mathbb G$ is not acyclic.
Then $\mathbb G$ contains some cycle of length $m$, and so $S_{\bc_m}$ lies in $\mathcal{W}$.
This implies that $S_{\bc_m}$ satisfies $\bc_m\approx x^3$, which is a contradiction.
Thus $\mathbb G$ is acyclic and so $S_{\mathbb G}$ is a acyclic graph semiring.
Hence $\mathcal{W}$ is a subvariety of $\mathcal{V}_{ac}$
and so $\mathcal{V}_{ac}=\mathcal{W}$.
\end{proof}

\begin{corollary}\label{everyacyclic}
  Every graph semiring in $\mathcal{V}_{ac}$ is acyclic.
\end{corollary}




\begin{pro}\label{vacnfb}
The variety $\mathcal{V}_{ac}$ is nonfinitely based.
\end{pro}
\begin{proof}
Assume, for contradiction, that $\mathcal{V}_{ac}$ is finitely based.
It follows from Lemma~\ref{vacbasis} and the Compactness Theorem for Equational Logic~\cite[Exercise 10 in \S14]{bs}
that $\mathcal{V}_{ac}$ is the subvariety of $\mathbf{NF}_3$ determined by the identities
\begin{equation}\label{ckx31km}
  \bc_k\approx x^3,~ 1\leq k\leq m
\end{equation}
for some $m$.
By Lemma~\ref{Scnm}, the cycle graph semiring $S_{\bc_{m+1}}$ satisfies the identities \eqref{ckx31km}.
This implies that $S_{\bc_{m+1}}$ is a member of $\mathcal{V}_{ac}$, which contradicts Corollary \ref{everyacyclic}.
So $\mathcal{V}_{ac}$ is nonfinitely based.
\end{proof}

\begin{corollary}\label{coro25060720}
The variety $\mathcal{V}_{ac}$ is not finitely generated.
\end{corollary}
\begin{proof}
This follows from Corollary \ref{coro25060310} and Proposition \ref{vacnfb} immediately.
\end{proof}

\begin{pro}\label{lvvac}
The subvariety lattice of the variety $\mathcal{V}_{ac}$ consists of $\mathcal{V}_{ac}$,
$\mathsf{V}(S_{\bp_n})$ and $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ for all $n\geq 1$.
This lattice is isomorphic to the linear sum of the lattice of
all natural numbers under the usual order and the trivial one-element lattice.
\end{pro}

\begin{proof}
Let $\mathcal{W}$ be a subvariety of $\mathcal{V}_{ac}$.
It follows from Corollary~\ref{everyacyclic} that $\mathcal{W}$ can be
generated by a family $(S_{\mathbb G_i})_{i\in I}$ of finite acyclic graph semirings.
For any $i \in I$, let $n_i$ denote the maximum of lengths of all paths in $\mathbb G_i$.
Consider the following two cases:

\textbf{Case 1.} The set $\{n_i \mid i\in I\}$ has a maximum element $n$.

\textbf{Subcase 1.1.} There are at least two paths of length $n$ in some graph $\mathbb G_i$.
It is obvious that $S_{\bp_n}\circ S_{\bp_n}$ is a member of $\mathcal{W}$,
and so $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ is a subvariety of $\mathcal{W}$.
On the other hand, for any $i\in I$, we may assume that $\mathbb G_i$ has exactly $n_i$ connected components.
Then $S_{\mathbb G_i}$ is a subalgebra of  $\bigcup_{1\leq k\leq n_i}^{\omega} S_{\bp_n}$.
It follows from Lemma~\ref{scnsln1}\eqref{eq250602011} that $S_{\mathbb G_i}$ lies in $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$.
So $\mathcal{W} = \mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$.

\textbf{Subcase 1.2.} There is at most one path of length $n$ in any graph $\mathbb G_i$.
It is easy to see that $S_{\bp_n}$ lies in $\mathcal{W}$.
Conversely, for any $i\in I$, suppose that $\mathbb G_i$ has exactly $n_i$ connected components.
Then $S_{\mathbb G_i}$ is a subalgebra of  $S_{\bp_{n}}\circ \bigcup_{1\leq k\leq n_i}^{\omega} S_{\bp_{n-1}}$.
It follows from Lemma~\ref{scnsln1}\eqref{eq250602012} that $S_{\mathbb G_i}$ is a member of $\mathsf{V}(S_{\bp_n})$.
Thus $\mathcal{W} = \mathsf{V}(S_{\bp_n})$.


\textbf{Case 2.} The set $\{n_i \mid i\in I\}$ has no upper bound.
It is easy to see that $S_{\bp_n}$ lies in $\mathcal{W}$ for all $n\geq 2$.
By Proposition \ref{pro25060725}, we have that $\mathcal{W}=\mathcal{V}_{ac}$.

So we have shown that the subvariety lattice of the variety $\mathcal{V}_{ac}$ consists of $\mathcal{V}_{ac}$,
$\mathsf{V}(S_{\bp_n})$ and $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ for all $n\geq 1$.
By Lemma~\ref{scnsln1}(1) one can deduce that
\[
\mathsf{V}(S_{\bp_1})<\mathsf{V}(S_{\bp_1}\circ S_{\bp_1})<\cdots <\mathsf{V}(S_{\bp_n})<\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})<\cdots<\mathcal{V}_{ac}.
\]
Therefore, the subvariety lattice of $\mathcal{V}_{ac}$ is isomorphic to
the linear sum of the lattice of all natural numbers under the usual order and the trivial one-element lattice.
\end{proof}

\begin{corollary}\label{coro250607001}
Every proper subvariety of $\mathcal{V}_{ac}$ is finitely based.
\end{corollary}
\begin{proof}
This is a consequence of Proposition \ref{lvvac} and Corollary \ref{coro25060310}.
\end{proof}

By Proposition \ref{vacnfb} and Corollary \ref{coro250607001} we immediately obtain
\begin{pro}\label{pro25060715}
$\mathcal{V}_{ac}$ is a limit variety.
\end{pro}

\begin{pro}\label{fgsvvac}
Let $\mathcal{V}$ be a subvariety of $\mathbf{NF}_3$.
Then $\mathcal{V}$ is finitely generated if and only if it does not contain $\mathcal{V}_{ac}$.
\end{pro}
\begin{proof}
Let $\mathcal{V}$ be a finitely generated subvariety of $\mathbf{NF}_3$.
By Proposition~\ref{fgsubvariety}, $\mathcal{V}$ is contained in some $\mathcal{V}_n$,
and so $\mathcal{V}$ satisfies the identity~\eqref{id26060101}.
Since the path graph semiring $S_{\bp_{n}}$ fails to satisfy the identity~\eqref{id26060101},
it follows that $S_{\bp_n}$ does not belong to $\mathcal{V}$.
Therefore, $\mathcal{V}$ does not contain $\mathcal{V}_{ac}$.

Conversely, suppose that $\mathcal{V}_{ac}$ is not contained in $\mathcal{V}$.
By Proposition~\ref{pro25060725}, there exists an integer $m\geq 2$ such that $S_{\bp_m}$ does not lie in $\mathcal{V}$.
It then follows from Corollary~\ref{fgsubkehua} that $\mathcal{V}$ is finitely generated.
\end{proof}

\begin{remark}
Corollary $\ref{coro25060720}$ and Proposition~$\ref{fgsvvac}$ together show that $\mathcal{V}_{ac}$
is the smallest not-finitely generated subvariety of $\mathbf{NF}_3$.
\end{remark}
Now we are ready to prove the main result of this section.
\begin{thm}
$\mathcal{V}_{ac}$ is the unique limit subvariety of $\mathbf{NF}_3$.
\end{thm}


\begin{proof}
From Proposition~\ref{pro25060715} we know that $\mathcal{V}_{ac}$ is a limit variety.
Let $\mathcal{V}$ be an arbitrary nonfinitely based subvariety of $\mathbf{NF}_3$.
By Corollary~\ref{coro25060115} we deduce that $\mathcal{V}$ is not finitely generated.
It follows from Proposition~\ref{fgsvvac} that $\mathcal{V}_{ac}$ is a subvariety of $\mathcal{V}$.
Thus $\mathcal{V}_{ac}$ is the unique limit subvariety of $\mathbf{NF}_3$ as required.
\end{proof}


\begin{corollary}
The variety $\mathcal{V}_{ac}$ is not a Cross variety, but every proper subvariety of $\mathcal{V}_{ac}$ is a Cross variety.
\end{corollary}

We end this section by providing finite equational bases for $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$
and $\mathsf{V}(S_{\bp_n})$, although both of them have been known to be finitely based.


\begin{pro}\label{bpnbpnfb}
$\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ is the subvariety of $\mathbf{NF}_3$
determined by the identities
\begin{equation}\label{id25060801}
\bp_{n+1}\approx x^3.
\end{equation}
\end{pro}
\begin{proof}
It is easy to check that $S_{\bp_n}\circ S_{\bp_n}$ satisfies \eqref{id25060801}.
In the remainder it is enough to show that every finite graph semiring that satisfies \eqref{id25060801}
lies in $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$.
Let $S_{\mathbb G}$ be such an algebra.
Then the graph $\mathbb G$ is acyclic and has no path of length greater than $n-1$.
By Lemma ~\ref{scnsln1}(1),
we have that $S_{\mathbb G}$ is a member of $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$.
Thus $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ is the subvariety of $\mathbf{NF}_3$ determined by \eqref{id25060801} as required.
\end{proof}

\begin{pro}\label{bpnfb}
$\mathsf{V}(S_{\bp_n})$ is the subvariety of $\mathbf{NF}_3$ determined by the identities
\eqref{id25060820} and \eqref{id25060801}.
\end{pro}
\begin{proof}
From Proposition \ref{bpnbpnfb} we know that $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ is the subvariety of $\mathbf{NF}_3$
defined by \eqref{id25060801}.
By proposition~\ref{lvvac}, $\mathsf{V}(S_{\bp_n})$ is a maximal subvariety of $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$.
Notice that the identity \eqref{id25060820} is true in $S_{\bp_n}$,
but does not hold in $S_{\bp_n}\circ S_{\bp_n}$.
It follows that $\mathsf{V}(S_{\bp_n})$ is determined within $\mathsf{V}(S_{\bp_n}\circ S_{\bp_n})$ by \eqref{id25060820}.
So the required result is true.
\end{proof}





\section{Conclusion}
We have shown that every finite $3$-nilpotent flat semiring is finitely based.
This partially solves an open problem proposed by Jackson et al.~\cite{jrz}.
However, the finite basis problem for general finite nilpotent flat semirings remains unresolved, even in the case of $S(W)$.
Unlike the $3$-nilpotent case, certain finite $4$-nilpotent flat semirings are nonfinitely based,
with $S_c(abc)$ being a specific example, which can be deduced by~\cite[Theorem 4.9]{jrz}.
This demonstrates the substantial challenges in obtaining a complete solution to the finite basis problem for finite nilpotent flat semirings.

