\subsection{Expectation and Variance Conditions of logistic Equation}\label{logisticsection}
Here we derive the equilibrium conditions for the mean and variance of~\eqref{eq:logistic3}, assuming that \( X_t \) is gamma-distributed at equilibrium. That is, at equilibrium, \( X_t \sim \mathrm{Gamma}(k, \theta) \), where \( k \) is the shape parameter and \( \theta \) is the scale parameter:

\begin{equation}
X_t \sim \text{Gamma}(k, \theta)
\label{gamma123}
\end{equation}
Because of nonlinearity, $X_{t+1}$ may not follow a gamma distribution, it is reasonable to assume that the mean and variance are the same: 
\begin{equation}
E[X_{t+1}] = E[X_t] \quad \text{and} \quad \text{Var}[X_{t+1}] = \text{Var}[X_t]
\label{mean_identity-123}
\end{equation}
It is easy to compute that 
\begin{align}
E[X_t] &= \mu = k \theta, \label{eq:mean_mu} \\
E[X_t^2] &= k (k + 1) \theta^2. \label{eq:second_moment}
\end{align}
\begin{align}
E[X_t^n] &= \theta^n \frac{\Gamma(k+n )}{\Gamma(k)}, \label{eq:gamma_moment} \\
\end{align}
Since $\epsilon_t$ is independent, we have  
\begin{equation} \label{eq:expected_value}
E[X_{t+1}] = E\left[ r X_t \left(1 - X_t \right )  \epsilon_t \right]=E\left[ r X_t \left(1 - X_t \right ) \right] E[\epsilon_t].
\end{equation}
Since $E[\epsilon_t]=1$, and at equilibrium, ($E[X_{t+1}] = E[X_t] = \mu$), we have
\begin{equation} \label{eq:expanded_equation}
\mu = r \left( \mu - E[X_t^2] \right).
\end{equation}
Subtract $r \mu$ from both sides and simplify it:
\begin{equation} \label{eq:simplified_equation}
\mu (1 - r) = - r E[X_t^2].
\end{equation}
Substituting $\mu = k \theta$ and $E[X_t^2]=\sigma^2 + \mu^2$ into the equilibrium equation \eqref{eq:simplified_equation}:
\begin{equation} \label{eq:equilibrium_in_k_theta}
k \theta (1 - r) = - r \left( k \theta^2 + k^2 \theta^2 \right).
\end{equation}
Divide both sides by $k \theta$ (since $k, \theta > 0$):

\begin{equation} \label{eq:equilibrium_divided}
(1 - r) = - r \theta (1 + k).
\end{equation}
Solve for $\theta$:

\begin{equation} \label{eq:theta_solution}
\theta = \frac{r - 1}{r (1 + k)}.
\end{equation}
Therefore, this suggests that for $r > 1$, this equilibrium may exist under the gamma distribution assumption.

In addition to the mean, we can compare the variance condition at equilibrium $$ \text{Var}[X_{t+1}] = \text{Var}[X_t].$$ This provides additional conditions that can help determine the gamma distribution parameters. To compute \( \text{Var}[X_{t+1}] \), we need \( E[X_{t+1}] \) and \( E[X_{t+1}^2] \):

\[
\text{Var}[X_{t+1}] = E[X_{t+1}^2] - \left( E[X_{t+1}] \right)^2.
\]
We already have \( E[X_{t+1}] = \mu = k \theta \). To compute \( E[X_{t+1}^2] \), we expand \( X_{t+1}^2 \):

\begin{align*}
X_{t+1}^2 &= \left( r X_t - r X_t^2  \right)^2 \epsilon_t^2 \\
%&= r^2 X_t^2 - 2 \frac{r^2}{K} X_t^3 + \left( \frac{r}{K} \right)^2 X_t^4
&= \left (r^2 X_t^2 - 2 r^2 X_t^3 + r^2 X_t^4 \right )\epsilon_t^2
\end{align*}
We take expectations:
\begin{equation} \label{eq:expectation_xt1_squared}
E[X_{t+1}^2] = \left ( r^2 E[X_t^2] - 2 r^2 E[X_t^3 ] + r^2 E[X_t^4] \right )E[\epsilon_t^2].
\end{equation}
At equilibrium, \( \text{Var}[X_{t+1}] = \text{Var}[X_t] = k \theta^2 \). Therefore,

\begin{equation} \label{eq:variance_equilibrium}
E[X_{t+1}^2] - (k \theta)^2 = k \theta^2
\end{equation}
and
\begin{equation} \label{eq:variance_equilibrium_simplified}
E[X_{t+1}^2] = k \theta^2 (1 + k).
\end{equation}
We can cancel \( \theta^2 \) from both sides as \( \theta > 0 \):

\begin{equation} \label{eq:variance_equilibrium_theta_cancelled}
\frac{E[X_{t+1}^2]}{\theta^2} = k (1 + k).
\end{equation}
Compute the required terms:

\begin{align*}
E[X_t^2] &= \theta^2 k (k + 1), \\
E[X_t^{3}] &= \theta^{3} \frac{\Gamma(k + 3)}{\Gamma(k)} = \theta^{3} (k + 2)(k + 1)k, \\
E[X_t^{4}] &= \theta^{4} \frac{\Gamma(k + 4)}{\Gamma(k)} = \theta^{4} (k + 3)(k + 2)(k + 1)k.
\end{align*}
With cancellation of $\theta^2$,  \eqref{eq:variance_equilibrium_theta_cancelled} and \eqref{eq:expectation_xt1_squared} give
\begin{align*}
& \Big( r^2 k (k + 1) - 2 r^2 \theta (k + 2)(k + 1)k + r^2 \theta^{2}  (k + 3)(k + 2)(k + 1)k \Big ) E[\epsilon_t^2] = k (1 + k).
\end{align*}
Dividing by $E[\epsilon_t^2]$ and subtracting $k (k + 1)$ at both sides give  
\begin{align*}
&  (r^2-1) k (k + 1) - 2 r^2 \theta (k + 2)(k + 1)k + r^2 \theta^{2}  (k + 3)(k + 2)(k + 1)k = \frac{k (1 + k)}{E[\epsilon_t^2]}-k(k+1).
\end{align*}
Multiplying by $-1$ at both sides produces 
\begin{align*}
&  (1-r^2) k (k + 1) + 2 r^2 \theta (k + 2)(k + 1)k - r^2 \theta^{2}  (k + 3)(k + 2)(k + 1)k = \frac{E[\epsilon_t^2]-1}{E[\epsilon_t^2]}k(k+1).
\end{align*}
Since $Var[\epsilon_t]=E[\epsilon_t^2]-E[\epsilon_t]^2=E[\epsilon_t^2]-1$, 
\begin{align*}
&  (1-r^2) k (k + 1) + 2 r^2 \theta (k + 2)(k + 1)k - r^2 \theta^{2}  (k + 3)(k + 2)(k + 1)k =\frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}k(k+1).
\end{align*}
