%
%\begin{align*}
%& r^2 k (k + 1) - 2 \frac{r^2}{K} \theta k (k + 1)(k + 2) + \left( \frac{r}{K} \right)^2 \theta^{2} k (k + 1)(k + 2)(k + 3) = k (k + 1).
%\end{align*}
%
%Subtract \( k (k + 1) \) from both sides:
%
%\begin{align*}
%& \left( r^2 - 1 \right) k (k + 1) - 2 \frac{r^2}{K} \theta k (k + 1)(k + 2) + \left( \frac{r}{K} \right)^2 \theta^{2} k (k + 1)(k + 2)(k + 3) = 0.
