Note that $\theta = \frac{(r - 1)}{r (1 + k)}$, therefore,
\begin{equation}
(1 - r^2) k (k + 1) + 2 r (r - 1) k (k + 2) - (r - 1)^2 k \cdot \dfrac{ (k + 2)(k + 3) }{ k + 1 } = \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}k(k+1)
\label{eq:simplified_main_n1}
\end{equation}
Dividing both sides by \( k (r - 1) \), we have

\begin{equation}
\dfrac{ (1 - r^2) k (k + 1) }{ k (r - 1) } + \dfrac{ 2 r (r - 1) k (k + 2) }{ k (r - 1) } - \dfrac{ (r - 1)^2 k \cdot \dfrac{ (k + 2)(k + 3) }{ k + 1 } }{ k (r - 1) } = \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}\frac{k+1}{r - 1}
\label{eq:divided_n1}
\end{equation}
After simplification, equation \eqref{eq:divided_n1} becomes:
\begin{equation}
- (r + 1)(k + 1) + 2 r (k + 2) - \dfrac{ (r - 1) (k + 2)(k + 3) }{ k + 1 } = \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}\frac{k+1}{r - 1}
\label{eq:divided_simplified_n1}
\end{equation}
Multiply equation \eqref{eq:divided_simplified_n1} by \( k + 1 \):
\begin{equation}
- (r + 1)(k + 1)^2 + 2 r (k + 2)(k + 1) - (r - 1)(k + 2)(k + 3) = \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}\frac{(k+1)^2}{r - 1}
\label{eq:multiplied_n12}
\end{equation}
The left side of \eqref{eq:multiplied_n12} is 
$$
- r k^2 - 2 r k - r - k^2 - 2k - 1 + 2 r k^2 + 6 r k + 4 r - r k^2 - 5 r k - 6 r + k^2 + 5k + 6 
$$
Thus, with simplification of the left side of \eqref{eq:multiplied_n12}, we arrive at 
\begin{equation} 
-r(k+3)+3k+5 =  \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}\frac{(k+1)^2}{r - 1}
\label{eq:multiplied_nr}
\end{equation}
Since $r>1$, it follows that 
\begin{equation}
-r(k+3)+3k+5 \ge 0 
\label{eq:multiplied_n1}
\end{equation}
and 
\begin{equation}
1<r \leq \frac{3k+5}{k+3}<3 
\label{eq:multiplied_q}
\end{equation}
Multiply both sides of \eqref{eq:multiplied_nr} by \( (r - 1) \):
\begin{equation}
(r - 1)\Big( -r(k + 3) + 3k + 5 \Big) =  \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}(k+1)^2
\label{eq:multiplied_qq}
\end{equation}
Simplification of the left side of \eqref{eq:multiplied_qq} leads to:
\begin{equation}
-r^2(k + 3) + 4kr + 8r - 3k - 5 =  \frac{Var[\epsilon_t]}{Var[\epsilon_t]+1}(k+1)^2
\label{eq:multiplied_qq1}
\end{equation}
Now express \eqref{eq:multiplied_qq1} as a quadratic equation in terms of \( r \):
\begin{equation}
(k + 3) r^2 - \left( 4k + 8 \right) r + \left( 3k + 5 + \dfrac{Var[\epsilon_t]}{Var[\epsilon_t] + 1}(k + 1)^2 \right) = 0.
\label{eq:multiplied_qq12}
\end{equation}
Let \( A \), \( B \), and \( C \) in \eqref{eq:multiplied_qq12} for computing its discriminant as:
\begin{align*}
A = k + 3, B = -\left( 4k + 8 \right) = -4k - 8, C = 3k + 5 + \dfrac{Var[\epsilon_t]}{Var[\epsilon_t] + 1}(k + 1)^2
\end{align*}
and
\begin{align*}
B^2 &= 16k^2 + 64k + 64,\\
4AC &= 4(k + 3)\left( 3k + 5 + \dfrac{Var[\epsilon_t]}{Var[\epsilon_t] + 1}(k + 1)^2 \right) \\
&= 4(k + 3)(3k + 5) + \dfrac{4Var[\epsilon_t](k + 3)(k + 1)^2}{Var[\epsilon_t] + 1}\\
  &=12k^2 + 56k + 60 + \dfrac{4Var[\epsilon_t](k + 3)(k + 1)^2}{Var[\epsilon_t] + 1}.
\end{align*}
Thus the discriminant \( D=B^2-4AC \) of the quadratic equation with respect to $r$ is given by:
\begin{align*}
D &= \left( 16k^2 + 64k + 64 \right) - \left( 12k^2 + 56k + 60 + \dfrac{4Var[\epsilon_t](k + 3)(k + 1)^2}{Var[\epsilon_t] + 1} \right) \\
&= 4k^2 + 8k + 4 - \dfrac{4Var[\epsilon_t](k + 3)(k + 1)^2}{Var[\epsilon_t] + 1}\\
&=  4(k + 1)^2 \left( \dfrac{1 - Var[\epsilon_t](k + 2)}{Var[\epsilon_t] + 1} \right).
\end{align*}
For real solutions, the discriminant \( D \) must be non-negative. Therefore, the condition for real solutions is:
\begin{equation}
0 < k \leq \dfrac{1}{Var[\epsilon_t]}-2.
\label{eq:multiplied_q1}
\end{equation}
We now have the maximum of the feasible variance of $\epsilon_t$ 
\begin{equation}
0 \leq Var[\epsilon_t] \leq 0.5.
\label{eq:multiplied_q2}
\end{equation}
Using the quadratic formula, we have
\begin{align}
r_{\pm} &= \dfrac{ 4k + 8 \pm 2(k + 1) \sqrt{ \dfrac{1 - Var[\epsilon_t](k + 2)}{Var[\epsilon_t] + 1} } }{ 2(k + 3) } \\
&= \dfrac{ 2k + 4 \pm (k + 1) \sqrt{ \dfrac{1 - Var[\epsilon_t](k + 2)}{Var[\epsilon_t] + 1} } }{ k + 3 }.
\label{eq:multiplied_q3}
\end{align}
It is easy to see that both $r_{\pm} \geq 1$.   Since $r_{+} > r_{-}$ and $\dfrac{1 - Var[\epsilon_t](k + 2)}{Var[\epsilon_t] + 1} \leq 1$ and therefore 
$$2k + 4 - (k + 1) \sqrt{ \dfrac{1 - Var[\epsilon_t](k + 2)}{Var[\epsilon_t] + 1} } \geq  k + 3 $$
We summarize the above result as Theorem \ref{theorm1}. 



