%\int_{0}^{\infty} x^{n + k - 1} e^{- x (s + 1 / \theta)} dx = \frac{\Gamma(n + k)}{\left( s + \dfrac{1}{\theta} \right)^{n + k}}
%\end{equation}
%and
\begin{eqnarray*}
