%&= \frac{\Gamma(n + k)}{\Gamma(k)} \cdot \frac{1}{\theta^{k}} \cdot \frac{1}{\left( s + \dfrac{1}{\theta} \right)^{n + k}}
%\end{align}
%Thus, we have:
%
%\begin{equation}
%E\left[ X_t^n e^{- s X_t} \right] 
&=& \frac{ \Gamma(k + n) }{ \Gamma(k) } \frac{ \theta^{n} }{ (1 + s \theta )^{ k + n } }
%\end{equation}
\end{eqnarray*}

%This completes the verification of the identity.




\subsubsection{Third Central Moment for Gamma Distribution}
Assume that 
\[
X_n \sim \operatorname{Gamma}(k,\theta),
\]
so that
\[
E[X_n] = k\theta \quad \text{and} \quad \operatorname{Var}(X_n) = k\theta^2.
\]
Define the fluctuation
\[
\beta_n = X_n - E[X_n] = X_n - k\theta.
\]
The third central moment is given by
\[
E[\beta_n^3] = E\Bigl[(X_n - k\theta)^3\Bigr].
\]
We will derive the following estimation. 

\begin{equation}
E[\beta_n^3] = O\Bigl((\operatorname{Var}(X_n))^{3/2}\Bigr).
\label{estimation1}
\end{equation}


Express this in terms of the raw moments:
\[
E[\beta_n^3] = E[X_n^3] - 3E[X_n]\,E[X_n^2] + 2E[X_n]^3.
\]
Using the identity
\[
E[X_n^n] = \frac{\Gamma(k+n)}{\Gamma(k)}\,\theta^n,
\]
we obtain:
\[
E[X_n] = k\theta,\quad E[X_n^2] = (k+1)k\,\theta^2,\quad E[X_n^3] = (k+2)(k+1)k\,\theta^3.
\]
Substitute these into the expression for \(E[\beta_n^3]\):
\[
\begin{aligned}
E[\beta_n^3] &= (k+2)(k+1)k\,\theta^3 - 3\,(k\theta)\,( (k+1)k\,\theta^2) + 2\,(k\theta)^3 \\
&= k\,\theta^3\Bigl[(k+2)(k+1) - 3k(k+1) + 2k^2\Bigr].
\end{aligned}
\]
Notice that
\[
(k+2)(k+1) = k^2 + 3k + 2.
\]
Then,
\[
\begin{aligned}
(k+2)(k+1) - 3k(k+1) + 2k^2 
&= (k^2 + 3k + 2) - 3k^2 - 3k + 2k^2 \\
&= k^2 + 3k + 2 - 3k^2 - 3k + 2k^2 \\
&= 2.
\end{aligned}
\]
Thus,
\[
E[\beta_n^3] = k\,\theta^3\cdot 2 = 2k\,\theta^3.
\]
Since 
\[
\operatorname{Var}(X_n) = k\,\theta^2,
\]
we have
\[
(\operatorname{Var}(X_n))^{3/2} = (k\,\theta^2)^{3/2} = k^{3/2}\,\theta^3.
\]
or equivalently,
\[
E[\beta_n^3] = O\Bigl((\operatorname{Var}(X_n))^{3/2}\Bigr).
\]


\subsubsection{Fourth Central Moment for Gamma Distribution}

Assume that 
\[
X_t\sim \operatorname{Gamma}(k,\theta),
\]
so that the mean and variance are
\[
E[X_t] = k\theta,\quad \operatorname{Var}(X_t)=k\theta^2.
\]
We define the fluctuation
\[
\beta_t = X_t - E[X_t].
\]

Our goal is to show that

\begin{equation}
E[\beta_t^4] = O\Bigl((\operatorname{Var}(X_t))^{2}\Bigr).
\label{estimation2}
\end{equation}
The identity \eqref{identity}
implies that by setting \(s=0\) we obtain the raw moments:
\[
E[X_t^n] = \frac{\Gamma(k+n)}{\Gamma(k)}\,\theta^n.
\]
In particular, we have:
\begin{align*}
E[X_t] &= \frac{\Gamma(k+1)}{\Gamma(k)}\,\theta = k\,\theta,\\[1mm]
E[X_t^2] &= \frac{\Gamma(k+2)}{\Gamma(k)}\,\theta^2 = (k+1)k\,\theta^2,\\[1mm]
E[X_t^3] &= \frac{\Gamma(k+3)}{\Gamma(k)}\,\theta^3 = (k+2)(k+1)k\,\theta^3,\\[1mm]
E[X_t^4] &= \frac{\Gamma(k+4)}{\Gamma(k)}\,\theta^4 = (k+3)(k+2)(k+1)k\,\theta^4.
\end{align*}

The fourth central moment (which is \(E[\beta_t^4]\)) is given by:
\[
E[(X_t-E[X_t])^4] = E[X_t^4] - 4E[X_t]\,E[X_t^3] + 6\bigl(E[X_t]\bigr)^2E[X_t^2] - 3\bigl(E[X_t]\bigr)^4.
\]
Substitute the moments computed above:
\begin{align*}
E[\beta_t^4] &= (k+3)(k+2)(k+1)k\,\theta^4 \\
&\quad - 4\,(k\,\theta)\,(k+2)(k+1)k\,\theta^3 \\
&\quad + 6\,(k\,\theta)^2\,(k+1)k\,\theta^2 \\
&\quad - 3\,(k\,\theta)^4.
\end{align*}
Factor out the common factor \(k^2\theta^4\) and simplify them:  
\[
E[\beta_t^4] = \left(3+\frac{6}{k}\right)k^2\theta^4,
\]
Since
\[
\operatorname{Var}(X_t) = k\theta^2,
\]
we have
\[
\operatorname{Var}(X_t)^2 = k^2\theta^4.
\]
Therefore, we conclude the verification of \eqref{estimation2}.

