    \section{Proofs of theorems}
\label{section: proofs}

\subsection{Proof of Theorem \ref{theorem:quantitativeLogan}} We have 
$$ {||\widehat{g}||}_{L^1({\mathbb Z}_N)} = {||\widehat{f}-\widehat{h}||}_{L^1({\mathbb Z}_N)}$$
$$ = {||\widehat{f} - \widehat{h}||}_{L^1(S)} + {||\widehat{h} - \widehat{f}||}_{L^1(S^c)} \ge {|| \widehat{f} ||}_{L^1(S)} - {|| \widehat{h} ||}_{L^1(S)} + {|| \widehat{h} ||}_{L^1(S^c)}-{|| \widehat{f} ||}_{L^1(S^c)}. $$

Since $\widehat{f}$ is $\epsilon$-concentrated on $S$, the right hand side is bounded from below by 

$${|| \widehat{f} ||}_{L^1(S)}- \frac{\epsilon}{N} {|| \widehat{f} ||}_{L^1({\mathbb Z}_N)} + \left( || \widehat{h} ||_{L^1(S^c)} - || \widehat{h}||_{L^1(S)} \right)$$
\begin{equation} \label{equation:almost} \ge \left( 1 - 2 \frac{\epsilon}{N} \right) || \widehat{f} ||_{L^1({\mathbb Z}_N)} + \left(|| \widehat{h} ||_{L^1(S^c)} - || \widehat{h} ||_{L^1(S)}\right).\end{equation} 

We now observe that 
$$ | \widehat{h}(m)| = \left| N^{-\frac{1}{2}} \sum_{x \in M} \chi(-x \cdot m) {h}(x) \right|\leq N^{-1} |M| \cdot {|| \widehat{h} ||}_{L^1({\mathbb Z}_N)}.$$

It follows that 
$$ {|| \widehat{h} ||}_{L^1(S)} \leq \delta \cdot {|| \widehat{h}||}_{L^1({\mathbb Z}_N)},$$ 

hence

$${|| \widehat{h} ||}_{L^1(S^c)}-{|| \widehat{h} ||}_{L^1(S)}={|| \widehat{h} ||}_{L^1({\mathbb Z}_N)} - 2{|| \widehat{h} ||}_{L^1(E)}$$
$$ \ge (1-2 \delta) {|| \widehat{h} ||}_{L^1({\mathbb Z}_N)}.$$

Plugging this back into (\ref{equation:almost}), we see that 

$${|| \widehat{g}||}_{L^1({\mathbb Z}_N)} \ge {|| \widehat{f} ||}_{L^1({\mathbb Z}_N)}+(1-2 \delta) {|| \widehat{h} ||}_{L^1({\mathbb Z}_N)}-2 \frac{\epsilon}{N} {|| \widehat{f} ||}_{L^1({\mathbb Z}_N)}.$$

To avoid contradiction the fact that $g$ is the $L^1$ minimizer, we must have 

$$(1-2 \delta) {|| \widehat{h} ||}_{L^1({\mathbb Z}_N)} - 2 \frac{\epsilon}{N} {||\widehat{f}||}_{L^1({\mathbb Z}_N)} \leq 0,$$

so 

$${||\widehat{h}||}_{L^1({\mathbb Z}_N)} \leq \frac{2 \epsilon}{1 - 2 \delta} \cdot \frac{1}{N} {|| \widehat{f} ||}_{L^1({\mathbb Z}_N)}.$$ 

To obtain equation (\ref{equation:minerrorboundreversed_space}) we note that for any function $\alpha:\mathbb{Z}_N \to \mathbb{C}$ we know that for $x \in {\mathbb Z}_N,$

$$\alpha(x) = N^{-\frac{1}{2}} \sum_{m \in \mathbb{Z}_N^d } \chi(xm) \widehat{\alpha} (m).$$

So,

$$|\alpha(x)| \leq N^{-\frac{1}{2}}  \| \widehat{\alpha} \|_{L^1({\mathbb Z}_N)} \Rightarrow \| \alpha \|_{L^1({\mathbb Z}_N)} \leq |supp(\alpha)| \cdot  N^{-\frac{1}{2}} \| \widehat{\alpha} \|_{L^1({\mathbb Z}_N)}.$$

Similarly, 

$$\|\widehat{\alpha}\|_{L^1({\mathbb Z}_N)} \leq |supp(\widehat{\alpha})| \cdot  N^{-\frac{1}{2}}  \| \alpha \|_{L^1({\mathbb Z}_N)}.$$

So, we get

$$\frac{N^{\frac{1}{2}}}{|M|} \|h\|_{L^1({\mathbb Z}_N)} \leq \frac{2 \varepsilon}{1 - 2\delta} \frac{N^{\frac{1}{2}}}{N} \|f\|_{L^1({\mathbb Z}_N)}
\Rightarrow \frac{1}{|M|} \|h\|_{L^1({\mathbb Z}_N)} \leq \frac{2 \varepsilon}{1 - 2\delta} \cdot \frac{1}{N} \|f\|_{L^1({\mathbb Z}_N)}.$$

\subsection{Proof of Theorem \ref{theorem:looseLogan}}
Just as in the proof of theorem \ref{theorem:quantitativeLogan}, we have equation (\ref{equation:almost}).  Now, know that for $m \in \mathbb{Z}_N$,
%
$$\widehat{h}(m) = N^{-\frac{1}{2}} \sum_{x \in M} \chi(x \cdot m) h(x) + N^{-\frac{1}{2}} \sum_{x \notin M} \chi(x \cdot m) h(x)$$
%
and so
%
\begin{align*}
| \widehat{h} (m) |
& \leq \frac{|M|}{N} \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} + \frac{1}{N^{\frac{1}{2}}} \| h \|_{L^1(M^c)} \\
& \leq \frac{|M|}{N} \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} + \frac{\alpha}{N^{\frac{1}{2}}} \| f \|_{L^1(M^c)} \\
& \leq \frac{|M|}{N} \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} + \frac{\alpha |M^c|}{N} \| \widehat{f} \|_{L^1(\mathbb{Z}_N)}.
\end{align*}
%
Thus,
%
$$ \| \widehat{h} \|_{L^1(S)} \leq \delta \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} + \alpha \delta' \| \widehat{f} \|_{L^1(\mathbb{Z}_N)}.$$

Plugging this back into equation (\ref{equation:almost}) gets

$$\| \widehat{g} \|_{L^1(\mathbb{Z}_N)} \geq \| \widehat{f} \|_{L^1(\mathbb{Z}_N)} + \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} (1 - 2 \delta) + \| \widehat{f} \|_{L^1(\mathbb{Z}_N)} \left( -2 \alpha \delta ' - 2 \frac{\varepsilon}{N} \right).$$

Again, to avoid a contradiction, we need

$$\| \widehat{f} \|_{L^1(\mathbb{Z}_N)} + \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} (1 - 2 \delta) + \| \widehat{f} \|_{L^1(\mathbb{Z}_N)} \left( -2 \alpha \delta ' - 2 \frac{\varepsilon}{N} \right) \leq \| \widehat{f} \|_{L^1(\mathbb{Z}_N)}$$ 
$$\Leftrightarrow \| \widehat{h} \|_{L^1(\mathbb{Z}_N)} \leq \frac{2\frac{\varepsilon}{N} + 2 \alpha \delta'}{1 - 2 \delta} \| \widehat{f} \|_{L^1(\mathbb{Z}_N)} = \frac{1}{N}\frac{2 \varepsilon + 2 N \alpha \delta'}{1 - 2 \delta} \| \widehat{f} \|_{L^1(\mathbb{Z}_N)}.$$

Again, as in the proof of theorem \ref{theorem:quantitativeLogan}, we get

$$\frac{1}{|M|} \| h \|_{L^1(\mathbb{Z}_N)} \leq \frac{2 \varepsilon + 2 N \alpha \delta'}{1 - 2\delta} \cdot \frac{1}{N} \| f \|_{L^1(\mathbb{Z}_N)}.$$

\subsection{Proof of Theorem \ref{theorem:quantitativerandomLogan}} As usual, let $g$ denote the quantity in \ref{equation:simpleL1recoveryreversed}. Let $f=g+h$. We have 
$$ {||\widehat{g}||}_1 = {||\widehat{f}-\widehat{h}||}_1$$
$$={||\widehat{f}-\widehat{h}||}_{L^1(S)}+{||\widehat{f}-\widehat{h}||}_{L^1(S^c)}$$
$$ \ge \left( {||\widehat{f}||}_{L^1(S)}-{||\widehat{f}||}_{L^1(S^c)} \right) + \left( {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \right)$$
$$ \ge {||\widehat{f}||}_1 \cdot \left(1-\frac{2\epsilon}{N} \right) + \left( {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \right),$$ where we have used the concentration assumption in the last line. 

There are two possibilities. If 
$$ -\frac{2\epsilon}{N} {||\widehat{f}||}_1  + \left( {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \right)>0,$$ we contradict the fact that $\widehat{g}$ is the $L^1$ minimizer, which forces $h$ to be identically $0$. Otherwise, we must have 
\begin{equation} \label{eq: dnieper}  {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \leq \frac{2\epsilon}{N} {||\widehat{f}||}_1. \end{equation} 

To exploit this, observe that 
$$ {||\widehat{h}||}_{L^1(S)} \leq {|S|}^{\frac{1}{2}} \cdot {||\widehat{h}||}_{L^2(S)} \leq {|S|}^{\frac{1}{2}} \cdot {||\widehat{h}||}_2 $$
$$ = {|S|}^{\frac{1}{2}} \cdot N^{\frac{1}{2}} \cdot {||\widehat{h}||}_{L^2(\mu)}$$
$$ \leq {|S|}^{\frac{1}{2}} \cdot N^{-\frac{1}{2}} \cdot C_T \sqrt{\log(N) \log \log(N)} \cdot {||\widehat{h}||}_1,$$
where in the last line we applied Talagrand's bound (Theorem \ref{thm: combo} above). Plugging this back into (\ref{eq: dnieper}), we obtain 
$$ {||\widehat{h}||}_1 (1-2{|S|}^{\frac{1}{2}} \cdot N^{-\frac{1}{2}} \cdot C_T \sqrt{\log(N) \log \log(N)}) \leq \frac{2 \epsilon}{N} {||\widehat{f}||}_1$$ with probability $1-o_N(1)$. 

Using the assumption regarding $|S|$, this implies that 

$$ {||\widehat{h}||}_1 \leq \frac{4 \epsilon}{N} {||\widehat{f}||}_1, $$ 

which is (\ref{equation:minerrorboundrandomreversed}), once again, with probability $1-o_N(1)$.  To prove (\ref{equation:minerrorboundreversed_space2}), we again proceed as we did in the proofs of theorems \ref{theorem:quantitativeLogan} and \ref{theorem:looseLogan} and get

$$\frac{1}{|M|} \| h \|_{L^1(\mathbb{Z}_N)} \leq 4\epsilon \cdot \frac{1}{N} \| f \|_{L^1(\mathbb{Z}_N)}.$$

This completes the proof of Theorem \ref{theorem:quantitativerandomLogan}. 

\vskip.25in 

\subsection{Proof of Theorem \ref{theorem:quantitativerandomnoisyLogan}} 

\vskip.125in 

Let $f=g+h$. We have 
$$ {||\widehat{g}||}_1 = {||\widehat{f}-\widehat{h}||}_1$$
$$={||\widehat{f}-\widehat{h}||}_{L^1(S)}+{||\widehat{f}-\widehat{h}||}_{L^1(S^c)}$$
$$ \ge \left( {||\widehat{f}||}_{L^1(S)}-{||\widehat{f}||}_{L^1(S^c)} \right) + \left( {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \right)$$
$$ \ge {||\widehat{f}||}_1 \cdot \left(1-\frac{2\epsilon}{N} \right) + \left( {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \right),$$ where we have used the concentration assumption in the last line. 

There are two possibilities. If 
$$ -\frac{2\epsilon}{N} {||\widehat{f}||}_1  + \left( {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \right)>0,$$ we contradict the fact that $\widehat{g}$ is the $L^1$ minimizer, which forces $h$ to be identically $0$. Otherwise, we must have 
\begin{equation} \label{eq: dniepernoisy} {||\widehat{h}||}_{L^1(S^c)} -{||\widehat{h}||}_{L^1(S)} \leq \frac{2\epsilon}{N} {||\widehat{f}||}_1. \end{equation} 

To exploit this, we write 
$$ h(x)=1_Mh(x)+1_{M^c}h(x). $$

This is necessary because $h$ is not supported in $M$ as it was in the previous theorem. We have 
$$ {||\widehat{1_Mh}||}_{L^1(S)} \leq {|S|}^{\frac{1}{2}} \cdot {||\widehat{1_Mh}||}_{L^2(S)} \leq {|S|}^{\frac{1}{2}} \cdot {||\widehat{1_Mh}||}_2 $$
$$ = {|S|}^{\frac{1}{2}} \cdot N^{\frac{1}{2}} \cdot {||\widehat{h}||}_{L^2(\mu)}$$
$$ \leq {|S|}^{\frac{1}{2}} \cdot N^{-\frac{1}{2}} \cdot C_T \sqrt{\log(N) \log \log(N)} \cdot {||\widehat{1_Mh}||}_1$$ 
$$ \leq {|S|}^{\frac{1}{2}} \cdot N^{-\frac{1}{2}} \cdot C_T \sqrt{\log(N) \log \log(N)} \cdot {||\widehat{h}||}_1.$$
where in the second to last line we applied Talagrand's bound (Theorem \ref{thm: combo} above). 

We now deal with ${||\widehat{1_{M^c}h}||}_{L^1(S)}$. This quantity is bounded by 
$$ |S| \cdot {||\widehat{1_{M^c}h}||}_{\infty} \leq |S| \cdot N^{-\frac{1}{2}} \cdot {||1_{M^c}h||}_1.$$ 

By assumption, this quantity is bounded by 
$$ |S| \cdot N^{-\frac{1}{2}} \cdot \delta \cdot N^{-1} {||f||}_{L^1(M^c)} \leq |S| \cdot N^{-\frac{1}{2}} \cdot \delta \cdot {||f||}_{L^1(\mu)}.$$

It follows that the left-hand side of (\ref{eq: dniepernoisy}) is bounded from below by 
$$ {||\widehat{h}||}_1 \cdot \left(1-2{|S|}^{\frac{1}{2}} \cdot N^{-\frac{1}{2}} \cdot C_T \sqrt{\log(N) \log \log(N)}\right)-|S| \cdot N^{-\frac{1}{2}} \cdot \delta \cdot {||f||}_{L^1(\mu)}$$
$$ \ge \frac{1}{2} {||\widehat{h}||}_1 - |S| \cdot N^{-\frac{1}{2}} \cdot \delta \cdot {||f||}_{L^1(\mu)}$$
in view of (\ref{eq:sizespectralnoisy}). 

Plugging everything back into (\ref{eq: dniepernoisy}), we see that 
\begin{equation} \label{eq: almostnitsahon} {||\widehat{h}||}_1 \leq \frac{4 \epsilon}{N} {||\widehat{f}||}_1+ 2|S| \cdot N^{-\frac{1}{2}} \cdot \delta \cdot {||f||}_{L^1(\mu)}. \end{equation} 

\vskip.125in 

To prove (\ref{equation:minerrorboundreversednoisy_space}), we write 
$$ \frac{1}{M} \sum_{x \in M} |h(x)| \leq N^{-\frac{1}{2}} {||\widehat{h}||}_1.$$

Applying (\ref{eq: almostnitsahon}), we see that this quantity is bounded by 
$$ N^{-\frac{1}{2}} \cdot \frac{4 \epsilon}{N} \cdot {||\widehat{f}||}_1 + 2|S| \cdot N^{-1} \cdot \delta \cdot {||f||}_{L^1(\mu)} \leq \left(4 \epsilon+2|S|N^{-1} \delta \right) \cdot \frac{1}{N} \sum_{x \in {\mathbb Z}_N} |f(x)|$$ 
$$ \leq (4 \epsilon+2 \delta) \cdot \frac{1}{N} \sum_x |f(x)|,$$ as claimed. This completes the proof of Theorem \ref{theorem:quantitativerandomnoisyLogan}. 

\subsection{Proof of Theorem \ref{theorem:hoeffding_M_vs_Z_N}}

We shall need the following concentration bound, known as Hoeffding's Inequality. 

\begin{theorem}[Hoeffding \cite{Hoeffding63}] \label{thm:hoeffding_finite_population} Let $X = \{x_1, ..., x_N\}$ be a finite population of real numbers and, for some $0 \leq n \leq N$, let $M \subset X$ be a random subset of $n$ elements where the elements are chosen without replacement and $S = n^{-1}\sum_{y \in M} y$. Then, for all $t > 0$

\[
\mathbb{P} \left( S - \mu \geq t \right) \leq \exp \left( -\frac{2nt^2}{(b - a)^2} \right).
\]
Furthermore,
\[
\mathbb{P} \left( |S - \mu| \geq t \right) \leq 2\exp \left( -\frac{2nt^2}{(b - a)^2} \right).
\]

Here, $\mu = n^{-1} \sum_{x \in X} x$, $b = \max X$ and $a = \min X$.

\end{theorem}

We can use theorem \ref{thm:hoeffding_finite_population} below. Let $A \sim Bin(N, p)$.

\begin{align*}
& Pr\left( \left| \frac{1}{|M|} \sum_{x \in M} |f(x)| - \frac{1}{N} \sum_{x \in \mathbb{Z}_N} |f(x)| \right| \geq t\right) \\
& = \sum_{k = 0}^{N} Pr \left( |M| = k\right) \cdot  Pr\left( \left| \frac{1}{|M|} \sum_{x \in M} |f(x)| - \frac{1}{N} \sum_{x \in \mathbb{Z}_N} |f(x)| \right| \geq t : |M| = k\right) \\
& = \sum_{k = 0}^{N} {N \choose k} p^k (1 - p)^{N - k} \cdot  Pr\left( \left| \frac{1}{|M|} \sum_{x \in M} |f(x)| - \frac{1}{N} \sum_{x \in \mathbb{Z}} |f(x)| \right| \geq t : |M| = k\right) \\
& \leq \sum_{k = 0}^{N} {N \choose k} p^k (1 - p)^{N - k} \cdot 2\exp \left( -\frac{2kt^2}{\|f \|_{\infty}^2} \right) \\
& = 2 \mathbb{E}\left[\exp \left( -\frac{2 A t^2}{\|f \|_{\infty}^2} \right)\right]
\end{align*}

where we used Hoeffding's inequality to obtain the fourth line. The expectation above is just the moment generating function for the binomial distribution with parameter $-\frac{2 t^2}{\|f \|_{\infty}^2}$ which is

$$\left(1 - p + p\exp\left({-\frac{2 t^2}{\|f \|_{\infty}^2}}\right)\right)^N.$$

