\begin{algorithm}[!h]
	\caption{\bf Growing a Single P-Tree}\label{alg:GT}
	\bigskip
    \small
	\begin{algorithmic}[1]
		\Procedure{GrowTree}{{\tt root}} \\
        \textbf{Input} Asset returns $\rr_{i,t}$ and ranked characteristics $\z_{i,t}$ \\
		\textbf{outcome} Grow P-Tree from the {\tt root} node, form leaf basis portfolios
		\For{$j$ from $1$ to $J$} \Comment{Loop over number of iterations}
		\If{current depth $\geq$ $d_\text{max}$} 
		\State \textbf{return}.
		\Else
		\State Search the tree, find all leaf nodes $\mathcal{N}$
		\For{each leaf node $N$ in $\mathcal{N}$} \Comment{Loop over all current leaf nodes}
		\For{each candidate split $\tilde{\cc}_{k,m,N}$ in $\mathcal{C}_N$}
		\State Partition data temporally in $N$ according to $\tilde{\cc}_{k,m,N}$.
		\If{Either left or right child of $N$ does not satisfy minimal leaf size}
		\State $\mathcal{L}(\tilde{\cc}_{k,m,N}) = - \infty$.
		\Else
		\State Calculate leaf basis portfolios. 
		\State Estimate tangency portfolio using \textit{all} leaf basis portfolios as in (\ref{eqn:SDF}).
		\State Calculate the split criteria $\mathcal{L}(\tilde{\cc}_{k,m,N})$ in (\ref{eqn:criteria}).
		\EndIf
		\EndFor
		\EndFor
		\State Find the best leaf node and split rule that maximize split criteria $$\tilde{\cc}_{j} = \argmax_{N \in \mathcal{N}, \tilde{\cc}_{k,m,N} \in \mathcal{C}_N}\{\mathcal{L}(\tilde{\cc}_{k,m,N})\}$$
		\State Split the node selected with the $j$-th split rule of the tree $\tilde{\cc}_{j}$. 
		\EndIf
		\EndFor
		\State \textbf{return} $\left\{\RR_{t}^{(J)}, f_t^{(J)} \right\}$ 
		\EndProcedure
	\end{algorithmic}
\end{algorithm}



