\section{\label{sec:Isotropic}Isotropic Field-Particle Model}

In this Appendix, we present a simple model that shows that the guiding-center collisional fluid flow \eqref{eq:coll_gcflow} is diffusive in character\cite{Hazeltine_Meiss}. For this purpose, we introduce the isotropic field-particle Maxwellian model \cite{Brizard_2004}, and we replace the coordinates $(p_{\|},\mu)$ with $(p,\theta \equiv \cos^{-1}p_{\|}/p)$, with Jacobian $p^{2}\sin\theta$, so that the test-particle Fokker-Planck coefficients become
\begin{eqnarray}
{\bf K}_{\rm gc} &=& -\,\nu(p)\,\left(p_{\|}\,\bhat + m\Omega\,\pd{\vb{\rho}_{0}}{\zeta}\right) \;=\; -\nu(p)\,p \left(\cos\theta\,\bhat \;+\frac{}{} \sin\theta\,\wh{\bot}\right) \;\equiv\; -\,\nu(p)\,p\;\wh{\sf p}, \\
\mathbb{D}_{\rm gc} &=& D_{\bot}(p)\,\mathbb{I} \;+\; \left[D_{\|}(p) \;-\; D_{\bot}(p)\right]\;\wh{\sf p}\wh{\sf p},
\end{eqnarray}
where the coefficients $(\nu,D_{\|},D_{\bot})$ are defined in terms of Rosenbluth potentials \cite{Xu_Rosenbluth_1991,Helander_Sigmar,Hirvijoki_Brizard_Pfefferle:2017}, $\mathbb{I}$ denotes the unit dyadic tensor, and $\wh{\bot} \equiv \partial\wh{\rho}/\partial\zeta$ is an explicit function of the gyroangle $\zeta$. Hence, the guiding-center collisional flux \eqref{eq:Sgc_flux} is expressed as
\begin{eqnarray}
{\bf S}_{\rm gc} &=&  -\,\nu\,p\;\wh{\sf p} \;-\; \left[D_{\bot}\,\mathbb{I} \;+\frac{}{} (D_{\|} \;-\; D_{\bot})\;\wh{\sf p}\wh{\sf p}\right] \bdot \left( \wh{\sf p}\,\pd{\ln F}{p} + \frac{\wh{\sf q}}{p}\;\pd{\ln F}{\theta} + \frac{c\bhat}{qB}\btimes\nabla\ln F\right) \nonumber \\
 &=& -\,\nu\,p\;\wh{\sf p} \;-\; D_{\|}\;\pd{\ln F}{p}\;\wh{\sf p} \;-\; \frac{D_{\bot}}{p}\;\pd{\ln F}{\theta}\;\wh{\sf q} \nonumber \\
  &&-\;  \left[D_{\bot}\,\mathbb{I} \;+\frac{}{} (D_{\|} \;-\; D_{\bot})\;\sin^{2}\theta\;\wh{\sf \bot}\wh{\sf \bot}\right] \bdot\frac{c\bhat}{qB}\btimes\nabla\ln F,
\end{eqnarray}
where $\wh{\sf q} \equiv \partial\wh{\sf p}/\partial\theta = -\,\sin\theta\;\bhat + \cos\theta\;\wh{\bot}$ and we omit displaying the guiding-center ordering parameter $\epsilon$. Using the rotating basis $(\bhat,\wh{\bot}, \wh{\rho} \equiv \bhat\btimes\wh{\bot})$, we also find the spatial guiding-center collisional flux
\begin{eqnarray}
\frac{c\bhat}{qB}\btimes{\bf S}_{\rm gc} &=& -\,\frac{c}{qB}\;\left[\left(\nu\,p\;+\; D_{\|}\,\pd{\ln F}{p}\right)\;\sin\theta \;+\; \frac{D_{\bot}}{p}\;\cos\theta\;\pd{\ln F}{\theta}\right]\wh{\rho} \nonumber \\
 &&-\; D_{\bot}\frac{c\bhat}{qB}\btimes\left(\frac{c\bhat}{qB}\btimes\nabla\ln F\right) + (D_{\|} - D_{\bot})\;\frac{c^{2}\sin^{2}\theta}{q^{2}B^{2}}\;\left(\wh{\rho}\frac{}{}\wh{\rho}\right)\bdot\nabla\ln F.
\end{eqnarray}
The guiding-center Fokker-Planck collision operator \eqref{eq:C_gc_FP} 
\begin{equation}
{\cal C}_{\rm gc}[F] \;=\; -\;\frac{1}{p^{2}}\pd{}{p}\left(p^{2}\;\langle S_{\rm gc}^{p}\rangle\;F \right) \;-\; \frac{1}{\sin\theta}\pd{}{\theta}\left(\sin\theta\;\langle S_{\rm gc}^{\theta}\rangle\;F \right) \;-\; \frac{1}{B}\nabla\bdot\left(B\;\langle S_{\rm gc}^{\bf X}\rangle\;F\right) 
\label{eq:gcFP_dk}
\end{equation}
is now expressed in terms of the gyroangle-averaged components
\begin{eqnarray}
\langle S_{\rm gc}^{p}\rangle &\equiv& \left\langle {\bf S}_{\rm gc}\bdot\wh{\sf p}\right\rangle \;=\; -\,\nu\;p \;-\; D_{\|}\;\pd{\ln F}{p}, \label{eq:Sgc_p} \\
\langle S_{\rm gc}^{\theta}\rangle &\equiv& \left\langle {\bf S}_{\rm gc}\bdot\frac{\wh{\sf q}}{p}\right\rangle \;=\; -\;\frac{D_{\bot}}{p^{2}}\;\pd{\ln F}{\theta}, \label{eq:Sgc_theta} \\
\langle S_{\rm gc}^{\bf X}\rangle &\equiv& \frac{c\bhat}{qB}\btimes\langle{\bf S}_{\rm gc}\rangle \;=\; \frac{1}{(m\Omega)^{2}}\left[ D_{\bot} \;+\; \frac{1}{2} (D_{\|} - D_{\bot})\,\sin^{2}\theta \right]\mathbb{I}_{\bot}\bdot\nabla\ln F, \label{eq:Sgc_X}
\end{eqnarray} 
where we used $\langle\wh{\rho}\wh{\rho}\rangle = \frac{1}{2}\,\mathbb{I}_{\bot} \equiv \frac{1}{2}\,(\mathbb{I} - \bhat\bhat)$. In Eq.~\eqref{eq:gcFP_dk}, the first term describes energy dissipation ($\nu)$ and diffusion $(D_{\|})$, the second term
\[ -\; \frac{1}{\sin\theta}\pd{}{\theta}\left(\sin\theta\;\langle S_{\rm gc}^{\theta}\rangle\;F \right) \;=\; \frac{D_{\bot}}{p^{2}}\;\pd{}{\xi}\left[(1 - \xi^{2})\;\pd{F}{\xi}\right] \]
is the standard pitch-angle scattering operator (with $\xi \equiv \cos\theta$), while the third term describes classical spatial diffusion. We note that the drift-kinetic collisional operator \eqref{eq:gcFP_dk} has been shown\cite{Decker_2010} to describe neoclassical transport behavior such as the bootstrap current. In addition, the metriplectic bracket structure introduced in the present work shows how the spatial collisional flux \eqref{eq:Sgc_X} contributes to the collisional guiding-center fluid flow \eqref{eq:coll_gcflow} and the guiding-center magnetization in Eq.~\eqref{eq:Hgc_col}.



