\section{Characterizing chaos and regularity with $\Delta \mathcal{L}$ [$p$-norm]}

In this appendix, we provide the derivation of the upper bounds for $\Delta \mathcal{L}$ where the  Lagrangian Descriptor is defined with the $p$-norm from functional analysis as shown in Eq. \eqref{eq:LD_p_norm}. To do so, we have followed the same approach as in Section.(\ref{subsec:arclength_proof}), meaning that the conditions that are imposed over Hamiltonian are the same.

Given an initial condition $\boldsymbol{x}_0$, the Lagrangian descriptor for the trajectory generated by it is:

\begin{equation}
    \mathcal{L}(\boldsymbol{x}_0) = \int_{t_0}^{t_0 + \tau} \mathcal{F}(\boldsymbol{x}) \, dt \, ,
\end{equation}
and given a random vector $\boldsymbol{\beta} \in \mathbb{R}^{n}$ such that $\|\boldsymbol{\beta}\| \ll 1$ and defining $\boldsymbol{x}^{\prime}_0 = \boldsymbol{x}_0 + \boldsymbol{\beta}$, the Lagrangian Descriptor for $\boldsymbol{x}^{\prime}_0$ is:

\begin{equation}
    \mathcal{L}(\boldsymbol{x}_0 + \boldsymbol{\beta}) = \int_{t_0}^{t_0 + \tau} \mathcal{F}(\boldsymbol{x^{\prime}}) \, dt \, .
\end{equation}

Then, the difference is given by:

\begin{equation}
    \Delta \mathcal{L} = \left| \mathcal{L}(\boldsymbol{x}_0) -  \mathcal{L}(\boldsymbol{x}_0 + \boldsymbol{\beta}) \right| = \left| \int_{t_0}^{t_0 + \tau} \left( \mathcal{F}(\boldsymbol{x}) - \mathcal{F}(\boldsymbol{x^{\prime}})  \right) \, dt \,  \right| \,.
\end{equation}

As the perturbation in the initial condition $\boldsymbol{x}_0$ is small, a Taylor expansion of the perturbed orbit can be done:

\begin{equation}
    f_i(\boldsymbol{x^{\prime}}) \approx f_i(\boldsymbol{x}) + \nabla_x f_i(\boldsymbol{x}) |_{x} \delta x_i(t) \, .
\end{equation}

so that:

\begin{equation}
    \left| f_i(\boldsymbol{x^{\prime}}) \right| \approx \left| f_i(\boldsymbol{x}) + \nabla_x f_i(\boldsymbol{x}) |_{x} \delta x_i(t) \right|
\end{equation}
and 

\begin{equation}
    \left| f_i(\boldsymbol{x^{\prime}}) \right|^{p} \leq \left| f_i(\boldsymbol{x}) \right|^{p} + \left| \nabla_x f_i(\boldsymbol{x}) |_{x} \delta x_i(t) \right|^{p} \, ,
\end{equation}

which can be then substituted in the definition of $\Delta \mathcal{L}$ to give the following:

\begin{equation}
    \begin{aligned}  
        \Delta \mathcal{L} &\leq \left| \int_{t_0}^{t_0 + \tau} \sum_{i=1}^{n} \left| \nabla_x f_i(\boldsymbol{x}) |_{x} \delta x_i(t) \right|^{p}   \, dt \,  \right| = \left| \sum_{i=1}^{n} \left| \nabla_x f_i(\boldsymbol{x}) |_{x}  \right|^{p} \int_{t_0}^{t_0 + \tau} \left| \delta x_i(t) \right|^{p} \, dt \, \right| \\
        &= \left| \sum_{i=1}^{n} \left| \nabla_x f_i(\boldsymbol{x}) |_{x}  \right|^{p} \int_{t_0}^{t_0 + \tau} \left| \|\boldsymbol{\beta}\| \exp{(\lambda_i (t - t_0))} \right|^{p} \, dt \, \right| \\
        & \leq \mathcal{C} \|\boldsymbol{\beta}\|^{p} \left| \sum_{i=1}^{2N} \int_{t_0}^{t_0 + \tau} \exp{(p \lambda_i (t - t_0))} \, dt \, \right| \, .
    \end{aligned}
\end{equation}

Given that $\lambda_{max}$ is the largest Lyapunov exponent, we find $\Delta \mathcal{L}$ to be bounded by:

\begin{equation}
    \Delta \mathcal{L} \leq \mathcal{C}_{max} |\boldsymbol{\beta}|^{p} \left| \sum_{i=1}^{2N} \int_{t_0}^{t_0 + \tau} \exp{(p \lambda_{max} (t - t_0))} \, dt \, \right|
\end{equation}
where $\mathcal{C}_{max} = \text{max}_{t \in [t_0, t_0 + \tau]} \left[\left| \sum_{i=1}^{2N} \left| \nabla_x f_i(\boldsymbol{x}) |_{x}  \right|^{p} \right|\right]$. This yields $\Delta \mathcal{L} \leq n \mathcal{C}_{max} \|\boldsymbol{\beta}\|^{p} \tau$ for $\lambda_{max} = 0$ and for $\lambda_{max} > 0$ we found that:

\begin{equation}
    \Delta \mathcal{L} \leq n\mathcal{C}_{max} \|\boldsymbol{\beta}\|^{p} \dfrac{\exp{(p\lambda_{max}\tau) - 1}}{\lambda_{max}} \, .
\end{equation}

