\section{Refined stratification} 
\label{sec: stratification}

The proof of \autoref{thm: main} involves decomposing $\M_{\mathsf{\Gamma}}(X, A, \cJ)$ into strata whose codimension in $\cJ$ is controlled by a rather subtle induction with respect to the complexity of $\G$. For the inductive argument it is important to consider only graphs of a particular shape and to augment them with certain additional discrete data corresponding to the stratification of $\M_{\mathsf{\Gamma}}(X, A, \cJ)$. 


\subsection{Augmented graphs}\label{sec: graphs}

We start recalling the standard definition of prestable graphs. 

\begin{definition}\label{def: stable graph}
An $n$-marked genus $g$ \textbf{prestable graph} $\mathsf{\Gamma}$ is a tuple
\[
\mathsf{\Gamma} = (V, H, \bg, v, \iota, \bp) 
\]
where
\begin{enumerate}[(i)]
    \item $V = V(\G)$ is a finite set of vertices, with a function $\bg \colon V \to \N_0$ assigning a genus to each vertex. We will write $g_\alpha$ in place of $\bg(\alpha)$; 
    \item  $H = H(\G)$ is a finite set of half-edges, with a map $v \colon H \to V$ assigning an incident vertex to each half-edge;
    \item  $\iota \colon H \to H$ is an involution  whose fixed points 
    \[
        P = P(\G) = \{ h \in H \ | \ \iota(h) = h\}
    \]
    form the set of markings and pairs 
    \[
        E = E(\G) = \{ \{ h, h' \} \subset H \ | \ h' = \iota(h), \ h\neq h' \}
    \]
    form the set of unoriented edges of $\G$;
    \item  $\bp : \{1, \ldots, n\} \to P$ is a bijection defining the marking. We will write $p_i$ in place of $\bp(i)$. 

\end{enumerate}
We will always assume that $\G$ is connected. The \textbf{genus} of $\G$ is 
\[
    g(\G) = \sum_{\alpha \in V} g_\alpha +h_1(\G).
\]
Finally, $\G$ is said to be \textbf{stable} if for all $\alpha \in V$ it satisfies
\[
    2g_\alpha - 2 + \mathrm{val}(\alpha) > 0,
\]
where the \textbf{valence} of $\alpha$ is defined by $\mathrm{val}(\alpha) = |\{ h \in H : v(h) = \alpha \}|$.

\end{definition}

\begin{example}
    The dual graph of a stable $n$-marked genus $g$ curve $(C,\bp)$ representing a point in the Deligne--Mumford space $\cM_{g,n}$ is a stable $n$-marked genus $g$ graph.    (By a slight abuse of notation, we will use the notation $\bp$ and $p_i$ to denote both the marking of the graph $\G$ and the corresponding marked points on the curve $C$ modelled on $\G$.)
\end{example}


We are interested in the stratification of the moduli space $\M_{\mathsf{\Gamma}}(X, A, \cJ)$ of maps $u \colon C \to X$ modelled on $\G$. Therefore, it will be important to keep track of additional data encoding the stratum containing $u$, such as the degree of each map $u_\alpha$ on its image, the homology class $[u_\alpha]$, as well as certain auxiliary weights $m_\alpha$. To this end, we enrich $\G$ with such additional data.

\begin{definition}\label{def: augmented graphs}
    An $(n+\ell)$-marked genus $g$ \textbf{augmented graph} is a tuple
    $$
    \widetilde{\mathsf{\Gamma}} = (\mathsf{\Gamma}, \underline{\mathsf{m}}, \underline{\mathsf{d}}, \underline{\mathsf{A}}, h, b).
    $$
    where
\begin{enumerate}[(i)]
    \item $\mathsf{\Gamma}$ is an $(n+\ell)$-marked genus $g$ prestable graph with an order on the set of vertices; the smallest vertex will be denoted by $0 \in V(\G)$; 
    \item The $(n+\ell)$-marking consists of an $n$-marking $\bp = (p_1,\ldots,p_n)$ and an $\ell$-marking $\bp' = (p_1', \ldots, p_\ell')$ where $0 \leq \ell \leq n$;
    \item $\underline{\mathsf{m}}$ and $\underline{\mathsf{d}}$ are vectors of weights $m_\alpha \in \N_0$ and degrees $d_\alpha \in \N_0$, indexed by $\alpha \in V(\G)$;
    \item $\underline{\mathsf{A}}$ is a vector of homology classes $A_\alpha \in H_2(X, \mathbb{Z})$ indexed by $\alpha \in V(\G)$ such that either $A_\alpha$ is positive or $A_\alpha = 0$, with the latter if and only if $d_\alpha = 0$ if and only if $ m_\alpha = 0$;
    \item $h$ is a function $h: \{ (\alpha, \alpha') \in V(\mathsf{\Gamma})^{\times 2} \mid \alpha \neq \alpha', \ d_\alpha, d_{\alpha'} > 0 \} \to \{ 0, 1 \}$, which will encode whether two components of the domain are mapped to the same image;
    \item $b$ is a function $b: \{ 1,\ldots , \ell \} \to \{ \alpha \in V(\G) \smallsetminus \{ 0\} \ | \ d_\alpha>0 \}
    $ which, roughly speaking, will encode which component of $C \smallsetminus C_{0}$ carries the marking $p_i'$; see also \autoref{def: condition *} below.
\end{enumerate}
We will call $\G$ the \textbf{underlying graph} of $\cG$ and $(\bm,\bd,\bA,h,b)$ the \textbf{augmentation data} of $\cG$.  The \textbf{homology class} of $\cG$ is 
\[
    [\cG] = \sum_{\alpha\in V} d_\alpha A_\alpha
\]
and the \textbf{weighted homology class} of $\cG$ is
\[
    [\cG,\bm] = \sum_{\alpha\in V} m_\alpha d_\alpha A_\alpha.
\]
\end{definition}

\begin{remark}
    When the number of marked points and the genus are clear from context, we will simply refer to $\cG$ as an augmented graph.
\end{remark}

In addition, the following properties of augmented graphs will be crucial in the proof of \autoref{thm: main}. From a geometric point of view, we are only interested in stable maps in the general fiber of \eqref{eqn: tau map} and the maps obtained by their simplification. This imposes additional constraints on the graph and augmentation data. 

\begin{definition}\label{def: condition *}
    We say that $\cG$ satisfies the \textbf{fixed domain constraint} if:
    \begin{enumerate}[(i)]
        \item The underlying graph $\G$ has the following shape. The smallest vertex $0 \in V(\G)$ has genus $g$ while all other vertices have genus $0$. In particular, $g(\G) = g + h_1(\mathsf{\Gamma})$.  
        \item  The markings $\bp$ and $\bp'$ are constrained as follows. Vertex $0$ carries the last $n - \ell$ markings $p_{\ell+1},\ldots, p_n$ and is connected via a single edge to $\ell$ vertices of $\alpha_1,\ldots,\alpha_\ell$ of genus $0$, each carrying the corresponding marking $p_1, \ldots, p_\ell$ and satisfying $\mathrm{val}(\alpha_i) = 3$.  The remaining markings in $\bp'$ are carried by vertices other than $0$ and $\alpha_1,\ldots,\alpha_\ell$; 
        \item Every loop of vertices in $\G$ contains a vertex $\alpha$ with $d_\alpha > 0$;
        \item For every $\alpha \in V(\G) \setminus \{0\}$ with $d_{\alpha} > 0$, we have $m_{\alpha} \geq | b^{-1}(\alpha)|$;
        \item For each $\alpha \in V(\G)$, denote by $V_\alpha \subset V(\G)$ the set consisting of $\alpha$ and all degree zero vertices connected to $\alpha$ through degree zero vertices. We require that if $p_i'$ belongs to $\alpha$, then $\alpha \in V_{b(i)}$;
        \item The number of edges connecting each connected component of $\G \smallsetminus \{ 0 \}$ to $0$ is equal to the number of markings in $\bp'$ on that component. In particular, $|E(\G)| \geq \ell$. 
    \end{enumerate}
\end{definition}

With two notable exceptions that will be explained later, all augmented graphs appearing in this paper will satisfy the fixed domain constraint. 


\subsection{Stable maps modelled on augmented graphs}

Recall that an \textbf{$n$-marked stable map} consists of a nodal curve $C$, an ordered set $\bp$ of $n$ distinct points in the smooth locus of $C$, and a pseudo-holomorphic map $u \colon C \to X$ such that the automorphism group of the triple $(C,\bp, u)$ is finite. 

\begin{definition}\label{def: stabilization morphism}
    The stabilized domain curve associated to the triple $(C, \bp, u)$ is the $n$-marked stable curve $(\bar C, \bar \bp)$, constructed as follows. The curve $\bar C$ is obtained by contracting each genus-zero component of $C$ that carries fewer than three special points (i.e., nodes or markings). If such a contracted component contains a marking $p_i$, the point to which it is contracted becomes the new marking $\bar p_i$. If $p_i$ lies on a component that is not contracted, then $\bar p_i = p_i$. For the definition of stabilization in families, see \cite[Chapter 10, Section 8]{ACGH}.
\end{definition}


The map
\[
\tau_{\G}:\M_{\mathsf{\Gamma}}(X,A,\cJ) \to X^n \times \cM_{g,n} \times \cJ;
\]
in \eqref{eqn: map tau} sends a point $[u,C,\bp, J]$ to $( \mathrm{ev}(u,\bp), [\bar C, \bar \bp], J)$ where $\ev$ denotes the evaluation map.

\begin{notation}
    Let $A \in H_2(X,\Z)$ be a positive class.
    Let $\G$ be an $n$-pointed genus $g$ graph. We denote by
    \[
    \mathcal{M}_\mathsf{\Gamma}(X, A, \cJ)
    \]
    the universal moduli space of marked stable maps modelled on $\G$, that is the space parametrizing isomorphism classes of data $(C,\bp, u,J)$ where
    \begin{enumerate}[(i)]
        \item $J \in \cJ$, 
        \item $C$ is a nodal curve and $\bp = (p_1,\ldots, p_n)$ is an ordered set of smooth points in $C$ such that the marked nodal curve $(C,\bp)$ is modelled on $\G$; that is:  $\G$ is the dual graph of $(C,\bp)$.
        \item $u \colon (C,\bp) \to X$ is a $J$-holomorphic stable map such that $[u] \coloneq u_*[C] = A$. 
    \end{enumerate}
    For every vertex $\alpha$ of $\G$ denote by $C_\alpha$ the corresponding irreducible component of $C$ and by $u_\alpha = u|_{C_\alpha}$ the restriction of $u$ to $C_\alpha$. 
\end{notation}

\begin{example}
    If $\G = T_{g,n}$ consists of a single vertex of genus $g$ with $n$ markings, then
    \[
        \mathcal{M}_\mathsf{\Gamma}(X, A, \cJ) = \mathcal{M}_{g,n}(X, A, \cJ)
    \]
    is the universal moduli space of pseudo-holomorphic maps to $X$ from genus $g$ smooth curves with $n$ marked points in class $A$. The corresponding Gromov--Kontsevich universal moduli space of stable maps is
    \[
        \overline\M_{g,n}(X, A, \cJ) = \bigcup_\G \mathcal{M}_\G (X, A, \cJ)
    \]
    where the union is taken over all $n$-marked genus $g$ graphs $\G$.
\end{example}

Let us define the map $\tau_\G$ mentioned in \eqref{eqn: map tau}.





The next is a higher genus generalization of \cite[Definition~6.1.1]{mcduff}, and will be a central notion in what follows.

\begin{definition}
    \label{def: simple}
    A stable map $(C,\bp, u)$ is called \textbf{simple} if it satisfies the following conditions:
    \begin{enumerate}[(i)]
        \item for every connected (possibly reducible) subcurve $C' \subset C$ of positive arithmetic genus, the restriction $u|_{C'}$ is nonconstant;
        \item each nonconstant component $u_\alpha$ is not multiply covered;
        \item if $u_\alpha$ is nonconstant and $\alpha \neq \beta$, then $\im(u_\alpha) \neq \im(u_\beta)$. 
    \end{enumerate}
    We denote by 
    $$
    \M_\mathsf{\Gamma}^*(X,A,\cJ) \subset \M_\mathsf{\Gamma}(X,A,\mathcal{J})
    $$ 
    the subset of simple maps.
\end{definition}



\begin{notation}
Recall that an ordered multiset of $n$ elements of a set $S$ is a sequence $(a_1,\ldots, a_n)$ where $a_i \in S$ and repetitions are allowed.  In this paper, we will use both ordered sets and ordered multisets of marked points, and the distinction will be important. 
\end{notation}

We will use the following generalization of this notion introduced in \cite[Section 6.1]{mcduff}. 

\begin{definition}
    \label{def: weighted prestable map}
    A \textbf{weighted $n$-marked prestable map} $(C, \bp, u, \bm)$ consists of
    \begin{enumerate}[(i)]
        \item a curve $C$ (not necessarily nodal),
        \item an ordered multiset of $n$ points in $C$ (not necessarily contained in the smooth locus),
        \item a vector $\bm$ of weights $m_\alpha \in \N_0$ indexed by the irreducible components $C_\alpha$ of $C$,
        \item a pseudo-holomorphic map $u \colon C \to X$,
    \end{enumerate}
    with the property that $(C,\bp,u)$ is obtained from an $n$-marked stable map $(\tilde C, \tilde\bp, \tilde u)$ by identifying, finitely many times, some number of $\P^1$ components which have the same image under $\tilde u$. Each such collection is identified to a single point in the resulting curve.

    A weighted $n$-marked prestable map $(C,\bp,u,\bm)$ is said to be \textbf{stable} if the underlying $n$-marked map $(C,\bp,u)$ is stable. Similarly, $(C, \bp, u, \bm)$ is called \textbf{simple} if $(C, u)$ is simple.

    Associated with such a map is the usual homology class
    \[
        [u] = \sum_\alpha [u_\alpha]
    \]
    where $u_\alpha = u|_{C_\alpha}$, as well as the \textbf{weighted homology class} is defined by
    \[
        [u,\bm] =  \sum_\alpha m_\alpha [u_\alpha].
    \]
\end{definition}


\begin{notation}
    When the number of marked points is clear from context, we will simply refer to $(C,\bp,u,\bm)$ as a weighted prestable (or stable) map. 
\end{notation}

\begin{remark}
    It follows from the definition that the underlying curve $C$ of a weighted prestable map has ordinary singularities. In particular, as a topological space, $C$ is the quotient of a smooth curve, its normalization, by an equivalence relation that identifies finitely many finite sets of points, each to a single point.
\end{remark}

\begin{definition}  
    \label{def: augmented maps}
    Let $\cG$ be an augmented graph as in \autoref{def: augmented graphs}. 
    A weighted $(n+\ell)$-marked stable map $(C,\bp\cup\bp', u,\bm)$ is \textbf{modelled on $\cG$} if 
    \begin{enumerate}[(i)]
        \item $\G$ is the dual graph of $(C,\bp \cup \bp')$; the component $C_0$ corresponding to the smallest vertex $0 \in V(\G)$ will be called the \textbf{main component}; 
        \item $\bm$ agrees with the vector of weights of $\cG$;
        \item $u_\alpha$ is constant if and only if $d_\alpha = 0$ if and only if $m_\alpha=0$, and otherwise $u_\alpha$ is a $d_\alpha$-fold cover of a simple map representing homology class $A_\alpha$; in particular:  $[u_\alpha] = d_\alpha A_\alpha$;
        \item $\im(u_\alpha) = \im(u_\beta)$ if and only if $h(\alpha,\beta) = 1$.
    \end{enumerate}
    Denote by 
    \[
        \M_{\cG}(X,\cJ)
    \]
    the universal moduli space of weighted $(n+\ell)$-marked stable maps modelled on $\cG$.
    % \begin{equation}\label{eqn: alternative map to Mgn}
    % \beta: \M_{\widetilde{\mathsf{\Gamma}}}( X, \mathcal{J})  \to \mathcal{M}_{g,n}
    % \end{equation}  
    % the map that records the smooth genus $g$ curve corresponding to the vertex $0$ along with all the markings $\bp$. \AD{Do we ever use this map?}
\end{definition}

\begin{remark}
    The order on the vertices of $\G$ as well as the function $b$ do not play any role in the definition of $\M_{\widetilde{\mathsf{\Gamma}}}( X, \mathcal{J})$, but they will play a role in our induction later.
\end{remark}


\begin{remark}
    The forgetful map
    \[
        \bigsqcup_{\cG} \M_{\cG}(X,\cJ) \to \M_{\G}(X,A,\cJ)
    \]
    where the disjoint union is taken over all augmented graphs $\cG$ with underlying graph $\G$ and homology class $[\cG] = A$ is a continuous surjection with finite fibers. (It is not, in general, a local homeomorphism as the components corresponding to different choices of discrete data $h$ in \autoref{def: augmented graphs} may interact in $\M_{\G}(X,A,\cJ)$.)
\end{remark}



