%\tau_{\cG}((C,u,\underline{\mathsf{m}}))= \tau_{\cG'}%((C',u',\underline{\mathsf{m}}')).
%$$

% We will only apply this process to types $\cG$ as in definition \autoref{def: augmented graphs} that satisfy $(*)$, or to types $\cG$ obtained through a sequence of partial simplifications starting from one of this form. In particular, the graph $\G$ will always have a distinguished vertex $0$.

\begin{definition}\label{def: simplification process}
    A \textbf{partial simplification} of a weighted stable map $(C,\bp\cup\bp',u,\bm)$ is the weighted stable map $(C^s,\bp^s\cup (\bp')^s,u^s,\bm^s)$  obtained by one of the following procedures.

\begin{enumerate}[(a)]
     \item (\textbf{Connected cover}). In this construction, we replace a component $u_\alpha$ with $d_\alpha > 1$ by the underlying simple map. To be more precise, $u_\alpha$ factors as
         $$
         u_\alpha: C_\alpha \xrightarrow{\phi} C_\alpha^s \xrightarrow{u_\alpha^s} X
         $$
     where 
     \begin{enumerate}[(i)]
        \item $C_\alpha^s$ is a smooth complex curve of genus $g_\alpha^s \leq g_\alpha$, 
        \item $\phi$ has degree $d_\alpha$, 
        \item $u_\alpha^s$ is simple.
    \end{enumerate}
    Let $\{ C_i^\circ \}$ be the connected components of $C \smallsetminus C_\alpha$ and $C_i$ their closure in $C$. Let $q_{i,1},\ldots, q_{i,k_i} \in C_\alpha$ be the points of intersection $C_i \cap C_\alpha$. Set
    \begin{align*}
        I &= \{ i \in \{\ell+1,\ldots,n\} \ | \ p_i \in C_\alpha \}, \\
        I' &= \{ i \in \{1,\ldots,\ell\} \ | \ p_i' \in C_\alpha \}.
    \end{align*}
    (Note that if $\cG$ satisfies the fixed domain constraint, then $I=\emptyset$ if $\alpha \neq 0$ and $I'=0$ if $\alpha=0$.) Define a weighted prestable map $(C^{\mathrm{pre}}, \bp^{\mathrm{pre}}\cup(\bp^{\mathrm{pre}})', u^{\mathrm{pre}}, \bm^{\mathrm{pre}})$  as follows:
    \begin{enumerate}[(i)]
        \item  $C^\mathrm{pre}$ is the curve obtained from $C$ by removing $C_\alpha$ and attaching $C_i$  to a new component $C_\alpha^s$ using the identification $q_{i,j} \sim \phi(q_{i,j})$;
        \item  $\bp^{\mathrm{pre}}$ and $(\bp^{\mathrm{pre}})'$ are ordered multisets of points in $C^{\mathrm{pre}}$ obtained from $\bp$ and $\bp'$ by replacing $\{ p_i \}_{i\in I}$ and $\{ p_i'\}_{i\in I'}$ by their images in $C_\alpha^s$ under $\phi$;
        \item $u^{\mathrm{pre}} \colon C^{\mathrm{pre}} \to X$ is obtained from $u$ by replacing $u_\alpha$ by $u_\alpha^s$ on the component $C_\alpha^s$; we equip it with degree $d_\alpha^s=1$ and weight $m_\alpha^s = d_\alpha m_\alpha$. 
    \end{enumerate}
    We then define $(C^s,\bp^s\cup (\bp')^s,u^s,\bm^s)$ as the result of the repeated stabilization process described in \autoref{def: stabilization process} and \autoref{rem: stabilization process}. The resulting weighted stable map is modelled on an augmented graph $\cG^s$ where the component $C_\alpha^s$ has genus $g_\alpha^s$ and the data $h^s$ and $b^s$ of $\cG'$ agree with the corresponding data $h$ and $b$ of $\cG$.

     \item  (\textbf{Disconnected cover.}) In this construction, we identify two simple components $u_\alpha$ and $u_\beta$ with the same image. To be precise, suppose that $h(\alpha, \beta) = 1$ and $d_\alpha = d_\beta = 1$. Since $\im(u_\alpha) = \im(u_\beta)$, there exists an isomorphism $\phi: C_\alpha \to C_{\beta}$ such that $u_{\alpha} = u_{\beta} \circ \phi$. By applying the procedure from case (a) to the disconnected double cover $\phi \sqcup \mathrm{id} \colon C_\alpha \sqcup C_\beta \to C_\beta$, define
     a new weighted prestable map $(C^{\mathrm{pre}}, \bp^{\mathrm{pre}}\cup (\bp^{\mathrm{pre}})', u^{\mathrm{pre}}, \bm^{\mathrm{pre}})$ with $C_\alpha\sqcup C_\beta$ collapsed to $C_\beta$. Equip the new component $u_\beta^s \colon C_\beta \to X$ with  weight $m_\beta^s = m_\alpha + m_\beta$. We then apply the repeated stabilization process to obtain a weighted stable map $(C^s,\bp^s\cup (\bp')^s,u^s,\bm^s)$ modelled on a graph $\cG^s$. The new function $h^s$ is defined on pairs where neither of the two vertices is $\alpha$, and on these pairs, it agrees with the previous $h$. The function $b^s$ now assigns $\beta$ to all indices $i$ that were assigned to $\alpha$ by the original function $b$ and otherwise agrees with $b$. 

    \item (\textbf{Contracted main component.}) In this construction, we assume that $d_0 = 0$, that is: $u$ is constant on the main component corresponding to $\alpha=0$, which we then collapse to a point. To be precise, in this case $u$ factors through a weighted prestable map $u^{\mathrm{pre}}: C^{\mathrm{pre}} \to X$ obtained from $C$ by collapsing $C_{0}$ to a point. Define $(C^s,\bp^s\cup (\bp')^s,u^s,\bm^s)$ to be the result of repeated stabilization applied to this weighted prestable map, with $\bd^s$ and $\bm^s$ obtained from $\bd$ and $\bm$ by declaring them to be zero on the new genus $0$ components added in the stabilization process, and $b^s = b$, $h^s = h$ unchanged.
\end{enumerate}

    In each of these constructions, we will say that $C_\alpha$  (and $C_\beta$ in case (b)) is the \textbf{component involved in the simplification}. 

\end{definition}


\begin{remark}
    By repeatedly applying the partial simplification process described above to a weighted stable map with no connected contracted subcurve of positive arithmetic genus, one obtains a weighted simple stable map. 
\end{remark}

An important point to make is that the fixed domain constraint from \autoref{def: condition *} is \emph{not} preserved by the partial the simplification process. However, as explained by the next result, this issue occurs only if the partial simplification involves the main component.


\begin{proposition}
    \label{prop: simplification}
    Let $(C,\bp\cup\bp',\bm)$ be a weighted stable map modelled on an augmented graph $\cG$ satisfying  the fixed domain constraint. Let $(C^s,\bp^s\cup (\bp')^s,u^s,\bm^s)$ be the result of the partial simplification process described in \autoref{def: simplification process}, with the corresponding augmented graph $\cG^s$. The partial simplification satisfies
    \[
        [\cG^s,\bm^s] = [\cG,\bm] \quad\text{and}\quad c_1([\cG^s]) \leq c_1([\cG])
    \]
    Moreover, $\cG^s$ satisfies the fixed domain constraint and
    \[
        \tau_{\cG}((C,\bp\cup\bp',\bm)) = \tau_{\cG^s}((C^s,\bp^s\cup (\bp')^s,u^s,\bm^s)),
    \]
    unless the partial simplification involves the main component $C_0$ of $C$. 
\end{proposition}

\begin{proof}  
    It is straightforward to verify from \autoref{def: simplification process} unless the partial simplification involves the main component the partial simplification process preserves all the conditions listed in \autoref{def: condition *}, so let us comment on what goes wrong in these two special cases.  

    In case (a), it is possible for the multiple cover $\phi \colon C_0 \to C_0^s$ to map two or more markings in  $p_{\ell+1}, \ldots, p_n \in C_0$, or the points joining $C_{0}$ to a degree $0$ component carrying one of the $p_1,\ldots, p_\ell$ to the same point. Consequently, the curve $C^s$ obtained from the simplification may no longer be modelled on a graph of the form described in items (i) and (ii) of \autoref{def: condition *}. When $g=0$, a similar issue can arise when case (b) of \autoref{def: simplification process} is applied at the vertex $0$, as the isomorphism $\phi \colon C_\alpha \to C_\beta$  may map one of the points $p_{\ell+1}, \ldots, p_n \in C_0$ to a marking in $\bp'$ on $C_\beta$. 
\end{proof}

\autoref{prop: simplification} shows that the class of stable maps satisfying the fixed domain constraint is almost closed under partial simplification. This will be used in the inductive step of the proof of \autoref{thm: main II}. The special cases when the partial simplification involves the main component will appear as the base cases of induction. For those we will use different arguments. The following observations will be useful.


\begin{remark}\label{rmk: simplication cover of spine}
