\section{Proof of \autoref{thm: main II}}\label{sec: proof of main II}


The following notation will be useful in estimating the dimension of various moduli spaces.

\begin{notation}
    For any manifold $M$, not necessarily complex, we will write
    \[
        \dim_\C M \coloneq \frac{1}{2} \dim_\R M.
    \]
    For any Fredholm operator $L$, not necessarily complex linear, we will write
    \[
        \mathrm{ind}_\C(L) \coloneq \frac{1}{2} \mathrm{ind}_\R(L),
    \]
    and similarly for Fredholm maps between real Banach manifolds. This will make various formulae in the upcoming discussion simpler by getting rid of the factor of two.
\end{notation}  

\begin{notation}
Let $F$ and $G$ be functions depending on $g,r,n$ and an $(n+\ell)$-marked genus $g$ augmented graph $\cG$, as defined in \autoref{def: augmented graphs}. One should think as $F$ as the dimension of a moduli space that we wish to prove empty. We will write $F \lesssim G$ if there is a function $H$ of $g$ and $r$ which does not depend on $n$, $\ell$, and $\cG$, such that 
\[
     F(g,r,n,\cG) \leq G(g,r,n,\cG) + H(g,r).
\]

\end{notation}
In particular, condition
\[
    F(g,r,n,\cG) \lesssim - a n
\]
for some $a > 0$ implies that for every pair $(g,r)$ there exists $C = C(g,r)$ with the property that $F(g,r,n,\cG) < 0$ for all $n \geq C$.

\subsection{Setting the induction} 
We will prove \autoref{thm: main II} by induction on the set of $\cG$ such that
\begin{enumerate}[(i)]
    \item $\cG$ is an $(n+\ell)$-marked genus $g$ augmented graph, as in \autoref{def: augmented graphs},
    \item $\cG$ satisfies the fixed domain constraint from \autoref{def: condition *}, 
    \item $\cG$ has weighted homology class
    \begin{equation}
        \label{eqn: degree bound}
        c_1([\cG,\bm]) \leq r(n+g-1).
    \end{equation}
\end{enumerate}
In particular, every such $\cG$ satisfies \eqref{eqn: num constraint inequality}. The set of such augmented graphs is partially ordered as follows. Let $\widetilde{\mathsf{\Gamma}} = (\mathsf{\Gamma}, \underline{\mathsf{m}}, \underline{d}, \underline{A}, h, b)$ and $\widetilde{\mathsf{\Gamma}'} = (\mathsf{\Gamma}',\underline{\mathsf{m}}', \underline{d}', \underline{A}', h', b')$. Recall that the vertices of $\G$ and $\G'$ are ordered, so that $\bd$ and $\bd'$ are vectors of nonnegative integers of length $|V(\G)|$ and $|V(\cG')|$ respectively. We declare $\cG < \cG'$ if and only if  $\mathrm{length}(\underline{d}) < \mathrm{length}(\underline{d}')$, or  
$\mathrm{length}(\underline{d}) = \mathrm{length}(\underline{d}')$ and, at the smallest index $i$ where $d_i$ and $d'_i$ differ, we have $d_i < d'_i$.  

