    % $$
    % \mathcal{M}^*_{\cG'}(X, J; x_1,\ldots, x_n)
    % $$
    % be its general fiber (i.e. the fiber over a point in a second-category subset of $X^n \times \cJ$). It is a manifold of dimension at most the quantity \eqref{eqn: Case I inequality}.
    %of this map over a point in a second-category subset of $X^n \times \cJ$ are manifolds of dimension  
    %\begin{equation}\label{eqn: Case I inequality}
    %\begin{split}
   % &\sum_{\alpha} c_1(A_{\alpha}) + (r-3)(1-g' -h_1(\G')) + n - |E(\G')| - nr \\
    %\leq & \ c_1(B) - (m_{0} d_{0} - 1) c_1(A_{0}) + (r-3) + n - |E(\G')| - nr 
    %\end{split}
    %\end{equation}  
    %\Ale{this uses $r \geq 3$}

    If \eqref{eqn: Case I inequality} is negative, then the image of \eqref{eqn: aux } has positive codimension. If this were true for every $\cG^s$ as above and $n$ large, this would conclude the proof in Case 2. However, \eqref{eqn: Case I inequality} is not always negative for $n$ large, and we will have to study in greater detail the relationship between $\mathcal{M}_{\cG}(X, \cJ)$ and $\mathcal{M}_{\cG^s}(X, \cJ)$. In what follows, it will be helpful to fix $\delta,\varepsilon \in (0,1)$ such that $\varepsilon +\delta>1$ and $4 \delta < \varepsilon$. For example, $\varepsilon = 0.9$ and $\delta = 0.2$. \\

    \emph{Case 2a: Many markings on the main component}. Recall that $\ell$ is the number of markings $p_1,\ldots, p_n$ which do not lie on the main component $C_0$, see part (ii) of \autoref{def: condition *}. Suppose that $\ell \leq \varepsilon n$. If $[u,J]$ is an element of $\mathcal{M}_{\cG^s}(X, \cJ)$, then $u_0 = u|_{C_0}$ is an element of the moduli space of simple maps $\M_{g^s,n-\ell}^*(X,A_0;\cJ)$. The map $\M_{g^s,n-\ell}^*(X,A_0;\cJ) \to X^{n-\ell} \times \cJ$ has index
    \[
        c_1(A_0) + (r-3)(1-g^s) - (r-1)(n-\ell).
    \]
    If this index is negative, then the image in $X^{n-\ell} \times \cJ$ has positive codimension and so does the image of \eqref{eqn: aux }. Therefore, we may assume that
    \begin{equation}
        \label{eqn: degree lower bound}
        c_1(A_{0}) \geq (r-1)(n-\ell) - (r-3)(1-g^s).
    \end{equation}
    Observe that \eqref{eqn: Case I inequality} is bounded above by
    \[
         c_1([\cG,\bm]) - c_1(A_{0}) + (r-3) + n - |E(\G^s)| - nr
    \]
    Combining \eqref{eqn: degree lower bound} with $|E(\G')| \geq |E(\G)| \geq \ell$ from $(ii)$ in \autoref{def: condition *} and \eqref{eqn: degree bound}, we estimate this number by
    $$
        \lesssim - (r-1)(n-\ell) + n  - \ell \leq -(r-2)(n-\ell) \leq -(r-2)(1-\epsilon)n
    $$
    which diverges to $-\infty$ when $n \to \infty$. \\
     %\Ale{this uses $r \geq 3$}

        \emph{Case 2b: Many markings on $\P^1$ components and high degree main component}. Suppose that $\ell \geq \varepsilon n$ and $d_{0} \geq \delta n$. This case is similar, but easier. We use $|E(\G')| \geq |E(\G)| \geq \ell$, $m_{0} \geq 1$, and $c_1(A_{0}) \geq 1$ to estimate \eqref{eqn: Case I inequality} by
        \begin{align*}
           \lesssim - (d_{0} - 1) + n - \ell \leq n(1 - \varepsilon - \delta) + 1,
        \end{align*}
        which diverges to $- \infty$ as $n\to \infty$ by  our choice of $\varepsilon$ and $\delta$. \\

        \emph{Case 2c: Many markings on $\P^1$ components and low degree main component}. Suppose that $\ell \geq \varepsilon n$ and $d_{0} \leq \delta n$. This is the most delicate case. %For instance, in the case of Del Pezzo surfaces, an ad hoc argument involving the specific geometry of the varieties is required (see \cite[Theorem 24]{CL2}). 
        Let $[u,J] \in \M_{\cG}(X,\cJ)$ be as above. Set $d= d_0$ to simplify notation. Let $m$, $q_i$ and $\beta$ be as in \autoref{rmk: simplication cover of spine}. We will show that the following exist:
        \begin{enumerate}[(i)]
            \item a subset $\M \subset \M_{\cG}(X,\cJ)$ containing $[u,J]$;
            \item a finite-dimensional manifold $\cH$;
            \item a map $\cH \to \M_{g,n}$; 
            \item a commutative diagram of continuous maps
            \[
            \scalebox{0.85}{$
            \xymatrix{
            & \mathcal{M} \ar[dl] \ar[dr] & \\
            \cH \ar[dr]_\gamma & & \mathcal{M}_{\cG^s}(X, \cJ) \ar[dl]^\beta \\
            & \mathcal{M}_{g^s,m } &
            }
            $}
            \]
        with $\gamma$ smooth and $\beta$ as in \autoref{rmk: simplication cover of spine};
        \end{enumerate}
        such that
        \begin{enumerate}[(i)]
            \item the map $\tau_{\cG} \colon \M \to \M_{g,n} \times X^n \times \cJ$ factors through $\cH \times \M_{\cG^s}(X, \cJ) \to \M_{g,n} \times X^n \times \cJ$;
            \item at every point of $\cH$,
            \begin{equation}
                \label{eqn: rank estimate}
                \dim \cH - \mathrm{rank}(d\gamma) \lesssim 4d;
            \end{equation}
            \item $\M_{\cG}(X,\cJ)$ can be covered by countably many subsets $\M$ as above.
        \end{enumerate}

        Before constructing such manifolds and maps, let us see how their existence implies the desired statement. Let $\cF \subset \cH \times\M_{\cG^s}(X, \cJ)$ be the fiber product of $\gamma$ and $\beta$. By assumption and by the universal property of the fiber product, $\tau_{\cG}|_{\M}$  factors through
        \begin{equation}
            \label{eqn: fiber product tau}
            \cF \hookrightarrow \cH \times \M_{\cG^s}(X, \cJ) \to \M_{g,n} \times X^n \times \cJ
        \end{equation}
        By \eqref{eqn: rank estimate} and \autoref{lem: fiber product}, there exists a submanifold $\widetilde\cF \subset \cH \times\M_{\cG^s}(X, \cJ)$ containing $\cF$ and such that the projection to $\M_{\cG^s}(X, \cJ)$ is Fredholm of index $\leq 4d$. Therefore, the composition
        \begin{equation}
            \label{eqn: fiber product diagram}
            \widetilde \cF \hookrightarrow \cH \times \M_{\cG^s}(X, \cJ) \to \M_{g,n} \times X^n \times \cJ
        \end{equation}
        contains the image of $\tau_{\cG} |_{\M}$ and is Fredholm. Since the index of the composition of Fredholm maps is the sum of indices, 
        \[
            \text{index of \eqref{eqn: fiber product tau} } 
            \lesssim \text{index of \eqref{eqn: aux }} + 4d - \dim \M_{g,n}.
        \]
        By \eqref{eqn: Case I inequality}, \eqref{eqn: degree bound}, and $|E(\G^s)| \geq \ell$, the right-hand side can be estimated by 
        \[
            \lesssim 4d - \ell \leq (4\delta-\varepsilon)n,
        \]
        where we have used $\ell \geq \varepsilon n$ and $d \leq \delta n$. By the assumption $\varepsilon > 4\delta$, the right-hand side converges to $-\infty$ as $n\to \infty$. Since $\M_{\cG}(X,\cJ)$ can be covered by countably many such sets $\M$, the theorem in Case 2c follows. 

        It remains to construct $\M$, $\cH$, and maps as above. Let $\cH$ be the Hurwitz space parametrizing data $(S,\bp,S^s,\bp^s, \varphi)$ where
        \begin{enumerate}[(i)]
            \item $(S,\bp)$ is an $n$-marked complex curve of genus $g$,
            \item $(S^s, \bp^s)$ is an $m$-marked complex curve of genus $g^s$,
            \item $\varphi \colon S \to S^s$ is a degree $d$ holomorphic map such that $\bp^s = \varphi(\bp)$  as sets (note that they have different cardinality) and $\varphi$ has the same ramification profile as $\phi \colon C_0 \to C_0^s$, 
        \end{enumerate}
        where by the ramification profile we mean the number of ramification points $b$ and the ramification index of $\varphi$ at each of these points. The space $\cH$ is defined in such a way that for $\bp = (q_1,\ldots, q_\ell, p_{\ell+1},\ldots, p_n)$ and $\bp^s = \phi(\bp)$, the collection $(C_0, \bp, C_0^s, \bp^s, \phi)$ is an element of $\cH$. Up to discrete ambiguity, the data $(S,\bp,\varphi)$ is determined by $S'$ and a choice of $b+m$ points in $S'$. Therefore, $\cH$ is a complex manifold of dimension
        \[
            \dim_\C \cH = 3g^s-3 + m + b.
        \]
        The map $\cH \to \M_{g^s,m}$ is given by $(S,\bp,S^s,\bp^s, \varphi) \mapsto (S^s,\bp^s)$. The map $\cH \to \M_{g,n}$ is given by $(S,\bp,S^s,\bp^s,\varphi) \mapsto (S,\bp)$. 

        Denote by $\M \subset \M_{\cG}(X,\cJ)$ the set of all pairs $[u',J']$ such that $u' \colon C' \to X$ is close to $u \colon C \to X$ and the restriction of $u'$ to the main component factors through a covering $\varphi \colon S \to S^s$ as above. By construction, this gives us a map $\M \to \cH$ which fits into the commutative diagram above and such that $\tau_{\cG}|_{\M}$ factors through \eqref{eqn: fiber product diagram}. Moreover, $\M_{\cG}(X,\cJ)$ is second countable and stratified according to the number $m$ and the ramification profile of $\phi \colon C_0 \to C_0^s$, so  $\M_{\cG}(X,\cJ)$ can be covered by countably many subsets $\M$ as above. 

        The final part of the proof in Case 2c is to show that the derivative of $\gamma \colon \cH \to \M_{g^s,m}$ satisfies estimate \eqref{eqn: rank estimate}.  We claim that the rank of $(d\gamma)_h$ is at least $m-b$ at every point of $h \in \cH$. Indeed, let $h= (S,\bp,S^s,\bp^s,\varphi)$. The restriction of $(d\gamma)_h$ to the subspace corresponding to varying the points $\bp$,
        \begin{equation*}
            \bigoplus_{p \in \bp} T_p S \subset T_h \cH
        \end{equation*}
        is given by evaluating $d\varphi$ at the points of $\bz$,
        \begin{equation*}
            \bigoplus_{p \in \bp} T_p S \xrightarrow{d\varphi} \bigoplus_{p^s \in \bp^s} T_{p^s} S^s \hookrightarrow T_{S^s,\bp^s} \M_{g^s,m}.  
        \end{equation*}
        This map is injective when restricted to the subspace corresponding to $\{ p \in \bp \ | \ d\varphi(p) \neq 0 \}$. Since $\varphi$ has $b$ ramification points, the size of this set is at least $\max\{ 0, m-b\}$ and we conclude that $\mathrm{rank}(d\gamma) \geq \max\{0,m-b\}$. Therefore,
        \[
            \dim \cH - \mathrm{rank}(d\gamma) \leq 3g^s-3 + m+b - \max\{0,m-b\} \lesssim 2b.
        \]
        The number of ramification points can be estimated using the Riemann--Hurwitz formula. If $i_k$ is the ramification index at the $k$-th ramification point, then 
        \[
            b \leq \sum_{k=1}^b i_k = d(2-2g^s) -     (2-2g) \lesssim 2d,
        \]
        which implies \eqref{eqn: rank estimate}, completing the proof in Case 2c. \\

