\begin{proposition}[Contracted main component] \label{prop: Base Case II}
    Suppose that $\cG$ satisfies the three conditions listed at the beginning of \autoref{sec: proof of main II}, as well as
    \begin{enumerate}[(i)]
        \item $d_{0}=0$;
        \item $d_\alpha \in \{0,1\}$ for all $\alpha\in V(\G)$;
        \item $h^{-1}(1)= \emptyset$.
    \end{enumerate}
    Then there exists $C=C(r,g)$ such for $n>C$ the image of the map $\tau_{\widetilde{\mathsf{\Gamma}}}$ in  \eqref{eqn: map tau tilde} has positive codimension.
\end{proposition}

\begin{proof}
    Applying the contracted main component simplification in part $(c)$ of \autoref{def: simplification process} to each $[u,J] \in \M_{\cG}(X,\cJ)$ we obtain a simple map $u^s$ modelled on an augmented graph $\cG^s$.  Since all maps in $\M_{\cG^s}(X,\cJ)$ are simple, by \autoref{thm: transversality} and \autoref{lem: fredholm projection}, $\M_{\cG^s}(X,\cJ)$ is a Banach manifold and $\M_{\cG^s}(X,\cJ) \to X^n \times \cJ$ is Fredholm of index
    \begin{equation}\label{eqn: contracted spine}
        (r-3)(1-h_1(\G^s)) +n +c_1([\cG^s])- |E(\G^s)| -nr \leq (r-3)+n + c_1([\cG])- |E(\G^s)|-nr
    \end{equation}
    %\Ale{This is using $r \geq 3$} 
    where $|E(\G^s)|$ denotes the number of edges of $\cG^s$. The result follows if we show that the right-hand side of \eqref{eqn: contracted spine} is negative for large $n$. Fix $\varepsilon \in (0, 1)$. We distinguish two cases. \\

    \emph{Case 1: Many edges.} Suppose that $|E(\G^s)| \geq (1+\varepsilon)n$.
    In this case, we use $c_1([\cG]) \leq c_1([\cG,\bm]) \lesssim nr$ by \eqref{eqn: degree bound} to bound the right-hand side of \eqref{eqn: contracted spine} by
    \[
        \lesssim n - |E(\G^s)| \leq -\varepsilon n,
    \]
    which diverges to $-\infty$ as $n\to\infty$. \\

    \emph{Case 2: Few edges.} Suppose that $|E(\G^s)| \leq (1+\varepsilon)n$. We first bound 
        \begin{equation}
            \label{eqn:degree-loss}
        c_1([\cG])= c_1([\cG,\bm]) - \sum_{\alpha}(m_\alpha-1) c_1(A_\alpha)
        \end{equation}
        above by bounding the loss in degree
        \[
            \sum_{\alpha}(m_\alpha-1) c_1(A_\alpha)
        \]
        below, as follows. Set $S = \{ \alpha \in V(\G) \ | \ d_\alpha > 0 \}$. The function $b \colon \{1, \ldots, \ell \} \to S$, which is part of the augmentation data of  $\cG$, as in \autoref{def: augmented graphs}, will be crucial in this argument. First, observe that that the factor $X^n$ can be decomposed into
        \begin{equation} \label{eqn: X decomposition}
            X^n = X^{n-\ell} \times X^\ell = X^{n-\ell} \times \prod_{\alpha \in S} X^{| b^{-1}(\alpha)|}.
        \end{equation}
        If there exists $\alpha \in S$ such that the evaluation map at the marked points in $b^{-1}(\alpha)$,
        \begin{equation} \label{eqn: sphere evaluation map}
            \mathcal{M}_{0, | b^{-1}(\alpha)|}^*(X,\cJ) \to X^{| b^{-1}(\alpha)|} \times \cJ
        \end{equation}
        has negative index, then the image of $\tau_{\cG}$ has positive codimension. % as it lies in the subset obtained by replacing the factor of \eqref{eqn: X decomposition} corresponding to $\alpha$ by the image of \eqref{eqn: sphere evaluation map}. 
        Thus, we may assume that for every $\alpha \in S$, the map \eqref{eqn: sphere evaluation map} has non-negative index, or equivalently
        \begin{equation}\label{eqn: lower bound tails}
            c_1(A_\alpha) \geq (r-1) |b^{-1}(\alpha)|-(r-3).
        \end{equation} 
        Set $s = |S|$ and for $j= 0, 1, \ldots, \ell$, let 
        \[ 
            S_j = \{ \alpha \in S \ | \ |b^{-1}(\alpha)|=j \} \quad\text{and}\quad s_j=|S_j|, 
        \]
        so that
        \[
            S = \bigsqcup_{j \geq 0} S_j.
        \]
        Therefore, we have
        \[
            \sum_{j \geq 0} s_j = \sum_{j\geq 0} |S_j| = |S| = s,
        \]
        as well as
        \[
            \sum_{j \geq 1} j s_j = \sum_{j \geq 1} j |S_j| = \sum_{j\geq 1} |b^{-1}(S_j)| = |b^{-1}(S)| = \ell. 
        \]
        Note that for every $\alpha \in S_j$ we have $m_\alpha \geq |b^{-1}(\alpha)| = j$ by  \autoref{def: condition *}.
        Moreover $m_\alpha \geq 1$ and $c_1(A_\alpha) > 0$ for every $\alpha \in S$. Putting this all together and using \eqref{eqn: lower bound tails} and $m_\alpha \geq 2$ when $j = |b^{-1}(\alpha)| \geq 2$, we obtain the following lower bound on the loss in degree: 
        \begin{align}\label{eqn: lower bound tails II} 
        \begin{split}
            \sum_{\alpha}(m_\alpha-1) c_1(A_\alpha) & \geq \sum_{j \geq 2} \sum_{\alpha  \in S_j} (m_\alpha-1) c_1(A_\alpha) \\
            &\geq \sum_{j \geq 2} \sum_{\alpha  \in S_j} (j-1)( (r-1) j-(r-3)) \\
            &\geq \sum_{j \geq 2} \sum_{\alpha  \in S_j}  ((r-1) j-(r-3)) \\
            & =  (r-1)\sum_{j \geq 2}  js_j - (r-3) \sum_{j \geq 2} s_j \\
            & = (r-1) \ell -(r-3)s -2 s_1 \\
            & \geq (r-1) \ell - (r-3)s - 2s \\
            & \geq  (r-1) (\ell -s).
        \end{split}
        \end{align}
        We may assume that $\ell \geq n-1$. Indeed, if $\ell < n-1$, then $u(p_n)=u(p_{n-1})$ for all $[u,J] \in \M_{\widetilde{\mathsf{\Gamma}}}( X, \mathcal{J}) $ and the image of $\tau_{\cG}$ lies in the positive codimension subset corresponding to $X^{n-1} \subset X^n$. Moreover, by \autoref{lemma: adges after spine contraction}, we have
        \[
        |E(\G^s)| -  |E(\G)| \geq \ell-3 \geq n-4,
        \]
        so that $|E(\G)| \leq \epsilon n +4$ by the assumption on $|E(\G^s)|$. Since $\G$ is a connected graph, the Euler characteristic gives us
        $$
        s \leq |V(\G)|= 1 - h_1(\G) + |E(\G)| \leq |E(\G)| + 1 \leq \varepsilon n +5. 
        $$
        where $V(\G)$ denotes the set of vertices of $\G$. Combining these inequalities with \eqref{eqn: lower bound tails II} yields
        \begin{equation}
            \label{eqn: lower bound tails III}
             \sum_{\alpha}(m_\alpha-1) c_1(A_\alpha) \geq (r-1)(n-\epsilon n - 6).
        \end{equation}
        Using \eqref{eqn:degree-loss} and \eqref{eqn: lower bound tails III}, and estimating $c_1([\cG,\bm]) \lesssim nr$ by \eqref{eqn: degree bound} and $|E(\G^s)| \geq n-4$, we estimate \eqref{eqn: contracted spine} above by
        \begin{align*}
            \lesssim  - |E(\G^s)|+n -(r-1)(n- \varepsilon n)
            \lesssim -(r-1)(1-\varepsilon) n
        \end{align*}
         which diverges to $-\infty$ for large $n$ by the assumption $\epsilon < 1$.
         %\Ale{this uses $r \geq 3$}.
\end{proof}

\begin{remark}
    In the proof we only use that $m_\alpha \geq 2$ whenever $|b^{-1}(\alpha)| \geq 2$, not the stronger inequality $m_\alpha \geq |b^{-1}(\alpha)|$ assumed in \autoref{def: condition *}. 
\end{remark}

This concludes the discussion of the base cases.

\subsection{The inductive step}\label{sec: the inductive step}

   With the base cases established, we prove \autoref{thm: main II} by induction on the set of augmented graphs $\cG$ satisfying the three conditions listed at the beginning of \autoref{sec: proof of main II}, with respect to the order explained in the same place. (In fact, throughout the induction, the weighted homology class $[\cG,\bm]$ remains fixed but we will not use this.)

    The base case, addressed in \autoref{prop: base case I}, is when $d_\alpha \in \{0,1\}$ for all $\alpha \in V(\G)$ and $h^{-1}(1) = \emptyset$. In that case, all maps in $\M_{\cG}(X,\cJ)$ are simple. Suppose now that $\cG$ is not of that form. Then one of the following situations must occur:
    \begin{enumerate}[(i)]
        \item There exists a vertex $\alpha \neq 0$ with $d_\alpha>1$. Then, the connected cover simplification described in part (a) of \autoref{def: simplification process} yields a new augmented graph $\cG^s$ such that $\cG^s < \cG$, $\cG^s$ satisfies the fixed domain constraint, $[\cG^s,\bm^s] = [\cG,\bm]$, and $\im(\tau_{\cG}) = \im(\tau_{\cG^s})$, and we are done by induction.
        \item There exist distinct vertices $\alpha \neq \beta$, both different from $0$, such that $h(\alpha, \beta) = 1$ and $d_{\alpha}= d_{\beta}=1$. In this case, the disconnected cover simplification described in part (b) of \autoref{def: simplification process} yields a new augmented graph $\cG^s$ such that $\cG^s < \cG$, $\cG^s$ satisfies the fixed domain constraint, $[\cG^s,\bm^s] = [\cG,\bm]$, and $\im(\tau_{\cG}) = \im(\tau_{\cG^s})$, and we are done by induction.
        \item The case where $d_{0} = 0$, $h^{-1}(1) = \emptyset$, and $d_\alpha \in \{0,1\}$ for all vertices $\alpha$ is treated in Proposition~\autoref{prop: Base Case II}.
        \item The case where $d_0>0$, $h^{-1}(1)= \{(0,\alpha)\}$ and $d_\alpha \in \{0,1\}$ for all $\alpha \neq 0$ is treated in \autoref{prop: base case I}.
        \item The case $h^{-1}(1)=\emptyset$ and $d_{\alpha} \in \{0,1\}$ for all $\alpha \neq 0$ and $d_{0}>1$ is also treated in \autoref{prop: base case I}.
    \end{enumerate}
    This concludes the proof of \autoref{thm: main II}.

\section{Proofs of main results}
\label{sec: proofs of main results}

\subsection{\autoref{thm: main II} implies  \autoref{thm: main}}
\label{subsec: thm II to I}

The first observation is that we can restrict ourselves to graphs $\G$ of a very specific shape, described below. Namely, for $m \geq 0$ and $0 \leq \ell \leq n$, let $\mathsf{\Gamma}$ be the dual graph of a curve $C$ of the kind depicted in \autoref{figure-1}. That is: $C$ consists of a main component $C_0$ of genus $g$ with $n-\ell$ marked points  $p_{\ell+1}, \ldots, p_n$. Attached to $C_0$ are $m$ trees $S_1,\ldots, S_m$ of $\P^1$ components. Similarly, there are $\ell$ trees $T_1,\ldots, T_\ell$ of $\P^1$ components attached to $C_0$ at points $q_1,\ldots,q_\ell$. Each of $T_i$ contains a marked point $p_i$ for $i=1,\ldots,\ell$.  The reason we can consider only such graphs is that unless $\G$ has this shape, the stabilized curve lies in $\cM_{g,n}\setminus\M_{g,n}$ and so the image of $\tau_{\G}$ has  positive codimension.


