\subsection{\autoref{thm: main} implies \autoref{thm: main 0}}

Let $T = T_{g,n}$ be the graph consisting of one genus $g$ component with $n$ markings.  By \autoref{thm: main}, \autoref{cor: transversality}, and the Sard--Smale theorem there exists $(\zeta,J) \in \M_{g,n} \times X^n \times \cJ$ such that 
\begin{enumerate}[(i)]
    \item $\zeta$ is in the manifold locus of $\M_{g,n} \times X^n$, that is: the corresponding complex structure in $\M_{g,n}$ has no automorphisms;
    \item for $\G \neq T$, $(\zeta,J)$ is not in the image of $\tau_\G$;
    \item for $\G = T$, $(\zeta,J)$ is not in the image of $\M_T(X,\cJ;A) \setminus \M^*_T(X,\cJ;A)$ under $\tau_{\G}$;
    \item $(\zeta,J)$ is a regular value of the restriction
    \[
        \tau_{T}^* \colon \M^*_T(X,\cJ;A) \to \M_{g,n} \times X^n \times \cJ.
    \]
\end{enumerate}
We have
\[
    \cM_{g,n}(X,\cJ;A) = \bigcup_\G \M_\G(X,\cJ;A),
\]
where the union is taken over all $n$-marked genus $g$ graphs $\G$. Therefore, the preimage of $\zeta$ under the map
\[
    \tau_J \colon \cM_{g,n}(X,J;A) \to \cM_{g,n} \times X^n
\]
is
\[
    \tau_J^{-1}(\zeta) = (\tau_{T}^*)^{-1}(\zeta,J).
\]
Since $\tau_T^*$ is Fredholm of index zero, it follows that $\tau_J^{-1}(\zeta)$ is a zero-dimensional manifold. Since $\cM_{g,n}(X,J;A)$ is compact, $\tau_J^{-1}(\zeta)$ is a finite set. Moreover, each point in  $\tau_J^{-1}(\zeta)$ carries a natural orientation constructed in \cite[Theorem 3.1.6, Remark 3.2.5]{mcduff} which, in this case, is simply a sign $\mathrm{sign}(u) \in \{ -1,1\}$ for every $[u] \in \tau_J^{-1}(\zeta)$. We will argue that
\begin{equation}
    \label{eqn: signed count}
    \vTev_{g,n}(X,\omega;A) = \sum_{[u] \in \tau_J^{-1}(\zeta)} \mathrm{sign}(u).
\end{equation}

Set $\cM = \cM_{g,n}(X,J;A)$. The virtual Tevelev degree is defined as the pairing
\[
    \vTev_{g,n}(X,\omega;A) = \langle [\cM]^\mathrm{vir}, \tau_J^*\gamma \rangle
\]
where 
\begin{enumerate}[(i)]
    \item $[\cM]^\mathrm{vir} \in H_d^{BM}(\cM, \Q)$ is the virtual fundamental class in the Borel--Moore homology;
    \item $d$ is the real virtual dimension of $\cM$, by assumption equal to $\dim_\R (\cM_{g,n} \times X^n)$;
    \item $\gamma \in H^d( \cM_{g,n} \times X^n, \Q)$ is the orientation class, Poincaré dual to a point.
\end{enumerate}
Let $\M^* = \M_T^*(X,J;A)$. This is an open subset of $\cM$. We claim that $\tau_J^* \gamma$ can be represented by a cochain with compact support in $\M^*$; in other words, that $\tau_J^*\gamma$ is in the image of the push-forward map in compactly supported cohomology induced by the open embedding $\iota \colon \M^* \to \cM$:
\[
   \iota_* \colon H^d_c(\M^*,\Q) \to H^d(\cM,\Q).
\]
Indeed, since $\cM$ is compact and $\tau_J^{-1}(\zeta)$ is contained in $\M^*$, there exists an open neighborhood $U \subset  \mathcal{M}_{g,n} \times X^n$ around $\zeta$ such that $U \cong \R^d$ and $\tau_J^{-1}(U)  \subset \M^*$. Moreover, the restriction of $\tau_J$ to $\tau_J^{-1}(U) \to U$ is proper. The orientation class $\gamma$ is the image of the Poincar\'e dual to a point in $U$ in $H^d_c(U,\Q)$ under the push-forward map
\begin{equation}
    \label{eqn: composition in cohomology}
    H^d_c(U,\Q) \to H^d(\cM_{g,n} \times X^n)
\end{equation}
so that $\tau_J^*\gamma$ is the image of $\mathrm{PD}[\mathrm{pt}]$ under the composition
\[
    H^d_c(U,\Q) \to H^d_c( \tau_J^{-1}(U), \Q) \to H^d_c( \M^*, \Q) \to H^d(\cM,\Q).
\]
which proves the claim. The first map above is the pull-back under the proper map $\tau_J$ and the other maps are induced by open inclusions. 

On the other hand, $\iota \colon \M^* \to \cM$ induces a pull-back map on the Borel--Moore homology
\[
    \iota^* \colon H^{BM}_d(\cM,\Q) \to H^{BM}_d(\M^*,\Q).
\]
Since $\M^*$ is a smooth, oriented manifold of dimension $d$, by \cite[Lemma 5.2.6 and Section 9.2, in particular Proposition 9.2.6]{pardon}, the image of the virtual fundamental class under this map is the standard fundamental class:
\[
   \iota^* [\cM]^\mathrm{vir} = [\M^*] \in H^{BM}_d(\M^*,\Q).
\]
Let $\gamma_0$ be the image of $\mathrm{PD}[pt]$ in $H^d_c(\M^*,\Q)$ in the diagram \eqref{eqn: composition in cohomology}, so that $\tau_J^*\gamma = \iota_*\gamma_0$. We have
\[
    \vTev_{g,n}(X,\gamma;A) = \langle [\cM]^\mathrm{vir}, \tau_J^*\gamma \rangle = \langle [\cM]^\mathrm{vir}, \iota_*\gamma_0 \rangle = \langle \iota^* [\cM]^\mathrm{vir}, \gamma_0 \rangle = \langle [\M^*], \gamma_0 \rangle.
\]
Since $\M^*$ is a smooth, oriented manifold and $(\zeta,J)$ is a regular value of the restriction of $\tau_J$ to $\M^*$, the right-hand side agrees with \eqref{eqn: signed count} by standard differential topology.


