%     We say that the pair $(\G,\bA)$ is \textbf{simple} if for every  vertex $\alpha \in V$ with $A_\alpha = 0$ we have $g_\alpha = 0$ and the subgraph consisting of all such vertices is a disjoint union of trees. 
% \end{definition}

% Let $(\G,\bA)$ be a simple pair. Let $\cJ$ be the space of $C^k$ almost complex structure on $X$ which are either tamed by or compatible with the symplectic form. Denote by $\M_\G^*(X,\cJ,\bA)$ the universal moduli space of stable maps $u\colon C \to X$ such that $C$ is modelled on $\G$, $u$ is simple in the sense of \autoref{def: simple map}, and $[u_\alpha] = A_\alpha$ for all $\alpha \in V$.
