Let $A \in H_2(X,\Z)$ be a positive class.  Consider the universal moduli space $\M_\G^*(X,\cJ; A)$  of simple pseudo-holomorphic maps $u \colon C \to X$ from $n$-marked genus $g$ domains modelled on $\G$. For the notion of a simple map, see \autoref{def: simple}

The following transversality theorem is proved when $g=0$ and $\G$ a tree in \cite[Sections 6.2, 6.3]{mcduff}, and in full generality in \cite[Section 4]{ruan1} and \cite[Section 3]{ruan2}; see also the discussion in \cite[Section 1.2]{zinger}. As \cite{ruan1,ruan2} use inhomogeneous perturbations of the Cauchy--Riemann equations, and concern a more general situation than the one in this paper, for completeness we include a short, self-contained proof.

\begin{theorem}
    \label{thm: transversality}
    $\M_\G^*(X,\cJ; A)$ is a Banach manifold and the map
    \[
        \pi \colon \M_\G^*(X,\cJ; A) \to \cJ 
    \]
    is Fredholm of complex index
    \begin{equation}
        \label{eqn:index}
        \mathrm{ind}_\C(\pi) =
        c_1(A) + (r-3)(1-g) - |E| + n.
    \end{equation}
\end{theorem}

\autoref{thm: transversality}
together with \autoref{lem: fredholm stabilization} imply the following.

\begin{corollary}
    \label{cor: transversality}
    The map
    \[
        \tau_\G \colon \M_\G^*(X,\cJ; A) \to \cM_{g,n} \times X^n \times \cJ 
    \]
    is Fredholm of complex index
    \begin{equation}
        \label{eqn:index with domain}
        \mathrm{ind}_\C(\pi) =
        c_1(A) + r(1-g) - |E| - nr.
    \end{equation}

\end{corollary}


\begin{proof}[Proof of \autoref{thm: transversality}]
    To keep the notation simple, assume that $n=0$. We will prove the theorem for $\M^*_\G(X,\cJ;A)$ replaced by the \emph{local} moduli space of simple maps from domains close to a given nodal curve $C$ modelled on $\G$, in the sense that we now explain.

    Let $\Sigma = \bigsqcup_{\alpha\in\G} C_\alpha$ be the normalization of $C$; note that $\Sigma$ is disconnected when $|V| > 1$.  We will think of $\Sigma$ as a smooth manifold equipped with an almost complex structure $j_0$. Fix also a Riemannian metric on $\Sigma$. 

    Let $\vv E$ be the set of pairs consisting of an edge in $E$ and a orientation on it, so that $|\vv E| = 2|E|$. We will write an element of $\vv E$ as $e = (\alpha,\beta)$ where $\alpha, \beta \in V$ are the beginning and end of the edge. The same edge with the reversed orientation will be denoted by $\bar e = (\beta,\alpha)$. 
    For every $e = (\alpha,\beta) \in \vv E$ there is a corresponding point $z_{0,e} \in C_\alpha$, such that the points $z_{0,e}$ and $z_{0, \bar e}$ map to the same node of $C$ under $\Sigma \to C$. Denote by $\bz_0$ the collection of all these points. 

    Denote by $\mathcal{P}$ the infinite-dimensional Fréchet manifold parametrizing pairs $(j,\bz)$ consisting of an (integrable) almost complex structure on $\Sigma$ and an ordered collection of $|\vv E|$ distinct points, distributed among the connected components of $\Sigma$ in the same way as the points in $\bz_0$. Set
    \[
        H = \prod_\alpha \mathrm{Diff}_+(C_\alpha),
    \] 
    where $\mathrm{Diff}_+$ denotes the group of orientation preserving diffeomorphisms. The group $H$ acts on $\mathcal{P}$, with the orbits corresponding to biholomorphism classes of marked curves of the relevant topological type. The stabilizer of $(j_0,\bz_0)$ in $H$ is the group $G =\mathrm{Aut}(\Sigma,j_0, \bz_0)$ of biholomorphisms of $(\Sigma,j_0)$ preserving every point in $\bz_0$.
    Let $\mathcal{S} \subset \mathcal{P}$ be a \emph{local Teichmüller slice} through $(j_0, \bz_0)$, characterized by the following properties:
    \begin{enumerate}[(i)]
        \item $\mathcal{S}$ is a smooth submanifold of $\mathcal{P}$ containing $(j_0,\bz_0)$ of dimension given by
        \begin{equation}
        \label{eqn:dimension of S}
        \dim_\C \mathcal{S} = 3g(\Sigma) -3|V| + |\vv E| + \dim_\C G,
     \end{equation}
    where we declare
    \[
        g(\Sigma) = \sum_{\alpha \in \G} g_\alpha;
    \]
        \item $\mathcal{S}$ is preserved by the action of $G$;
        \item the map
        \begin{equation*}
            (\mathcal{S} \times H)/ G  \to \mathcal{P}  
        \end{equation*}
        induced by the $G$-invariant multiplication map $\mathcal{S}\times H \to \mathcal{P}$, is an $H$-equivariant local homeomorphism from a neighborhood of $[j,\bz_0, \mathrm{id} ]$ to a neighborhood of $(j,\bz_0)$; in particular, the natural map
        \[
            \mathcal{S} / G \to \mathcal{P} / H
        \]
        is a local homeomorphism around $[j_0,\bz_0]$;
        \item the  tangent space to $\mathcal{S}$ at $(j_0,\bz_0)$ is transverse to the tangent space to the $H$-orbit of $(j_0,\bz_0)$ in the $L^p$ sense explained in \cite[Definition 2.49]{wendl}. 
    \end{enumerate}
    See \cite[Sections 4.2, 4.3; in particular, Theorem 4.30, Lemma 4.41, Theorem 4.43]{wendl} for a discussion of Teichmüller slices and a proof of their existence.

    Fix $p>2$. Let $\cB \subset W^{1,p}(\Sigma, X)$ be the space of simple maps $u \colon \Sigma \to X$ of Sobolev class $W^{1,p}$ with fixed $u_*[C_\alpha]$ for every $\alpha \in \G$; this is an open subset of $W^{1,p}(\Sigma, X)$ and so a Banach manifold. Let $\cE \to \cJ \times \cS \times \cB$ be the Banach vector bundle whose fiber over $(J, j,\bz,u)$ is the space $L^p \Omega^{0,1}(\Sigma, u^*TX)$ of $L^p$ sections of the bundle $\Lambda^{0,1} T^*\Sigma \otimes u^*TX$, where $(0,1)$ forms on $\Sigma$ are taken with respect to $j$ and the tensor product is taken over complex numbers with respect to $J$.  Consider the $G$-equivariant section
    \begin{gather*}
        \psi \colon \cJ \times \mathcal{S} \times \cB \to \cE, \\
        \psi(J,j,\bz,u) = \delbar_{J,j}(u)
    \end{gather*}
    where
    \[
        \delbar_{J,j}(u) = \frac12 (d u + J (u) \circ du \circ j)
    \]
    is the nonlinear Cauchy--Riemann operator with respect to $J$ and $j$. For a future argument, it is useful to compute the index of the restriction $\psi_J$ of $\psi$ to the slice $\{ J \} \times \cS \times \cB$.      First, the restriction of $\psi$ to every slice $\{ (J,j,\bz) \} \times \cB$ is a Fredholm section. Its index is given by the Riemann--Roch formula,
    \[
         \mathrm{ind}_\C(\delbar_{J,j}) = \sum_{\alpha\in\G} c_1(A_\alpha) + r(1-g_\alpha).
    \]
    Therefore, \autoref{lem: fredholm stabilization} and \eqref{eqn:dimension of S}, the restriction $\psi_J$ of $\psi$ to the slice $\{ J \} \times \mathcal{S} \times \cB$ is a Fredholm section of index 
    \begin{equation}
        \label{eqn:index with varying j}
        \mathrm{ind}_\C(\psi_J) =  
        \mathrm{ind}_\C(\delbar_{J,j}) + \mathrm{dim}_\C \mathcal{S} = c_1(A) + (r-3)(|\G|-g(\Sigma)) + |\vv E|) + \dim_\C G.
    \end{equation}

    A standard argument shows that $\psi$ is transverse to the zero section and so $\psi^{-1}(0)$ is a Banach manifold. We could then study an appropriate evaluation map defined on $\psi^{-1}(0)$, as in \cite[Section 6.3]{mcduff}. However, we choose a different approach, and instead of looking at $\psi^{-1}(0)$ we will study a map combining $\psi$ and the evaluation map. To that end, consider the $G$-invariant evaluation map
    \begin{gather*}
        \ev \colon \mathcal{S} \times \cB \to X^{\vv E} = \prod_{e\in \vv E} X  \\
        \ev(j,\bz,u) = \ev(\bz,u) = ( u(z_{e}) ).
    \end{gather*}
    Define
    \begin{gather*}
        \Psi \colon \cJ \times\mathcal{S} \times \cB \to \cE \times X^{\vv E}, \\
        \Psi(J,j,\bz,u) = ( \psi(J,j,u), \ev(\bz,u) ).
    \end{gather*}
    Consider the diagonal in $X^{\vv E}$,
    \[
        \Delta^E = \{ (x_{e}) ) \in X^{\vv E} \ | \ x_{e} = x_{\bar e} \},
    \]  
    and set 
    \[
        \M^*_{\mathrm{loc}} = \Psi^{-1}(0 \times \Delta^E)/G
    \]
    Note that $G$ acts freely on $\Psi^{-1}(0\times\Delta^E)$ by the definition of $\mathcal{B}$ as a space of simple maps. Therefore, to show that $\M^*_{\mathrm{loc}}$ is a Banach manifold, it suffices to show that $\Psi$ is transverse to $0 \times \Delta^E$, where $0 \subset \cE$ denotes the zero section. It follows then from \autoref{lem: fredholm projection} that the projection $\pi \colon \M^*_{\mathrm{loc}} \to \cJ$ is Fredholm. The index of $\pi$  is computed by subtracting from \eqref{eqn:index with varying j} the dimension of $G$ and the codimension of $\Delta^E$ in $X^{\vv E}$:
    \begin{align*}
         \mathrm{ind}_\C(\pi) &= c_1(A) + (r-3)(|\G|-g(\Sigma)) + |\vv E| - r |E| \\
        &= c_1(A) + (r-3)(1-g(\Sigma)-h_1(\G) + |E|) + (2-r)|E| \\
        &= c_1(A) + (r-3)(1-g) - |E|, 
    \end{align*}
    which agrees with \eqref{eqn:index} for $n=0$. 

    It remains to prove the transversality of the map $\Psi$ to $0 \times \Delta^E$. Let $p = (J,j,\bz,u)$ be a point in $\Psi^{-1}(0\times\Delta^E)$. Set $\bx = \ev(p)$ and denote by $N_{\bx} = T_{\bx} X^{\vv E} / T_{\bx} \Delta^E$ the normal space to $\Delta^E$ at $\bx$. We can realize $N_{\bx}$ as the subspace of $T_{\bx} X^{\vv E}$ consisting of collections  $\bv = (v_e)$ of vectors $v_e \in T_{x_e} X$ satisfying $v_e = - v_{\bar e}$ for every $e \in \vv E$. 
    Consider the operators
    \begin{gather*}
        \mathcal{L}_J \colon T_J \cJ \to L^p \Omega^{0,1}(C,j; u^*TX) \oplus N_{\bx}, \\
        \mathcal{L}_u \colon T_u \cB \to L^p \Omega^{0,1}(C,j; u^*TX) \oplus N_{\bx}
    \end{gather*}
    defined by differentiating $\Psi$ at $p$ in the direction of $J$ and $u$, respectively, and applying projection
    \[
         T_{\Psi(p)}(\cE \times X^{\vv E}) \to L^p\Omega^{0,1}(C,j; u^*TX) \oplus N_{\bx}.
    \]
    In fact, the image of $\mathcal{L}_J$ lies in the first summand as the evaluation map does not depend on $J$.

    We will show that $\mathcal{L} = \mathcal{L}_J + \mathcal{L}_u$ is surjective; this implies that $\Psi$ is transverse to $0\times\Delta^E$ at $p$. Since $\mathcal{L}_u$ is Fredholm (see below), the image of $\mathcal{L}$ is closed and has finite codimension. If $\mathcal{L}$ is not surjective, then, by the Hahn--Banach theorem, there exists a non-zero pair $(\eta, \bv)$ such that
    \begin{itemize}
        \item $\eta \in L^q \Omega^{0,1}(\Sigma, u^*TX)$ for $1/p + 1/q = 1$, 
        \item $\bv = (v_e) \in N_{\bx} \subset T_{\bx} X^{\vv E}$; 
        \item $(\eta,\bv)$ pairs to zero with every element in the image of $\mathcal{L}$, with respect to the pairing induced by the pairing of $L^p$ and $L^q$ and a Riemannian metric on $X$. 
    \end{itemize}
    Let $\hat u \in W^{1,p}(\Sigma, u^*TX) = T_u \cB$. We have
    \[
        \mathcal{L}_u \hat u = (D_u\hat u, ( \hat u(z_e) )  )
    \]
    where $D_u$ is the linearization of the Cauchy--Riemann operator $\delbar_{Jj}$ with fixed $(J,j)$ \cite[Section 3.1]{mcduff}. Therefore,
    \begin{equation}
        \label{eqn:variation of u}
        0 = \langle \mathcal{L}_u \hat u, (\eta,\bv) \rangle = \langle D_u \hat u, \eta \rangle + \sum_{e \in \vv E} \langle \hat u(z_e), v_e \rangle.
    \end{equation}
    In particular, for all $\hat u$ vanishing at $\bz$,
    \[
        \langle D_u \hat u, \eta \rangle = 0,
    \]
    that is: $\eta$ is a weak $L^q$ solution to the equation $D_u^*\eta =0$ in $\Sigma\setminus\bz$. Here $D_u^*$ is the formal adjoint of $D_u$: the first order differential operator defined by the property 
    \[
        \int_\Sigma \langle D_u \xi_1, \xi_2 \rangle \mathrm{vol}_\Sigma = \int_\Sigma \langle \xi_1, D_u^*\xi_2 \rangle \mathrm{vol}_\Sigma
    \]
    for all $\xi_1 \in \G(\Sigma,u^*TX)$, $\xi_2 \in \Omega^{0,1}(\Sigma, u^*TX)$ \cite[Section 3.1]{mcduff}. It follows from elliptic regularity \cite[Proposition 3.1.11]{mcduff} that $\eta$ is, in fact, of class $W^{1,p}_{\mathrm{loc}}$ in $\Sigma\setminus\bz$; therefore, continuous in that region. 

    Moreover, for every $\hat J \in T_J \cJ = C^k(X, \mathrm{End}(TX,J,\omega))$, we have
    \[
        \langle \mathcal{L}_J \hat J, \eta \rangle = 0
    \]
    Explicitly, as in \cite[Proof of Proposition 3.2.1]{mcduff}, 
    \begin{equation}
        \label{eqn:variation of J}
        \int_{\Sigma} \langle \hat J(u) \circ du \circ j, \eta \rangle \mathrm{vol}_{\Sigma} = 0
    \end{equation} 
    for every $\hat J$. It follows in a standard way from equation \eqref{eqn:variation of J} and the continuity of $\eta$ on $\Sigma \setminus \bz$ that $\eta$ vanishes on the set of injective points 
    \[
        R = \{ z \in \Sigma \setminus \bz \ | \ du(z) \neq 0, \ u^{-1}(u(z)) = \{ z \} \};
    \]
    see \cite[Proof of Proposition 3.2.1]{mcduff}.  Let $\G^* \subset \G$ be the set of vertices $\alpha \in \G$ with $A_\alpha \neq 0$ and let $\Sigma^* \subset \Sigma$ be the union of the corresponding connected components of $\Sigma$. Since $u$ is simple, $R$ is dense in $\Sigma^*$, so $\eta$ vanishes on $\Sigma^*$.    Let $\hat u \in W^{1,p}(\Sigma, u^*TX)$ be any  section (not necessarily vanishing at $\bz$) supported on $\Sigma^*$. Since $\eta = 0$ on $\Sigma^*$, 
    \[
        \langle \mathcal{L}\hat u, \bv \rangle = 0,
    \]
    which by \eqref{eqn:variation of u} is equivalent to
    \[
        \sum_{e \in \vv E^*} \langle \widehat u(z_e), v_e \rangle  = 0
    \]
    with $\vv E^* \subset \vv E$ denoting the set of oriented edges beginning in $\G^*$. 
    Since we can find $\hat u$ such that $\hat u(z_e) \in T_{x_e} X$ are arbitrary vectors, it follows that $v_e = 0$ for $e \in \vv E^*$. Note that this implies also $v_e = 0$ if $\bar e \in \vv E^*$ because $\bv$ is in $N_{\bx}$.

    It remains to show that $\eta = 0$ on $\Sigma\setminus\Sigma^*$ and $v_e = 0$ for $e \in \vv E\setminus \vv E^*$. By assumption, the subgraph $\G\setminus\G^*$ is a disjoint union of trees and $u$ is constant on each connected component of $\Sigma\setminus\Sigma^*$. Let $T$ be a connected component of $\G\setminus\G^*$ and $\Sigma_T \subset \Sigma\setminus\Sigma^*$ the corresponding union of  $\P^1$ components. Denote $u_T = u|_{\Sigma_T}$ and by $\mathcal{L}_{u_T}$ the corresponding operator. It is related to $\mathcal{L}_u$ as follows:
    \[
        \mathcal{L}_u = \bigoplus_{\alpha \in V(\G)} L_{u_\alpha} \quad\text{and}\quad \mathcal{L}_{u_T} = \bigoplus_{\alpha \in V(T)} L_{u_\alpha}.
    \]
    Since $u_T$ is locally constant, we can compute $\mathcal{L}_{u_T}$ directly. This is done in \autoref{lem:surjectivity for constant maps}  proved below, which shows that $\mathcal{L}_{u_T}$ is surjective, i.e. $\eta =0$ on $\Sigma_T$ and $v_e=0$ for $e \in \vv E_T$. 
\end{proof}

The proof of \autoref{lem:surjectivity for constant maps} is preceded by a lemma which describes the cokernel of $\mathcal{L}_u$  in the following general  situation. Let $u \colon (\Sigma,j) \to (X,J)$ be a $J$--holomorphic map from a compact, possibly disconnected Riemann surface $(\Sigma,j)$ and let $\bz = (z_i)_{i\in I}$ be a collection of distinct points in $\Sigma$ indexed by a finite set $I$. Set $\bx = (x_i)_{i\in I}$ where $x_i = u(z_i)$. Assume that $\bx$ belongs to a generalized diagonal in $X^I$. Such a diagonal is specified by an equivalence relation $\sim$ on $I$:
\[
    \Delta = \Delta_{\sim} = \{ (y_i) \in X^I \ | \ y_i = y_j \text{ if } i \sim j \}.
\]
Let $N_{\bx} = T_{\bx} X^I / T_{\bx} \Delta$ be the normal space to $\Delta$ at $\bx$.

\begin{lemma}
    \label{lem:cokernel of evaluation}
    In the situation described above, consider the operator
    \begin{gather*}
        \mathcal{L}_u \colon W^{1,p}(\Sigma,u^*TX) \to \Omega^{0,1}(\Sigma,u^*TX) \oplus N_{\bx}, \\
        \mathcal{L}_u \hat u = (D_u \hat u, [\ev_{\bz}(\hat u)] ),
    \end{gather*}
    where $D_u$ is the linearization of the Cauchy--Riemann operator $\delbar_{Jj}$ at $u$ and
    \[
        [\ev_{\bz}] \hat u = [ (\hat u(z_i))_{i\in I} ]
    \]
    is the projection of the evaluation map at $\bz$ on $N_{\bx}$. There is a short exact sequence
    \[
        \begin{tikzcd}
        0 \ar{r} & \coker( [\ev_{\bz} ]|_{\ker D_u} ) \ar{r} & \coker \mathcal{L}_u \ar{r} & \coker D_u \ar{r} & 0.
        \end{tikzcd}
    \]
\end{lemma}
\begin{proof}
    The statement follows from the snake lemma applied to the diagram
    \[
        \begin{tikzcd}
            0 \ar{r} & \ker D_u \ar{r} \ar{d}{ [\ev_{\bz}] } & W^{1,p}(\Sigma,u^*TX) \ar{r} \ar{d}{ \mathcal{L}_u} &  \ar{r} \im D_u \arrow[hookrightarrow]{d} \ar{r} & 0, \\
            0 \ar{r} & N_{\bx} \ar{r} & \Omega^{0,1}(\Sigma,u^*TX) \oplus N_{\bx} \ar{r} & L^p\Omega^{0,1}(\Sigma,u^*TX)  \ar{r} & 0. \qedhere
        \end{tikzcd} 
    \]
\end{proof}

We now apply \autoref{lem:cokernel of evaluation} to the special case of constant maps from trees, which appears in the proof of \autoref{thm: transversality}.

\begin{lemma}
    \label{lem:surjectivity for constant maps}
    Let $T$ be a tree and $\Sigma = \bigsqcup_{\alpha \in T} C_\alpha$ where $C_\alpha = \P^1$ and let $u \colon \Sigma \to X$ be a constant map with image $x \in X$.  Let $\bz$ be a collection of points in $\Sigma$ of the form $z_{\alpha\beta} \in C_\alpha$ and $z_{\beta\alpha} \in C_\beta$ for every edge $(\alpha,\beta) \in T$. Consider the diagonal
    \[
        \Delta = \Delta^{E(T)} = \{ (x_{e}) ) \in X^{\vv E(T)} \ | \ x_{e} = x_{\bar e} \},
    \]  
    In this case, the map $\mathcal{L}_u$ from \autoref{lem:cokernel of evaluation} is surjective. 
\end{lemma}

\begin{proof}
    Since $u$ is constant, the restriction of $D_u$ to every component $C_\alpha$ is the standard $\delbar$ operator
    \[
        \delbar \colon W^{1,p}(\P^1,\C) \otimes T_x X \to L^p\Omega^{0,1}(\P^1, \C) \otimes T_x X
    \]
    which is surjective as $(\coker \delbar)^* \cong H^0(\P^1, K_{\P^1}) \otimes T_x X = 0$. The kernel $\ker\delbar \cong T_x X$ is given by constant maps. Instead of the set $\vv E = \vv E(T)$ of edges with orientations, it is convenient to use the set of $E = E(T)$ of edges. To that end, pick an arbitrary orientation on each of the edges in $E$, so that 
    \[
        X^{\vv E} = \prod_{e\in E} (X\times X)
    \]
    where the first summand corresponds to the beginning and the second to the end of $E$; then $\Delta$ is the product of diagonals $X \subset X \times X$ over $e\in E$. Let $V_\alpha = T_x X$ be the copy of $T_x X$ for every $\alpha \in T$, and similarly $V_e = T_x X$ for $e \in E$.  By \autoref{lem:cokernel of evaluation}, the cokernel of $\mathcal{L}_u$ is isomorphic to the cokernel of the map
    \[
         b  \colon \bigoplus_{\alpha\in T} V_\alpha \to N_{\bx}
    \]
    where $N_{\bx}$ is the normal space to the sum of diagonals in $\bigoplus_{e\in E} V_e \oplus V_e$. Alternatively, the map above is identified with
    \[
        b \colon \colon \bigoplus_{\alpha\in T} V_\alpha \to \bigoplus_{e \in E} V_e
    \]
    where $b \colon V_\alpha \to V_e$ is the identity map when $\alpha$ is the beginning of $e$ and minus the identity when $\alpha$ is the end of $e$. It is clear from this description that adding one vertex and one edge to $T$ perserves surjectivity of $b$. Therefore, by induction with respect to $|T|$, the map $b$ is surjective for every tree $T$.
\end{proof}


