\section{Fredholm maps} 
Recall that a smooth map $f \colon X \to Y$ between Banach manifolds is said to be Fredholm if for every $p \in X$ the differential $d_p f \colon T_p X \to T_{f(p)} Y$ is a Fredholm operator. The index of $f$ at $p$ is defined as $\mathrm{ind}(d_p f)$. If $X$ is connected, which we will assume in this section, the index does not depend on $p$. In this section we will always consider $C^1$ maps whose derivative has closed image. Finally, all results of this section have obvious analogs for sections of Banach vector bundles, after replacing the differential by a covariant derivative. 

The following is used to compute in index computations throughout the paper. 

\begin{lemma}
    \label{lem: fredholm stabilization}
        Let $X$ and $Y$ be Banach manifolds and let $U_0$ and $U_1$ be finite dimensional manifolds. Let  $\overline f \colon X \times U_0 \to Y \times U_1$ be a $C^1$ map and denote its projection on $Y$ by $f$. If for every $u \in U_0$ the map $f(\cdot, u)$ is Fredholm, then $\overline f$ is Fredholm of index
    \begin{equation}
        \label{eqn: index of stabilization}
        \mathrm{ind}(\overline f) = \mathrm{ind}(f) + \dim(U_0) - \dim(U_1). 
    \end{equation}
\end{lemma}

\begin{proof}
    By looking at the derivatives, it suffices to consider the case when $X$ and $Y$ are Banach spaces, $U_0$, $U_1$ are finite dimensional vector spaces, and $\overline f$ is a bounded linear map of the form
    \begin{gather*}
        \overline f \colon X \oplus U_0 \to Y \oplus U_1, \\
        \overline f =
        \begin{pmatrix}
            f & * \\
            * & *
        \end{pmatrix}
    \end{gather*}
    such that $f \colon X \to Y$ is a Fredholm operator. The operator $f \oplus 0: X \oplus U_0 \to Y \oplus U_1$ satisfies
    \begin{align*}
        \ker(f \oplus 0) &= \ker (f) \oplus U_0, \\
        \coker (f\oplus 0) &\cong \coker(f) \oplus U_1. 
    \end{align*}
    Therefore, $f\oplus 0$ is Fredholm of index given by the right-hand side of \eqref{eqn: index of stabilization}. The difference $\overline f - f\oplus 0$ is a bounded operator  with finite-dimensional image; therefore, $\mathrm{ind}(\overline f) = \mathrm{ind}(f \oplus 0)$. 
\end{proof}

The next lemma allows us to relate the index of the projection from universal moduli spaces to the space of almost complex structures $\cJ$ to the index of the linearization with $J \in \cJ$ fixed. 

\begin{lemma}
    \label{lem: fredholm projection}
    Let $X$, $Y$, and $Z$ be Banach manifolds and let $S \subset Z$ be a  $C^1$ submanifold. Let $f \colon X \times Y \to Z$ be a smooth map which is transverse to $S$. Set $\widehat S = f^{-1}(S)$. Denote by $\pi \colon \widehat S \to Y$ the projection on $Y$, by $d_X f$ the restriction of $df$ to $TX$, and by $(\cdot)^N$ the projection on the normal bundle $N$ of $S$. For every $p = (x,y) \in \widehat S$ we have
    \begin{gather*}
        \ker (d\pi)_p \cong \ker ( (d_X f)_p^N \colon T_x X \to N_{f(p)} ), \\
        \coker (d\pi)_p \cong \coker ((d_X f)_p^N \colon T_x X \to N_{f(p)} ).
    \end{gather*}
\end{lemma}

\begin{proof}
    The statement follows from the snake lemma applied to the diagram
    \[
        \begin{tikzcd}
        0 \ar{r} & T_p \widehat S \ar{d}{(d\pi)_p} \ar{r} & T_p (X\times Y) \ar{d} \ar{r}{(d f)^N_p} \ar{r} & N_{f(p)} \ar{r} \ar{d} & 0 \\
        0 \ar{r} & T_y Y \ar{r} & T_y Y \ar{r} & 0 \ar{r} & 0 .
        \end{tikzcd}
    \]

\end{proof}


We will also use fiber products of Fredholm maps. Recall that the fiber product of maps $f \colon X \to Y$ and $g \colon Y \to Z$ is defined by
\[
    F = X \times_Z Y = \{ (x,y) \in X \times Y \ | \ f(x) = g(y) \},
\]
and it fits into the commutative diagram
\[
    \scalebox{0.85}{$
    \xymatrix{
    & F \ar[dl] \ar[dr] & \\
    X \ar[dr]_f & & Y \ar[dl]^g \\
    & Z &
    }
    $}
\]
The map $f$ is transverse to $g$ if for every $p=(x,y) \in F$ with value $z = f(x)=g(y)$ the map 
\[
    L_p = (df)_x - (dg)_y \colon T_x X \oplus T_y Y \to T_z Z
\]
is surjective. In that case, $F$ is a smooth submanifold of $X\times Y$. Denote by $\pi_X \colon F \to X$ and $\pi_Y \colon F \to Y$ the projection maps. By \autoref{lem: fredholm projection} applied to $S$ being the diagonal in $Z \times Z$, if $f$ is transverse to $g$, then
\begin{gather*}
    \ker( d\pi_X)_{p} ) \cong \ker( (dg)_y ) \quad\text{and}\quad     \coker( d\pi_X)_{p} ) \cong \coker( (dg)_y ), \\
    \ker( d\pi_Y)_{p} ) \cong \ker( (df)_x ) \quad\text{and}\quad     \coker( d\pi_Y)_{p} ) \cong \coker( (df)_x ).
\end{gather*}
In particular, if $f$ is Fredholm, then so is $\pi_Y$ and $\mathrm{ind}(\pi_Y) = \mathrm{ind}(f)$, and similarly for $g$ and $\pi_X$. In a non-transverse situation, the failure of transversality at $p\in F$ is measured by $\dim\coker(L_p)$, and the following generalization holds.

\begin{lemma}
    \label{lem: fiber product}
    In the situation described above, suppose that $f$ is a Fredholm map. For every $p \in F$ there exists a $C^1$ submanifold $S \subset X \times Y$ containing an open neighborhood of $p$ in $F$ and such that the projection $\pi_Y \colon S \to Y$ is a Fredholm map of index
    \[
        \mathrm{ind}(\pi_Y) = \mathrm{ind}(f) + \dim\coker(L_p).
    \]  
\end{lemma}
\begin{proof}
    Since this is a local statement, without loss of generality assume that $Z$ is a Banach space and $z=0$. Let $V = \im L_p$ and let $\pi_V \colon Z \to V$ be a projection on $V$  (since $L_p$ is Fredholm, there exists such a projection). By construction, the operator
    \[
        \pi_V \circ L_p \colon T_x X \oplus T_y Y \to V
    \]
    is surjective. Therefore,  $\pi_V\circ f$ is transverse to $\pi_V \circ g$ at $p$, and therefore at every point in some neighborhood $U \subset X \times Y$ of $p$. Therefore, 
    \[
        S = \{ (x,y) \in U \ | \ \pi_V( f(x) ) = \pi_V( g(y) )
    \]
    is a $C^1$ submanifold of $U$ containing $F$ and the statement follows from the transverse case applied to the maps $\pi_V\circ f$ and $\pi_V \circ g$. 
\end{proof}

